INSERT INTO `mst_kbli` (`id`, `kode`, `uraian`, `keterangan`, `created_at`, `updated_at`, `id_parent`)
VALUES
	(1,'01111','PERTANIAN JAGUNG','Kelompok ini mencakup usaha pertanian komoditas jagung mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman jagung. Termasuk kegiatan pembibitan dan pembenihan tanaman jagung.',NULL,NULL,0),
	(2,'01112','PERTANIAN GANDUM','Kelompok ini mencakup usaha pertanian gandum mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman serealia gandum, seperti sorgum/cantel, gandum (wheat/oats), jelai (barley), gandum hitam (rye), jawawut (millet) dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman gandum.',NULL,NULL,0),
	(3,'01113','PERTANIAN KEDELAI','Kelompok ini mencakup usaha pertanian kedelai mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman kedelai (kacang palawija). Termasuk kegiatan pembibitan dan pembenihan tanaman kedelai.',NULL,NULL,0),
	(4,'01114','PERTANIAN KACANG TANAH','Kelompok ini mencakup usaha pertanian kacang tanah mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman kacang tanah (kacang palawija). Termasuk kegiatan pembibitan dan pembenihan tanaman kacang tanah.',NULL,NULL,0),
	(5,'01115','PERTANIAN KACANG HIJAU','Kelompok ini mencakup usaha pertanian kacang hijau mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman kacang hijau (kacang palawija). Termasuk kegiatan pembibitan dan pembenihan tanaman kacang hijau.',NULL,NULL,0),
	(6,'01116','PERTANIAN ANEKA KACANG HORTIKULTURA','Kelompok ini mencakup usaha pertanian aneka kacang hortikultura mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman aneka kacang hortikultura, seperti buncis, buncis besar, kacang panjang, kacang merah, gude, kara, kapri, kecipir, cow peas, miju- miju, lupin, kacang polong, pigeon peas dan tanaman aneka kacang lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman aneka kacang hortikultura.',NULL,NULL,0),
	(7,'01117','PERTANIAN BIJI-BIJIAN PENGHASIL MINYAK MAKAN','Kelompok ini mencakup usaha pertanian biji-bijian penghasil minyak makan mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman biji-bijian penghasil minyak makan, seperti biji wijen, biji bunga matahari dan tanaman biji-bijian penghasil minyak makan lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman biji-bijian penghasil minyak makan.',NULL,NULL,0),
	(8,'01118','PERTANIAN BIJI-BIJIAN PENGHASIL BUKAN MINYAK MAKAN','Kelompok ini mencakup usaha pertanian biji-bijian penghasil bukan minyak makan mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman biji-bijian penghasil bukan minyak makan, seperti biji kapas, biji rami, biji mustard, niger seeds, biji jarak pohon dan tanaman biji-bijian penghasil bukan minyak makan lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman biji-bijian penghasil bukan minyak makan.',NULL,NULL,0),
	(9,'01119','PERTANIAN SEREALIA LAINNYA, ANEKA KACANG DAN BIJI-BIJIAN PENGHASIL MINYAK LAINNYA','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman serealia lainnya bukan padi, jagung dan gandum, tanaman aneka kacang palawija lainnya dan pertanian tanaman lainnya yang belum diklasifikasikan pada kelompok 01111 s.d. 01118. Termasuk kegiatan pembibitan dan pembenihan tanaman serealia dan biji-bijian penghasil minyak lainnya.',NULL,NULL,0),
	(10,'01121','PERTANIAN PADI HIBRIDA','Kelompok ini mencakup usaha pertanian padi hibrida mulai dari kegiatan pengolahan lahan, penyemaian, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan sampai dengan dihasilkan komoditas gabah kering panen (GKP). Termasuk kegiatan pembibitan dan pembenihan tanaman padi hibrida. Padi hibrida adalah keturunan pertama (F1) yang dihasilkan dari persilangan antara dua galur atau lebih tetua pembentuknya dan/atau galur/inbrida homozigot. Contohnya: Bernas Super, Bernas Prima, Sembada B3, SL 11 SHS. Turunan dari padi hibrida tidak termasuk sebagai padi hibrida.',NULL,NULL,0),
	(11,'01122','PERTANIAN PADI INBRIDA','Kelompok ini mencakup usaha pertanian inbrida (bukan hibrida) mulai dari kegiatan pengolahan lahan, penyemaian, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan sampai dengan dihasilkan komoditas gabah kering panen (GKP). Termasuk kegiatan pembibitan dan pembenihan tanaman padi in hibrida. Padi in hibrida adalah padi yang produksi benihnya dilakukan melalui penyerbukan sendiri atau terjadi secara alami. Terdiri dari Padi varietas Unggul Non Hibrida seperti Memberamo, Menkongga, Ciherang, IR-6, Inpari, Inpara, Inpago dan Padi Varietas Lokas yang telah ada dan dibudidayakan secara turun temurun oleh petani.',NULL,NULL,0),
	(12,'01131','PERTANIAN HORTIKULTURA SAYURAN DAUN','Kelompok ini mencakup usaha pertanian hortikultura dan sayuran daun mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan, dan pasca panen jika menjadi satu kesatuan kegiatan tanaman hortikultura sayuran yang dipanen sekali, seperti petsai/sawi, asparagus, kubis/kol, kembang kol dan brokoli, selada dan seledri/chicory, daun bawang, bayam, kangkung, tumbuhan yang bunganya dimakan sebagai sayur dan sayuran daun dan batang lainnya. Bayam dan kangkung yang dipanen dengan akarnya juga dimasukkan dalam kelompok ini. Termasuk kegiatan pembibitan dan pembenihan tanaman hortikultura sayuran daun.',NULL,NULL,0),
	(13,'01132','PERTANIAN HORTIKULTURA BUAH','Kelompok ini mencakup usaha pertanian hortikultura buah mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman hortikultura buah, seperti semangka, belewah, melon, timun suri dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman hortikultura buah.',NULL,NULL,0),
	(14,'01133','PERTANIAN HORTIKULTURA SAYURAN BUAH','Kelompok ini mencakup usaha pertanian hortikultura sayuran buah mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman hortikultura buah yang dipakai sebagai sayuran (labu), seperti mentimun, terung, tomat, belimbing sayur dan labu sayur (siam), waluh/labu kuning, gambas/oyong dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman hortikultura sayuran buah.',NULL,NULL,0),
	(15,'01134','PERTANIAN HORTIKULTURA SAYURAN UMBI','Kelompok ini mencakup usaha pertanian hortikultura sayuran umbi mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, pemanenan, dan pasca panen jika menjadi satu kesatuan kegiatan tanaman umbi-umbian hortikultura, seperti kentang, kentang manis, wortel, lobak cina, rebung, bawang putih, bawang bombay atau bawang merah, bawang perai dan sayuran alliaceous lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman hortikultura sayuran umbi.',NULL,NULL,0),
	(16,'01135','PERTANIAN ANEKA UMBI PALAWIJA','Kelompok ini mencakup usaha pertanian aneka umbi palawija mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, dan juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman aneka umbi palawija, seperti ubi kayu, ubi jalar, talas, ganyong dan irut, gembili dan tanaman palawija, iles-iles, porang dan umbi-umbian palawija lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman aneka umbi palawija.',NULL,NULL,0),
	(17,'01136','PERTANIAN JAMUR','Kelompok ini mencakup usaha pertanian jamur mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman jamur dan truffle, seperti jamur merang, jamur tiram, jamur shitake, jamur kuping dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman jamur.',NULL,NULL,0),
	(18,'01137','PERTANIAN BIT GULA DAN TANAMAN PEMANIS BUKAN TEBU','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman bit gula dan tanaman pemanis lainnya bukan tebu, seperti stevia dan sorgum manis. Termasuk kegiatan pembibitan dan pembenihan tanaman bit gula dan tanaman pemanis bukan tebu.',NULL,NULL,0),
	(19,'01139','PERTANIAN SAYURAN, BUAH DAN ANEKA UMBI LAINNYA','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penanaman, pemeliharaan, juga pemanenan dan pasca panen jika menjadi satu kesatuan kegiatan tanaman sayuran, buah dan aneka umbi lainnya yang dipanen lebih dari sekali; dan pertanian sayuran lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman sayuran lainnya, kecuali bibit tanaman bit.',NULL,NULL,0),
	(20,'01140','PERKEBUNAN TEBU','Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan jika menjadi satu kesatuan kegiatan tanaman tebu. Termasuk kegiatan pembibitan dan pembenihan tebu.',NULL,NULL,0),
	(21,'01150','PERKEBUNAN TEMBAKAU','Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan jika menjadi satu kesatuan kegiatan tanaman tembakau. Termasuk kegiatan pembersihan dan perajangan tembakau yang tidak dapat dipisahkan dari kegiatan perkebunannya. Kegiatan pembibitan dan pembenihan tanaman tembakau juga tercakup dalam kelompok ini.',NULL,NULL,0),
	(22,'01160','PERTANIAN TANAMAN BERSERAT','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, dan pemanenan jika menjadi satu kesatuan kegiatan tanaman berserat sebagai bahan baku tekstil, seperti kapuk, kapas, rosela, rami, yute, linen, agave, abaca dan kenaf, pertanian sisal dan tanaman bahan baku tekstil lainnya termasuk genus agave dan pertanian tanaman serat lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman berserat.',NULL,NULL,0),
	(23,'01191','PERTANIAN TANAMAN PAKAN TERNAK','Kelompok ini mencakup bidang usaha produksi hijauan pakan ternak mulai dari kegiatan penyiapan dan pengolahan lahan, penyemaian, penanaman, pemeliharaan, pemanenan dan pengolahan pasca panen. Meliputi rumput pakan ternak dan leguminosa/kacang-kacangan tanaman pakan ternak seperti Rumput Gajah, Rumput Raja, Rumput Odot, Rumput Setaria, Alfalfa, Kaliandra, Gamal, Lamtoro, Indigofera Zollingeriana dll.',NULL,NULL,0),
	(24,'01192','PERBENIHAN TANAMAN PAKAN TERNAK DAN PEMBIBITAN BIT (BUKAN BIT GULA)','Kelompok ini mencakup usaha pertanian mulai dari kegiatan penyiapan dan pengolahan lahan, penyemaian, penanaman, pemeliharaan, pemanenan dan pengolahan pascapanen, perbenihan tanaman pakan ternak dan pembibitan bit (bukan bit gula). Perbenihan tanaman pakan ternak meliputi rumput pakan ternak dan leguminosa/kacang-kacangan tanaman pakan ternak seperti Rumput Gajah, Rumput Raja, Rumput Odot, Rumput Setaria, Alfalfa, Kaliandra, Gamal, Lamtoro, Indigofera Zollingeriana dll.',NULL,NULL,0),
	(25,'01193','PERTANIAN TANAMAN BUNGA','Kelompok ini mencakup pertanian tanaman bunga, yang produksinya adalah bunga potong dan kuncup bunga. Tanaman bunga pada kelompok ini misalnya anggrek, anyelir, gerbera/hebras, gladiol, krisan, mawar, melati, sedap malam dan tanaman bunga lainnya. Termasuk tanaman bunga lainnya yang diambil bunganya. Pertanian tanaman bunga yang hasilnya adalah tanaman bunga hidup masuk ke golongan 013.',NULL,NULL,0),
	(26,'01194','PERTANIAN PEMBIBITAN TANAMAN BUNGA','Kelompok ini mencakup usaha pertanian pembibitan tanaman bunga.',NULL,NULL,0),
	(27,'01199','PERTANIAN TANAMAN SEMUSIM LAINNYA YTDL','Kelompok ini mencakup pertanian tanaman semusim lainnya yang belum terklasifikasi di tempat lain dan kegiatan pembibitannya.',NULL,NULL,0),
	(28,'01210','PERTANIAN BUAH ANGGUR','Kelompok ini mencakup usaha pertanian mulai dari kegiatan penyiapan atau pelaksanaan, penanaman, pembibitan, pemeliharaan, pemanenan dan pasca panen buah anggur. Termasuk kegiatan pembibitan dan pembenihan tanaman buah anggur.',NULL,NULL,0),
	(29,'01220','PERTANIAN BUAH-BUAHAN TROPIS DAN SUBTROPIS','Kelompok ini mencakup usaha pertanian mulai dari kegiatan penyiapan/pelaksanaan, penanaman, pembibitan, pemeliharaan, pemanenan dan pasca panen buah-buahan tropis dan subtropis, seperti rambutan, alpukat, durian, duku, pisang dan pisang raja, kurma, buah ara, pepaya, jambu biji, jambu air, lengkeng, nangka, nenas, mangga, manggis, sawo, belimbing, salak, sirsak, buah naga dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman buat tropis dan subtropis.',NULL,NULL,0),
	(30,'01230','PERTANIAN BUAH JERUK','Kelompok ini mencakup usaha pertanian mulai dari kegiatan penyiapan/pelaksanaan, penanaman, pembibitan, pemeliharaan, pemanenan dan pasca panen buah jeruk besar dan jeruk keprok atau jeruk siam, seperti jeruk bali, jeruk lemon dan limau, jeruk orange, jeruk keprok, jeruk tangerin, jeruk mandarin dan clementine, dan buah jeruk lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman buah jeruk.',NULL,NULL,0),
	(31,'01240','PERTANIAN BUAH APEL DAN BUAH BATU (POME AND STONE FRUITS)','Kelompok ini mencakup usaha pertanian mulai dari kegiatan penyiapan/pelaksanaan, penanaman, pembibitan, pemeliharaan, pemanenan dan pasca panen buah apel dan buah batu, seperti apel, aprikot, cherry, peach dan nectarine, pear dan quince, plum dan sloe, markisa, kepel, terong Belanda dan buah delima, dan buah batu lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman buah apel dan buah batu.',NULL,NULL,0),
	(32,'01251','PERTANIAN BUAH BERI','Kelompok ini mencakup usaha pertanian mulai dari kegiatan penyiapan atau pelaksanaan, penanaman, pembibitan, pemeliharaan, pemanenan dan pasca panen buah beri, seperti blueberry, gooseberry, kiwi, raspberry, strawberry dan beri lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman buah beri.',NULL,NULL,0),
	(33,'01252','PERTANIAN BUAH BIJI KACANG-KACANGAN','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, dan pemanenan tanaman buah biji kacang-kacangan yang dapat dimakan, seperti almond, kacang mede, chestnut, kenari, walnut dan kacang-kacangan yang lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman buah biji kacang-kacangan.',NULL,NULL,0),
	(34,'01253','PERTANIAN SAYURAN TAHUNAN','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan tanaman sayuran tahunan, seperti kluwih atau timbul, sukun, nangka sayur, petai, jengkol, melinjo dan sejenisnya. Kegiatan pembibitan dan pembenihan tanaman sayuran tahunan.',NULL,NULL,0),
	(35,'01259','PERTANIAN BUAH SEMAK LAINNYA','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan tanaman buah semak lainnya, termasuk locust beans. Termasuk kegiatan pembibitan dan pembenihan tanaman buah semak lainnya.',NULL,NULL,0),
	(36,'01261','PERKEBUNAN BUAH KELAPA','Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan buah kelapa. Termasuk kegiatan pembibitan dan pembenihan tanaman buah kelapa.',NULL,NULL,0),
	(37,'01262','PERKEBUNAN BUAH KELAPA SAWIT','Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan buah kelapa sawit. Termasuk kegiatan pembibitan dan pembenihan tanaman buah kelapa sawit.',NULL,NULL,0),
	(38,'01269','PERKEBUNAN BUAH OLEAGINOUS LAINNYA','Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan tanaman buah oleaginous lain, seperti buah zaitun dan lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman buah oleoginous lainnya.',NULL,NULL,0),
	(39,'01270','PERTANIAN TANAMAN UNTUK BAHAN MINUMAN','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan tanaman untuk bahan minuman, seperti tanaman kopi, teh, mate dan kakao. Termasuk kegiatan pembibitan dan pembenihan tanaman untuk bahan minuman.',NULL,NULL,0),
	(40,'01281','PERKEBUNAN LADA','Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan lada atau merica (piper spp). Termasuk kegiatan pembibitan dan pembenihan tanaman lada.',NULL,NULL,0),
	(41,'01282','PERKEBUNAN CENGKEH','Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan cengkeh. Termasuk kegiatan pembibitan dan pembenihan tanaman cengkeh.',NULL,NULL,0),
	(42,'01283','PERTANIAN CABAI','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, pemanenan dan pasca panen sayuran cabai (capsicum spp), seperti cabai besar, cabai rawit dan paprika. Termasuk kegiatan pembibitan dan pembenihan tanaman cabai.',NULL,NULL,0),
	(43,'01284','PERKEBUNAN TANAMAN AROMATIK/PENYEGAR','Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan tanaman perkebunan minyak atsiri, seperti sereh wangi, nilam, menthol, kenanga, ilang-ilang, gandapura, lawang. Termasuk kegiatan pembibitan dan pembenihan tanaman aromatik/penyegar.',NULL,NULL,0),
	(44,'01285','PERTANIAN TANAMAN OBAT ATAU BIOFARMAKA RIMPANG','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, dan pemanenan tanaman obat atau biofarmaka rimpang (termasuk pula tanaman bahan insektisida dan fungisida dan yang sejenis), seperti jahe, kunyit, temulawak, temugiring, temuireng, temukunci, kencur, lengkuas, lempuyang, dlingo dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman obat atau biofarmaka rimpang.',NULL,NULL,0),
	(45,'01286','PERTANIAN TANAMAN OBAT ATAU BIOFARMAKA NON RIMPANG','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, dan pemanenan tanaman obat atau biofarmaka non rimpang (termasuk pula tanaman bahan insektisida dan fungisida dan yang sejenis), seperti kina, adas, kapulaga, orang-aring, iles-iles, pinang, gambir, lidah buaya, kejibeling, sambiloto, kumis kucing, mengkudu atau pace, mahkota dewa dan sejenisnya. Termasuk kegiatan pembibitan dan pembenihan tanaman obat atau biofarmaka non rimpang.',NULL,NULL,0),
	(46,'01287','PERTANIAN TANAMAN NARKOTIKA DAN TANAMAN OBAT TERLARANG','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, dan pemanenan tanaman narkotika dan tanaman obat terlarang.',NULL,NULL,0),
	(47,'01289','PERTANIAN TANAMAN REMPAH-REMPAH, AROMATIK/PENYEGAR, DAN OBAT LAINNYA','Kelompok ini mencakup usaha pertanian mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan, dan pemanenan tanaman rempah lainnya, seperti kemiri, panili, kayu manis dan pala. Termasuk kegiatan pembibitan dan pembenihannya.',NULL,NULL,0),
	(48,'01291','PERKEBUNAN KARET DAN TANAMAN PENGHASIL GETAH LAINNYA','Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan tanaman karet dan tanaman penghasil getah lainnya, seperti getah perca dan kemenyan. Termasuk pengolahan hasil tanaman karet yang tidak dapat dipisahkan dari kegiatan perkebunan. Termasuk kegiatan pembibitan dan pembenihan tanaman karet dan tanaman penghasil getah lainnya.',NULL,NULL,0),
	(49,'01299','PERTANIAN CEMARA DAN TANAMAN TAHUNAN LAINNYA','Kelompok ini mencakup usaha perkebunan mulai dari kegiatan pengolahan lahan, penyemaian, pembibitan, penanaman, pemeliharaan dan pemanenan pohon cemara, tanaman jarak pagar dan tanaman tahunan lainnya. Termasuk kegiatan pembibitan dan pembenihan tanaman cemara dan tanaman tahunan lainnya.',NULL,NULL,0),
	(50,'01301','PERTANIAN TANAMAN HIAS','Kelompok ini mencakup pertanian atau budidaya tanaman hias daun dan tanaman hias bunga hidup, seperti bonsai, suplir, kuping gajah, heliconia (pisang-pisangan), dracaena, phylodendrom, monstera, cordyline, anthurium daun, pakis, aglonema, difenbacia, sansifera (lidah mertua), caladium (keladi), palem dan tanaman hias bunga, seperti anggrek, mawar, adenium (kaboja jepang, anthurium bunga, euphorbia, ixora (soka) dan tanaman bunga lainnya. Termasuk penanaman tumbuhan untuk tujuan ornamen dan tanah berumput untuk transplantasi.',NULL,NULL,0),
	(51,'01302','PERTANIAN PENGEMBANGBIAKAN TANAMAN','Kelompok ini mencakup produksi semua bibit tanaman secara vegetatif termasuk batang stek, potongan dan pembibitan untuk kelangsungan pengembangbiakan tanaman atau membuat batang okulasi tanaman pada keturunannya terpilih yang diokulasi yang pada akhirnya ditanam untuk menghasilkan tanaman. Termasuk kegiatan penanaman tumbuhan untuk ditanam kembali, penanaman tumbuhan hidup untuk umbi-umbian, akar-akaran; pemotongan, stek dan cangkokan; spawn jamur dan kebun bibit tanaman, kecuali kebun bibit tanaman hutan.',NULL,NULL,0),
	(52,'01411','PEMBIBITAN DAN BUDIDAYA SAPI POTONG','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan sapi potong, untuk menghasilkan ternak bibit sapi potong, semen dan embrio, dan kegiatan budidaya sapi potong berupa pengembangbiakan untuk menghasilkan anak atau calon indukan dan penggemukan untuk menghasilkan calon sapi siap potong.',NULL,NULL,0),
	(53,'01412','PEMBIBITAN DAN BUDIDAYA SAPI PERAH','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan sapi perah untuk menghasilkan ternak bibit sapi perah, semen dan embrio dan usaha budidaya sapi perah berupa pengembangbiakan untuk menghasilkan anak atau calon indukan dan untuk menghasilkan susu dan penggemukan.',NULL,NULL,0),
	(54,'01413','PEMBIBITAN DAN BUDIDAYA KERBAU POTONG','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan kerbau potong untuk menghasilkan ternak bibit kerbau potong, semen dan embrio dan usaha budidaya kerbau potong berupa pengembangbiakan untuk menghasilkan anak atau calon indukan dan penggemukan untuk menghasilkan calon kerbau siap potong.',NULL,NULL,0),
	(55,'01414','PEMBIBITAN DAN BUDIDAYA KERBAU PERAH','Kelompok ini mencakup usaha peternakan yang menyelenggarakan pembibitan kerbau perah untuk menghasilkan ternak bibit kerbau perah, semen dan embrio dan usaha budidaya kerbau perah yang menyelenggarakan pengembangbiakan untuk menghasilkan anak atau calon indukan dan untuk menghasilkan susu.',NULL,NULL,0),
	(56,'01420','PETERNAKAN KUDA DAN SEJENISNYA','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan kuda dan sejenisnya, untuk menghasilkan ternak bibit kuda dan sejenisnya, semen dan embrio dan usaha budidaya kuda yang melakukan kegiatan pengembangbiakan untuk menghasilkan kuda potong, kuda perah, kuda pacu, kuda tunggang, kuda tarik, kuda kavaleri, kuda polo, dan kuda kesayangan, bagal, hinni dan sejenisnya. Kelompok ini mencakup : Produksi Susu Kuda dan Sejenisnya',NULL,NULL,0),
	(57,'01430','PETERNAKAN UNTA DAN SEJENISNYA','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan unta dan sejenisnya untuk menghasilkan ternak bibit unta dan sejenisnya, semen dan embrio dan melakukan kegiatan budidaya unta berupa pengembangbiakan untuk menghasilkan unta potong, unta perah dan sejenisnya seperti llama, alpacas, vicunas dan guanacos. Kelompok ini mencakup : Produksi susu unta dan sejenisnya',NULL,NULL,0),
	(58,'01441','PEMBIBITAN DAN BUDIDAYA DOMBA POTONG','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan domba potong untuk menghasilkan ternak bibit domba potong, semen dan embrio dan kegiatan budidaya domba potong berupa pengembangbiakan untuk menghasilkan anak atau calon indukan dan penggemukan untuk menghasilkan calon domba siap potong.',NULL,NULL,0),
	(59,'01442','PEMBIBITAN DAN BUDIDAYA KAMBING POTONG','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan kambing potong untuk menghasilkan ternak bibit kambing potong, semen dan embrio dan kegiatan budidaya kambing potong berupa pengembangbiakan untuk menghasilkan anak atau calon indukan dan penggemukan untuk menghasilkan calon kambing siap potong.',NULL,NULL,0),
	(60,'01443','PEMBIBITAN DAN BUDIDAYA KAMBING PERAH','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan kambing perah, untuk menghasilkan ternak bibit kambing perah, semen dan embrio; dan kegiatan budidaya kambing perah berupa pengembangbiakan untuk menghasilkan anak atau calon indukan dan untuk menghasilkan susu. (sama dengan sapi perah)',NULL,NULL,0),
	(61,'01444','PEMBIBITAN DAN BUDIDAYA DOMBA PERAH','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan domba perah untuk menghasilkan ternak bibit domba perah, semen dan embrio; dan kegiatan budidaya domba perah berupa pengembangbiakan untuk menghasilkan anak atau calon indukan dan untuk menghasilkan susu.',NULL,NULL,0),
	(62,'01445','PRODUKSI BULU DOMBA MENTAH/RAW WOOL','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan produksi bulu domba (wool) mentah.',NULL,NULL,0),
	(63,'01450','PETERNAKAN BABI','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan babi, untuk menghasilkan ternak bibit babi, semen dan embrio dan usaha budidaya babi berupa pengembangbiakan untuk menghasilkan anak atau calon indukan dan penggemukan untuk menghasilkan calon babi siap potong.',NULL,NULL,0),
	(64,'01461','BUDIDAYA AYAM RAS PEDAGING','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan budidaya ayam ras untuk menghasilkan ayam pedaging.',NULL,NULL,0),
	(65,'01462','BUDIDAYA AYAM RAS PETELUR','Kelompok ini mencakup usaha peternakan yang menyelenggarakan budidaya ayam ras untuk menghasilkan telur konsumsi dan lainnya.',NULL,NULL,0),
	(66,'01463','PEMBIBITAN AYAM LOKAL DAN PERSILANGANNYA','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan ayam lokal dan persilangannya,untuk menghasilkan ternak bibit ayam dan telur tetas ayam lokal petelur dan pedaging,dan persilangannya.',NULL,NULL,0),
	(67,'01464','BUDIDAYA AYAM LOKAL DAN PERSILANGANNYA','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan budidaya ayam lokal dan persilangannya, untuk menghasilkan pullet, ayam lokal pedaging siap potong dan telur konsumsi.',NULL,NULL,0),
	(68,'01465','PEMBIBITAN DAN BUDIDAYA ITIK DAN/ATAU BEBEK','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan itik dan/atau bebek, untuk menghasilkan telur tetas, ternak bibit itik dan/atau bebek dan peternakan yang menyelenggarakan budidaya itik dan/atau bebek untuk menghasilkan itik dan/atau bebek pedaging, itik dan/atau bebek petelur, telur konsumsi dan lainnya.',NULL,NULL,0),
	(69,'01466','PEMBIBITAN DAN BUDIDAYA BURUNG PUYUH','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan burung puyuh, untuk menghasilkan ternak bibit burung puyuh dan atau telur tetas dan peternakan yang menyelenggarakan budidaya burung puyuh untuk menghasilkan burung puyuh potong, burung puyuh petelur atau telur konsumsi.',NULL,NULL,0),
	(70,'01467','PEMBIBITAN DAN BUDIDAYA BURUNG MERPATI','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan burung merpati, untuk menghasilkan ternak bibit burung merpati dan atau telur tetas dan peternakan yang menyelenggarakan budidaya burung merpati untuk menghasilkan burung merpati potong atau untuk keperluan lainnya.',NULL,NULL,0),
	(71,'01468','PEMBIBITAN AYAM RAS','Kelompok ini mencakup usaha peternakan yang menyelenggarakan pembibitan ayam ras pedaging dan ayam ras petelur untuk menghasilkan ayam bibit, telur tetas, bibit niaga (final stock) day old chick (DOC) dari ayam ras pedaging dan ayam ras petelur.',NULL,NULL,0),
	(72,'01469','PEMBIBITAN DAN BUDIDAYA TERNAK UNGGAS LAINNYA','Kelompok ini mencakup usaha peternakan yang melakukan kegiatan pembibitan ternak unggas lainnya, seperti kalkun, angsa, unggas persilangan dan unggas lainnya untuk menghasilkan bibit dan atau telur tetas dan peternakan yang melakukan kegiatan budidaya unggas tersebut untuk menghasilkan, unggas pedaging, unggas petelur dan telur.',NULL,NULL,0),
	(73,'01491','PEMBIBITAN DAN BUDIDAYA BURUNG UNTA','Kelompok ini mencakup usaha peternakan yang menyelenggarakan pembibitan burung unta, untuk menghasilkan ternak bibit burung unta dan atau telur tetas dan peternakan yang menyelenggarakan budidaya burung unta konsumsi untuk menghasilkan burung unta potong, telur dan atau lainnya.',NULL,NULL,0),
	(74,'01492','PENGUSAHAAN KOKON/KEPOMPONG ULAT SUTERA','Kelompok ini mencakup usaha penanaman, pemeliharaan, pemungutan hasil, pengolahan dan pemasaran kokon/kepompong ulat sutera.',NULL,NULL,0),
	(75,'01493','PEMBIBITAN DAN BUDIDAYA LEBAH','Kelompok ini mencakup usaha peternakan yang menyelenggarakan pembibitan dan budidaya lebah, termasuk pengusahaan madu.',NULL,NULL,0),
	(76,'01494','PEMBIBITAN DAN BUDIDAYA RUSA','Kelompok ini mencakup usaha peternakan yang menyelenggarakan pembibitan dan budidaya ternak rusa/kijang, baik untuk menghasilkan bibit dan daging, kulit dan lainnya.',NULL,NULL,0),
	(77,'01495','PEMBIBITAN DAN BUDIDAYA KELINCI','Kelompok ini mencakup usaha peternakan yang menyelenggarakan pembibitan dan budidaya ternak kelinci, baik untuk menghasilkan bibit dan daging, kulit dan lainnya.',NULL,NULL,0),
	(78,'01496','PEMBIBITAN DAN BUDIDAYA CACING','Kelompok ini mencakup usaha peternakan yang menyelenggarakan pembibitan dan budidaya ternak cacing, baik untuk menghasilkan bibit dan daging, dan lainnya.',NULL,NULL,0),
	(79,'01497','PEMBIBITAN DAN BUDIDAYA BURUNG WALET','Kelompok ini mencakup usaha pembibitan dan budidaya burung walet untuk menghasilkan burung dan sarang burung walet, termasuk pengusahaan pembersihan, pencucian, pengolahan dan pengemasan sarang burung walet.',NULL,NULL,0),
	(80,'01499','PEMBIBITAN DAN BUDIDAYA ANEKA TERNAK LAINNYA','Kelompok ini mencakup usaha peternakan yang menyelenggarakan pembibitan aneka ternak, seperti marmut, anjing, kucing, kera/primata lainnya, ulat, jangkrik dan aneka ternak lainnya, untuk menghasilkan bibit dan peternakan yang menyelenggarakan budidaya aneka ternak untuk menghasilkan daging, kulit dan lainnya.',NULL,NULL,0),
	(81,'01611','JASA PENGOLAHAN LAHAN','Kelompok ini mencakup usaha pengolahan lahan pertanian tanaman pangan dan perkebunan atas dasar balas jasa (fee) atau kontrak dengan tujuan untuk persiapan penanaman, baik di lahan sawah maupun di lahan kering.',NULL,NULL,0),
	(82,'01612','JASA PEMUPUKAN, PENANAMAN BIBIT/BENIH DAN PENGENDALIAN HAMA DAN GULMA','Kelompok ini mencakup usaha yang bergerak dalam pemupukan lahan pertanian, penanaman bibit/benih dan pengendalian hama penyakit dan tanaman pengganggu (gulma) tanaman pangan dan perkebunan atas dasar balas jasa (fee) atau kontrak.',NULL,NULL,0),
	(83,'01613','JASA PEMANENAN','Kelompok ini mencakup usaha pemanenan tanaman atas dasar balas jasa (fee) atau kontrak.',NULL,NULL,0),
	(84,'01614','JASA PENYEMPROTAN DAN PENYERBUKAN MELALUI UDARA','Kelompok ini mencakup usaha penyemprotan dan penyerbukan melalui udara dengan pesawat udara khusus berdasarkan keadaan tertentu.',NULL,NULL,0),
	(85,'01619','JASA PENUNJANG PERTANIAN LAINNYA','Kelompok ini mencakup jasa penunjang pertanian lainnya yang belum termasuk dalam kelompok jasa penunjang pertanian di atas, seperti penyelenggaraan pengairan/penyiraman serta penyediaan alat pertanian berikut operatornya, pemeliharaan dan perawatan alat pertanian atas dasar balas jasa (fee) atau kontrak. Penyewaan khusus alat pertanian tanpa operatornya dimasukkan dalam 77305.',NULL,NULL,0),
	(86,'01621','JASA PELAYANAN KESEHATAN TERNAK','Kelompok ini mencakup usaha yang bergerak dalam bidang pelayanan kesehatan/pengobatan ternak atas dasar balas jasa (fee) atau kontrak.',NULL,NULL,0),
	(87,'01622','JASA PERKAWINAN TERNAK','Kelompok ini mencakup usaha yang bergerak dalam bidang perkawinan ternak atas dasar balas jasa (fee) atau kontrak, seperti inseminasi buatan, transfer embrio, pemeriksaan kebuntingan, pelayanan kuda biak.',NULL,NULL,0),
	(88,'01623','JASA PENETASAN TELUR','Kelompok ini mencakup usaha yang bergerak dalam bidang penetasan telur atas dasar balas jasa (fee) atau kontrak.',NULL,NULL,0),
	(89,'01629','JASA PENUNJANG PETERNAKAN LAINNYA','Kelompok ini mencakup usaha yang bergerak dalam jasa penunjang peternakan lainnya atas dasar balas jasa (fee) atau kontrak, seperti pencukuran bulu ternak, pemasangan dan pemberian identitas ternak, pembersihan kandang ternak, termasuk juga usaha pelayanan pencari rumput, pemeliharaan dan perawatan hewan dan penggembalaan ternak. Termasuk juga kegiatan farrier (tukang tapal kuda) dan pengebirian hewan.',NULL,NULL,0),
	(90,'01630','JASA PASCA PANEN','Kelompok ini mencakup usaha pasca panen meliputi usaha penyiapan hasil panen pertanian untuk dijual, seperti pembersihan, sortasi, pengupasan, pengeringan dengan sinar matahari dan pengepakan dari macam-macam hasil pertanian atas dasar balas jasa (fee) atau kontrak. Termasuk usaha disinfektan hasil panen, pemisahan biji kapas, penyiapan daun tembakau, penyiapan biji cokelat dan pemberian lilin pada buah- buahan.',NULL,NULL,0),
	(91,'01640','PEMILIHAN BENIH TANAMAN UNTUK PENGEMBANGBIAKAN','Kelompok ini mencakup semua kegiatan pasca panen yang ditujukan untuk meningkatkan perkembangan kualitas benih melalui pemilahan material non benih, benih berukuran terlalu kecil, benih yang rusak secara mekanik atau kerusakan benih karena serangga dan benih yang belum matang, dan juga menjaga kelembaban benih ke kondisi aman untuk penyimpanan benih. Kegiatan ini mencakup pengeringan, pembersihan, sortasi dan lainnya sampai benih dipasarkan. Pemeliharaan benih yang telah dimodifikasi juga termasuk di sini.',NULL,NULL,0),
	(92,'01711','PERBURUAN DAN PENANGKAPAN PRIMATA','Kelompok ini mencakup usaha perburuan dan penangkapan primata dalam rangka pengendalian populasi dan pelestarian. Termasuk perburuan dan penangkapan primata dengan perangkap, penangkapan primata (mati atau hidup) untuk makanan, bulu, kulit atau untuk penelitian, untuk ditempatkan dalam kebun binatang atau sebagai hewan peliharaan. Termasuk perburuan dan penangkapan primata untuk diambil organnya. Contohnya kera, monyet dan primata lainnya.',NULL,NULL,0),
	(93,'01712','PERBURUAN DAN PENANGKAPAN MAMALIA','Kelompok ini mencakup usaha perburuan dan penangkapan mamalia dalam rangka pengendalian populasi dan pelestarian. Termasuk perburuan dan penangkapan mamalia dengan perangkap, penangkapan mamalia (mati atau hidup) untuk makanan, bulu, kulit atau untuk penelitian, untuk ditempatkan dalam kebun binatang atau sebagai hewan peliharaan. Termasuk perburuan dan penangkapan mamalia untuk diambil organnya. Contohnya rusa, babi, kelinci, dan mamalia lainnya.',NULL,NULL,0),
	(94,'01713','PERBURUAN DAN PENANGKAPAN REPTIL','Kelompok ini mencakup usaha perburuan dan penangkapan reptil dalam rangka pengendalian populasi dan pelestarian. Termasuk perburuan dan penangkapan reptil dengan perangkap, penangkapan reptil (mati atau hidup) untuk makanan, bulu, kulit atau untuk penelitian, untuk ditempatkan dalam kebun binatang atau sebagai hewan peliharaan. Termasuk perburuan dan penangkapan reptil untuk diambil organnya. Contohnya buaya, ular, dan reptil lainnya.',NULL,NULL,0),
	(95,'01714','PERBURUAN DAN PENANGKAPAN BURUNG','Kelompok ini mencakup usaha perburuan dan penangkapan segala jenis burung dalam rangka pengendalian populasi dan pelestarian. Termasuk perburuan dan penangkapan burung dengan perangkap, penangkapan burung (mati atau hidup) untuk makanan, bulu, kulit atau untuk penelitian, untuk ditempatkan dalam kebun binatang atau sebagai hewan peliharaan. Termasuk perburuan dan penangkapan burung untuk diambil organnya.',NULL,NULL,0),
	(96,'01715','PERBURUAN DAN PENANGKAPAN INSEKTA','Kelompok ini mencakup usaha perburuan dan penangkapan insekta dalam rangka pengendalian populasi dan pelestarian. Termasuk perburuan dan penangkapan insekta dengan perangkap, penangkapan insekta (mati atau hidup) untuk makanan, kulit atau untuk penelitian, untuk ditempatkan dalam kebun binatang atau sebagai hewan peliharaan. Termasuk perburuan dan penangkapan insekta untuk diambil organnya. Contohnya kupu-kupu, dan insekta lainnya.',NULL,NULL,0),
	(97,'01719','PERBURUAN DAN PENANGKAPAN SATWA LIAR LAINNYA','Kelompok ini mencakup usaha perburuan dan penangkapan satwa liar lainnya dalam rangka pengendalian populasi dan pelestarian. Termasuk perburuan dan penangkapan satwa liar lainnya dengan perangkap, penangkapan satwa liar lainnya (mati atau hidup) untuk makanan, kulit atau untuk penelitian, untuk ditempatkan dalam kebun binatang atau sebagai hewan peliharaan. Termasuk perburuan dan penangkapan satwa liar lainnya untuk diambil organnya. Termasuk dalam kelompok ini adalah satwa liar yang belum tercakup dalam kelompok 01711 s.d. 01715.',NULL,NULL,0),
	(98,'01721','PENANGKARAN PRIMATA','Kelompok ini mencakup usaha penangkaran, pembesaran, pembiakan dan penelitian untuk pelestarian orang utan, beruk, bekantan, kera ekor panjang, dan primata lainnya.',NULL,NULL,0),
	(99,'01722','PENANGKARAN MAMALIA','Kelompok ini mencakup usaha penangkaran, pembesaran, pembiakan dan penelitian untuk pelestarian mamalia, seperti hariamau, badak, anoa, dan mamalia lainnya.',NULL,NULL,0),
	(100,'01723','PENANGKARAN REPTIL','Kelompok ini mencakup usaha penangkaran, pembesaran, pembiakan dan penelitian untuk pelestarian reptil, seperti komodo, buaya, dan reptil lainnya.',NULL,NULL,0),
	(101,'01724','PENANGKARAN BURUNG','Kelompok ini mencakup usaha penangkaran, pembesaran, pembiakan dan penelitian untuk pelestarian burung, seperti kakatua, cendrawasih, rangkong, dan burung lainnya.',NULL,NULL,0),
	(102,'01725','PENANGKARAN INSEKTA','Kelompok ini mencakup usaha penangkaran, pembesaran, pembiakan dan penelitian untuk pelestarian insekta, seperti kupu-kupu, lebah, dan insekta lainnya.',NULL,NULL,0),
	(103,'01726','PENANGKARAN ANGGREK','Kelompok ini mencakup usaha penangkaran, pembesaran, pembiakan dan penelitian untuk pelestarian jenis anggrek, seperti anggrek hitam, dan jenis anggrek lainnya yang dilindungi.',NULL,NULL,0),
	(104,'01727','PENANGKARAN IKAN DAN CORAL/KARANG','Kelompok ini mencakup usaha penangkaran, pembesaran, pembiakan dan penelitian untuk pelestarian berbagai jenis ikan dan coral/karang, seperti ikan arwana (super red, golden, green, banjar, jardini/payang Irian), kima, dan jenis lainnya.',NULL,NULL,0),
	(105,'01729','PENANGKARAN TUMBUHAN/SATWA LIAR LAINNYA','Kelompok ini mencakup usaha penangkaran, pembesaran, pembiakan dan penelitian untuk pelestarian tumbuhan/satwa liar lainnya, baik yang hidup di darat maupun di laut.',NULL,NULL,0),
	(106,'02111','PEMANFAATAN KAYU HUTAN TANAMAN PADA HUTAN PRODUKSI','Kelompok ini mencakup usaha pemanfaatan kayu yang meliputi penanaman atau pengayaan, pemeliharaan, pemanenan atau penebangan hasil yang berasal dari hutan tanaman pada hutan produksi. Jenis tanaman kayu kehutanan seperti jati, pinus, mahoni, sonokeling, sengon/albasia/jeunjing, jabon, akasia, ekalitus, cendana, dan tanaman kayu kehutanan lainnya.',NULL,NULL,0),
	(107,'02112','PEMANFAATAN KAYU HUTAN TANAMAN HASIL REHABILITASI PADA HUTAN PRODUKSI','Kelompok ini mencakup usaha pemanfaatan kayu yang meliputi penanaman atau pengayaan, pemeliharaan, pemanenan atau penebangan hasil yang berasal dari hutan tanaman yang dibangun melalui kegiatan merehabilitasi lahan dan hutan pada hutan produksi. Jenis tanaman kayu kehutanan seperti jati, pinus, mahoni, sonokeling, sengon/albasia/jeunjing, jabon, akasia, ekalitus, cendana, dan tanaman kayu kehutanan lainnya.',NULL,NULL,0),
	(108,'02113','PEMANFAATAN KAYU HUTAN TANAMAN RAKYAT','Kelompok ini mencakup usaha pemanfaatan kayu yang meliputi penanaman atau pengayaan, pemeliharaan, pemanenan atau penebangan hasil yang berasal dari hutan tanaman rakyat yang dibangun oleh kelompok masyarakat untuk meningkatkan potensi dan kualitas hutan produksi dengan menerapkan silvikultur dalam rangka menjamin kelestarian sumber daya hutan. Jenis tanaman kayu kehutanan seperti jati, pinus, mahoni, sonokeling, sengon/albasia/jeunjing, jabon, akasia, ekalitus, cendana, dan tanaman kayu kehutanan lainnya.',NULL,NULL,0),
	(109,'02119','PEMANFAATAN KAYU HUTAN TANAMAN LAINNYA','Kelompok ini mencakup usaha pemanfaatan hasil hutan kayu yang berasal dari hutan tanaman lainnya yang tidak termasuk dalam kelompok diatas yang merupakan hasil inovasi pemanfaatan hasil hutan tanaman. Contoh hutan rakyat seperti tanaman kehutanan yang dikelola oleh masyarakat yang berada di luar hutan.',NULL,NULL,0),
	(110,'02121','PEMANFAATAN KAYU HUTAN ALAM','Kelompok ini mencakup usaha pemanfaatan hutan alam melalui kegiatan pemanenan atau penebangan dengan batas diameter, pengayaan, dan pemeliharaan. Kegiatan pemanenan/penebangan/pengayaan/penanaman dilakukan terhadap jenis-jenis pohon yang dikelompokan ke dalam kelompok jenis meranti, kelompok rimba campuran, kelompok kayu indah dan kelompok kayu jenis lainnya yang berlaku di seluruh indonesia, tidak termasuk jenis kayu yang dilindungi.',NULL,NULL,0),
	(111,'02122','PEMANFAATAN KAYU HASIL RESTORASI EKOSISTEM PADA HUTAN ALAM','Kelompok ini mencakup usaha untuk membangun kawasan dalam hutan alam yang memiliki ekosistem penting sehingga dapat dipertahankan fungsi dan keterwakilannya melalui kegiatan pemeliharaan, perlindungan dan pemulihan ekosistem hutan termasuk penanaman, pengayaan, penjarangan, penangkaran satwa, pelepasliaran flora dan fauna untuk mengembalikan unsur hayati (flora dan fauna) dan unsur non hayati (tanah, iklim, dan tofografi) pada suatu kawasan kepada jenis yang asli, sehingga tercapai keseimbangan ekosistemnya, serta usaha pemanfaatan kayu hasil restorasi ekosistem yang sudah tercapai keseimbangan ekosistemnya.',NULL,NULL,0),
	(112,'02130','PEMANFAATAN HASIL HUTAN BUKAN KAYU','Kelompok ini mencakup pemanfaatan hasil hutan bukan kayu yang meliputi penanaman atau pengayaan, pemeliharaan, pemanenan atau penebangan hasil hutan bukan kayu (rotan, getah pinus, daun kayu putih, bambu, damar, gaharu, dan lainnya).',NULL,NULL,0),
	(113,'02140','PENGUSAHAAN PERBENIHAN TANAMAN KEHUTANAN','Kelompok ini mencakup usaha pengadaan benih dan/atau pembuatan bibit tanaman hutan dan pemeliharaannya sampai dengan umur tertentu untuk ditanam dengan tujuan komersil. Jenis benih/bibit tanaman kayu kehutanan seperti jati, pinus, mahoni, sonokeling, sengon/albasia/jeunjing, jabon, akasia, ekalitus, cendana, dan tanaman kayu kehutanan lainnya.',NULL,NULL,0),
	(114,'02201','PEMANENAN KAYU','Kelompok ini mencakup kegiatan poduksi kayu gelondongan untuk industri pengolahan dan produksi kayu gelondongan digunakan dalam bentuk yang tidak diolah, seperti pit-props, tonggak pagar dan tiang listrik atau telepon.',NULL,NULL,0),
	(115,'02202','USAHA PEMUNGUTAN KAYU','Kelompok ini mencakup usaha pemungutan hasil kayu dengan batas diameter tertentu yang terpisah dari usaha pengusahaan kayu. Termasuk kegiatan pengumpulan dan produksi kayu bakar.',NULL,NULL,0),
	(116,'02209','USAHA KEHUTANAN LAINNYA','Kelompok ini mencakup usaha di bidang kehutanan yang tidak tercakup dalam kelompok manapun, seperti produksi arang di hutan dengan cara tradisional.',NULL,NULL,0),
	(117,'02301','PEMUNGUTAN GETAH KARET','Kelompok ini mencakup usaha pemungutan getah tanaman karet dan tanaman penghasil getah lainnya, seperti pemungutan getah tanaman karet hutan, getah perca, jelutung dan kemenyan.',NULL,NULL,0),
	(118,'02302','PEMUNGUTAN ROTAN','Kelompok ini mencakup usaha pemungutan jenis tanaman rotan.',NULL,NULL,0),
	(119,'02303','PEMUNGUTAN GETAH PINUS','Kelompok ini mencakup usaha pemungutan getah pinus.',NULL,NULL,0),
	(120,'02304','PEMUNGUTAN DAUN KAYU PUTIH','Kelompok ini mencakup usaha pemungutan daun tanaman kayu putih.',NULL,NULL,0),
	(121,'02305','PEMUNGUTAN KOKON/KEPOMPONG ULAT SUTERA','Kelompok ini mencakup usaha pemungutan kokon/kepompong ulat sutera.',NULL,NULL,0),
	(122,'02306','PEMUNGUTAN DAMAR','Kelompok ini mencakup usaha pemungutan damar.',NULL,NULL,0),
	(123,'02307','PEMUNGUTAN MADU','Kelompok ini mencakup usaha pemungutan madu.',NULL,NULL,0),
	(124,'02308','PEMUNGUTAN BAMBU','Kelompok ini mencakup usaha pemungutan bambu.',NULL,NULL,0),
	(125,'02309','PEMUNGUTAN BUKAN KAYU LAINNYA','Kelompok ini mencakup usaha pemungutan hasil bukan kayu yang tidak dicakup dalam 02301 s.d. 02308 yang terpisah dari usaha pengusahaan hasil hutan bukan kayu, misalnya pemungutan gumpalan shellak, jernang, daun ekaliptus, kulit kayu lawang dan kayu manis, kenanga, daun/kulit/ranting cendana, kopal, pandan, purun, jamur, berry, lumut, dan lainnya. Termasuk pemungutan hasil hutan bukan kayu seperti gaharu dan sarang burung walet.',NULL,NULL,0),
	(126,'02401','JASA PENGGUNAAN KAWASAN HUTAN DI LUAR SEKTOR KEHUTANAN','Kelompok ini mencakup jasa kehutanan bidang penggunaan kawasan hutan/planologi dalam rangka penyiapan data dasar pengelolaan hutan di kawasan untuk usaha di luar sektor kehutanan.',NULL,NULL,0),
	(127,'02402','JASA PERLINDUNGAN HUTAN DAN KONSERVASI ALAM','Kelompok ini mencakup usaha dalam rangka menunjang Pemantauan Informasi Lingkungan (PIL)/ ANDAL, Usaha Kelola Lingkungan (UKL), Usaha Pemantauan Lingkungan (UPL). Termasuk didalamnya usaha pemanfaatan jasa penyimpanan dan penyerapan karbon.',NULL,NULL,0),
	(128,'02403','JASA REHABILITASI DAN RESTORASI KEHUTANAN SOSIAL','Kelompok ini mencakup usaha dalam rangka rehabilitasi lahan dan kehutanan sosial baik di dalam maupun kawasan hutan.',NULL,NULL,0),
	(129,'02404','JASA KEHUTANAN BIDANG PERENCANAAN KEHUTANAN','Kelompok ini mencakup usaha jasa kehutanan dalam rangka penyiapan data dasar seperti inventarisasi hutan, pengukuran dan penataan batas, dan penafsiran citra indra jarak jauh.',NULL,NULL,0),
	(130,'02409','JASA PENUNJANG KEHUTANAN LAINNYA','Kelompok ini mencakup usaha jasa di bidang kehutanan lainnya yang tidak tercakup dalam kelompok 02401 s.d. 02404, seperti kegiatan pengevaluasian kayu, pemadaman kebakaran hutan dan pengendalian hama dan jasa penebangan kayu, serta jasa pengangkutan kayu di dalam hutan.',NULL,NULL,0),
	(131,'03111','PENANGKAPAN PISCES/IKAN BERSIRIP DI LAUT','Kelompok ini mencakup usaha atau kegiatan penangkapan pisces/ikan bersirip dengan alat penangkapan ikan: jaring lingkar (surrounding nets) termasuk pukat cincin pelagis besar dengan satu kapal, pukat cincin pelagis kecil dengan satu kapal, pukat cincin teri, pukat cincin pelagis besar dengan dua kapal, pukat cincin pelagis kecil dengan dua kapal, yang menangkap jenis ikan cakalang, madidihang, tongkol krai, tongkol komo, pelagis besar lainya, layang, kembung, selar, lemuru, kembang, pelagis kecil lainnya, dll); pukat tarik (seine nets) termasuk pukat tarik pantai (beach seine), dogol (danish seine), payang, cantrang, yang menangkap jenis ikan kakap putih, kakap merah, kuwe, manyung, cucut, kerapu, pari, kurisi, remang, layang, kembung, selar, lemuru, tembang, siro, dll; pukat hela (trawls) berupa pukat hela dasar udang, yang menangkap jenis ikan pelagis kecil, pelagis besar, demersal, dll; jaring angkat (lift nets) termasuk anco (portable lift net), bagan berperahu, bouke ami, bagan tancap, yang menangkap jenis ikan tongkol krai, tongkol komo, madidihang, cakalang, kembung, pelagis besar lainnya, pelagis kecil lainnya, dll; alat yang dijatuhkan atau ditebarkan (falling gears), termasuk jala jatuh berkapal (cast net) dan jala tebar (falling gear not specified) menangkap jenis ikan beronang, biji nangka, pelagis kecil lainya, dll; jaring insang (gillnets and entangling nets), termasuk jaring insang tetap (set gillnet (anchored)), jaring insang hanyut (drift gillnet), jaring insang lingkar (encircling gillnets), jaring insang berpancang (fixed gillnet (on stakes)), jaring insang berlapis (trammel net), combined gillnets-trammel net, yang menangkap jenis ikan cucut, pari, demersal lainya, cakalang, tongkol krai, tongkol komo, madidihang, tenggiri bulat, cucut, pelagis besar lainnya, pelagis kecil lainnya, dll; perangkap (traps), termasuk set net, bubu (pot), bubu bersayap (fyke net), pukat labuh (long bag set net), togo, ambai, jermal, pengerih, sero, yang menangkap jenis ikan Belanak, kuwe, julung-julung, pelagis kecil lainnya dll; pancing (hooks and lines), termasuk pancing ulur nontuna, pancing ulur tuna, pancing berjoran, huhate, pancing cumi, pancing cumi mekanis (squid jigging), huhate mekanis, rawai dasar (set longline), rawai tuna, tonda, pancing layang-layang, yang menangkap jenis ikan cakalang, tongkol krai, tongkol komo, tuna lainnya, tenggiri, pelagis besar lainnya, ikan tuna mata besar, madidihang, albacora, marlin, meka, kakap putih, kakap merah, kuwe, manyung, cucut, kerapu, pari, kurisi, remang, demersal lainya, karang lainnya, kerapu, kurisi, lencam, dll; alat penangkapan ikan lainnya (miscellaneous gears), termasuk tombak (harpoon), ladung, panah, pukat dorong (pushnet), muro ami (drive-in net), seser, yang menangkap jenis ikan ekor kuning, pisang-pisang, kapas-kapas, ikan karang dan ikan demersal, dll di laut, muara sungai, laguna dan tempat lain yang dipengaruhi pasang surut. Termasuk pula kegiatan kapal yang digunakan baik untuk menangkap ikan maupun pengolahan dan pengawetan ikan.',NULL,NULL,0),
	(132,'03112','PENANGKAPAN CRUSTACEA DI LAUT','Kelompok ini mencakup usaha atau kegiatan penangkapan crustacea dengan alat penangkapan ikan: pukat hela (trawls) berupa pukat hela dasar udang; pukat tarik (seine nets), termasuk pukat tarik pantai, dogol (danish seine), payang, cantrang; penggaruk (dredges), berupa penggaruk tanpa kapal (hand dredge); jaring angkat (lift nets), termasuk bagan berperahu, bagan tancap; alat yang dijatuhkan atau ditebarkan (falling gears), berupa jala tebar (falling gear not specified); jaring insang (gillnets and entangling nets), termasuk jaring insang berpancang (fixed gillnet (on stakes)), jaring insang tetap (set gillnet (anchored)); perangkap (traps), termasuk bubu (pot), pukat labuh (long bag set net), ambai, pengerih; pancing (hooks and lines), termasuk pancing berjoran, pancing ulur; alat penangkap ikan lainnya (miscellaneous gears), termasuk seser, ladung, dll yang menangkap jenis ikan udang (udang windu, udang putih, udang dogol), lobster dan crustacea laut lainnya (kepiting dan anjungan) di laut, muara sungai, laguna dan tempat lain yang dipengaruhi pasang surut.',NULL,NULL,0),
	(133,'03113','PENANGKAPAN MOLLUSCA DI LAUT','Kelompok ini mencakup usaha atau kegiatan penangkapan mollusca dengan alat penangkapan ikan: pancing (hooks and lines) termasuk pancing cumi, yang menangkap jenis ikan cumi-cumi, sotong, gurita, dll; alat yang dijatuhkan atau ditebarkan (falling gear), termasuk Jala jatuh berkapal, yang menangkap jenis ikan cumi-cumi, sotong, gurita, dll; jaring angkat (lift nets), termasuk bouke ami, yang menangkap jenis ikan cumi-cumi, dll; penggaruk (dredges), yang menangkap jenis kekerangan, seperti remis, simping, kerang darah, kerang hijau dan tiram, di laut, muara sungai, laguna dan tempat lain yang dipengaruhi pasang surut.',NULL,NULL,0),
	(134,'03114','PENANGKAPAN/PENGAMBILAN TUMBUHAN AIR DI LAUT','Kelompok ini mencakup usaha atau kegiatan penangkapan/pengambilan semua jenis tumbuhan air, seperti algae, rumput laut, ganggang laut, dan tumbuhan hias di laut, muara sungai, laguna dan tempat lain yang dipengaruhi pasang surut dengan alat penangkapan ikan penggaruk (dredges) berupa penggaruk tanpa kapal (hand dredge).',NULL,NULL,0),
	(135,'03115','PENANGKAPAN/PENGAMBILAN INDUK/BENIH IKAN DI LAUT','Kelompok ini mencakup usaha atau kegiatan penangkapan/pengambilan induk/benih ikan seperti induk/benih ikan bersirip, induk/benih udang, induk/benih kerang, induk/benih kepiting, dan induk/benih biota lainnya di laut, muara sungai, laguna dan tempat lain yang dipengaruhi pasang surut dengan alat penangkapan ikan : perangkap (traps) berupa bubu (induk/benih ikan); alat penangkapan ikan lainnya (miscellaneous gears) berupa seser (induk/benih ikan); penggaruk (dregdes) (induk/benih kerang, induk/benih kepiting, dan induk/benih biota lainnya); jaring angkat (lift nets) berupa anco (induk/benih ikan).',NULL,NULL,0),
	(136,'03116','PENANGKAPAN ECHINODERMATA DI LAUT','Kelompok ini mencakup usaha atau kegiatan penangkapan/pengambilan jenis hewan laut seperti bintang laut, teripang, bulu babi, lili laut , dan lainnya, dengan alat penangkapan ikan penggaruk (dredges) termasuk penggaruk tanpa kapal dan alat penangkapan ikan lainnya (miscellaneous gears) termasuk tombak, ladung, dll di laut, muara sungai, laguna, dan tempat lain yang dipengaruhi pasang surut.',NULL,NULL,0),
	(137,'03117','PENANGKAPAN COELENTERATA DI LAUT','Kelompok ini mencakup usaha atau kegiatan penangkapan ikan dengan alat penangkapan ikan anemon laut, karang laut, terumbu karang, polip, ubur-ubur, dan lainnya dengan alat penangkapan ikan jaring lingkar (surrounding nets), termasuk pukat cincin pelagis besar dengan satu kapal; jaring angkat (lift nets), termasuk bagan tancap (shore-operated stationary lift net); penggaruk (dredges) termasuk penggaruk tanpa kapal (hand dredge); alat yang ditebarkan (falling gears), termasuk jala tebar; jaring insang (gillnets and endtangling nets), termasuk jaring insang berpancang; perangkap (traps), termasuk pukat labuh; alat penangkapan ikan lainnya (miscellaneous gears), termasuk ladung, seser dll di laut, muara sungai, laguna, dan tempat lain yang dipengaruhi pasang surut.',NULL,NULL,0),
	(138,'03118','PENANGKAPAN IKAN HIAS LAUT','Kelompok ini mencakup usaha atau kegiatan penangkapan/pengambilan ikan hias laut, seperti kuda laut (hippocampus), angel fish, clown fish, lion fish, ikan sekar taji layar lurik, ikan buntel pasir, ikan kalong, dan ikan hias lainnya di laut, muara sungai, laguna, dan tempat lain yang dipengaruhi pasang surut dengan alat penangkapan ikan bubu; alat penangkapan ikan lainnya (miscellaneous gears), termasuk seser dan panah; penggaruk (dredges), baik penggaruk berkapal (towed dredge) atau penggaruk tanpa kapal (hand dredge).',NULL,NULL,0),
	(139,'03119','PENANGKAPAN BIOTA AIR LAINNYA DI LAUT','Kelompok ini mencakup usaha atau kegiatan penangkapan dan pengumpulan biota laut lainnya seperti cacing laut, siput laut di laut, muara sungai, laguna, dan tempat lain yang dipengaruhi pasang surut dengan alat tangkap penggaruk (dredges), baik penggaruk berkapal (towed dredge) atau penggaruk tanpa kapal (hand dredge).',NULL,NULL,0),
	(140,'03121','PENANGKAPAN PISCES/IKAN BERSIRIP DI PERAIRAN DARAT','Kelompok ini mencakup usaha atau kegiatan penangkapan pisces/ikan bersirip air tawar dengan alat penangkapan ikan: alat yang dijatuhkan atau ditebarkan (falling gears) yang meliputi jala jatuh berkapal (cast net) dan jala tebar (falling gear not specified), menangkap jenis ikan betok, sepat, bilih, depik, genggehek, kancera, kendia, lalang, mas, lukas, repang, lampan, tawes,seren, tontong tebu, tambakan, tempe, sumpit, dll; jaring angkat (lift nets) termasuk anco, menangkap jenis ikan betok, sepat rawa, berukung, depik, jelawat, kendia, lalang, lukas, parang, teri, lampan, seren, tontong tebu, tambakan, tempe, bentilak, lais, sumpit, dll; alat penangkapan ikan lainnya (miscellaneous gears), termasuk seser, menangkap jenis ikan betok, sepat siam, lalang, teri, betutu, jenis bilih, dll; pancing (hooks and lines), menangkap jenis ikan gurame, betok, sidat, baung, keting, sepat, gabus, toman, lele, berukung, hampal, lalawak, mas, nilem, parang, teri, semah tawes, betutu, silih, belida, siluk/arwana, patin, tempe, bentilak, lais, lempuk, sumpit, dll 5. perangkap (traps), termasuk bubu (pot), sero, menangkap jenis ikan sidat, gabus, mujair, nila, jelawat, bentilak, lais, ikan bersirip, dll; Jaring Insang (gillnets and entangling nets), menangkap jenis ikan baung, keting, sepat siam, gabus, mujair, nila, berukung, beunteur, bilih, depik, genggehek, hampal, jelawat, kendia, koan, lalawak, lukas, mas, nilem, parang, repang, lampan, semah, seren, tawes, totong tebu, betutu, silih, patin, tempe, lempuk, sumpit, dll di perairan darat, seperti di danau, sungai, waduk, rawa dan genangan air lainnya.',NULL,NULL,0),
	(141,'03122','PENANGKAPAN CRUSTACEA DI PERAIRAN DARAT','Kelompok ini mencakup usaha atau kegiatan penangkapan crustacea air tawar, seperti udang grago (Athya spp.), udang galah (Macrobrachium rosenbergii), udang tawar (Palaemon spp), dll dengan alat penangkapan ikan: alat yang di jatuhkan atau ditebarkan (falling gears), meliputi jala jatuh berkapal (cast net) dan jala tebar (falling gear not specified); perangkap (traps), termasuk bubu, jermal, pengerih; alat penangkapan ikan lainnya (miscleeaneous gears) termasuk seser, dll; di perairan darat, seperti di danau, sungai, waduk, rawa dan genangan air lainnya.',NULL,NULL,0),
	(142,'03123','PENANGKAPAN MOLLUSCA DI PERAIRAN DARAT','Kelompok ini mencakup usaha atau kegiatan penangkapan mollusca air tawar seperti remis (Meretrix spp.), siput (Philalanka sp) dll dengan alat penangkapan ikan penggaruk (dredges) di perairan darat, seperti di danau, sungai, waduk, rawa dan genangan air lainnya.',NULL,NULL,0),
	(143,'03124','PENANGKAPAN/PENGAMBILAN TUMBUHAN AIR DI PERAIRAN DARAT','Kelompok ini mencakup usaha atau kegiatan penangkapan/pengambilan semua jenis tumbuhan air, seperti ganggang, eceng gondok, lumut, dan tumbuhan hias di perairan darat seperti di danau, sungai, waduk, rawa, dan genangan air lainnya dengan alat penangkapana ikan penggaruk (dredges).',NULL,NULL,0),
	(144,'03125','PENANGKAPAN/PENGAMBILAN INDUK/BENIH IKAN DI PERAIRAN DARAT','Kelompok ini mencakup usaha atau kegiatan penangkapan induk/benih ikan sidat, arwana, baung dengan alat penangkapan ikan : pancing (hooks and lines) termasuk pancing berjoran; perangkap (traps) termasuk bubu (pot); jaring angkat (lift nets) termasuk anco (portable lift net), dan; alat penangkapan ikan lainnya (miscellaneous gears) termasuk seser: di perairan darat seperti di danau, sungai, waduk, rawa, dan genangan air lainnya.',NULL,NULL,0),
	(145,'03126','PENANGKAPAN IKAN HIAS DI PERAIRAN DARAT','Kelompok ini mencakup usaha atau kegiatan penangkapan ikan hias di perairan darat seperti di danau, sungai, waduk, rawa, dan genangan air lainnya, seperti ikan pelangi dan botia dengan alat penangkapan ikan lainnya (miscellaneous gears) termasuk seser, perangkat (traps) termasuk bubu (pot).',NULL,NULL,0),
	(146,'03129','PENANGKAPAN BIOTA AIR LAINNYA DI PERAIRAN DARAT','Kelompok ini mencakup usaha atau kegiatan penangkapan/ pengambilan hewan atau biota air tawar seperti katak, bulus, labi-labi, belut, dan lainnya di perairan darat seperti di danau, sungai, waduk, rawa, dan genangan air lainnya dengan alat penangkapan ikan : perangkap (traps) termasuk bubu (pot); penggaruk (dredges); dan alat penangkapan ikan lainnya (miscellaneous gears) termasuk seser.',NULL,NULL,0),
	(147,'03131','JASA SARANA PRODUKSI PENANGKAPAN IKAN DI LAUT','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha penyiapan sarana penangkapan ikan dan biota laut yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa penyediaan alat tangkap, jasa penyediaan armada penangkapan, jasa rumpon, jasa perbengkelan, jasa perbaikan alat tangkap, slipway/docking, dan lainnya.',NULL,NULL,0),
	(148,'03132','JASA PRODUKSI PENANGKAPAN IKAN DI LAUT','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha produksi penangkapan ikan dan biota laut yang dilakukan atas dasar balas jasa (fee) atau kontrak seperti jasa penyediaan logistik kapal, dan lainnya.',NULL,NULL,0),
	(149,'03133','JASA PASCA PANEN PENANGKAPAN IKAN DI LAUT','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha pasca panen penangkapan ikan dan biota laut yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa persiapan lelang, jasa sortasi dan gradasi, jasa uji mutu dan sebagainya.',NULL,NULL,0),
	(150,'03141','JASA SARANA PRODUKSI PENANGKAPAN IKAN DI PERAIRAN DARAT','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha penyiapan sarana penangkapan ikan air tawar di perairan darat yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa pengolahan lahan, alat tangkap, jasa penyediaan logistik kapal, jasa perbengkelan, jasa perbaikan alat tangkap, dan sebagainya.',NULL,NULL,0),
	(151,'03142','JASA PRODUKSI PENANGKAPAN IKAN DI PERAIRAN DARAT','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha produksi penangkapan ikan air tawar di perairan darat yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa perubahan benih, jasa penebaran benih, jasa pengendalian jasad pengganggu, jasa pemantauan dan sebagainya.',NULL,NULL,0),
	(152,'03143','JASA PASCA PANEN PENANGKAPAN IKAN DI PERAIRAN DARAT','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha pasca panen penangkapan ikan air tawar di perairan darat yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa pemanenan, jasa persiapan lelang, jasa sortasi dan gradasi, jasa uji mutu, jasa pengeringan, jasa pemberian es, jasa pengepakan dan penyimpanan dan sebagainya.',NULL,NULL,0),
	(153,'03151','PENANGKAPAN/PENGAMBILAN IKAN BERSIRIP (PISCES) YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha atau kegiatan penangkapan jenis ikan taksa ikan bersirip (Pisces) yang dilindungi dan/atau Appendiks CITES sesuai ketentuan perlindungannya, yang hidup di perairan laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan komersial, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria, pertukaran dan pemeliharaan untuk kesenangan. Contoh ikan bersirip yang termasuk kelompok ini: Ikan Napoleon, Ikan Capungan Banggai, Ikan Hiu Lanjaman, Ikan Hiu Martil, Ikan Pari Mobula, dll. Kelompok ini tidak mencakup penangkapan untuk tujuan perdagangan jenis ikan bersirip yang dilindungi penuh, dilarang peredarannya berdasarkan regulasi nasional dan/atau tercantum dalam daftar Appendiks I CITES, seperti Ikan Arwana Merah dan Ikan Pari Gergaji.',NULL,NULL,0),
	(154,'03152','PENANGKAPAN/PENGAMBILAN CRUSTACEA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha atau kegiatan penangkapan jenis ikan taksa Crustacea yang dilindungi dan/atau Appendiks CITES sesuai ketentuan perlindungannya, yang hidup di perairan laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan komersial, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria, pertukaran dan pemeliharaan untuk kesenangan. Kelompok ini tidak mencakup penangkapan jenis ikan taksa CRUSTACEA yang dilindungi penuh, dilarang peredarannya berdasarkan regulasi nasional dan/atau tercantum dalam daftar Appendiks I CITES, seperti Tachypleus gigas, Tachypleus tridentatus dan Carcinoscorpius rotundicauda.',NULL,NULL,0),
	(155,'03153','PENANGKAPAN/PENGAMBILAN MOLLUSCA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha atau kegiatan penangkapan jenis ikan taksa Mollusca yang dilindungi dan/atau Appendiks CITES sesuai ketentuan perlindungannya, yang hidup di perairan laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan komersial, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria, pertukaran dan pemeliharaan untuk kesenangan. Contoh Mollusca yang masuk dalam kelompok ini: Tridacna spp., (Kima) dan Strombus gigas (Keong Ratu). Kelompok ini tidak mencakup penangkapan untuk tujuan perdagangan jenis ikan taksa Mollusca yang dilindungi penuh, dilarang peredarannya berdasarkan regulasi nasional dan/atau tercantum dalam daftar Appendiks I CITES, seperti: Nautilus spp., Hippopus hippopus, Hippopus porcellanus, Cassis cornuta dan Charonia tritonis.',NULL,NULL,0),
	(156,'03154','PENANGKAPAN/PENGAMBILAN COELENTERATA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pemanfaatan yang mengambil Coelenterata yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Daftar Coelenterata yang masuk dalam kelompok ini dapat mengalami perubahan sesuai dengan perubahan regulasi dan/atau keputusan Konvensi CITES. Kelompok ini tidak mencakup pengambilan jenis Coelenterata yang dilindungi penuh berdasarkan regulasi nasional, termasuk dalam daftar Appendiks I CITES dan/atau dilarang penangkapan/ pengambilannya berdasarkan kebijakan Pemerintah. Contoh: karang keras Ordo Scleractinia.',NULL,NULL,0),
	(157,'03155','PENANGKAPAN/PENGAMBILAN ECHINODERMATA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pemanfaatan yang mengambil echinodermata yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Contoh Echinodermata yang masuk dalam kelompok ini: Holothoria fuscogilva, Holothuria nobilis, dan Holothuria whitmaei. Kelompok ini tidak mencakup pengambilan jenis Echinodermata yang dilindungi penuh berdasarkan regulasi nasional, termasuk dalam daftar Appendiks I CITES dan/atau dilarang penangkapan/pengambilannya berdasarkan kebijakan Pemerintah.',NULL,NULL,0),
	(158,'03156','PENANGKAPAN/PENGAMBILAN AMPHIBIA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pemanfaatan yang mengambil Amphibia yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Contoh Amphibia yang masuk dalam kelompok ini: Amyda cartiliginea (Labi-Labi) dan Orlitia borneensis (Kura- Kura Sungai Kalimantan). Kelompok ini tidak mencakup pengambilan jenis Amphibia yang dilindungi penuh berdasarkan regulasi nasional, termasuk dalam daftar Appendiks I CITES dan/atau dilarang penangkapan/pengambilannya berdasarkan kebijakan Pemerintah.',NULL,NULL,0),
	(159,'03157','PENANGKAPAN/PENGAMBILAN REPTILIA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pemanfaatan yang mengambil reptilia yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Kelompok ini tidak mencakup pengambilan jenis reptilia yang dilindungi penuh berdasarkan regulasi nasional, termasuk dalam daftar Appendiks I CITES dan/atau dilarang penangkapan/pengambilannya berdasarkan kebijakan Pemerintah, seperti: Penyu.',NULL,NULL,0),
	(160,'03158','PENANGKAPAN/PENGAMBILAN MAMALIA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pemanfaatan yang mengambil mamalia yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Kelompok ini tidak mencakup pengambilan jenis mamalia yang dilindungi penuh berdasarkan regulasi nasional, termasuk dalam daftar Appendiks I CITES dan/atau dilarang penangkapan/pengambilannya berdasarkan kebijakan pemerintah seperti: paus, lumba-lumba, dan dugong.',NULL,NULL,0),
	(161,'03159','PENANGKAPAN/PENGAMBILAN ALGAE DAN BIOTA PERAIRAN LAINNYA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pemanfaatan yang mengambil Algae dan biota perairan lainnya yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Kelompok ini tidak mencakup pengambilan jenis Algae danbiota perairan lainnya yang dilindungi penuh berdasarkan regulasi nasional, termasuk dalam daftar Appendiks I CITES dan/atau dilarang penangkapan/pengambilannya berdasarkan kebijakan Pemerintah.',NULL,NULL,0),
	(162,'03211','PEMBESARAN PISCES/ IKAN BERSIRIP LAUT','Kelompok ini mencakup usaha atau kegiatan pemeliharaan dan pembesaran serta pemanenan pisces/ikan bersirip di laut, muara sungai, laguna, tempat lain yang dipengaruhi pasang surut dan fasilitas buatan lainnya, seperti ikan kerapu, kakap putih, cobia, bawal bintang, ikan bubara. Tidak termasuk kegiatan budidaya ikan hias air laut.',NULL,NULL,0),
	(163,'03212','PEMBENIHAN IKAN LAUT','Kelompok ini mencakup usaha pembenihan (produksi induk, telur, larva sampai dengan benih siap tebar) ikan bersirip, mollusca, crustacea, echinodermata dan biota air laut lainnya dengan media air laut, seperti benih ikan kerapu, benih kakap putih, benih bawal bintang, benih lobster, benih abalone, benih kerang mutiara, benih kerang darah, benih teripang, dan bibit rumput laut (mencakup semua jenis rumput laut). Termasuk pembibitan algae untuk menghasilkan bioenergi dan non-pangan lainnya. Tidak termasuk kegiatan pembenihan ikan hias air laut.',NULL,NULL,0),
	(164,'03213','BUDIDAYA IKAN HIAS AIR LAUT','Kelompok ini mencakup usaha atau kegiatan pembenihan, pemeliharaan, dan pembesaran serta pemanenan ikan hias air laut dengan menggunakan lahan perairan dan fasilitas buatan lainnya, seperti kuda laut, clownfish, cardinal fish, angel piyama, blue devil dan lainnya.',NULL,NULL,0),
	(165,'03214','BUDIDAYA KARANG (CORAL)','Kelompok ini mencakup usaha atau kegiatan budidaya/pemeliharaan dan pembesaran serta pemanenan karang (coral) dan pemanfaatannya, seperti pembesaran ornamental coral, pembesaran sponge, dan pembesaran karang (soft coral maupun sel). Termasuk juga kegiatan transplantasinya.',NULL,NULL,0),
	(166,'03215','PEMBESARAN MOLLUSCA LAUT','Kelompok ini mencakup usaha atau kegiatan pemeliharaan dan pembesaran serta pemanenan mollusca di laut, muara sungai, laguna, tempat lain yang dipengaruhi pasang surut dan fasilitas buatan lainnya, seperti kerang darah, kerang hijau, kerang mutiara, dan abalone.',NULL,NULL,0),
	(167,'03216','PEMBESARAN CRUSTACEA LAUT','Kelompok ini mencakup usaha atau kegiatan pemeliharaan dan pembesaran serta pemanenan crustacea di laut, muara sungai, laguna, tempat lain yang dipengaruhi pasang surut dan fasilitas buatan lainnya, seperti lobster, udang barong',NULL,NULL,0),
	(168,'03217','PEMBESARAN TUMBUHAN AIR LAUT','Kelompok ini mencakup usaha atau kegiatan pemeliharaan dan pembesaran serta pemanenan tumbuhan laut di laut, muara sungai, laguna, tempat lain yang dipengaruhi pasang surut dan fasilitas buatan lainnya, seperti rumput laut (makro algae penghasil karaginan, agar dan alginat). Termasuk pembesaran algae untuk menghasilkan bioenergi dan non-pangan lainnya.',NULL,NULL,0),
	(169,'03219','BUDIDAYA BIOTA AIR LAUT LAINNYA','Kelompok ini mencakup usaha atau kegiatan budidaya biota air laut lainnya di laut, muara sungai, laguna, tempat lain yang dipengaruhi pasang surut dan fasilitas buatan lainnya.',NULL,NULL,0),
	(170,'03221','PEMBESARAN IKAN AIR TAWAR DI KOLAM','Kelompok ini mencakup usaha atau kegiatan pemeliharaan dan pembesaran serta pemanenan ikan bersirip, mollusca, crustacea, katak dan biota air tawar lainnya seperti buaya, labi-labi, kura-kura, sidat, patin, ikan mas, nila, gurame, lele, lobster air tawar, dan udang galah di kolam tanah/kolam semen/kolam terpal. Termasuk pembesaran ikan tawar di bak, tong atau drum.',NULL,NULL,0),
	(171,'03222','PEMBESARAN IKAN AIR TAWAR DI KARAMBA JARING APUNG','Kelompok ini mencakup usaha pembesaran ikan bersirip, mollusca, crustacea, dan biota air tawar lainnya di karamba jaring apung dengan menggunakan lahan, perairan dan fasilitas buatan lainnya. Contohnya nila, patin, ikan mas, bandeng, dan lainnya.',NULL,NULL,0),
	(172,'03223','PEMBESARAN IKAN AIR TAWAR DI KARAMBA','Kelompok ini mencakup usaha pembesaran ikan bersirip, crustacea, mollusca, dan pembesaran biota air tawar lainnya di karamba dengan menggunakan lahan, perairan dan fasilitas buatan lainnya. Contohnya nila, patin, ikan mas.',NULL,NULL,0),
	(173,'03224','PEMBESARAN IKAN AIR TAWAR DI SAWAH','Kelompok ini mencakup usaha pembesaran ikan bersirip , crustacea, mollusca, dan biota air tawar lainnya di sawah. Contohnya udang galah, nila, ikan mas, lele.',NULL,NULL,0),
	(174,'03225','BUDIDAYA IKAN HIAS AIR TAWAR','Kelompok ini mencakup usaha pembenihan, pemeliharaan, pembesaran dan pemanenan ikan hias air tawar dengan menggunakan lahan, perairan dan fasilitas buatan lainnya seperti ikan diskus, botia, mas koki, mas koi, arwana, black ghost, cupang, silver dollar, palmas, rainbow, tetra, diamond tetra, barnabus fish dan manfish. Termasuk juga budidaya tanaman hias air tawar, seperti cabomba, egeria densa, cryptocoryne longicauda, anubias.',NULL,NULL,0),
	(175,'03226','PEMBENIHAN IKAN AIR TAWAR','Kelompok ini mencakup usaha atau kegiatan pembenihan (produksi induk, telur, larva sampai dengan benih siap tebar), ikan bersirip, mollusca, crustacea dan biota air tawar lainnya di air tawar. Contohnya patin, ikan mas, lele, gurame, lobster air tawar, nila, katak, dan buaya.',NULL,NULL,0),
	(176,'03227','PEMBESARAN IKAN AIR TAWAR DI KARAMBA JARING TANCAP','Kelompok ini mencakup usaha pembesaran ikan bersirip, mollusca, crustacea, dan biota air tawar lainnya di karamba jaring tancap dengan menggunakan lahan, perairan dan fasilitas buatan lainnya. Contohnya nila, patin, ikan mas, bandeng, dan lainnya.',NULL,NULL,0),
	(177,'03229','BUDIDAYA IKAN AIR TAWAR DI MEDIA LAINNYA','Kelompok ini mencakup usaha atau kegiatan budidaya biota air tawar di media lainnya, seperti bekas galian tambang dan pasir, saluran irigasi (sariban) dan lainnya. Contohnya ikan lele, patin, nila dan ikan mas.',NULL,NULL,0),
	(178,'03231','JASA SARANA PRODUKSI BUDIDAYA IKAN LAUT','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha penyiapan sarana budidaya ikan yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa pengikatan bibit rumput laut, pembuatan jaring, pelampung, pakan/alami, karamba dan jaring apung dan sebagainya.',NULL,NULL,0),
	(179,'03232','JASA PRODUKSI BUDIDAYA IKAN LAUT','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha produksi budidaya ikan yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa sortir, pemberian pakan/pakan alami, pemantauan, pengendalian lingkungan dan penyakit, dan sebagainya. Contohnya KSO (kerjasama operasional)',NULL,NULL,0),
	(180,'03233','JASA PASCA PANEN BUDIDAYA IKAN LAUT','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha pasca panen budidaya ikan yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa pemanenan, jasa sortasi dan gradasi, jasa uji mutu dan sebagainya.',NULL,NULL,0),
	(181,'03241','JASA SARANA PRODUKSI BUDIDAYA IKAN AIR TAWAR','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha penyiapan sarana budidaya ikan air tawar yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa penyediaan terpal, jaring, pakan, probiotik, vaksin, kapur, pupuk, pengolahan lahan, pembuatan kolam, karamba jaring apung, jasa penampungan hasil budidaya, dan sebagainya.',NULL,NULL,0),
	(182,'03242','JASA PRODUKSI BUDIDAYA IKAN AIR TAWAR','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha produksi budidaya ikan air tawar yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa sortasi, pemberian pakan, jasa pengendalian jasad pengganggu, jasa pemantauan dan sebagainya.',NULL,NULL,0),
	(183,'03243','JASA PASCA PANEN BUDIDAYA IKAN AIR TAWAR','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha pasca panen budidaya ikan air tawar yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa pemanenan, jasa sortasi dan gradasi, jasa uji mutu, jasa pengeringan, jasa pemberian es, jasa pengepakan dan penyimpanan, dan sebagainya.',NULL,NULL,0),
	(184,'03251','PEMBESARAN PISCES/IKAN BERSIRIP AIR PAYAU','Kelompok ini mencakup usaha atau kegiatan pembesaran pisces/ikan bersirip air payau (ikan bandeng, patin, nila, ikan mas dan kakap putih dan kerapu), di air payau dengan menggunakan lahan, perairan dan fasilitas buatan lainnya.',NULL,NULL,0),
	(185,'03252','PEMBENIHAN IKAN AIR PAYAU','Kelompok ini mencakup usaha atau kegiatan pembenihan (produksi induk, telur, larva sampai dengan benih siap tebar), ikan air payau (bandeng dan kakap putih), udang galah, udang windu, udang putih dan biota air payau lainnya (kepiting dan rumput laut/Gracilaria) di air payau dengan menggunakan lahan, perairan dan fasilitas buatan lainnya.',NULL,NULL,0),
	(186,'03253','PEMBESARAN MOLLUSCA AIR PAYAU','Kelompok ini mencakup usaha atau kegiatan pembesaran mollusca air payau dengan menggunakan lahan, perairan dan fasilitas buatan lainnya.',NULL,NULL,0),
	(187,'03254','PEMBESARAN CRUSTACEA AIR PAYAU','Kelompok ini mencakup usaha atau kegiatan pembesaran crustacea air payau seperti, udang galah, udang windu, udang putih, di air payau dengan menggunakan lahan, perairan dan fasilitas buatan lainnya.',NULL,NULL,0),
	(188,'03255','PEMBESARAN TUMBUHAN AIR PAYAU','Kelompok ini mencakup usaha atau kegiatan pembesaran tumbuhan air payau seperti rumput laut/Gracilaria dengan menggunakan lahan, perairan dan fasilitas buatan lainnya.',NULL,NULL,0),
	(189,'03259','BUDIDAYA BIOTA AIR PAYAU LAINNYA','Kelompok ini mencakup usaha atau kegiatan budaidaya biota air payau lainnya dengan menggunakan lahan, perairan dan fasilitas buatan lainnya.',NULL,NULL,0),
	(190,'03261','JASA SARANA PRODUKSI BUDIDAYA IKAN AIR PAYAU','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha penyiapan sarana budidaya ikan air payau yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa pembuatan tambak, dan sebagainya',NULL,NULL,0),
	(191,'03262','JASA PRODUKSI BUDIDAYA IKAN AIR PAYAU','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha produksi budidaya ikan air payau yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa penebaran benih, jasa pengendalian jasad pengganggu, jasa pengendalian lingkungan dan penyakit, jasa pemberian pakan, jasa pemantauan dan sebagainya.',NULL,NULL,0),
	(192,'03263','JASA PASCA PANEN BUDIDAYA IKAN AIR PAYAU','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha pasca panen budidaya ikan air payau yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa pemanenan, jasa sortasi dan gradasi, jasa uji mutu, jasa pengeringan, jasa pemberian es, jasa pengepakan dan penyimpanan, dan sebagainya.',NULL,NULL,0),
	(193,'03271','PENGEMBANGBIAKAN IKAN BERSIRIP (PISCES) YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pengembangbiakan ikan bersirip (Pisces) yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Contoh ikan bersirip yang termasuk kelompok ini: Ikan Napoleon, Ikan Capungan Banggai, Ikan Hiu Lanjaman, Ikan Hiu Martil, Ikan Pari Mobula, Kuda Laut, Ikan Arwana, dll.',NULL,NULL,0),
	(194,'03272','PENGEMBANGBIAKAN CRUSTACEA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pengembangbiakan Custacea yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Contoh Crustacea yang masuk dalam kelompok ini: Tachypleus gigas, Tachypleus tridentatus dan Carcinoscorpius rotundicauda.',NULL,NULL,0),
	(195,'03273','PENGEMBANGBIAKAN MOLLUSCA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pengembangbiakan Mollusca yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Contoh Mollusca yang masuk dalam kelompok ini: Tridacna spp., (Kima) dan Strombus gigas (Keong Ratu).',NULL,NULL,0),
	(196,'03274','PENGEMBANGBIAKAN COELENTERATA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pengembangbiakan Coelenterata yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Contoh Coelenterata yang masuk dalam kelompok ini: Antipatharia spp., Helioporidae spp., Sclerectinia spp., Tubiporidae spp., dan Milleporidae spp.',NULL,NULL,0),
	(197,'03275','PENGEMBANGBIAKAN ECHINODERMATA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pengembangbiakan Echinodermata yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Contoh Ceolenterata yang masuk dalam kelompok ini: Holothoria fuscogilva., Holothuria nobilis., dan Holothoria whitmaei.',NULL,NULL,0),
	(198,'03276','PENGEMBANGBIAKAN AMPHIBIA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pengembangbiakan Amphibia yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran.',NULL,NULL,0),
	(199,'03277','PENGEMBANGBIAKAN REPTILIA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pengembangbiakan Reptilia yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Contoh Reptilia yang masuk dalam kelompok ini: Amyda cartilaginea, Chitra chitra, dan Carettochelys insculpta.',NULL,NULL,0),
	(200,'03278','PENGEMBANGBIAKAN MAMALIA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pengembangbiakan mamalia yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Contoh mamalia yang masuk dalam kelompok ini: lumba-lumba.',NULL,NULL,0),
	(201,'03279','PENGEMBANGBIAKAN ALGAE DAN BIOTA PERAIRAN LAINNYA YANG DILINDUNGI DAN/ATAU TERMASUK DALAM APPENDIKS CITES','Kelompok ini mencakup usaha pengembangbiakan Algae dan biota perairan lainnya yang dilindungi dan/atau Appendiks CITES terbatas diluar ketentuan perlindungannya dan/atau yang dibatasi pemanfaatannya sesuai ketentuan konvensi internasional yang diratifikasi yang hidup di habitat laut, perairan tawar dan perairan payau untuk kegiatan penelitian dan pengembangan, pengembangbiakan, perdagangan dalam negeri, perdagangan luar negeri, aquaria dan pertukaran. Pertambangan dan Penggalian',NULL,NULL,0),
	(202,'05100','PERTAMBANGAN BATU BARA','Kelompok ini mencakup usaha operasi pertambangan, pengeboran berbagai kualitas batu bara seperti antrasit, bituminous dan subbitominous baik pertambangan di permukaan tanah atau bawah tanah, termasuk pertambangan dengan cara pencairan (liquefaction). Operasi pertambangan tersebut meliputi penggalian, penghancuran, pencucian, penyaringan dan pencampuran serta pemadatan untuk meningkatkan kualitas atau memudahkan pengangkutan dan penyimpanan/penampungan. Termasuk pencarian batu bara dari kumpulan tepung bara (culm bank).',NULL,NULL,0),
	(203,'05200','PERTAMBANGAN LIGNIT','Kelompok ini mencakup usaha operasi pertambangan, pengeboran berbagai kualitas lignit, seperti pertambangan lignit di permukaan tanah atau bawah tanah, termasuk pertambangan dengan cara pencairan (liquefaction). Operasi pertambangan tersebut meliputi penggalian, penghancuran, pencucian, penyaringan dan pencampuran serta pemadatan lignit untuk meningkatkan kualitas dan memudahkan pengangkutan dan penyimpanan/penampungan.',NULL,NULL,0),
	(204,'06100','PERTAMBANGAN MINYAK BUMI','Kelompok ini mencakup usaha atau kegiatan pertambangan minyak bumi mentah termasuk usaha pencarian kandungan minyak bumi, pengeboran, penambangan, pemisahan serta penampungan, produksi minyak bumi mentah kondensat, pemrosesan untuk menghasilkan minyak mentah dengan cara penampungan, penyaringan, pengeringan, stabilisasi dan lain-lain. Hasil pertambangan minyak bumi antara lain minyak mentah atau crude oil dan kondensat. Kelompok ini juga mencakup usaha operasi penambangan pasir bituminous atau oil shale (serpihan minyak) dan pasir aspal. Kegiatan pertambangan tersebut meliputi penggalian, pengeboran, penghancuran, pencucian, penyaringan dan pencampuran serta penampungan. Termasuk kegiatan produksi minyak bumi mentah dari serpihan minyak dan pasir bituminous jika terkait dengan pertambangannya. Pengolahan lanjut dari hasil minyak bumi dimasukkan dalam kelompok 19211.',NULL,NULL,0),
	(205,'06201','PERTAMBANGAN GAS ALAM','Kelompok ini mencakup usaha pencarian kandungan gas alam, pengeboran, penambangan, pemisahan serta penampungan. Hasil pertambangan gas alam antara lain gas alam. Pencairan gas alam menjadi LNG sampai ke pengapalannya masih termasuk kegiatan pertambangan. Termasuk kegiatan CBM (Coalbed Methane).',NULL,NULL,0),
	(206,'06202','PENGUSAHAAN TENAGA PANAS BUMI','Kelompok ini mencakup usaha pencarian dan pengeboran tenaga panas bumi termasuk lokasi di kawasan hutan. Termasuk kegiatan lain yang berhubungan dengan pengusahaan tenaga panas bumi sampai ke tempat pemanfaatannya. Kegiatan pengubahan tenaga panas bumi menjadi tenaga listrik termasuk golongan pokok 35.',NULL,NULL,0),
	(207,'07101','PERTAMBANGAN PASIR BESI','Kelompok ini mencakup usaha pertambangan pasir besi. Termasuk kegiatan sortasi, pemisahan, dan pembersihannya.',NULL,NULL,0),
	(208,'07102','PERTAMBANGAN BIJIH BESI','Kelompok ini mencakup usaha pertambangan bijih besi termasuk kegiatan peningkatan mutu dan aglomerasi bijih besi serta konsentratnya.',NULL,NULL,0),
	(209,'07210','PERTAMBANGAN BIJIH URANIUM DAN TORIUM','Kelompok ini mencakup usaha pertambangan bijih uranium dan torium. Termasuk kegiatan pengkonsentratan uranium dan torium dan produksi yellow cake.',NULL,NULL,0),
	(210,'07291','PERTAMBANGAN BIJIH TIMAH','Kelompok ini mencakup usaha pertambangan bijih timah.',NULL,NULL,0),
	(211,'07292','PERTAMBANGAN BIJIH TIMAH HITAM','Kelompok ini mencakup usaha pertambangan bijih timah hitam.',NULL,NULL,0),
	(212,'07293','PERTAMBANGAN BIJIH BAUKSIT','Kelompok ini mencakup usaha pertambangan dan penampungan bijih bauksit.',NULL,NULL,0),
	(213,'07294','PERTAMBANGAN BIJIH TEMBAGA','Kelompok ini mencakup usaha pertambangan bijih tembaga, yang terdiri dari kalkosit serta batuan berupa campuran monticellit dan skarnyakut.',NULL,NULL,0),
	(214,'07295','PERTAMBANGAN BIJIH NIKEL','Kelompok ini mencakup usaha pertambangan bijih nikel.',NULL,NULL,0),
	(215,'07296','PERTAMBANGAN BIJIH MANGAN','Kelompok ini mencakup usaha pertambangan bijih mangan.',NULL,NULL,0),
	(216,'07299','PERTAMBANGAN BAHAN GALIAN LAINNYA YANG TIDAK MENGANDUNG BIJIH BESI','Kelompok ini mencakup usaha pertambangan bahan galian lainnya yang tidak mengandung bijih besi yang belum termasuk kelompok 07291 s.d. 07296, seperti bijih seng platinum dan silicon, serta litium, berilium, magnesium, kalium, kalsium, bismuth, molibdenum, raksa, wolfram, titanium, vanadium, kromit, antimoni, kobalt, tantalum, cadmium, galium, indium, yitrium, magnetit, niobium, zirkonium, ilmenit, khrom, cesium, niobium, hafnium, scandium, ruthenium, selenium, telluride, stronium, germanium, zenotin, dan sejenisnya.',NULL,NULL,0),
	(217,'07301','PERTAMBANGAN EMAS DAN PERAK','Kelompok ini mencakup usaha pertambangan, pembersihan, dan pemisahan bijih emas dan perak.',NULL,NULL,0),
	(218,'07309','PERTAMBANGAN BIJIH LOGAM MULIA LAINNYA','Kelompok ini mencakup usaha pertambangan, dan pembersihan bijih logam mulia lainnya, selain bijih logam emas dan perak, seperti bijih platina.',NULL,NULL,0),
	(219,'08101','PENGGALIAN BATU HIAS DAN BATU BANGUNAN','Kelompok ini mencakup usaha penggalian batu hias dan batu bangunan seperti batu pualam atau marmer, batu andesit (batu gajah, base course), paras, obsidian, dan granit. Termasuk disini kegiatan pemecahan, pemisahan dan pembersihannya.',NULL,NULL,0),
	(220,'08102','PENGGALIAN BATU KAPUR/GAMPING','Kelompok ini mencakup usaha penggalian batu kapur atau gamping. Termasuk disini kegiatan pemecahan, penghancuran, penyaringan dan penghalusannya.',NULL,NULL,0),
	(221,'08103','PENGGALIAN KERIKIL/SIRTU','Kelompok ini mencakup usaha penggalian, pembersihan dan pemisahan kerikil. Hasil dari penggalian kerikil antara lain batu pasir, bongkah keras dan pasir kerikil.',NULL,NULL,0),
	(222,'08104','PENGGALIAN PASIR','Kelompok ini mencakup usaha penggalian, pembersihan dan pemisahan pasir. Hasil dari penggalian pasir berupa pasir beton, pasir pasang (sedikit mengandung tanah), pasir uruk (banyak mengandung tanah) dan lainnya.',NULL,NULL,0),
	(223,'08105','PENGGALIAN TANAH DAN TANAH LIAT','Kelompok ini mencakup usaha penggalian tanah dan tanah liat. Kegiatan pembentukan, penghancuran dan penggilingan tanah dan tanah liat dimasukkan dalam kelompok ini. Hasil dari penggalian tanah dan tanah liat/lempung antara lain kaolin (china clay), ball clay (firing clay), abu bumi, serpih dan tanah urug.',NULL,NULL,0),
	(224,'08106','PENGGALIAN GIPS','Kelompok ini mencakup usaha penggalian gips. Termasuk disini kegiatan pembersihan, dan penghalusannya.',NULL,NULL,0),
	(225,'08107','PENGGALIAN TRAS','Kelompok ini mencakup usaha penggalian tras (batuan gunung api yang mengalami perubahan kimia karena pelapukan dan kondisi air bawah tanah). Termasuk disini kegiatan pembersihannya.',NULL,NULL,0),
	(226,'08108','PENGGALIAN BATU APUNG','Kelompok ini mencakup usaha penggalian batu apung (jenis batuan yang berwarna terang, mengandung buih yang terbuat dari gelembung berdinding gelas, dan biasanya disebut juga sebagai batuan gelas vulkanik silikat). Termasuk disini kegiatan pembersihannya.',NULL,NULL,0),
	(227,'08109','PENGGALIAN BATU, PASIR DAN TANAH LIAT LAINNYA','Kelompok ini mencakup usaha penggalian batu, pasir dan tanah liat lainnya, yang tidak terklasifikasikan di kelompok 08101 - 08108. Kegiatan penggalian yang masuk dalam kelompok ini seperti penggalian diorit, basalt, breksi, dan lainnya. Termasuk disini kegiatan pemecahan, penghancuran, pemisahan, penyaringan, dan penghalusannya.',NULL,NULL,0),
	(228,'08911','PERTAMBANGAN BELERANG','Kelompok ini mencakup usaha pertambangan bijih belerang. Termasuk juga kegiatan penghancuran, dan pembersihan terhadap mineral belerang. Pengolahan lanjutan dari mineral belerang dimasukkan dalam kelompok 20114.',NULL,NULL,0),
	(229,'08912','PERTAMBANGAN FOSFAT','Kelompok ini mencakup usaha pertambangan bahan galian fosfat. Termasuk disini kegiatan sortasi, penghancuran, pembersihan dan peningkatan kadar bahan galian fosfat.',NULL,NULL,0),
	(230,'08913','PERTAMBANGAN NITRAT','Kelompok ini mencakup usaha pertambangan bahan galian nitrat. Termasuk disini kegiatan pembersihan, pemecahan, dan sortasi dengan cara lain terhadap bahan galian nitrat.',NULL,NULL,0),
	(231,'08914','PERTAMBANGAN YODIUM','Kelompok ini mencakup usaha pertambangan ekstraksi air tanah yang mengandung yodium. Termasuk disini kegiatan distilasi dari ekstraksi mineral tersebut.',NULL,NULL,0),
	(232,'08915','PERTAMBANGAN POTASH (KALIUM KARBONAT)','Kelompok ini mencakup usaha pertambangan potash dalam bentuk garam, feldpar dan leusit analeum. Termasuk disini kegiatan penghancuran dan pembersihan terhadap mineral tersebut.',NULL,NULL,0),
	(233,'08919','PERTAMBANGAN MINERAL, BAHAN KIMIA DAN BAHAN PUPUK LAINNYA','Kelompok ini mencakup usaha pertambangan mineral bahan kimia dan bahan pupuk lainnya yang belum tercakup dalam kelompok 08911 s.d. 08915. Misalnya pertambangan barium sulfat alam dan karbonat (barite dan witherit), borat alam, magnesium sulfat alam (kiserit), pertambangan earth coulor, flour, bentonite, dolomit, magnesit, phiroplit, tawas, diatomea, dan mineral lain yang utamanya sebagai bahan kimia dan pertambangan guano (bahan pupuk dari kotoran burung atau kelelawar). Termasuk disini kegiatan pembersihan, pemisahan dan sortasi.',NULL,NULL,0),
	(234,'08920','EKSTRAKSI TANAH GEMUK (PEAT)','Kelompok ini mencakup usaha operasi ekstraksi dan penggalian tanah gemuk, aglomerasi tanah gemuk dan pencampuran tanah gemuk (peat) untuk meningkatkan kualitas atau memudahkan pengangkutan atau penyimpanan. Operasi ekstraksi tersebut meliputi penggalian, penghancuran, pencucian, penyaringan, serta penampungannya.',NULL,NULL,0),
	(235,'08930','EKSTRAKSI GARAM','Kelompok ini mencakup usaha ekstraksi garam yaitu pengambilan garam dari bawah tanah termasuk dengan pelarutan dan pemompaan, serta produksi garam dengan penguapan air laut atau air garam lainnya di tambak/empang/media lainnya, dan penghancuran, pemisahan dan penyulingan garam oleh petani garam.',NULL,NULL,0),
	(236,'08991','PERTAMBANGAN BATU MULIA','Kelompok ini mencakup usaha pertambangan dan penggalian batu mulia/batu permata, seperti intan. Termasuk kegiatan pemisahan/sortasi, dan pembersihannya dengan cara lain terhadap batu mulia/batu permata.',NULL,NULL,0),
	(237,'08992','PENGGALIAN FELDSPAR DAN KALSIT','Kelompok ini mencakup usaha penggalian feldspar dan kalsit, serta batu tulis/sabak. Termasuk disini kegiatan pemecahan, penghancuran, penyaringan dan penghalusannya.',NULL,NULL,0),
	(238,'08993','PERTAMBANGAN ASPAL ALAM','Kelompok ini mencakup usaha pertambangan aspal alam, batu beraspal dan bitumen padat alam. Termasuk disini kegiatan pemisahan dan penuangan terhadap mineral tersebut.',NULL,NULL,0),
	(239,'08994','PENGGALIAN ASBES','Kelompok ini mencakup usaha penggalian asbes dalam bentuk serabut maupun tidak. Termasuk disini kegiatan pembersihan dan pemisahannya.',NULL,NULL,0),
	(240,'08995','PENGGALIAN KUARSA/PASIR KUARSA','Kelompok ini mencakup usaha penggalian kuarsa/pasir kuarsa/pasir silika. Termasuk disini kegiatan pemecahan, penghancuran, penyaringan dan penghalusannya.',NULL,NULL,0),
	(241,'08999','PERTAMBANGAN DAN PENGGALIAN LAINNYA YTDL','Kelompok ini mencakup usaha pertambangan dan penggalian lainnya yang belum termasuk dalam golongan manapun. Termasuk kegiatan pemisahan/sortasi, dan pembersihan dengan cara lain terhadap bahan tambang/galian tersebut. Pertambangan dan penggalian ini antara lain mika, leusit, yarosit, zeolit, batu penggosok, grafit alam, steatite (talc), tepung fosil siliceous, oker, toseki dan mineral logam tanah jarang lainnya.',NULL,NULL,0),
	(242,'09100','AKTIVITAS PENUNJANG PERTAMBANGAN MINYAK BUMI DAN GAS ALAM','Kelompok ini mencakup kegiatan jasa yang berkaitan dengan pertambangan minyak dan gas bumi yang dilakukan atas dasar balas jasa (fee) atau kontrak, seperti jasa eksplorasi pengambilan minyak atau gas dengan cara tradisional yaitu membuat observasi geologi, pemasangan alat pengeboran, perbaikan dan pembongkaran penyemenan sumur minyak dan sumur gas, pembuatan saluran sumur, pemompaan sumur produksi, penyumbatan dan penutupan sumur produksi, pengujian produksi, dismantling, pencairan dan regasifikasi gas alam untuk kebutuhan transportasi di lokasi pertambangan, pengeboran percobaan dalam rangka penyulingan minyak bumi dan gas alam dan jasa pemadam kebakaran ladang minyak bumi dan gas alam.',NULL,NULL,0),
	(243,'09900','AKTIVITAS PENUNJANG PERTAMBANGAN DAN PENGGALIAN LAINNYA','Kelompok ini mencakup jasa penunjang atas dasar balas jasa atau kontrak, yang dibutuhkan dalam kegiatan pertambangan golongan pokok 05, 07, dan 08, seperti jasa eksplorasi misalnya dengan cara tradisional seperti mengambil contoh bijih dan membuat observasi geologi, jasa pemompaan dan penyaluran hasil tambang dan jasa percobaan penggalian dan pengeboran ladang atau sumur tambang.',NULL,NULL,0),
	(244,'10110','KEGIATAN RUMAH POTONG DAN PENGEPAKAN DAGING BUKAN UNGGAS','Kelompok ini mencakup kegiatan operasional rumah potong hewan yang berkaitan dengan kegiatan pemotongan, pengulitan, pembersihan dan pengepakan daging, seperti daging sapi, babi, biri-biri, kelinci, domba, unta dan daging segar lainnya bukan unggas, kegiatan pengurusan hasil sampingan, seperti produksi kulit dan jangat dari tempat pemotongan hewan termasuk fellmongery, penjemuran tulang, pengolahan sisaan atau kotoran hewan, penyortiran wol dan bulu dan pembersihan lemak. Termasuk kegiatan pemotongan dan pengolahan paus di darat atau di kapal khusus. Pemotongan yang dilakukan oleh pedagang dimasukkan dalam golongan 462, 472 dan 478.',NULL,NULL,0),
	(245,'10120','KEGIATAN RUMAH POTONG DAN PENGEPAKAN DAGING UNGGAS','Kelompok ini mencakup kegiatan operasional rumah potong unggas dan pengepakan daging unggas, termasuk kegiatan pengurusan hasil sampingan, seperti pemrosesan sisa atau kotoran unggas, pementangan kulit, penyortiran bulu dan pembersihan lemak. Pemotongan yang dilakukan oleh pedagang dimasukkan dalam golongan 462, 472 dan 478.',NULL,NULL,0),
	(246,'10130','INDUSTRI PENGOLAHAN DAN PENGAWETAN PRODUK DAGING DAN DAGING UNGGAS','Kelompok ini mencakup usaha pengolahan dan pengawetan produk daging dan daging unggas dengan cara pengalengan, pengasapan, penggaraman, pembekuan, pemanisan, pengiradiasian (dengan iradiator) dan sebagainya. Kegiatannya mencakup produksi daging beku dalam bentuk carcase, produksi daging beku yang telah dipotong, produksi daging beku dalam porsi tersendiri, produksi daging yang dikeringkan, daging yang diasinkan atau daging yang diasapkan, produksi produk- produk daging, seperti sosis, salami, puding, \"andovillettes\", saveloy, bologna, patc, rillet, dan daging ham. Termasuk kegiatan pengolahan daging paus di darat atau di kapal khusus.',NULL,NULL,0),
	(247,'10211','INDUSTRI PENGGARAMAN/PENGERINGAN IKAN','Kelompok ini mencakup usaha pengolahan dan pengawetan ikan (bersirip/pisces) melalui proses penggaraman/pengeringan, seperti ikan tembang asin, ikan teri asin, dan ikan kering tawar.',NULL,NULL,0),
	(248,'10212','INDUSTRI PENGASAPAN/PEMANGGANGAN IKAN','Kelompok ini mencakup usaha pengolahan dan pengawetan ikan (bersirip/pisces) melalui proses pengasapan/pemanggangan seperti ikan bandeng asap, ikan julung- julung/roa asap, ikan fufu/asar asap, ikan lele asap, dan ikan patin asap.',NULL,NULL,0),
	(249,'10213','INDUSTRI PEMBEKUAN IKAN','Kelompok ini mencakup usaha pengawetan ikan (bersirip/pisces) melalui proses pembekuan, seperti ikan bandeng beku, ikan tuna/cakalang beku dan kakap beku. Termasuk juga ikan utuh maupun dipotong (fillet, loin, saku, steak, chunk, brown meat) yang dibekukan. Kegiatan ini tidak termasuk usaha pendinginan ikan dengan es yang dimaksud untuk mempertahankan kesegaran ikan tersebut (10217).',NULL,NULL,0),
	(250,'10214','INDUSTRI PEMINDANGAN IKAN','Kelompok ini mencakup usaha pengolahan dan pengawetan ikan (bersirip/pisces) melalui proses pemindangan, seperti pindang bandeng/paso, pindang tongkol, pindang cuwe, pindang naya, pindang lemuru/tembang, pindang layang, dan pindang cakalang.',NULL,NULL,0),
	(251,'10215','INDUSTRI PERAGIAN/FERMENTASI IKAN','Kelompok ini mencakup usaha pengolahan dan pengawetan ikan (bersirip/pisces) melalui proses peragian/fermentasi, seperti peragian/fermentasi peda, ikan kayu, dan kecap ikan.',NULL,NULL,0),
	(252,'10216','INDUSTRI BERBASIS DAGING LUMATAN DAN SURIMI','Kelompok ini mencakup usaha pengolahan dan pengawetan ikan (bersirip/pisces) melalui proses pelumatan daging ikan/ penggilingan. Termasuk industri daging lumat yang dicampur bahan tambahan melalui proses pemasakan atau tidak dimasak kemudian dibekukan. Contoh berbasis daging lumatan dan surimi: mata goyang, kurisi, dll. Berbasis surimi: baso, nuget, otak-otak, kamaboko, sosis, pempek, siomay, dimsum, chikuwa, imitation crab.',NULL,NULL,0),
	(253,'10217','INDUSTRI PENDINGINAN/PENGESAN IKAN','Kelompok ini mencakup usaha pengolahan dan pengawetan ikan (bersirip/pisces) melalui proses pendinginan/pengesan.',NULL,NULL,0),
	(254,'10219','INDUSTRI PENGOLAHAN DAN PENGAWETAN LAINNYA UNTUK IKAN','Kelompok ini mencakup usaha pengolahan dan pengawetan ikan (bersirip/pisces) dengan cara selain yang tercakup dalam kelompok 10211 s.d. 10217. Termasuk kegiatan kapal yang digunakan hanya untuk pengolahan dan pengawetan ikan dan biota air lainnya (dalam hal ini tidak termasuk pengalengannya), produksi tepung ikanuntuk konsumsi manusia dan makanan hewan dan produksi daging dan bagian dari ikan bukan untuk konsumsi manusia, konsentrat tepung ikan. Termasuk dalam kelompok ini adalah industri pengolahan dan pengawetan ikan dengan menggunakan radiasi (dengan iradiator).',NULL,NULL,0),
	(255,'10221','INDUSTRI PENGOLAHAN DAN PENGAWETAN IKAN DAN BIOTA AIR (BUKAN UDANG) DALAM KALENG','Kelompok ini mencakup usaha pengolahan dan pengawetan ikan dan biota perairan lainnya kecuali udang melalui proses pengalengan, seperti ikan sardencis dalam kaleng, kerang dalam kaleng, lemuru dalam kaleng, mackarel dalam kaleng, cephalopoda (cumi/gurita/sotong) dalam kaleng, tuna dalam kaleng, rajungan/kepiting dalam kaleng. Kegiatan kapal pengolah ikan yang hanya melakukan pengolahan dan pengawetan dalam kaleng (tanpa melakukan kegiatan penangkapan) termasuk dalam kelompok ini.',NULL,NULL,0),
	(256,'10222','INDUSTRI PENGOLAHAN DAN PENGAWETAN UDANG DALAM KALENG','Kelompok ini mencakup usaha pengolahan dan pengawetan udang melalui proses pengalengan (udang dalam kaleng). Kegiatan kapal pengolah udang yang hanya melakukan pengolahan dan pengawetan dalam kaleng (tanpa melakukan kegiatan penangkapan) termasuk dalam kelompok ini.',NULL,NULL,0),
	(257,'10291','INDUSTRI PENGGARAMAN/PENGERINGAN BIOTA AIR LAINNYA','Kelompok ini mencakup usaha pengolahan dan pengawetan crustacea, mollusca, echinodermata dan biota perairan lainnya melalui proses penggaraman/pengeringan, seperti udang asin, cumi-cumi asin, ebi, ubur-ubur asin, sotong asin, teripang kering, sotong kering, dan lainnya.',NULL,NULL,0),
	(258,'10292','INDUSTRI PENGASAPAN/PEMANGGANGAN BIOTA AIR LAINNYA','Kelompok ini mencakup usaha pengolahan dan pengawetan crustacea, mollusca, echinodermata dan biota perairan lainnya melalui proses pengasapan/pemanggangan, seperti sotong asap/panggang, teripang asap/panggang.',NULL,NULL,0),
	(259,'10293','INDUSTRI PEMBEKUAN BIOTA AIR LAINNYA','Kelompok ini mencakup usaha pengawetan crustacea, mollusca, echinodermata dan biota perairan lainnya melalui proses pembekuan, seperti udang beku, paha kodok beku, cephalopoda (cumi/sotong/gurita) beku, kepiting/rajungan beku, dan kerang beku. Kegiatan ini tidak termasuk usaha pendinginan crustacea, mollusca dan biota air lainnya dengan es yang dimaksud untuk mempertahankan kesegarannya (10297).',NULL,NULL,0),
	(260,'10294','INDUSTRI PEMINDANGAN BIOTA AIR LAINNYA','Kelompok ini mencakup usaha pengolahan dan pengawetan crustacea, mollusca, echinodermata dan biota perairan lainnya melalui proses pemindangan.',NULL,NULL,0),
	(261,'10295','INDUSTRI PERAGIAN/FERMENTASI BIOTA AIR LAINNYA','Kelompok ini mencakup usaha pengolahan dan pengawetan crustacea, mollusca, echinodermata dan biota perairan lainnya melalui proses peragian/fermentasi seperti terasi udang.',NULL,NULL,0),
	(262,'10296','INDUSTRI BERBASIS LUMATAN BIOTA AIR LAINNYA','Kelompok ini mencakup usaha pengolahan dan pengawetan biota air lainnya melalui proses pelumatan daging/penggilingan/pencampuran bahan tambahan/pengukusan, seperti lumatan cumi, lumatan udang, baso udang, baso cumi, baso kepiting, dan kaki naga udang.',NULL,NULL,0),
	(263,'10297','INDUSTRI PENDINGINAN/PENGESAN BIOTA AIR LAINNYA','Kelompok ini mencakup usaha pengolahan dan pengawetan crustacea, mollusca, echinodermata dan biota perairan lainnya melalui proses pendinginan/pengesan, seperti cumi segar, kerang segar, teripang segar, dan kepiting segar.',NULL,NULL,0),
	(264,'10298','INDUSTRI PENGOLAHAN RUMPUT LAUT','Kelompok ini mencakup usaha pengolahan rumput laut menjadi rumput laut kering dan olahan (alkali treated caragenan chips), gelatin, agar-agar, karagenan dan lainnya.',NULL,NULL,0),
	(265,'10299','INDUSTRI PENGOLAHAN DAN PENGAWETAN LAINNYA UNTUK BIOTA AIR LAINNYA','Kelompok ini mencakup usaha pengolahan dan pengawetan crustacea, mollusca, echinodermata dan biota perairan lainnya dengan cara selain yang tercakup dalam kelompok 10291 s.d. 10298, seperti tepung udang, tepung kerang, dan tepung kodok. Termasuk dalam kelompok ini adalah industri pengolahan dan pengawetan untuk biota air lainnya dengan menggunakan radiasi (dengan iradiator).',NULL,NULL,0),
	(266,'10311','INDUSTRI PENGASINAN BUAH-BUAHAN DAN SAYURAN','Kelompok ini mencakup usaha pengawetan buah-buahan dan sayuran dengan proses pengasinan, baik dalam bentuk kemasan ataupun tidak, seperti asinan kedondong, asinan wortel.',NULL,NULL,0),
	(267,'10312','INDUSTRI PELUMATAN BUAH-BUAHAN DAN SAYURAN','Kelompok ini mencakup usaha pengawetan buah-buahan dan sayuran dengan proses pelumatan, baik dalam bentuk kemasan ataupun tidak, seperti selai mangga, jelly murbai, dan cabe giling.',NULL,NULL,0),
	(268,'10313','INDUSTRI PENGERINGAN BUAH-BUAHAN DAN SAYURAN','Kelompok ini mencakup usaha pengawetan buah-buahan dan sayuran dengan cara pengeringan, baik dalam bentuk kemasan ataupun tidak, seperti kismis (anggur), bawang merah, bawang putih, cabe kering, rebung kering dan jamur kering. Termasuk Industri keripik dari buah dan sayuran.',NULL,NULL,0),
	(269,'10314','INDUSTRI PEMBEKUAN BUAH-BUAHAN DAN SAYURAN','Kelompok ini mencakup usaha pengawetan buah-buahan dan sayuran dengan proses pembekuan, seperti buah-buahan beku dan sayur-sayuran beku.',NULL,NULL,0),
	(270,'10320','INDUSTRI PENGOLAHAN DAN PENGAWETAN BUAH-BUAHAN DAN SAYURAN DALAM KALENG','Kelompok ini mencakup usaha pengolahan dan pengawetan buah-buahan dan sayuran melalui proses pengalengan, seperti nanas dalam kaleng, rambutan dalam kaleng, kacang dalam kaleng dan wortel dalam kaleng. Yang dimaksud pengalengan di sini merupakan proses pengawetan dan bukan hanya pengemasan.',NULL,NULL,0),
	(271,'10330','INDUSTRI PENGOLAHAN SARI BUAH DAN SAYURAN','Kelompok ini mencakup usaha pengawetan buah-buahan dan sayuran dengan cara pengolahan sari buah-buahan dan sayuran, seperti bubuk sari buah-buahan, air/sari pekat buah-buahan dan air/sari pekat sayuran (konsentrat), nektar buah dan atau sayuran.',NULL,NULL,0),
	(272,'10391','INDUSTRI TEMPE KEDELAI','Kelompok ini mencakup usaha pembuatan tempe dari kedelai. Usaha pembuatan tempe yang bahan bakunya selain kedelai (dari kacang tanah/kacang-kacangan lainnya), seperti tempe bongkrek, dimasukkan dalam kelompok 10393.',NULL,NULL,0),
	(273,'10392','INDUSTRI TAHU KEDELAI','Kelompok ini mencakup usaha pembuatan tahu dari kedelai. Usaha pembuatan tahu yang bahan bakunya selain kedelai (dari kacang tanah/kacang-kacangan lainnya) dimasukkan dalam kelompok 10393.',NULL,NULL,0),
	(274,'10393','INDUSTRI PENGOLAHAN DAN PENGAWETAN KEDELAI DAN KACANG-KACANGAN LAINNYA SELAIN TAHU DAN TEMPE','Kelompok ini mencakup usaha pengolahan dan pengawetan kedelai dan kacang- kacangan lainnya selain tahu dan tempe seperti natto, yuba/kembang tahu, fu zhu, dan douchi. Termasuk tempe gembus dan tempe bongkrek.',NULL,NULL,0),
	(275,'10399','INDUSTRI PENGOLAHAN DAN PENGAWETAN LAINNYA BUAH-BUAHAN DAN SAYURAN BUKAN KACANG-KACANGAN','Kelompok ini mencakup usaha pengawetan buah-buahan dan sayuran dengan cara selain yang tercakup dalam subgolongan 10391 s.d. 10393, seperti industri pengupasan kentang, produk buah-buahan dan sayuran yang diproses dengan pasteurisasi atau sterilisasi dan dikemas dalam kemasan selain kaleng.',NULL,NULL,0),
	(276,'10411','INDUSTRI MINYAK MENTAH DAN LEMAK NABATI','Kelompok ini mencakup usaha pengolahan bahan-bahan dari nabati menjadi minyak mentah (crude oil) yang masih perlu diolah lebih lanjut dan biasanya produk ini dipakai oleh industri lain (kecuali minyak mentah kelapa sawit (crude plam oil) dan minyak mentah kelapa) termasuk juga industri hasil lemak dari nabati yang dapat digunakan sebagai bahan makanan, seperti minyak bunga matahari.',NULL,NULL,0),
	(277,'10412','INDUSTRI MARGARINE','Kelompok ini mencakup usaha pembuatan margarine dari minyak makan nabati.',NULL,NULL,0),
	(278,'10413','INDUSTRI MINYAK MENTAH DAN LEMAK HEWANI SELAIN IKAN','Kelompok ini mencakup usaha pengolahan bahan-bahan dari hewani selain ikan menjadi minyak mentah dan lemak hewani, seperti minyak/lemak babi, lemak sapi dan lemak unggas.',NULL,NULL,0),
	(279,'10414','INDUSTRI MINYAK IKAN','Kelompok ini mencakup usaha pembuatan minyak yang berbahan baku dari badan ikan yang berlemak tinggi, seperti lemuru, atau dari organ badan ikan seperti hati cucut. Mencakup juga industri minyak yang dihasilkan dari hasil sampingan pengalengan ikan, seperti hasil pengalengan sarden. Pengolahan minyak ikan/biota perairan lainnya yang digunakan untuk bahan farmasi ataupun kosmetik dimasukkan dalam subgolongan 2101 dan 2102.',NULL,NULL,0),
	(280,'10415','INDUSTRI MINYAK GORENG BUKAN MINYAK KELAPA DAN MINYAK KELAPA SAWIT','Kelompok ini mencakup usaha pembuatan minyak goreng lainnya, bukan minyak goreng kelapa dan minyak goreng kelapa sawit, seperti minyak bekatul, minyak goreng babi dan minyak goreng unggas.',NULL,NULL,0),
	(281,'10421','INDUSTRI KOPRA','Kelompok ini mencakup usaha pembuatan kopra.',NULL,NULL,0),
	(282,'10422','INDUSTRI MINYAK MENTAH KELAPA','Kelompok ini mencakup usaha pengolahan kelapa menjadi minyak mentah (crude oil) yang masih perlu diolah lebih lanjut dan biasanya produk ini dipakai oleh industri lain.',NULL,NULL,0),
	(283,'10423','INDUSTRI MINYAK GORENG KELAPA','Kelompok ini mencakup usaha pengolahan lebih lanjut (pemurnian, pemucatan dan penghilangan bau yang tidak dikehendaki) dari minyak mentah kelapa menjadi minyak goreng kelapa.',NULL,NULL,0),
	(284,'10424','INDUSTRI PELET KELAPA','Kelompok ini mencakup usaha pengolahan lebih lanjut kelapa, seperti pelet kelapa.',NULL,NULL,0),
	(285,'10431','INDUSTRI MINYAK MENTAH KELAPA SAWIT (CRUDE PALM OIL)','Kelompok ini mencakup usaha pengolahan kelapa sawit menjadi minyak mentah (crude palm oil/CPO) yang masih perlu diolah lebih lanjut dan biasanya produk ini dipakai oleh industri lain.',NULL,NULL,0),
	(286,'10432','INDUSTRI MINYAK MENTAH INTI KELAPA SAWIT (CRUDE PALM KERNEL OIL)','Kelompok ini mencakup usaha pengolahan inti kelapa sawit menjadi minyak mentah inti (crude palm kernel oil/CPKO) yang masih perlu diolah lebih lanjut dan biasanya produk ini dipakai oleh industri lain.',NULL,NULL,0),
	(287,'10433','INDUSTRI PEMISAHAN/FRAKSINASI MINYAK MENTAH KELAPA SAWIT DAN MINYAK MENTAH INTI KELAPA SAWIT','Kelompok ini mencakup pemisahan fraksi padat dan fraksi cair dari minyak mentah kelapa sawit menjadi minyak mentah kelapa sawit olein (Crude Palm Olein) dan minyak mentah kelapa sawit stearin (Crude Palm Stearin) atau dari minyak mentah inti kelapa sawit menjadi minyak mentah inti kelapa sawit olein (Crude Palm Kernel Olein) dan minyak mentah inti kelapa sawit stearin (Crude Palm Kernel Stearin) yang masih perlu diolah lebih lanjut.',NULL,NULL,0),
	(288,'10434','INDUSTRI PEMURNIAN MINYAK MENTAH KELAPA SAWIT DAN MINYAK MENTAH INTI KELAPA SAWIT','Kelompok ini mencakup pemurnian minyak mentah dari kelapa sawit menjadi minyak murni kelapa sawit (Refined Bleached Deodorized Palm Oil) atau dari minyak inti kelapa sawit menjadi minyak murni inti kelapa sawit (Refined Bleached Deodorized Palm Kernel Oil) yang masih perlu diolah lebih lanjut.',NULL,NULL,0),
	(289,'10435','INDUSTRI PEMISAHAN/FRAKSINASI MINYAK MURNI KELAPA SAWIT','Kelompok ini mencakup usaha pemisahan fraksi padat dan fraksi cair dari minyak murni kelapa sawit menjadi miyak murni kelapa sawit olein (Refined Bleached Deodorized Palm Olein) dan minyak murni kelapa sawit stearin (Refined Bleached Deodorized Palm Stearin).',NULL,NULL,0),
	(290,'10436','INDUSTRI PEMISAHAN/FRAKSINASI MINYAK MURNI INTI KELAPA SAWIT','Kelompok ini mencakup usaha pemisahan fraksi padat dan fraksi cair dari minyak murni inti kelapa sawit menjadi minyak murni inti kelapa sawit olein (Refined Bleached Deodorized Palm Kernel Olein) dan miyak murni inti kelapa sawit stearin (Refined Bleached Deodorized Palm Kernel Stearin).',NULL,NULL,0),
	(291,'10437','INDUSTRI MINYAK GORENG KELAPA SAWIT','Kelompok ini mencakup usaha pengolahan lebih lanjut (pemurnian, pemucatan dan penghilangan bau yang tidak dikehendaki) dari minyak mentah kelapa sawit (CPO) menjadi minyak goreng kelapa sawit yang siap dikonsumsi. Termasuk pengolahan minyak merah kelapa sawit (red palm oil) dan/atau aktivitas penambahan zat tertentu pada minyak goreng untuk meningkatkan kualitas/nilai tambah.',NULL,NULL,0),
	(292,'10490','INDUSTRI MINYAK MENTAH DAN LEMAK NABATI DAN HEWANI LAINNYA','Kelompok ini mencakup usaha pengolahan lainnya untuk minyak dan lemak, yang belum tercakup pada subgolongan 1041 s.d. 1043, seperti industri shorterning (minyak roti), industri minyak dan lemak dari binatang yang tidak dapat dimakan, produksi (linter) sisaan kapas, bungkil atau ampas dan hasil sisaan lainnya dari produksi minyak dan penyulingan minyak dari ikan dan mamalia laut.',NULL,NULL,0),
	(293,'10510','INDUSTRI PENGOLAHAN SUSU SEGAR DAN KRIM','Kelompok ini mencakup usaha industri pengolahan susu cair segar, susu dipasteurisasi, disterilisasi, homogenisasi dan atau pemanasan ultra (UHT) dan industri pengolahan krim dari susu cair segar, pasteurisasi, sterilisasi dan homogenisasi, dalam bentuk cair atau semi cair dan produk sejenis lainnya.',NULL,NULL,0),
	(294,'10520','INDUSTRI PENGOLAHAN SUSU BUBUK DAN SUSU KENTAL','Kelompok ini mencakup usaha industri pengolahan susu bubuk atau susu kental atau krimer kental, susu evaporasi, dengan pemanis atau tidak dan industri pengolahan susu atau krim dalam bentuk yang padat, dan produk sejenis lainnya.',NULL,NULL,0),
	(295,'10531','INDUSTRI PENGOLAHAN ES KRIM','Kelompok ini mencakup usaha pembuatan berbagai macam es krim yang bahan utamanya dari susu. Pembuatan es krim yang bahan utamanya bukan dari susu dimasukkan dalam kelompok 10532.',NULL,NULL,0),
	(296,'10532','INDUSTRI PENGOLAHAN ES SEJENISNYA YANG DAPAT DIMAKAN (BUKAN ES BATU DAN ES BALOK)','Kelompok ini mencakup usaha pembuatan berbagai macam es yang bahan utamanya bukan dari susu, seperti sorbet, es lilin, ice drop, es dengan berbagai rasa lainnya, es mambo dan es puter, premiks es rasa dan produk sejenis es untuk dimakan lainnya. Usaha es kering (dry ice) dimasukkan dalam kelompok 20112.',NULL,NULL,0),
	(297,'10590','INDUSTRI PENGOLAHAN PRODUK DARI SUSU LAINNYA','Kelompok ini mencakup usaha pengolahan produk dari susu lainnya, seperti mentega, yoghurt, keju dan dadih, air dadih, kaseinatau laktosa (susu manis), premiks es krim bubuk (bubuk es krim), premiks es krim cair, susu fermentasi, whey, dan produk- produk olahan susu sejenis lainnya. Pembuatan es krim yang bahan utamanya dari susu dimasukkan dalam kelompok 10531',NULL,NULL,0),
	(298,'10611','INDUSTRI PENGGILINGAN GANDUM DAN SERELIA LAINNYA','Kelompok ini mencakup usaha penggilingan gandum dan serelia lainnya menjadi tepung dan pelet , seperti gandum dan sorghum, rye, oat dan serelia lainnya.',NULL,NULL,0),
	(299,'10612','INDUSTRI PENGGILINGAN ANEKA KACANG (TERMASUK LEGUMINOUS)','Kelompok ini mencakup usaha pembuatan tepung dari aneka kacang melalui proses penggilingan, seperti tepung tepung kacang hijau, tepung kacang kedelai dan tepung lainnya (seperti dari kacang tanah, kacang merah dan tanaman leguminous lainnya).',NULL,NULL,0),
	(300,'10613','INDUSTRI PENGGILINGAN ANEKA UMBI DAN SAYURAN (TERMASUK RHIZOMA)','Kelompok ini mencakup usaha pembuatan tepung dari aneka umbi dan sayuran termasuk rhizoma melalui proses penggilingan, seperti tepung dari ubi kayu (gaplek), ubi jalar, talas, irut, jahe, temulawak, kunyit dan kapulaga dan sayuran.',NULL,NULL,0),
	(301,'10614','INDUSTRI TEPUNG CAMPURAN DAN ADONAN TEPUNG','Kelompok ini mencakup usaha pembuatan tepung campuran dan adonan tepung yang sudah dicampur untuk roti, kue, biskuit, kue dadar, termasuk tepung untuk adonan, misalnya untuk melapisi permukaan ikan atau daging ayam, seperti tepung pelapis, tepung bumbu, tepung bakwan, tepung bakso, premiks untuk makanan pencuci mulut berbasis serealia dan pati dan tepung custard tanpa telur.',NULL,NULL,0),
	(302,'10615','INDUSTRI MAKANAN SEREAL','Kelompok ini mencakup usaha pembuatan makanan sereal termasuk semua jenis produk sereal siap santap, instan dan sereal panas. Contoh rolled sereal, granola sereal, oatmeal instan, corn flakes, puffed gandum atau beras, muesli,produk sereal dari kedelai dan produk sereal dari tepung serealia dengan menggunakan proses ekstrusi.',NULL,NULL,0),
	(303,'10616','INDUSTRI TEPUNG TERIGU','Kelompok ini mencakup usaha pembuatan tepung terigu.',NULL,NULL,0),
	(304,'10631','INDUSTRI PENGGILINGAN PADI DAN PENYOSOHAN BERAS','Kelompok ini mencakup usaha pembuatan pati ubi kayu melalui ekstraksi, seperti tepung tapioka.',NULL,NULL,0),
	(305,'10632','INDUSTRI PENGGILINGAN DAN PEMBERSIHAN JAGUNG','Kelompok ini mencakup usaha pembuatan pati dari berbagai macam tanaman suku palma, seperti pati sagu/pati mutiara dan pati aren.',NULL,NULL,0),
	(306,'10633','INDUSTRI TEPUNG BERAS DAN TEPUNG JAGUNG','Kelompok ini mencakup usaha pembuatan gula glukosa, selain yang termasuk dalam kelompok 10721 dan 10722, seperti glucosa, fructosa, lactosa, maltosa, sacharosa, dan sediaan pemanis lainnya. Termasuk pemanis buatan.',NULL,NULL,0),
	(307,'10634','INDUSTRI PATI BERAS DAN JAGUNG','Kelompok ini mencakup usaha pembuatan berbagai macam pati melalui proses ekstraksi yang belum termasuk kelompok 10621 s.d. 10623, seperti pati kentang, pati bengkoang, pati temulawak, pati irut dan pati biji mangga.',NULL,NULL,0),
	(308,'10635','INDUSTRI PEMANIS DARI BERAS DAN JAGUNG','Kelompok ini mencakup usaha penggilingan padi menjadi beras, termasuk penyosohan beras yang terpisah dengan usaha penggilingan padi.',NULL,NULL,0),
	(309,'10636','INDUSTRI MINYAK DARI JAGUNG DAN BERAS','Kelompok ini mencakup usaha penggilingan dan pembersihan jagung.',NULL,NULL,0),
	(310,'10621','INDUSTRI PATI UBI KAYU','Kelompok ini mencakup usaha pembuatan tepung beras dan tepung jagung.',NULL,NULL,0),
	(311,'10622','INDUSTRI BERBAGAI MACAM PATI PALMA','Kelompok ini mencakup usaha pembuatan pati beras dan pati jagung (maizena).',NULL,NULL,0),
	(312,'10623','INDUSTRI GLUKOSA DAN SEJENISNYA','Kelompok ini mencakup usaha pembuatan pemanis dari beras dan jagung seperti fructosa, glucosa, maltosa, sacharosa dan dextrosa.',NULL,NULL,0),
	(313,'10629','INDUSTRI PATI DAN PRODUK PATI LAINNYA','Kelompok ini mencakup usaha pembuatan minyak dari dan jagung dan beras.',NULL,NULL,0),
	(314,'10710','INDUSTRI PRODUK ROTI DAN KUE','Kelompok ini mencakup usaha pembuatan berbagai macam roti, kue dan produk bakeri lainnya seperti industri roti tawar dan roti kadet; industri kue, pie, tart; industri biskuit dan produk roti kering lainnya; industri pengawetan kue kering dan cake; industri produk makanan ringan baik yang manis atau asin; industri tortillas; dan industri produk roti yang dibekukan, seperti pancake, waffle dan roti kadet.',NULL,NULL,0),
	(315,'10721','INDUSTRI GULA PASIR','Kelompok ini mencakup usaha pembuatan gula yang berbentuk kristal (pasir), bahan utamanya dari tebu, bit ataupun lainnya.',NULL,NULL,0),
	(316,'10722','INDUSTRI GULA MERAH','Kelompok ini mencakup usaha pembuatan gula merah baik berbentuk cetakan, serbuk/granul maupun cair, yang murni dari nira sebagai bahan baku baik berasal dari tebu maupun tanaman palma (aren, kelapa dan sejenisnya).',NULL,NULL,0),
	(317,'10723','INDUSTRI SIROP','Kelompok ini mencakup usaha pengolahan gula menjadi sirop, seperti industri sirup gula dan produksi sirup dan gula maple. Kegiatan pembuatan sirop yang tergabung dengan pabrik gula dan tidak dapat dipisahkan tersendiri dimasukkan dalam kelompok 10721 atau 10722.',NULL,NULL,0),
	(318,'10729','INDUSTRI PENGOLAHAN GULA LAINNYA BUKAN SIROP','Kelompok ini mencakup usaha pengolahan gula ke dalam bentuk lain, termasuk pembuatan gula batu, gula cair, tepung gula, gula pengganti dari jus tebu, bit, maple gula cair, gula stevia, kelapa, nira, aren dan molasse (harum manis), toping (non-buah) saus manis, dan gula merah yang tidak murni dari nira sebagai bahan baku utamanya dan yang tidak termasuk dalam kelompok 10721 sd. 10723.',NULL,NULL,0),
	(319,'10731','INDUSTRI KAKAO','Kelompok ini mencakup usaha pengolahan biji kakao menjadi bubuk kakao, lemak kakao, pasta kakao, bungkil kakao dan produk kakao lainnya.',NULL,NULL,0),
	(320,'10732','INDUSTRI MAKANAN DARI COKELAT DAN KEMBANG GULA DARI COKLAT','Kelompok ini mencakup usaha pembuatan segala macam makanan yang bahan utamanya dari cokelat seperti cokelat, cokelat compound, coklat couverture, cokelat imitasi, coklat putih, gula-gula dari cokelat, olesan dan isian berbasis kakao. Termasuk industri minuman dari cokelat dalam bentuk bubuk maupun cair.',NULL,NULL,0),
	(321,'10733','INDUSTRI MANISAN BUAH-BUAHAN DAN SAYURAN KERING','Kelompok ini mencakup usaha pengawetan buah-buahan dan sayuran baik buah, kacang, kulit buah dan bagian lain dari tumbuhan dengan proses pemanisan dan pengeringan, baik dalam bentuk kemasan ataupun tidak, seperti manisan pala dan manisan mangga kering, sayuran dan buah-buahan kering lainnya.',NULL,NULL,0),
	(322,'10734','INDUSTRI KEMBANG GULA','Kelompok ini mencakup usaha pembuatan kembang gula termasuk seluruh kembang gula keras, kembang gula lunak, kembang gula karet, caramel, cachous, nougat, foundant, dan marzipan, yang bahan utamanya bukan dari coklat.',NULL,NULL,0),
	(323,'10739','INDUSTRI KEMBANG GULA LAINNYA','Kelompok ini mencakup usaha industri kembang gula lainnya, yang tidak termasuk pada kategori 10731 sd. 10734 seperti permen karet dan permen obat batuk dan pastilles.',NULL,NULL,0),
	(324,'10740','INDUSTRI MAKARONI, MIE DAN PRODUK SEJENISNYA','Kelompok ini mencakup usaha pembuatan makaroni, mie, spagheti, bihun, so\'un dan sejenisnya, baik dimasak atau tidak dalam bentuk basah maupun kering. Termasuk industri couscous dan industri produk pasta yang dibekukan atau dikalengkan.',NULL,NULL,0),
	(325,'10750','INDUSTRI MAKANAN DAN MASAKAN OLAHAN','Kelompok ini mencakup industri makanan siap saji (diolah, dibumbui dan dimasak) diolah untuk tujuan diawetkan dalam kaleng atau dibekukan dan biasanya dikemas dan dilabel untuk dijual kembali. Mencakup juga industri masakan daging atau unggas, industri masakan ikan (kecuali masakan ikan dan udang dalam kaleng), industri masakan sayuran siap saji, industri masakan rebusan dalam kaleng dan makanan di dalam wadah hampa udara dan industri masakan siap saji yang lain. Termasuk industri pizza beku, pepes, presto, dendeng ikan, baby fish goreng/crispy ikan, udang tepung dan ikan tepung.',NULL,NULL,0),
	(326,'10761','INDUSTRI PENGOLAHAN KOPI','Kelompok ini mencakup usaha penyangraian, penggilingan dan pensarian (ekstraksi) kopi menjadi berbagai macam bubuk atau cairan, seperti kopi sangrai, kopi bubuk, kopi instan, ekstrak dan sari kopi. Termasuk industri pengganti kopi. Penggilingan kopi bubuk di tempat pedagang kopi dimasukkan dalam kelompok 47222 dan 47823.',NULL,NULL,0),
	(327,'10762','INDUSTRI PENGOLAHAN HERBAL (HERB INFUSION)','Kelompok ini mencakup usaha pengolahan herbal (mint, vervain, chamomil). Termasuk industri seduhan herbal.',NULL,NULL,0),
	(328,'10763','INDUSTRI PENGOLAHAN TEH','Kelompok ini mencakup usaha pengolahan daun teh menjadi teh. Termasuk kegiatan pencampuran teh dan mate, industri ekstraksi dan olahan berbahan dasar teh dan mate.',NULL,NULL,0),
	(329,'10771','INDUSTRI KECAP','Kelompok ini mencakup usaha pembuatan kecap dari kedele/kacang-kacangan lainnya, dan pembuatan tauco (baik dari kedelai/kacang-kacangan lainnya yang masih segar, maupun dari hasil sisa pembuatan kecap). Usaha pembuatan kecap ikan tercakup dalam kelompok 10215.',NULL,NULL,0),
	(330,'10772','INDUSTRI BUMBU MASAK DAN PENYEDAP MASAKAN','Kelompok ini mencakup usaha pembuatan bumbu masak dalam keadaan sudah diramu atau belum, baik berbentuk bubuk ataupun lainnya, seperti bumbu gulai, bumbu kari, bumbu merica, bubuk jahe, bubuk jinten, bubuk pala, bubuk cabe dan bubuk kayu manis. Termasuk usaha industri penyedap masakan baik yang asli, natura maupun sintesa khemis, seperti vetsin dan serbuk panili dan industri bumbu-bumbu, saus dan rempah-rempah, seperti mayonais, tepung mustar, mustar olahan, sauce tomat, sauce selada, dan pengganti garam yang digunakan sebagai bumbu pada produk pangan.',NULL,NULL,0),
	(331,'10773','INDUSTRI PRODUK MASAK DARI KELAPA','Kelompok ini mencakup usaha pembuatan produk masak dari kelapa yang belum tercakup dalam golongan manapun, seperti santan pekat dan santan cair, kecap kelapa, sari kelapa (nata de coco), kelapa parut kering (dicicated coconut), krim kelapa dan tepung kelapa.',NULL,NULL,0),
	(332,'10774','INDUSTRI PENGOLAHAN GARAM','Kelompok ini mencakup usaha pengolahan garam dapur/konsumsi.',NULL,NULL,0),
	(333,'10779','INDUSTRI PRODUK MASAK LAINNYA','Kelompok ini mencakup usaha pembuatan petis, saus tiram, terasi, khitin/khitosan, atau yang sejenisnya, dengan bahan baku utamanya ikan dan udang ataupun bagian- bagiannya, industri madu dan karamel buatan, industri ekstraksi dan jus dari daging dan ikan, industri konsentrat buatan/pembuatan macam-macam makanan yang belum tercakup dalam golongan manapun, seperti cincau, gist, baking powder, essence dan cuka makan. Usaha pembuatan terasi udang tercakup dalam kelompok 10295.',NULL,NULL,0),
	(334,'10791','INDUSTRI MAKANAN BAYI','Kelompok ini mencakup usaha pembuatan makanan bayi, seperti formula bayi, susu lanjutan dan makanan lanjutan lainnya, makanan bayi dan makanan yang mengandung bahan yang dihomogenisasi. Termasuk pembuatan pangan diet dan keperluan medis khusus bayi dan anak, seperti formula pertumbuhan, makanan pendamping ASI, dan makanan selingan untuk anak.',NULL,NULL,0),
	(335,'10792','INDUSTRI KUE BASAH','Kelompok ini mencakup usaha pembuatan macam-macam makanan kue basah, yaitu sejenis kue yang relatif tidak tahan lama, seperti wajik, lemper, kue lapis, lumpia, dan martabak (termasuk pembuatan tape dan lempok).',NULL,NULL,0),
	(336,'10793','INDUSTRI MAKANAN DARI KEDELE DAN KACANG-KACANGAN LAINNYA BUKAN KECAP, TEMPE DAN TAHU','Kelompok ini mencakup usaha pembuatan makanan dari kedele/kacang-kacangan lainnya bukan kecap dan tempe, seperti keripik/peyek dari kacang-kacangan, daging sintetis, kacang kapri, kacang asin, kacang telur, kacang sukro, kacang bogor, kacang atom, kacang mete dan enting-enting. Termasuk produk protein kedelai dan texturized vegetable protein.',NULL,NULL,0),
	(337,'10794','INDUSTRI KERUPUK, KERIPIK, PEYEK DAN SEJENISNYA','Kelompok ini mencakup usaha industri berbagai macam kerupuk, keripik, peyek dan sejenisnya, seperti kerupuk udang, kerupuk ikan dan kerupuk pati (kerupuk terung). Dan usaha pembuatan berbagai macam makanan sejenis kerupuk, seperti macam- macam emping, kecimpring, karak, gendar, opak, keripik paru, keripik bekicot dan keripik kulit, peyek teri, peyek udang. Kegiatan atau usaha pembuatan keripik/peyek dari kacang kacangan dimasukkan dalam kelompok 10793',NULL,NULL,0),
	(338,'10795','INDUSTRI KRIMER NABATI','Kelompok ini mencakup usaha pembuatan krimer nabati emulsi lemak nabati yang berasal dari kelapa atau kelapa sawit yang digunakan sebagai campuran makanan atau minuman.',NULL,NULL,0),
	(339,'10796','INDUSTRI DODOL','Kelompok ini mencakup usaha pembuatan dodol yang terbuat diperoleh dari bahan utama tepung beras atau tepung beras ketan, santan kelapa dan gula, dengan atau tanpa bahan tambahan lain yang dimasak hingga mencapai tekstur yang diinginkan. Pembuatan lempok masuk kedalam kelompok 10792',NULL,NULL,0),
	(340,'10799','INDUSTRI PRODUK MAKANAN LAINNYA','Kelompok ini mencakup usaha pembuatan produk makanan lainnya yang tidak diklasifikasikan di tempat lain, seperti telur asin, soup dan kaldu, makanan yang tidak tahan lama, seperti sandwich, pizza mentah, selongsong sosis dari kolagen, selulosa, usus hewan, dan lainnya. Termasuk industri ragi, susu dan keju pengganti dari selain susu dan produk telur dan albumin telur, pangan diet khusus dewasa dan pangan keperluan medis khusus dewasa, seperti minuman untuk ibu hamil dan menyusui, makanan untuk penderita penyakit tertentu, pangan protein produk seperti Hydrolised Vegetable Protein (HVP).',NULL,NULL,0),
	(341,'10801','INDUSTRI RANSUM MAKANAN HEWAN','Kelompok ini mencakup usaha pembuatan berbagai macam ransum pakan ternak, unggas, ikan dan hewan lainnya.',NULL,NULL,0),
	(342,'10802','INDUSTRI KONSENTRAT MAKANAN HEWAN','Kelompok ini mencakup usaha pembuatan konsentrat pakan ternak, unggas dan hewan lainnya. Pengolahan konsentrat pakan ternak, unggas dan hewan lainnya yang tidak dapat di pisahkan dari usaha peternakan dimasukkan dalam golongan 014(Peternakan).',NULL,NULL,0),
	(343,'11010','INDUSTRI MINUMAN BERALKOHOL HASIL DESTILASI','Kelompok ini mencakup industri pengolahan minuman yang menggunakan bahan baku alkohol (ethyl alcohol) dengan proses destilasi seperti whisky, brandy, rum, gin, liqueurs, tidak termasuk residu sulphite dari pabrik pulp dan pencampuran minuman beralkohol, termasuk produk minuman beralkohol netral (tanpa rasa/flavor) dan produk minuman beralkohol hasil destilasi yang dibuat secara tradisional. Industri alkohol murni dimasukkan dalam kelompok 20115.',NULL,NULL,0),
	(344,'11020','INDUSTRI MINUMAN BERALKOHOL HASIL FERMENTASI ANGGUR DAN HASIL PERTANIAN LAINNYA','Kelompok ini mencakup industri pengolahan minuman secara fermentasi dengan bahan baku anggur, apel, buah-buahan lain atau hasil pertanian lainnya, seperti beras, sayuran, daun, batang dan akar (kecuali malt). Kegiatan yang tercakup adalah industri minuman anggur, sparkling wine, minuman anggur dari sari anggur, fermentasi tanpa destilasi minuman beralkohol, seperti sake, sari buah apel, perry, mead, minuman anggur dari buah lain dan minuman campuran yang mengandung alkohol, minuman anggur putih dan sejenisnya, fermentasi tanpa destilasi minuman beralkohol yang dibuat secara tradisional, pencampuran minuman anggur dan minuman anggur beralkohol rendah atau tidak beralkohol.',NULL,NULL,0),
	(345,'11031','INDUSTRI MINUMAN BERALKOHOL HASIL FERMENTASI MALT','Kelompok ini mencakup industri minuman beralkohol dari malt, seperti bir, ale, porter dan stout. Termasuk Industri bir beralkohol rendah atau tanpa alkohol.',NULL,NULL,0),
	(346,'11032','INDUSTRI MALT','Kelompok ini mencakup industri pembuatan malt (kecambah barley atau sereal lainnya yang dikeringkan).',NULL,NULL,0),
	(347,'11040','INDUSTRI MINUMAN RINGAN','Kelompok ini mencakup usaha industri minuman yang tidak mengandung alkohol, kecuali bir dan anggur tanpa alkohol. Termasuk industri minuman ringan beraroma tanpa alkohol dan atau rasa manis, seperti lemonade, orangeade, cola, minuman buah, air tonik, limun, air soda, krim soda dan air anggur, minuman yang dikarbonasi maupun tidak, dan minuman yang mengandung konsentrat, dan minuman serbuk.',NULL,NULL,0),
	(348,'11051','INDUSTRI AIR KEMASAN','Kelompok ini mencakup usaha industri yang melakukan proses pengolahan air baku menjadi air minum yang dikemas dan siap dikonsumsi langsung, mengandung mineral ataupun tidak, dengan atau tanpa penambahan gas seperti O2 ataupun CO2, dengan atau tanpa penambahan mineral.',NULL,NULL,0),
	(349,'11052','INDUSTRI AIR MINUM ISI ULANG','Kelompok ini mencakup industri air minum yang dapat langsung dikonsumsi berupa depot air isi ulang baik yang dioperasikan manual oleh manusia maupun mesin pengisi otomatis (automatic tap water machine) dengan menggunakan wadah dan tutup tanpa merk yang dapat disediakan oleh depot dan/atau dibawa sendiri oleh konsumen.',NULL,NULL,0),
	(350,'11090','INDUSTRI MINUMAN LAINNYA','Kelompok ini mencakup usaha industri minuman lainnya yang tidak termasuk dalam subgolongan 1101 s.d 1105, seperti minuman penyegar, nira, air tebu, air kelapa, minuman sereal panas, serbuk sekoteng, dan serealia celup.',NULL,NULL,0),
	(351,'12011','INDUSTRI SIGARET KRETEK TANGAN','Kelompok ini mencakup usaha pembuatan kretek yang mengandung tembakau rajangan, krosok rajang, cengkeh rajang, dan tambahan bahan-bahan perisa, yang menghasilkan campuran beraroma khas, dilinting dengan berbagai bahan pembungkus (ambri/papir/tipping). Termasuk industri kretek tangan, kretek tangan dan kretek tangan filter.',NULL,NULL,0),
	(352,'12012','INDUSTRI ROKOK PUTIH','Kelompok ini mencakup usaha pembuatan rokok putih yang tidak mengandung komponen cengkeh.',NULL,NULL,0),
	(353,'12013','INDUSTRI SIGARET KRETEK MESIN','Kelompok ini mencakup usaha pembuatan kretek yang mengandung tembakau rajangan, krosok rajang, cengkeh rajang, dan tambahan bahan-bahan perisa, yang menghasilkan campuran beraroma khas, dilinting dengan berbagai bahan pembungkus (ambri/papir/tipping). Termasuk industri kretek mesin.',NULL,NULL,0),
	(354,'12019','INDUSTRI ROKOK LAINNYA','Kelompok ini mencakup usaha pembuatan rokok lainnya, selain kretek atau rokok putih, seperti cerutu, rokok kelembak menyan dan rokok klobot/kawung, tembakau iris (TIS), cerutek, dan hasil pengolahan tembakau lainnya (HPTL). Termasuk industri tembakau pipa, tembakau yang dikunyah dan tembakau sedot (snuff).',NULL,NULL,0),
	(355,'12091','INDUSTRI PENGERINGAN DAN PENGOLAHAN TEMBAKAU','Kelompok ini mencakup usaha pengeringan daun tembakau dengan pengasapan atau dengan cara lain termasuk juga usaha perajangan daun tembakau.',NULL,NULL,0),
	(356,'12099','INDUSTRI BUMBU ROKOK SERTA KELENGKAPAN ROKOK LAINNYA','Kelompok ini mencakup industri pengolahan tembakau yang belum diklasifikasikan ditempat lain, seperti industri homogenisasi atau rekonstitusi tembakau dan tembakau bersaus. Termasuk pembuatan bumbu rokok, serta kelengkapan rokok lainnya, seperti kelembak menyan, saus rokok/tembakau, uwur, klobot, kawung serta pembuatan filter.',NULL,NULL,0),
	(357,'13111','INDUSTRI PERSIAPAN SERAT TEKSTIL','Kelompok ini mencakup usaha persiapan serat tekstil, seperti reeling (pilin/menggulung) dan pencucian serat sutera, degreasasi (penghilangan lemak) dan karbonisasi wol dan pencelupan bulu domba, termasuk proses penyusunan dan penyisiran (carding atau combing) dari serat rambut hewan serat tumbuhan, dan serat buatan (sintetis dan artifisial).',NULL,NULL,0),
	(358,'13112','INDUSTRI PEMINTALAN BENANG','Kelompok ini mencakup usaha pemintalan serat menjadi benang, kecuali benang jahit. Termasuk kegiatan penteksturan, penyimpulan, pelipatan dan pencucian benang rajutan filamen sintetis dan benang artifisial (dari bubur kayu).',NULL,NULL,0),
	(359,'13113','INDUSTRI PEMINTALAN BENANG JAHIT','Kelompok ini mencakup usaha pembuatan benang jahit, baik dengan bahan baku serat maupun benang. termasuk kegiatan penteksturan, penyimpulan, pelipatan dan pencucian benang jahit.',NULL,NULL,0),
	(360,'13121','INDUSTRI PERTENUNAN (BUKAN PERTENUNAN KARUNG GONI DAN KARUNG LAINNYA)','Kelompok ini mencakup usaha pertenunan, baik yang dibuat dengan alat gedogan, alat tenun bukan mesin (ATBM), alat tenun mesin (ATM) ataupun alat tenun lainnya, termasuk pembuatan sarung, kecuali industri kain tenun ikat. Usaha pertenunan karung goni dan karung lainnya dimasukkan dalam kelompok 13925, 13926, 13929.',NULL,NULL,0),
	(361,'13122','INDUSTRI KAIN TENUN IKAT','Kelompok ini mencakup usaha pembuatan kain tenun ikat dan usaha pewarnaan benang dengan cara mengikat terlebih dahulu.',NULL,NULL,0),
	(362,'13123','INDUSTRI BULU TIRUAN TENUNAN','Kelompok ini mencakup usaha pembuatan bulu tiruan dengan penenunan.',NULL,NULL,0),
	(363,'13131','INDUSTRI PENYEMPURNAAN BENANG','Kelompok ini mencakup usaha pengelantangan, pencelupan dan penyempurnaan lainnya untuk benang maupun benang jahit.',NULL,NULL,0),
	(364,'13132','INDUSTRI PENYEMPURNAAN KAIN','Kelompok ini mencakup usaha pengelantangan, pencelupan dan penyempurnaan lainnya untuk kain.',NULL,NULL,0),
	(365,'13133','INDUSTRI PENCETAKAN KAIN','Kelompok ini mencakup usaha pencetakan kain dengan media perantara seperti kasa dan sebagainya, termasuk juga pencetakan kain motif batik.',NULL,NULL,0),
	(366,'13134','INDUSTRI BATIK','Kelompok ini mencakup usaha pembatikan dengan proses malam (lilin), baik yang dilakukan dengan tulis, cap maupun kombinasi antara cap dan tulis.',NULL,NULL,0),
	(367,'13911','INDUSTRI KAIN RAJUTAN','Kelompok ini mencakup usaha pembuatan kain yang dibuat dengan cara rajut seperti handuk, kain ihram, vitrase.',NULL,NULL,0),
	(368,'13912','INDUSTRI KAIN SULAMAN','Kelompok ini mencakup usaha kain sulaman dikerjakan dengan tangan.',NULL,NULL,0),
	(369,'13913','INDUSTRI BULU TIRUAN RAJUTAN','Kelompok ini mencakup usaha pembuatan bulu tiruan rajutan.',NULL,NULL,0),
	(370,'13921','INDUSTRI BARANG JADI TEKSTIL UNTUK KEPERLUAN RUMAH TANGGA','Kelompok ini mencakup usaha pembuatan barang-barang jadi tekstil, seperti selimut, seprei, taplak meja, sarung bantal, bed cover, gorden, handuk, sarung alas kursi, sajadah/penutup lantai yang dibuat dengan proses penggabungan dan/atau penjahitan beberapa bahan tekstil, selubung mobil dan selimut listrik dan lain-lain. Sajadah/penutup lantai dari karpet/permadani dimasukkan dalam kelompok 13930.',NULL,NULL,0),
	(371,'13922','INDUSTRI BARANG JADI TEKSTIL SULAMAN','Kelompok ini mencakup usaha barang jadi tekstil sulaman, baik yang dikerjakan dengan tangan maupun dengan mesin, seperti pakaian/barang jadi sulaman dan badge.',NULL,NULL,0),
	(372,'13923','INDUSTRI BANTAL DAN SEJENISNYA','Kelompok ini mencakup usaha pembuatan bantal dan sejenisnya, seperti bantal dan guling, selimut kapas, selimut bulu angsa, bantal kursi, kantong tidur dan lain-lain dari kapuk, dakron dan sejenisnya.',NULL,NULL,0),
	(373,'13924','INDUSTRI BARANG JADI RAJUTAN DAN SULAMAN','Kelompok ini mencakup usaha pembuatan barang jadi rajutan, seperti kaos lampu, deker, bando.',NULL,NULL,0),
	(374,'13925','INDUSTRI KARUNG GONI','Kelompok ini mencakup usaha pembuatan karung goni.',NULL,NULL,0),
	(375,'13926','INDUSTRI KARUNG BUKAN GONI','Kelompok ini mencakup usaha pembuatan karung bagor (karung terigu/gula blacu) dan karung lainnya. Kecuali pembuatan karung plastik masuk dalam kelompok 22220.',NULL,NULL,0),
	(376,'13929','INDUSTRI BARANG JADI TEKSTIL LAINNYA','Kelompok ini mencakup usaha pembuatan barang jadi tekstil lainnya, seperti layar, tenda, bendera, terpal, parasut, pelampung/jaket penyelamat dan lain-lain: lap pembersih, serbet piring dan barang perlengkapan sejenisnya dan lain-lain.',NULL,NULL,0),
	(377,'13930','INDUSTRI KARPET DAN PERMADANI','Kelompok ini mencakup usaha pembuatan karpet, permadani, sajadah, dan sejenisnya yang terbuat dari serat, baik serat alam, sintetis maupun serat campuran, baik yang dikerjakan dengan proses tenun (woven), tufting, braiding, flocking dan needle punching. Termasuk industri penutup lantai dari lakan atau bulu kempa yang dibuat dengan jarum tenun. Karpet yang terbuat dari bahan-bahan gabus, karet atau plastik masing-masing dimasukkan dalam kelompok 16299, 22191 atau 22210. Sajadah/penutup lantai yang dibuat dengan proses penggabungan dan/atau penjahitan beberapa bahan tekstil dimasukkan dalam kelompok 13921. Kain alas lantai dengan lapisan permukaan keras dimasukkan dalam kelompok 13999.',NULL,NULL,0),
	(378,'13941','INDUSTRI TALI','Kelompok ini mencakup usaha pembuatan berbagai macam tali, baik terbuat dari serat alam maupun serat sintetis atau serat campuran, seperti tali rami, tali goni (yute), tali sisal (agave), tali rafia dan tali nylon.',NULL,NULL,0),
	(379,'13942','INDUSTRI BARANG DARI TALI','Kelompok ini mencakup usaha pembuatan barang-barang dari tali, seperti jaring ikan, jala ikan, tali kapal, tali sepatu, sumbu kompor dan sumbu lampu, baik terbuat dari tali serat alam, tali serat sintetis atau tali serat campuran.',NULL,NULL,0),
	(380,'13991','INDUSTRI KAIN PITA (NARROW FABRIC)','Kelompok ini mencakup usaha pembuatan kain pita, seperti kain pita, renda, kain label, velcro, dan badges.',NULL,NULL,0),
	(381,'13992','INDUSTRI YANG MENGHASILKAN KAIN KEPERLUAN INDUSTRI','Kelompok ini mencakup usaha pembuatan kain dilapisi/ditutupi/diresapi dengan plastik atau karet dan selanjutnya digunakan untuk keperluan industri, seperti kain terpal, kain layar, kain tenda, kain payung, kain kanvas untuk melukis dan kulit imitasi dari media tekstil.',NULL,NULL,0),
	(382,'13993','INDUSTRI NON WOVEN (BUKAN TENUNAN)','Kelompok ini mencakup usaha industri kain yang dibuat tanpa dengan proses anyaman atau perajutan, seperti kain kempa, kain felting dan kain laken. Termasuk industri kain untuk keperluan pelayanan kesehatan manusia, seperti duk operasi (surgical drape); baju, masker, penutup kepala dan perlengkapan non woven lain untuk operasi; dan pembalut luka non woven.',NULL,NULL,0),
	(383,'13994','INDUSTRI KAIN BAN','Kelompok ini mencakup usaha pembuatan kain ban dari benang sintetik kekuatan tinggi, seperti kain ban dari nylon dan kain ban dari polyester.',NULL,NULL,0),
	(384,'13995','INDUSTRI KAPUK','Kelompok ini mencakup usaha pengolahan kapuk.',NULL,NULL,0),
	(385,'13996','INDUSTRI KAIN TULLE DAN KAIN JARING','Kelompok ini mencakup usaha pembuatan kain tulle, kain trikot, kain bordir, dan kain jaring lainnya. Jaring ikan dikelompokkan ke dalam 13942.',NULL,NULL,0),
	(386,'13999','INDUSTRI TEKSTIL LAINNYA YTDL','Kelompok ini mencakup usaha industri tekstil lainnya yang belum/tidak tercakup dalam golongan industri tekstil manapun, seperti benang karet, benang logam dan pipa/selang kain dan lainnya.',NULL,NULL,0),
	(387,'14111','INDUSTRI PAKAIAN JADI (KONVEKSI) DARI TEKSTIL','Kelompok ini mencakup usaha pembuatan pakaian jadi (konveksi) dari tekstil/kain (tenun maupun rajutan) dengan cara memotong dan menjahit sehingga siap dipakai, seperti kemeja, celana, kebaya, blus, rok, baju bayi, pakaian tari dan pakaian olahraga.',NULL,NULL,0),
	(388,'14112','INDUSTRI PAKAIAN JADI (KONVEKSI) DARI KULIT','Kelompok ini mencakup usaha pembuatan pakaian jadi (konveksi) dari kulit atau kulit imitasi, dengan cara memotong dan menjahit sehingga siap pakai, seperti jaket, mantel, rompi, celana dan rok. Termasuk pembuatan aksesori pakaian dari kulit seperti pakaian pekerja las (welder) dari kulit.',NULL,NULL,0),
	(389,'14120','PENJAHITAN DAN PEMBUATAN PAKAIAN SESUAI PESANAN','Kelompok ini mencakup usaha penjahitan dan pembuatan pakaian sesuai pesanan yang melayani masyarakat umum dengan tujuan komersil.',NULL,NULL,0),
	(390,'14131','INDUSTRI PERLENGKAPAN PAKAIAN DARI TEKSTIL','Kelompok ini mencakup usaha pembuatan perlengkapan pakaian jadi (konveksi) tekstil dan dari kain dengan cara memotong dan menjahit sehingga siap dipakai, seperti topi, peci, dasi, sarung tangan, mukena, selendang, kerudung, ikat pinggang, syal, bando, dasi tuksedo, jaring rambut, dan lain-lain, baik dari kain tenun maupun kain rajut yang dijahit. Termasuk industri alas kaki dari bahan kain tanpa sol dan bagian-bagian dari produk yang disebutkan sebelumnya.',NULL,NULL,0),
	(391,'14132','INDUSTRI PERLENGKAPAN PAKAIAN DARI KULIT','Kelompok ini mencakup usaha pembuatan perlengkapan pakaian jadi dari kulit atau kulit imitasi, dengan cara memotong dan menjahit sehingga siap pakai, seperti topi, sarung tangan, ikat pinggang, bando, jaring rambut, dan lain-lain. Termasuk industri penutup kepala dari kulit berbulu dan bagian-bagian dari produk yang disebutkan sebelumnya.',NULL,NULL,0),
	(392,'14200','INDUSTRI PAKAIAN JADI DAN BARANG DARI KULIT BERBULU','Kelompok ini mencakup usaha pembuatan pakaian jadi/barang jadi dari kulit berbulu dan atau perlengkapannya, seperti mantel berbulu, berbagai barang dari kulit berbulu, misalnya gambar, tikar, keset dan barang lain dari kulit berbulu, seperti permadani, pouffes tanpa isi, kain kilap industri.',NULL,NULL,0),
	(393,'14301','INDUSTRI PAKAIAN JADI RAJUTAN','Kelompok ini mencakup usaha pembuatan pakaian jadi, seperti sweater, kardigan, baju kaos, mantel, dan barang sejenisnya, termasuk topi yang dibuat dengan cara dirajut ataupun renda, kecuali industri rajutan kaos kaki.',NULL,NULL,0),
	(394,'14302','INDUSTRI PAKAIAN JADI SULAMAN/BORDIR','Kelompok ini mencakup usaha pakaian jadi sulaman, baik yang dikerjakan dengan tangan maupun dengan mesin.',NULL,NULL,0),
	(395,'14303','INDUSTRI RAJUTAN KAOS KAKI DAN SEJENISNYA','Kelompok ini mencakup usaha pembuatan kaos kaki yang dibuat dengan cara rajut ataupun renda, seperti kaos kaki, termasuk kaos kaki, stocking, pantyhose.',NULL,NULL,0),
	(396,'15111','INDUSTRI PENGAWETAN KULIT','Kelompok ini mencakup usaha pengawetan kulit yang berasal dari hewan besar, hewan kecil, reptil, ikan dan hewan lainnya, baik yang dilakukan dengan pengeringan, penggaraman, maupun pengasaman (pikel), seperti kulit hewan besar (sapi, kerbau), kulit hewan kecil (domba, kambing), kulit reptil (buaya, ular, biawak), kulit ikan (ikan pari,hiu/cucut, kakap, belut) dan kulit hewan lainnya.',NULL,NULL,0),
	(397,'15112','INDUSTRI PENYAMAKAN KULIT','Kelompok ini mencakup usaha penyamakan kulit yang berasal dari ternak besar (sapi, kerbau), ternak kecil (domba, kambing), reptil (buaya, ular, biawak), ikan (ikan pari, hiu cucut, kakap, belut) dan hewan lainnya yang dimasak dengan chrome nabati, sintetis, samak minyak dan samak kombinasi menjadi kulit tersamak, seperti wet blue, crust, sol, vache raam, kulit box, kulit beludru, kulit gelase dan kulit hiasan, kulit berbulu, kulit laminasi, kulit patent, kulit jaket, kulit sarung tangan, kulit chamois dan lainnya.',NULL,NULL,0),
	(398,'15113','INDUSTRI PENCELUPAN KULIT BULU','Kelompok ini mencakup usaha pemberian warna atau pencelupan pada kulit bulu yang digunakan pada barang jadi kulit.',NULL,NULL,0),
	(399,'15114','INDUSTRI KULIT KOMPOSISI','Kelompok ini mencakup usaha pembuatan kulit komposisi yang berasal dari potongan/remahan kulit hewan yang direkatkan kembali. Industri kulit buatan/imitasi yang berbahan utama tekstil dimasukkan dalam kelompok 13992. Industri kulit buatan/imitasi yang berbahan utama karet dimasukkan dalam kelompok 2219; dan industri kulit buatan/imitasi yang berbahan utama plastik dimasukkan dalam kelompok 2229.',NULL,NULL,0),
	(400,'15121','INDUSTRI BARANG DARI KULIT DAN KULIT KOMPOSISI UNTUK KEPERLUAN PRIBADI','Kelompok ini mencakup usaha pembuatan barang-barang dari kulit dan kulit komposisi atau bahan lain seperti plastik, tekstil, serat yang divulkanisir atau paperboard untuk keperluan pribadi, seperti koper, ransel, tas, dompet, kotak rias, sarung senjata, tempat kaca mata dan tali jam. Termasuk industri tali sepatu kulit.',NULL,NULL,0),
	(401,'15122','INDUSTRI BARANG DARI KULIT DAN KULIT KOMPOSISI UNTUK KEPERLUAN TEKNIK/INDUSTRI','Kelompok ini mencakup usaha pembuatan barang-barang dari kulit dan kulit komposisi untuk keperluan teknik/industri, seperti klep, packing, rem pickers, sarung tangan kerja, kulit pompa, kulit ban mesin (belt), kulit apron dan sisir kulit pada mesin (combing leather).',NULL,NULL,0),
	(402,'15123','INDUSTRI BARANG DARI KULIT DAN KULIT KOMPOSISI UNTUK KEPERLUAN HEWAN','Kelompok ini mencakup usaha pembuatan barang-barang dari kulit dan kulit komposisi untuk keperluan hewan, seperti ikat leher hewan, tali kekang hewan, pelana hewan, brongsong mulut hewan, cambuk dan sepatu hewan.',NULL,NULL,0),
	(403,'15129','INDUSTRI BARANG DARI KULIT DAN KULIT KOMPOSISI UNTUK KEPERLUAN LAINNYA','Kelompok ini mencakup usaha pembuatan barang-barang dari kulit dan kulit komposisi untuk keperluan yang belum terliput dalam kelompok 15121 sampai dengan 15123, seperti jok, sabuk pengaman, alat pengepak dan kerajinan tatah sungging (hiasan, wayang dan kap lampu) dan lain-lain.',NULL,NULL,0),
	(404,'15201','INDUSTRI ALAS KAKI UNTUK KEPERLUAN SEHARI-HARI','Kelompok ini mencakup usaha pembuatan alas kaki keperluan sehari-hari dari kulit dan kulit buatan, karet, kanvas dan kayu, seperti sepatu harian, sepatu santai (casual shoes), sepatu sandal, sandal kelom dan selop. Termasuk juga usaha pembuatan bagian-bagian dari alas kaki tersebut, seperti atasan, sol dalam, sol luar, penguat depan, penguat tengah, penguat belakang, lapisan dan aksesori dari kulit dan kulit buatan.',NULL,NULL,0),
	(405,'15202','INDUSTRI SEPATU OLAHRAGA','Kelompok ini mencakup usaha pembuatan sepatu untuk olahraga dari kulit dan kulit buatan, karet dan kanvas, seperti sepatu sepak bola, sepatu atletik, sepatu senam, sepatu jogging dan sepatu ballet. Termasuk juga usaha pembuatan bagian bagian dari sepatu olahraga tersebut, meliputi atasan, sol luar, sol dalam, lapisan dan aksesori.',NULL,NULL,0),
	(406,'15203','INDUSTRI SEPATU TEKNIK LAPANGAN/KEPERLUAN INDUSTRI','Kelompok ini mencakup usaha pembuatan sepatu termasuk pembuatan bagian-bagian dari sepatu untuk keperluan teknik lapangan/industri dari kulit, kulit buatan, karet dan plastik, seperti sepatu tahan kimia, sepatu tahan panas, sepatu pengaman.',NULL,NULL,0),
	(407,'15209','INDUSTRI ALAS KAKI LAINNYA','Kelompok ini mencakup usaha pembuatan alas kaki lainnya yang belum termasuk golongan manapun, seperti sepatu kesehatan dan sepatu lainnya, misalnya sepatu dari gedebog (pelepah batang pisang) dan eceng gondok. Termasuk industri gaiter, legging dan barang sejenisnya.',NULL,NULL,0),
	(408,'16101','INDUSTRI PENGGERGAJIAN KAYU','Kelompok ini mencakup usaha penggergajian, pengirisan, pengulitan dan pemotongan kayu gelondongan menjadi balok, kaso (usuk), reng, papan dan sebagainya. Termasuk industri kayu untuk bantalan rel kereta dan bahan baku untuk pembuatan lantai kayu.',NULL,NULL,0),
	(409,'16102','INDUSTRI PENGAWETAN KAYU','Kelompok ini mencakup usaha pengawetan kayu dengan cara pengeringan kayu, pengolahan kimia dan perendaman kayu dengan bahan pengawet atau bahan lainnya.',NULL,NULL,0),
	(410,'16103','INDUSTRI PENGAWETAN ROTAN, BAMBU DAN SEJENISNYA','Kelompok ini mencakup usaha pengawetan rotan, bambu dan sejenisnya.',NULL,NULL,0),
	(411,'16104','INDUSTRI PENGOLAHAN ROTAN','Kelompok ini mencakup usaha pengolahan rotan menjadi bahan setengah jadi, seperti rotan poles, hati rotan dan kulit rotan.',NULL,NULL,0),
	(412,'16105','INDUSTRI PARTIKEL KAYU DAN SEJENISNYA','Kelompok ini mencakup usaha pembuatan partikel kayu dan sejenisnya seperti wol kayu, tepung kayu, dan irisan atau serpih kayu (woodchips).',NULL,NULL,0),
	(413,'16211','INDUSTRI KAYU LAPIS','Kelompok ini mencakup usaha pembuatan kayu lapis biasa, seperti kayu lapis tripleks, multipleks, kayu lapis interior, eksterior dan sejenisnya. Termasuk juga kayu lapis konstruksi, seperti kayu lapis cetak beton, kayu lapis tahan air dan sejenisnya.',NULL,NULL,0),
	(414,'16212','INDUSTRI KAYU LAPIS LAMINASI, TERMASUK DECORATIVE PLYWOOD','Kelompok ini mencakup usaha pembuatan kayu lapis yang dilaminasi, seperti teak wood, rose wood, polyester plywood dan sejenisnya. Termasuk juga bambu lapis yang dilaminasi.',NULL,NULL,0),
	(415,'16213','INDUSTRI PANEL KAYU LAINNYA','Kelompok ini mencakup usaha pembuatan panel kayu lainnya, seperti particle board, chip board, fibre board, Medium Density Fibreboard (MDF) dan sejenisnya.',NULL,NULL,0),
	(416,'16214','INDUSTRI VENEER','Kelompok ini mencakup usaha pembuatan serutan pelapis (veneer) dengan cara pengupasan (rotary), penyayatan (slicer) dan sejenisnya.',NULL,NULL,0),
	(417,'16215','INDUSTRI KAYU LAMINASI','Kelompok ini mencakup industri kayu laminasi seperti barecore, blockboard, dan lamin board.',NULL,NULL,0),
	(418,'16221','INDUSTRI BARANG BANGUNAN DARI KAYU','Kelompok ini mencakup industri komponen bahan bangunan dari kayu yang digunakan utamanya untuk industri konstruksi, seperti balok, kaso, rangka atap yang dihaluskan keempat sisinya; tiang penopang yang dibuat dari kayu secara bilah sambung (finger joint) dengan perekat atau dihubungkan dengan logam (metal); profil dan moulding kayu, daun pintu/jendela dan rangkanya (kusen), tangga dan susuran tangga, manik-manik dari kayu dan papan penghias tembok dan papan nama; atap sirap, lantai kayu siap pasang yang terbuat dari kayu solid (solid wood) atau engineering wood; serta pengerjaan kayu untuk bahan bangunan lainnya.',NULL,NULL,0),
	(419,'16222','INDUSTRI BANGUNAN PRAFABRIKASI DARI KAYU','Kelompok ini mencakup usaha pengerjaan kayu untuk bangunan prafabrikasi. Termasuk industri rumah bergerak dan partisi kayu (tidak termasuk penyekat ruangan yang berdiri sendiri/furnitur)',NULL,NULL,0),
	(420,'16230','INDUSTRI WADAH DARI KAYU','Kelompok ini mencakup usaha pembuatan segala macam wadah atau peti/kotak dari kayu untuk pengemasan, seperti kotak kemas, boks, peti kayu, drum kayu dan kemasan sejenisnya dari kayu; palet (pallets), kotak palet dan papan muat dari kayu lainnya; barel, tong, ember dan produk dari kayu lainnya; dan gulungan kawat dari kayu.',NULL,NULL,0),
	(421,'16291','INDUSTRI BARANG ANYAMAN DARI ROTAN DAN BAMBU','Kelompok ini mencakup usaha pembuatan macam-macam tikar, webbing, lampit, tas, topi, tampah, kukusan, bakul, kipas, tatakan, bilik/gedek dan sejenisnya yang bahan utamanya dari rotan atau bambu.',NULL,NULL,0),
	(422,'16292','INDUSTRI BARANG ANYAMAN DARI TANAMAN BUKAN ROTAN DAN BAMBU','Kelompok ini mencakup usaha pembuatan macam-macam tikar, keset, tas, topi, tatakan dan kerajinan tangan lainnya yang bahan utamanya bukan rotan dan bambu, seperti pandan, mendong, serat, rumput dan sejenisnya.',NULL,NULL,0),
	(423,'16293','INDUSTRI KERAJINAN UKIRAN DARI KAYU BUKAN MEBELLER','Kelompok ini mencakup usaha pembuatan macam-macam barang kerajinan dan ukir- ukiran dari kayu, seperti relief, topeng, patung, wayang, vas bunga, pigura dan kap lampu.',NULL,NULL,0),
	(424,'16294','INDUSTRI ALAT DAPUR DARI KAYU, ROTAN DAN BAMBU','Kelompok ini mencakup usaha pembuatan alat-alat dapur yang bahan utamanya kayu, bambu, dan rotan, seperti rak piring, rak bumbu masak, parutan, alu, lesung, talenan, cobek, dan sejenisnya.',NULL,NULL,0),
	(425,'16295','INDUSTRI KAYU BAKAR DAN PELET KAYU','Kelompok ini mencakup industri kayu bakar dan pelet kayu yang dibuat dari serbuk kayu atau bahan substitusi seperti ampas kopi atau biji kedelai yang dipres.',NULL,NULL,0),
	(426,'16299','INDUSTRI BARANG DARI KAYU, ROTAN, GABUS LAINNYA YTDL','Kelompok ini mencakup usaha pembuatan barang-barang dari kayu, rotan dan gabus lainnya yang belum tercakup sebelumnya. Barang-barang dari kayu misalnya alat tenun, gantungan baju, chopstik, tusuk gigi, sempoa (alat hitung), penggaris dan papan tulis. Termasuk juga pembuatan alat-alat kerja dari kayu, seperti plesteran, palu, rumah serutan kayu, gagang pegangan perkakas, palet, papan cucian dan sejenisnya. Barang dari gabus misalnya gabus lembaran, sumbat, piringan, cincin, pelapis, pelampung dan lainnya.',NULL,NULL,0),
	(427,'17011','INDUSTRI BUBUR KERTAS (PULP)','Kelompok ini mencakup usaha pembuatan bubur kertas dengan bahan dari kayu atau serat lainnya dan atau kertas bekas. Kegiatannya mencakup industri bubur kertas yang diputihkan, separuh putihkan atau yang tidak diputihkan baik melalui proses mekanis, kimia (pelarutan atau non pelarutan), maupun semi kimia, industri bubur kertas cotton- linters dan penghilangan tinta dan industri bubur kertas dari kertas bekas.',NULL,NULL,0),
	(428,'17012','INDUSTRI KERTAS BUDAYA','Kelompok ini mencakup usaha pembuatan kertas koran dan kertas tulis cetak.',NULL,NULL,0),
	(429,'17013','INDUSTRI KERTAS BERHARGA','Kelompok ini mencakup usaha pembuatan kertas bandrol, bank notes, cheque paper, security paper, watermark paper, meterai, perangko dan sejenisnya.',NULL,NULL,0),
	(430,'17014','INDUSTRI KERTAS KHUSUS','Kelompok ini mencakup usaha pembuatan kertas khusus, seperti cardiopan, kertas litmus/lakmus, metalic paper, acid proof paper, kertas pola, kertas tersalut, kertas celopan dan sejenisnya. Pengerjaan kertas yang melapisi dengan segala cara, seperti coating, glazing, gumming, dan laminating serta pembuatan kertas karbon dan stensil dimasukkan dalam kelompok 17099, jika dalam bentuk potongan siap dijual ke konsumen. Pembuatan kertas fotografi dimasukkan dalam kelompok 20299. Pembuatan kertas penggosok/amplas (abrasive paper) dimasukkan dalam kelompok 23990.',NULL,NULL,0),
	(431,'17019','INDUSTRI KERTAS LAINNYA','Kelompok ini mencakup usaha pembuatan kertas magnetik, kertas kerut (crep) dan gumpalan selulosa dan webs serat selulosa.',NULL,NULL,0),
	(432,'17021','INDUSTRI KERTAS DAN PAPAN KERTAS BERGELOMBANG','Kelompok ini mencakup usaha pembuatan kertas konstruksi (kertas isolasi, condensor, roofing board, building board dan lain-lain), kertas bungkus dan pengepakan (kraftliner, medium liner/corrugating medium, ribbed kraft paper/kertas payung, kraft paper), board (post card karthotek, kertas londen, triplex, multiplex, bristol, straw board, chip board, duplex).',NULL,NULL,0),
	(433,'17022','INDUSTRI KEMASAN DAN KOTAK DARI KERTAS DAN KARTON','Kelompok ini mencakup usaha pembuatan segala macam kemasan dan kotak dari kertas/karton yang digunakan untuk pembungkus/pengepakan, termasuk juga pembuatan kotak untuk rokok dan barang lainnya. Misalnya kemasan dan kotak dari kertas dan papan kertas bergelombang, kemasan dan kotak papan kertas yang dapat dilipat, kemasan dan kotak dari papan padat, kemasan dan kotak lain dari kertas dan papan kertas, sak dan kantong kertas dan kotak file kantor dan barang sejenisnya.',NULL,NULL,0),
	(434,'17091','INDUSTRI KERTAS TISSUE','Kelompok ini mencakup usaha pembuatan kertas untuk kertas rumah tangga, kertas kebersihan pribadi dan barang kertas kapas selulosa, seperti tisu pembersih, facial tissue, toilet tissue, lens tissue, sapu tangan, handuk, serbet, kertas toilet, napkin, napkin untuk bayi, sanitary napkin (pembalut wanita), tampon, popok dewasa, dan napkin untuk cangkir, piring dan baki dan usaha pembuatan kertas kapas dan barang dari kertas kapas, seperti handuk/lap, kertas sigaret dan cork tipping paper.',NULL,NULL,0),
	(435,'17099','INDUSTRI BARANG DARI KERTAS DAN PAPAN KERTAS LAINNYA YTDL','Kelompok ini mencakup usaha pembuatan barang dari kertas dan papan kertas atau karton yang belum tercakup dalam subgolongan lain, seperti industri kertas tulis dan kertas cetak siap pakai, industri kertas printout komputer siap pakai, industri kertas kopi siap pakai, industri kertas tempel atau berperekat siap pakai, industri buku register, buku akuntansi, binder, album dan alat-alat tulis baik yang bersifat komersil atau untuk pendidikan sejenisnya, industri kotak, kantong, dompet dan buku catatan yang mengandung susunan kertas, industri wallpaper (kertas dinding) dan jenis pelapis dinding lainnya, termasuk wallpaper berlapis vinyl dan tekstil, industri label, industri kertas filter dan papan kertas filter, industri gulungan kertas dan papan kertas, gelendong kertas dan papan kertas dan sebagainya, industri tempat telur dan barang lainnya yang dibuat dari cetakan bubur kertas dan sebagainya, dan industri kertas kreasi baru. Termasuk di sini pengerjaan kertas dan karton dengan segala cara, seperti coating, glazing, gumming, laminating, pembuatan kertas karbon dan kertas stensil sheet dalam bentuk potongan siap dijual ke konsumen. Termasuk juga pembuatan kertas EKG dan pembuatan alat tulis kantor (stationeries) yang tidak dicetak, seperti amplop, kertas surat, kertas pembersih, dinner ware dari kertas dan sejenisnya. Pembuatan alat tulis kantor dan kartu yang dicetak dimasukkan dalam kelompok 18111.',NULL,NULL,0),
	(436,'18111','INDUSTRI PENCETAKAN UMUM','Kelompok ini mencakup kegiatan industri percetakan surat kabar, majalah dan periodik lainnya seperti tabloid, surat kabar, majalah, jurnal, pamflet, buku dan brosur, naskah musik, peta, atlas, poster, katalog periklanan, prospektus dan iklan cetak lainnya, buku harian, kalender, formulir bisnis dan barang-barang cetakan komersial lainnya, kertas surat atau alat tulis pribadi dan barang-barang cetakan lainnya hasil mesin cetak, offset, klise foto, fleksografi dan sejenisnya, mesin pengganda, printer komputer, huruf timbul dan sebagainya termasuk alat cetak cepat; pencetakan secara langsung tanpa adanya media perantara ke bahan tekstil, plastik, kaca, logam, kayu dan keramik, kecuali pencetakan tabir sutera pada kain dan pakaian jadi; dan pencetakan pada label atau tanda pengenal (litografi, pencetakan tulisan di makam, pencetakan fleksografi dan sebagainya). Termasuk pula mencetak ulang melalui komputer, mesin stensil dan sejenisnya. Barang cetakan ini biasanya merupakan hak cipta. Industri label kertas atau karton termasuk kelompok 17099.',NULL,NULL,0),
	(437,'18112','INDUSTRI PENCETAKAN KHUSUS','Kelompok ini mencakup industri pencetakan perangko pos, perangko perpajakan, dokumen, cek dan kertas rahasia lainnya, materai, uang kertas, blangko cek, giro, surat andil, obligasi surat saham, surat berharga lainnya, paspor, tiket pesawat terbang dan cetakan khusus lainnya.',NULL,NULL,0),
	(438,'18113','INDUSTRI PENCETAKAN 3D PRINTING','Kelompok ini mencakup industri percetakan tiga dimensi (3D Printing) untuk berbagai keperluan dari polimer, plastik, clay, bijih logam dan lainnya.',NULL,NULL,0),
	(439,'18120','KEGIATAN JASA PENUNJANG PENCETAKAN','Kelompok ini mencakup usaha penjilidan lembar cetakan, misalnya menjadi buku, brosur, majalah, katalog dan sebagainya, dengan melipat, memasang, menjahit, merekatkan, menyatukan, penjilidan dengan perekat, perapihan dan gold stamping; produksi composed type, plates atau cylinders, penjilidan buku; komposisi, pemasangan huruf, pemasangan foto, input data mencakup scanning dan pengenalan karakter atau huruf optik, penyusunan elektronik; pembuatan gambar mencakup pemasangan image atau gambar (untuk proses pencetakan mesin cetak dan offset); pengukiran atau sketsa cylinders untuk gravure; proses pembuatan gambar langsung di atas pelat (temasuk pelat fotopolimer); pembuatan gambar untuk pencetakan dan pengecapan relief; pembuatan cetakan untuk percobaan; pekerjaan artistik mencakup penyiapan batu litho dan woodblocks (produksi batu lithographic, untuk digunakan dalam kegiatan percetakan di unit lain); pembuatan barang reprografi; desain barang cetakan seperti sketsa, layout, barang contoh dan sebagainya; dan kegiatan grafis lainnya seperti die-sinking dan die-stamping, penggandaan huruf braille, pemukulan dan pengeboran, penyulaman timbul, pemvernisan dan pelapisan, penyisipan dan pelipatan.',NULL,NULL,0),
	(440,'18201','REPRODUKSI MEDIA REKAMAN SUARA DAN PIRANTI LUNAK','Kelompok ini mencakup usaha reproduksi dari kopi master pelat atau piringan gramofon, compact disk atau CD dan pita yang berisikan musik atau rekaman suara (audio) dan reproduksi dari kopi master perangkat lunak atau software dan data pada disk dan pita magnetik. Pembuatan piringan hitam kosong, pita kaset kosong, pita komputer dan disket kosong untuk merekam data dimasukkan dalam kelompok 26800. Industri rekaman suara di piringan hitam, pita kaset dan sejenisnya dimasukkan dalam kelompok 59201.',NULL,NULL,0),
	(441,'18202','REPRODUKSI MEDIA REKAMAN FILM DAN VIDEO','Kelompok ini mencakup usaha reproduksi dari kopi master rekaman, compact disk\n         atau CD dan tape yang berisikan gambar bergerak atau film dan rekaman video\n         lainnya. Penerbitan rekaman film dan video dimasukkan dalam kelompok 59131 dan\n         59132.',NULL,NULL,0),
	(442,'19100','INDUSTRI PRODUK DARI BATU BARA','Kelompok ini mencakup usaha industri pengolahan gas, kokas dari batu bara, termasuk juga destilasi batu bara yang bukan merupakan bagian pabrik gas atau besi dan baja, atau destilasi batu bara yang menjadi bagian pabrik besi dan baja yang pembukuannya dapat dipisahkan. Termasuk pengoperasian tungku kokas, produksi kokas dan semi kokas, produksi pitch kokas, produksi kokas mentah dan ter lignit dan pengaglomerasian kokas. Usaha destilasi gas oleh pabrik gas yang penyalurannya melalui pipa saluran dimasukkan dalam kelompok 35202. Usaha pembuatan gas dan kokas yang tergabung dalam kegiatan pengolahan besi dan baja dimasukkan dalam kelompok 24101 sampai dengan 24103.',NULL,NULL,0),
	(443,'19211','INDUSTRI BAHAN BAKAR DARI PEMURNIAN DAN PENGILANGAN MINYAK BUMI','Kelompok ini mencakup usaha pemurnian dan pengilangan minyak bumi yang menghasilkan bahan bakar seperti Avigas, Avtur, Gasoline, Minyak Tanah atau Kerosin, Minyak Solar, Minyak Diesel, Minyak Bakar atau Bensin, Solvent/Pelarut, termasuk LPG dari hasil pengilangan minyak bumi.',NULL,NULL,0),
	(444,'19212','INDUSTRI PEMBUATAN MINYAK PELUMAS','Kelompok ini mencakup usaha pembuatan minyak pelumas, oli dan gemuk yang berbahan dasar minyak.',NULL,NULL,0),
	(445,'19213','INDUSTRI PENGOLAHAN KEMBALI MINYAK PELUMAS BEKAS','Kelompok ini mencakup usaha pengolahan kembali minyak pelumas bekas untuk dapat digunakan sebagai minyak pelumas.',NULL,NULL,0),
	(446,'19214','INDUSTRI PENGOLAHAN MINYAK PELUMAS BEKAS MENJADI BAHAN BAKAR','Kelompok ini mencakup usaha pengolahan kembali minyak pelumas bekas untuk dapat digunakan sebagai bahan bakar minyak.',NULL,NULL,0),
	(447,'19291','INDUSTRI PRODUK DARI HASIL KILANG MINYAK BUMI','Kelompok ini mencakup usaha industri pengolahan aspal/ter, bitumen dan lilin (dapat digunakan untuk lapisan jalan, atap, kayu, kertas dan sebagainya) serta Petroleum Coke. Termasuk industri produk untuk industri petrokimia, industri bermacam-macam produk, seperti white spirit, vaseline, lilin parafin, jeli minyak bumi (petroleum jelly), industri briket minyak bumi dan pencampuran biofuel, seperti pencampuran alkohol dengan minyak bumi (misalnya gasohol).',NULL,NULL,0),
	(448,'19292','INDUSTRI BRIKET BATU BARA','Kelompok ini mencakup usaha pembuatan briket dari batu bara atau lignit, baik di lokasi penambangan maupun di luar lokasi penambangan. Termasuk pula pembuatan briket yang menggunakan batu bara atau lignit yang dibeli dari pihak lain.',NULL,NULL,0),
	(449,'20111','INDUSTRI KIMIA DASAR ANORGANIK KHLOR DAN ALKALI','Kelompok ini mencakup usaha industri kimia dasar yang menghasilkan bahan kimia khlor dan alkali, seperti soda kostik, soda abu, natrium khlorida, kalium hidroksida dan senyawa khlor lainnya. Termasuk juga usaha industri yang menghasilkan logam alkali, seperti lithium, natrium dan kalium, serta senyawa alkali lainnya. Industri pembuatan garam dapur/konsumsi dimasukkan dalam kelompok 10774.',NULL,NULL,0),
	(450,'20112','INDUSTRI KIMIA DASAR ANORGANIK GAS INDUSTRI','Kelompok ini mencakup usaha industri kimia dasar yang menghasilkan bahan kimia gas industri, seperti zat asam, zat lemas, zat asam arang, amoniak dan dry ice. Termasuk juga usaha industri kimia dasar yang menghasilkan gas mulia, seperti helium, neon, argon dan radon; serta jenis-jenis gas industri lainnya.',NULL,NULL,0),
	(451,'20113','INDUSTRI KIMIA DASAR ANORGANIK PIGMEN','Kelompok ini mencakup usaha industri kimia dasar yang menghasilkan bahan anorganik pigment, seperti meni merah, chrome yellow, zinc yellow, barium sulphate, pigmen serbuk aluminium, oker dan pigment dengan dasar titanium.',NULL,NULL,0),
	(452,'20114','INDUSTRI KIMIA DASAR ANORGANIK LAINNYA','Kelompok ini mencakup usaha industri kimia dasar anorganik yang belum tercakup dalam golongan industri kimia dasar anorganik di atas, seperti fosfor dengan turunannya, belerang dengan turunannya, nitrogen dengan turunannya, dan industri kimia dasar yang menghasilkan senyawa halogen dengan turunannya, logam kecuali logam alkali, senyawa oksida kecuali pigmen. Termasuk industri bahan baku untuk bahan peledak.',NULL,NULL,0),
	(453,'20115','INDUSTRI KIMIA DASAR ORGANIK YANG BERSUMBER DARI HASIL PERTANIAN','Kelompok ini mencakup usaha industri kimia organik yang menghasilkan bahan kimia dari hasil pertanian termasuk kayu, getah (gum), minyak nabati industri (IVO) dengan produk antara lain: asam alufamat, asam asetat, asam citrat, asam benzoat, fatty acid, fatty alcohol, glycerine, furfural, sarbitol, dan bahan kimia organik lainnya dari hasil pertanian. Kelompok ini juga mencakup pembuatan biofuel, arang kayu, arang batok kelapa dengan produk: biofuel cair (biodiesel dan bioethanol anhidrat), biohidrokarbon (minyak diesel nabati, minyak bensin nabati, minyak avtur/jet fuel nabati) dan bahan kimia resin/damar buatan berbasis bahan terbarukan (biobenzene, biotoluene dan bioxylene dan biopolymer - bioplastik dari bahan terbarukan).',NULL,NULL,0),
	(454,'20116','INDUSTRI KIMIA DASAR ORGANIK UNTUK BAHAN BAKU ZAT WARNA DAN PIGMEN, ZAT WARNA DAN PIGMEN','Kelompok ini mencakup usaha industri kimia dasar yang menghasilkan bahan kimia organik, zat warna dan pigment dengan hasil antara siklisnya, seperti hasil antara phenol dan turunannya, zat warna tekstil dan zat warna untuk makanan dan obat- obatan.',NULL,NULL,0),
	(455,'20117','INDUSTRI KIMIA DASAR ORGANIK YANG BERSUMBER DARI MINYAK BUMI, GAS ALAM DAN BATU BARA','Kelompok ini mencakup usaha industri kimia dasar organik yang menghasilkan bahan kimia, yang bahan bakunya berasal dari minyak bumi dan gas bumi maupun batu bara, seperti ethylene, propilene, benzena, toluena, caprolactam termasuk pengolahan coaltar.',NULL,NULL,0),
	(456,'20118','INDUSTRI KIMIA DASAR ORGANIK YANG MENGHASILKAN BAHAN KIMIA KHUSUS','Kelompok ini mencakup usaha industri kimia dasar organik yang menghasilkan bahan kimia khusus, seperti bahan kimia khusus untuk minyak dan gas bumi, pengolahan air, karet, kertas, konstruksi, otomotif, bahan tambahan makanan (food additive), tekstil, kulit, elektronik, katalis, minyak rem (brake fluid), serta bahan kimia khusus lainnya.',NULL,NULL,0),
	(457,'20119','INDUSTRI KIMIA DASAR ORGANIK LAINNYA','Kelompok ini mencakup usaha industri Kimia Dasar Organik yang belum tercakup dalam golongan Industri Kimia Dasar Organik, seperti plasticizer, bahan untuk bahan baku pestisida, zat aktif permukaan, bahan pengawet.',NULL,NULL,0),
	(458,'20121','INDUSTRI PUPUK ALAM/NON SINTETIS HARA MAKRO PRIMER','Kelompok ini mencakup usaha pembuatan pupuk hara makro primer jenis pupuk alam seperti pupuk fosfat alam (pupuk alam anorganik).',NULL,NULL,0),
	(459,'20122','INDUSTRI PUPUK BUATAN TUNGGAL HARA MAKRO PRIMER','Kelompok ini mencakup usaha pembuatan pupuk hara makro primer jenis pupuk buatan tunggal seperti urea, ZA, TSP, DSP dan Kalsium Sulfat. Termasuk juga pembuatan gas CO2, asam sulfat, amoniak, asam fosfat, asam nitrat dan lain-lain yang berkaitan dengan pembuatan pupuk dan tidak dapat dilaporkan secara terpisah.',NULL,NULL,0),
	(460,'20123','INDUSTRI PUPUK BUATAN MAJEMUK HARA MAKRO PRIMER','Kelompok ini mencakup usaha pembuatan pupuk yang mengandung minimal 2 unsur hara makro primer melalui proses reaksi kimia seperti Mono Amonium Fosfat (pupuk buatan majemuk nitrogen fosfat), Kalium Amonium Khlorida (pupuk buatan majemuk nitrogen kalium), Kalium Metafosfat (pupuk buatan majemuk fosfat kalium) dan Amonium Kalium Fosfat (pupuk buatan majemuk nitrogen fosfat kalium). Total kandungan unsur hara makro primer minimal 10 persen sampai dengan 30 persen.',NULL,NULL,0),
	(461,'20124','INDUSTRI PUPUK BUATAN CAMPURAN HARA MAKRO PRIMER','Kelompok ini mencakup usaha pembuatan pupuk yang mengandung minimal 2 unsur hara makro primer melalui pencampuran pupuk secara fisik tanpa merubah sifat kimia dan sifat pupuk aslinya. Total kandungan unsur hara makro primer minimal 10 persen.',NULL,NULL,0),
	(462,'20125','INDUSTRI PUPUK HARA MAKRO SEKUNDER','Kelompok ini mencakup usaha pembuatan pupuk yang mengandung unsur hara makro sekunder jenis Ca, Mg, dan S seperti Kiserit (Mg, S), Oksida Magnio (Mg).',NULL,NULL,0),
	(463,'20126','INDUSTRI PUPUK HARA MIKRO','Kelompok ini mencakup usaha pembuatan pupuk yang mengandung unsur hara mikro seperti Seng, Besi, Tembaga, Mangan, Boron dan Molybdenum.',NULL,NULL,0),
	(464,'20127','INDUSTRI PUPUK PELENGKAP','Kelompok ini mencakup usaha pembuatan pupuk yang mengandung mikro organisme atau formula pupuk yang berasal dari hasil samping industri yang mempunyai kandungan hara mikro sebagai komponen utama serta mengandung total unsur hara makro primer dalam jumlah rendah sampai sedang (kurang dari 30 persen).',NULL,NULL,0),
	(465,'20128','INDUSTRI MEDIA TANAM','Kelompok ini mencakup usaha pembuatan media tanam dengan tanah gemuk/gambut sebagai unsur pokok. Termasuk juga usaha pembuatan media tanam campuran dari tanah alami, pasir, tanah liat dan mineral.',NULL,NULL,0),
	(466,'20129','INDUSTRI PUPUK LAINNYA','Kelompok ini mencakup usaha pembuatan pupuk yang belum termasuk dalam kelompok manapun.',NULL,NULL,0),
	(467,'20131','INDUSTRI DAMAR BUATAN (RESIN SINTETIS) DAN BAHAN BAKU PLASTIK','Kelompok ini mencakup usaha pembuatan damar buatan dan bahan baku plastik (bijih plastik murni), seperti alkid, poliester, aminos, poliamid, epoksid, silikon, poliuretan, polietilen (PE), polipropilen (PP), polistiren, polivinil klorid, selulosa asetat dan selulosa nitrat. Pengolahan lanjutan dari damar buatan dan bahan plastik yang dibeli untuk menghasilkan barang dari bahan baku tersebut, seperti barang plastik, film dan lembaran film yang belum peka terhadap sinar dimasukkan dalam kelompok 26800.',NULL,NULL,0),
	(468,'20132','INDUSTRI KARET BUATAN','Kelompok ini mencakup usaha pembuatan karet buatan, seperti styrene butadiene rubber (SBR), polychloroprene (neoprene), acrylonitrile butadine rubber (nitrile rubber), silicone rubber (polysiloxane) dan isoprene rubber.',NULL,NULL,0),
	(469,'20211','INDUSTRI BAHAN BAKU PEMBERANTAS HAMA (BAHAN AKTIF)','Kelompok ini mencakup usaha pembuatan bahan baku untuk pestisida, seperti buthyl phenyl methyl carbamat (BPMC), methyl isopropyl carbamat (MIPC), diazinon, carbofuran, glyphosate, monocrotophos, arsentrioxyde dan copper sulphate.',NULL,NULL,0),
	(470,'20212','INDUSTRI PEMBERANTAS HAMA (FORMULASI)','Kelompok ini mencakup usaha pengolahan bahan aktif menjadi pemberantas hama (pestisida) dalam bentuk siap dipakai seperti insektisida, fungisida, rodentisida, herbisida, nematisida, molusida dan akarisida. Termasuk juga pembuataan disinfektan untuk pertanian dan kegunaan lainnya.',NULL,NULL,0),
	(471,'20213','INDUSTRI ZAT PENGATUR TUMBUH','Kelompok ini mencakup usaha pengolahan bahan kimia menjadi zat pengatur tumbuh, seperti atonik, ethrel, cepha, dekamon, mixtalol, hidrasil dan sitozim.',NULL,NULL,0),
	(472,'20214','INDUSTRI BAHAN AMELIORAN (PEMBENAH TANAH)','Kelompok ini mencakup usaha pembuatan bahan amelioran (pembenah tanah) seperti kapur pertanian, kapur fosfat, dolomit, zeolit dan bahan amelioran yang mengandung bahan organik.',NULL,NULL,0),
	(473,'20221','INDUSTRI CAT DAN TINTA CETAK','Kelompok ini mencakup usaha pembuatan macam-macam cat, seperti cat dasar, cat logam, cat kayu, cat tembok, cat kapal, cat epoksi dan email dan lacquer. Termasuk Industri pigmen dan bahan celup olahan, pewarna dan opacifier (pembuat tidak jelas), industri email pengkilap dan pelapis dan preparat sejenisnya, tinta cetak dan cat untuk melukis.',NULL,NULL,0),
	(474,'20222','INDUSTRI PERNIS (TERMASUK MASTIK)','Kelompok ini mencakup usaha pembuatan berbagai macam pernis, seperti pelarut komposit organik dan tiner dan penghapus cat atau pernis. Termasuk Mastik.',NULL,NULL,0),
	(475,'20223','INDUSTRI LAK','Kelompok ini mencakup usaha pembuatan lak. Termasuk industri dempul dan plamur atau senyawa dempul dan dempul non refraktori atau bahan penutup permukaan sejenis.',NULL,NULL,0),
	(476,'20231','INDUSTRI SABUN DAN BAHAN PEMBERSIH KEPERLUAN RUMAH TANGGA','Kelompok ini mencakup usaha pembuatan sabun (selain sabun yang tercakup dalam kelompok 20232) dalam berbagai bentuk, baik padat, bubuk, cream atau cair, industri pembuatan deterjen dan bahan pembersih rumah tangga lainnya, seperti pembersih lantai organik; kertas, gumpalan kapas, laken dan sebagainya yang dilapisi dengan sabun atau deterjen seperti tisue basah; gliserol mentah; pembersih permukaan, seperti bubuk pencuci baik padat maupun cair dan deterjen, preparat pencuci piring dan pelembut bahan pakaian; produk pembersih dan pengkilap, seperti pengharum dan deodorant ruangan, lilin buatan dan lilin olahan (wax), pengilap dan krim untuk barang dari kulit, pengilap dan krim untuk kayu, pengilap kaca dan logam, pasta dan bubuk gosok, termasuk kertas, gumpalan dan lain-lain yang dilapisi dengan pasta dan bubuk penggosok.',NULL,NULL,0),
	(477,'20232','INDUSTRI KOSMETIK UNTUK MANUSIA, TERMASUK PASTA GIGI','Kelompok ini mencakup usaha pembuatan kosmetik untuk manusia, seperti tata rias muka, wangi-wangian atau parfum, produk perawatan rambut (shampo, obat pengeriting dan pelurus rambut, dan lain-lain), produk perawatan kuku atau menikur dan pedikur, produk perawatan kulit (krim atau lotion pencegah terbakar sinar matahari dan krim atau lotion agar kulit terlihat cokelat setelah berjemur), produk untuk kebersihan badan (sabun kosmetik, sabun mandi, sabun antiseptik, external intimate hygiene, deodorant, garam mandi dan lain-lain), produk untuk bercukur. Kosmetik dekoratif seperti tata rias muka, tata rias mata, wangi-wangian atau parfum, tata rias kuku dan tata rias rambut termasuk pewarna rambut. Termasuk pasta gigi dan produk untuk menjaga higienitas mulut, termasuk produk kosmetik pemutih gigi.',NULL,NULL,0),
	(478,'20233','INDUSTRI KOSMETIK UNTUK HEWAN','Kelompok ini mencakup usaha pembuatan kosmetik untuk hewan, termasuk parfum, shampo, sabun, bedak, krim atau lotion, dan lainnya.',NULL,NULL,0),
	(479,'20234','INDUSTRI PEREKAT GIGI','Kelompok ini mencakup usaha pembuatan produk perekat gigi.',NULL,NULL,0),
	(480,'20291','INDUSTRI PEREKAT/LEM','Kelompok ini mencakup usaha pembuatan perekat/lem untuk keperluan industri atau alat rumah tangga yang berasal dari tanaman, hewan atau plastik, seperti starch, perekat dari tulang, cellulose ester dan ether, phenol formaldehyde, urea formaldehyde, melamine formaldehyde dan perekat epoksi.',NULL,NULL,0),
	(481,'20292','INDUSTRI BAHAN PELEDAK','Kelompok ini mencakup usaha pembuatan barang peledak, seperti mesiu, dinamit, detonator, kembang api, petasan, mercuri fulminat dan bahan pendorong roket.',NULL,NULL,0),
	(482,'20293','INDUSTRI TINTA','Kelompok ini mencakup usaha pembuatan macam-macam tinta, seperti tinta tulis dan tinta khusus.',NULL,NULL,0),
	(483,'20294','INDUSTRI MINYAK ATSIRI','Kelompok ini mencakup usaha pembuatan minyak atsiri, seperti minyak jahe, minyak keningar, minyak ketumbar, minyak cengkeh, minyak kapol, minyak pala, minyak melati, minyak kenanga, minyak mawar, minyak akar wangi, minyak sereh, minyak nilam, minyak cendana, minyak kayu putih, minyak permen, minyak rempah-rempah, minyak jarak dan minyak dari rumput-rumputan/semak, daun dan kayu yang belum termasuk kelompok manapun.',NULL,NULL,0),
	(484,'20295','INDUSTRI KOREK API','Kelompok ini mencakup usaha pembuatan korek api dalam bentuk batangan (matches). Pembuatan batu korek api (flint) dimasukkan dalam kelompok 23990. Industri korek api dari logam (lighter) dimasukkan dalam kelompok 32909.',NULL,NULL,0),
	(485,'20296','INDUSTRI MINYAK ATSIRI RANTAI TENGAH','Kelompok ini mencakup usaha pengolahan lebih lanjut dari minyak atsiri yang masuk pada KBLI 20294 menjadi aneka produk hilir minyak atsiri untuk bahan baku produksi bahan perasa (flavour) dan produksi bahan perisa/wewangian (fragrance), termasuk untuk produksi aneka bahan kimia yang berbasis pengolahan hilir minyak atsiri. Termasuk didalamnya industri bioaditif bahanbakar minyak dari minyak atsiri. Contoh minyak atsiri rantai tengah/hilir yaitu turunan minyak cengkeh antara lain carryophyllene, eugenol, methyl eugenol, vaniline; turunan minyak sereh wangi antara lain citronellol, geraniol, citronellal, rodinol, dsb.',NULL,NULL,0),
	(486,'20299','INDUSTRI BARANG KIMIA LAINNYA YTDL','Kelompok ini mencakup usaha pembuatan bermacam-macam bahan-bahan dan barang-barang kimia yang belum diklasifikasikan dalam kelompok manapun seperti gelatin, bahan isolasi panas selain plastik dan karet, bahan semir/polish. Termasuk juga pembuatan film yang peka terhadap cahaya dan kertas fotografi.',NULL,NULL,0),
	(487,'20301','INDUSTRI SERAT/BENANG/STRIP FILAMEN BUATAN','Kelompok ini mencakup usaha pembuatan serat, benang, atau strip filamen buatan dalam bentuk gulungan tow, seperti poliamida, poliester, polipropilena, akrilik, selulosa asetat dan sebagainya untuk diolah lebih lanjut dalam industri tekstil.',NULL,NULL,0),
	(488,'20302','INDUSTRI SERAT STAPEL BUATAN','Kelompok ini mencakup usaha pembuatan serat stapel buatan, seperti poliamida, poliester, rayon viskosa, akrilik, selulosa asetat dan sebagainya (kecuali serat gelas dan serat optik) untuk diolah lebih lanjut dalam industri tekstil. Serat stapel adalah serat buatan yang dipotong pendek-pendek.',NULL,NULL,0),
	(489,'KODE','INDUSTRI BAHAN FARMASI UNTUK MANUSIA','Kelompok ini mencakup usaha pembuatan dan pengolahan bahan obat, bahan pembantu dan bahan pengemas untuk manusia, yang berasal dari bahan kimia, bahan alam, hewan dan tumbuh-tumbuhan termasuk yang berasal dari hasil biologis, seperti bahan obat-obatan, seperti antisera dan fraksi darah lainnya, vaksin dan preparat homeopatik. Termasuk industri substansi aktif obat (antibiotik, vitamin, salisilik dan asam o-asetilsalsilik dan lain-lain) untuk bahan farmakologi dalam industri obat- obatan, pengolahan darah, industri gula murni kimia dan pengolahan kelenjar dan industri ekstraksi kelenjar dan lain-lain.',NULL,NULL,0),
	(490,'21012','INDUSTRI PRODUK FARMASI UNTUK MANUSIA','Kelompok ini mencakup usaha pembuatan dan pengolahan obat-obatan, suplemen kesehatan/makanan, yang berbentuk jadi (sediaan) untuk manusia, misalnya dalam bentuk tablet, kapsul, salep, bubuk, larutan, larutan parenteral dan suspensi, obat kontrasepsi hormonal, industri produksi radiofarmaka, dan industri farmasi bioteknologi.',NULL,NULL,0),
	(491,'21013','INDUSTRI PRODUK FARMASI UNTUK HEWAN','Kelompok ini mencakup usaha pembuatan, pengolahan dan pengemasan ulang obat- obatan yang berbentuk jadi (sediaan) untuk hewan, misalnya dalam bentuk serbuk, tablet, kapsul, salep, larutan, suspensi, aerosol dan lainnya. Termasuk industri produk benang bedah, industri alat-alat diagnosa medis, industri produksi radioisotop untuk radiofarmaka, industri farmasi bioteknologi dan industri pembalut medis, perban dan sejenisnya yang dikhususkan untuk hewan.',NULL,NULL,0),
	(492,'21014','INDUSTRI BAHAN FARMASI UNTUK HEWAN','Kelompok ini mencakup usaha pembuatan dan pengolahan bahan obat, bahan pembantu dan bahan pengemas untuk hewan, yang berasal dari bahan kimia, bahan alam, hewan dan tumbuh-tumbuhan termasuk yang berasal dari hasil biologis, seperti bahan obat-obatan, seperti antisera dan fraksi darah lainnya, vaksin dan preparat homeopatik. Termasuk industri substansi aktif obat untuk bahan farmakologi dalam industri obat-obatan, seperti antibiotik, vitamin, salisilik dan asam o-asetilsalsilik dan lain-lain, pengolahan darah, industri gula murni kimia dan pengolahan kelenjar dan industri ekstraksi kelenjar dan lain-lain.',NULL,NULL,0),
	(493,'21015','INDUSTRI ALAT KESEHATAN DALAM SUBGOLONGAN 2101','Kelompok ini mencakup usaha pembuatan dan pengolahan alat kesehatan terkait diagnosa medis dan produk lainnya dalam subgolongan 2011. Kelompok ini mencakup industri produk kontrasepsi untuk penggunaan eksternal, industri alat-alat diagnosa medis seperti uji kehamilan, dan industri pembalut medis, perban dan sejenisnya dan kapas kosmetik.',NULL,NULL,0),
	(494,'21021','INDUSTRI BAHAN BAKU OBAT TRADISIONAL UNTUK MANUSIA','Kelompok ini mencakup usaha pengolahan macam-macam ekstrak dan simplisia, sediaan galenik, bahan tambahan atau bahan lainnya, baik yang berkhasiat maupun yang tidak berkhasiat, yang berubah maupun yang tidak berubah, yang digunakan dalam pengolahan obat tradisional, walaupun tidak semua bahan tersebut masih terdapat di dalam produk ruahan.',NULL,NULL,0),
	(495,'21022','INDUSTRI PRODUK OBAT TRADISIONAL UNTUK MANUSIA','Kelompok ini mencakup usaha pengolahan macam-macam produk obat tradisional yang bahannya berasal dari tumbuh-tumbuhan, bahan hewan, bahan mineral, sediaan sarian (galenik), atau campuran dari bahan tersebut yang berbentuk serbuk, rajangan, pil, dodol/jenang, pastiles, tablet, kapsul, cairan, larutan, emulsi dan suspensi, salep, krim dan gel, supositoria. Termasuk industri minuman jamu dan suplemen kesehatan/makanan bukan produk farmasi.',NULL,NULL,0),
	(496,'21023','INDUSTRI PRODUK OBAT TRADISIONAL UNTUK HEWAN','Kelompok ini mencakup usaha pengolahan macam-macam produk obat tradisional atau obat alami untuk hewan yang bahannya berasal antara lain dari tumbuh- tumbuhan, bahan hewan, bahan mineral, sediaan sarian (galenik), atau campuran dari bahan tersebut yang berbentuk serbuk, rajangan, pil, dodol/jenang, pastiles, tablet, kapsul, cairan, larutan, emulsi dan suspensi, salep, krim dan gel, supositoria.',NULL,NULL,0),
	(497,'21024','INDUSTRI BAHAN BAKU OBAT TRADISIONAL UNTUK HEWAN','Kelompok ini mencakup usaha pengolahan macam-macam ekstrak dan simplisia, sediaan galenik, bahan tambahan atau bahan lainnya, baik yang berkhasiat maupun yang tidak berkhasiat, yang berubah maupun yang tidak berubah, yang digunakan dalam pengolahan obat tradisional untuk hewan.',NULL,NULL,0),
	(498,'22111','INDUSTRI BAN LUAR DAN BAN DALAM','Kelompok ini mencakup usaha pembuatan ban luar dan ban dalam dengan bahan utamanya dari karet alam ataupun karet buatan untuk semua jenis kendaraan bermotor, sepeda, kendaraan angkutan lainnya dan peralatan yang memakai ban.',NULL,NULL,0),
	(499,'22112','INDUSTRI VULKANISIR BAN','Kelompok ini mencakup usaha perbaikan ban yang telah terpakai (ban bekas) menjadi seperti ban baru, sehingga dapat digunakan lagi untuk kendaraan bermotor, sepeda, kendaraan angkutan lainnya dan peralatan yang memakai ban.',NULL,NULL,0),
	(500,'22121','INDUSTRI PENGASAPAN KARET','Kelompok ini mencakup usaha pengasapan karet yang dilakukan dengan tujuan mengawetkan karet, seperti Ribbed Smoked Sheet (RSS) dan brown crepe dari pengasapan.',NULL,NULL,0),
	(501,'22122','INDUSTRI REMILLING KARET','Kelompok ini mencakup usaha pengolahan karet dengan cara digiling sehingga menghasilkan karet dalam bentuk lembaran, seperti sheet (lembaran karet halus) dan crepe (lembaran karet yang berkeriput).',NULL,NULL,0),
	(502,'22123','INDUSTRI KARET REMAH (CRUMB RUBBER)','Kelompok ini mencakup usaha pengolahan karet yang menghasilkan karet remah, termasuk karet spon (busa).',NULL,NULL,0),
	(503,'22191','INDUSTRI BARANG DARI KARET UNTUK KEPERLUAN RUMAH TANGGA','Kelompok ini mencakup usaha pembuatan barang-barang dari karet, untuk keperluan rumah tangga, seperti karpet karet, selang karet, tabung, pipa atau selang air, benang dan tali karet, benang rajut atau tenun dan kain berlapis karet, penutup bingkai penggulung dari karet, matras karet yang bisa dipompa, balon yang bisa dipompa, sikat dari karet dan matras waterbed (kasur air) dari karet. Termasuk usaha pembuatan keset, tali timba dan pot bunga dari karet.',NULL,NULL,0),
	(504,'22192','INDUSTRI BARANG DARI KARET UNTUK KEPERLUAN INDUSTRI','Kelompok ini mencakup usaha pembuatan barang-barang dari karet, untuk keperluan industri, seperti belt conveyor, fan belt, engine mounting, lining dari karet, karet berbentuk plat, lembaran, potongan, batangan dan bentuk profil, perkakas, cincin dan segel dari karet, batang pipa untuk uap panas dari karet keras dan bahan repair dari karet. Seal/segel dari karet bagian dan kelengkapan dari motor penggerak, transmisi, body, frame, suspensi, steering, axle terbuat dari karet.',NULL,NULL,0),
	(505,'22193','INDUSTRI BARANG DARI KARET UNTUK KEPERLUAN INFRASTRUKTUR','Kelompok ini mencakup usaha pembuatan kompon dan barang-barang dari karet untuk keperluan infrastruktur, seperti: kompon untuk aspal karet, serbuk karet alam teraktivasi (SKAT), dock fender, seismic bearing, bantalan jembatan, rubber dam, road bump, rail pad, rail guard, canal blocking, traffic cone.',NULL,NULL,0),
	(506,'22194','INDUSTRI BARANG DARI KARET UNTUK KESEHATAN','Kelompok ini mencakup usaha pembuatan barang dari karet untuk kebutuhan menunjang kesehatan, antara lain seperti sarung kontrasepsi (KB)/kondom, dot dan alat kompres, sarung tangan karet medis, dan kateter urin (folley catheter).',NULL,NULL,0),
	(507,'22199','INDUSTRI BARANG DARI KARET LAINNYA YTDL','Kelompok ini mencakup usaha pembuatan barang lainnya dari karet, seperti pembuatan barang dari ban bekas dan sisa macam-macam barang dari karet, antara lain sarung tangan karet selain medis. Termasuk barang-barang karet untuk pakaian (jika hanya disatukan bersama, bukan dijahit), sisir, jepit rambut, rol rambut dan sejenisnya dari karet keras, kain tekstil yang diresapi, dilapisi atau dilaminasi dengan karet, di mana karet adalah bahan pokok, topi dan baju mandi dari karet, jas hujan dan pakaian menyelam dari karet dan alat-alat seks dari karet.',NULL,NULL,0),
	(508,'22210','INDUSTRI BARANG DARI PLASTIK UNTUK BANGUNAN','Kelompok ini mencakup usaha pembuatan barang dari plastik untuk bangunan, seperti pintu, jendela, kusin, daun penutup jendela, kerai, skirting boards dari plastik, tangki, tandon air dari plastik, penutup lantai, dinding dan langit-langit plastik dalam bentuk gulungan atau lembaran dan peralatan kebersihan dari plastik, seperti hordeng plastik, shower, wastafel, lavatory pan, bak penyiram (flushing) dan lain-lain.',NULL,NULL,0),
	(509,'22220','INDUSTRI BARANG DARI PLASTIK UNTUK PENGEMASAN','Kelompok ini mencakup usaha pembuatan kemasan dari plastik, seperti tas atau kantong plastik, sak atau karung plastik, kemasan kosmetik, kemasan film, kemasan obat, kemasan makanan dan kemasan lainnya dari plastik (wadah, botol, boks, kotak, rak dan lain-lain).',NULL,NULL,0),
	(510,'22230','INDUSTRI PIPA PLASTIK DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha pembuatan pipa dan selang dari plastik, seperti pipa PVC/PE/PP dan selang plastik PVC/PE/PP. Termasuk tabung plastik dan perlengkapan pipa.',NULL,NULL,0),
	(511,'22291','INDUSTRI BARANG PLASTIK LEMBARAN','Kelompok ini mencakup usaha pembuatan barang plastik lembaran, seperti plastik lembaran berbagai jenis PE/PP/PVC, kulit imitasi, formika, kaca plastik dan plastik lembaran lainnya. Termasuk plate plastik, lembaran plastik, balok plastik, film, foil, potongan plastik dan lain-lain (baik berperekat atau tidak).',NULL,NULL,0),
	(512,'22292','INDUSTRI PERLENGKAPAN DAN PERALATAN RUMAH TANGGA (TIDAK TERMASUK FURNITUR)','Kelompok ini mencakup usaha pembuatan barang-barang perlengkapan dan peralatan rumah tangga dari plastik, seperti tikar, karpet, ember, sikat gigi, vas dan peralatan rumah tangga lainnya. Termasuk industri peralatan makan, peralatan dapur dan barang-barang toilet plastik serta industri penutup lantai elastis, seperti vynil, linoleum dan sebagainya.',NULL,NULL,0),
	(513,'22293','INDUSTRI BARANG DAN PERALATAN TEKNIK/INDUSTRI DARI PLASTIK','Kelompok ini mencakup usaha pembuatan barang-barang dan peralatan teknik/industri dari plastik, seperti bagian-bagian mesin, bagian dan kelengkapan dari motor penggerak, transmisi, body, frame, suspensi, steering, axle terbuat dari plastik, botol-botol, pipa-pipa dan lemari plastik untuk keperluan teknik/industri. Termasuk industri ban berjalan pembawa barang (conveyer belt).',NULL,NULL,0),
	(514,'22299','INDUSTRI BARANG PLASTIK LAINNYA YTDL','Kelompok ini mencakup usaha pembuatan barang-barang yang belum diklasifikasikan dimanapun, seperti peralatan kantor/pendidikan, peralatan kesehatan/laboratorium dari plastik, film atau lembaran kertas kaca (cellophane), batu buatan dari plastik, tanda dari plastik (bukan listrik), berbagai barang plastik, seperti tutup kepala, peralatan penyekat, bagian dari peralatan penerangan, barang-barang kantor atau sekolah, barang-barang pakaian (jika hanya disegel atau disatukan, tidak dijahit), perlengkapan untuk furnitur, patung, tape perekat dari plastik, kertas dinding plastik, alas sepatu dari plastik, pegangan cerutu dan rokok dari plastik, sisir, pengeriting rambut dari plastik, barang kesenangan dari plastik dan sebagainya. Termasuk juga pembuatan barang dari busa plastik. Pembuatan barang-barang peralatan olahraga dimasukkan dalam kelompok 32300. Pembuatan mainan anak-anak dari plastik dimasukkan dalam kelompok 32402. Pembuatan tas, buku saku dan sejenisnya dari kulit dan kulit buatan diklasifikasikan dalam kelompok 15121.',NULL,NULL,0),
	(515,'23111','INDUSTRI KACA LEMBARAN','Kelompok ini mencakup usaha pembuatan macam-macam kaca lembaran, seperti kaca lembaran bening tak berwarna, kaca lembaran bening berwarna, kaca lembaran buram berwarna, kaca patri, kaca berukir dan kaca cermin.',NULL,NULL,0),
	(516,'23112','INDUSTRI KACA PENGAMAN','Kelompok ini mencakup usaha pembuatan macam-macam kaca pengaman seperti kaca pengaman diperkeras, kaca pengaman berlapis, kaca pengaman isolasi dan kaca pengaman lainnya.',NULL,NULL,0),
	(517,'23119','INDUSTRI KACA LAINNYA','Kelompok ini mencakup usaha pembuatan macam-macam kaca yang belum termasuk kelompok 23111 dan 23112, seperti tubes, rods, kaca batangan atau kaca pipa.',NULL,NULL,0),
	(518,'23121','INDUSTRI PERLENGKAPAN DAN PERALATAN RUMAH TANGGA DARI KACA','Kelompok ini mencakup usaha pembuatan macam-macam perlengkapan rumah tangga dari kaca , seperti cangkir, piring, mangkok, teko, stoples, asbak dan botol susu bayi. Termasuk juga usaha pembuatan barang-barang pajangan dari kaca, seperti patung atau arca dari kaca, vas, lampu kristal, semprong lampu tekan dan semprong lampu tempel.',NULL,NULL,0),
	(519,'23122','INDUSTRI ALAT-ALAT LABORATORIUM NON KLINIS, FARMASI DAN KESEHATAN DARI KACA','Kelompok ini mencakup usaha pembuatan macam-macam alat laboratorium selain laboratorium klinis, farmasi dan kesehatan dari gelas, seperti botol serum/infus, ampul, tabung uji, tabung ukur, kaca sorong mikroskop, cuvet dan dessicator.',NULL,NULL,0),
	(520,'23123','INDUSTRI KEMASAN DARI KACA','Kelompok ini mencakup usaha pembuatan macam-macam barang untuk kemasan dari kaca, seperti botol dan guci. Termasuk wadah lain dari kaca atau kristal.',NULL,NULL,0),
	(521,'23124','INDUSTRI ALAT LABORATORIUM KLINIS DARI KACA','Kelompok ini mencakup usaha pembuatan macam-macam alat laboratorium klinis, pada umumnya untuk keperluan diagnosis, seperti tabung uji untuk sampel biologis (darah, urin, saliva).',NULL,NULL,0),
	(522,'23129','INDUSTRI BARANG LAINNYA DARI KACA','Kelompok ini mencakup usaha pembuatan macam-macam barang lainnya dari gelas yang belum tercakup dalam kelompok 23121 s.d. 23123 seperti tasbih, rosario, manik gelas, gelas enamel dan aquarium, serat kaca (fiberglass), termasuk produk-produk dari wol kaca dan non woven kaca, kaca jam dinding atau kaca arloji, kaca dan elemen optik yang tidak bekerja secara optis, barang kaca yang digunakan pada perhiasan imitasi dan kaca isolasi dan perlengkapan isolasi kaca. Termasuk juga usaha pembuatan bahan bangunan dari gelas seperti bata, ubin, genteng, paving blocks dan sekat dinding dari kaca.',NULL,NULL,0),
	(523,'23911','INDUSTRI BATA, MORTAR, SEMEN, DAN SEJENISNYA YANG TAHAN API','Kelompok ini mencakup usaha pembuatan macam-macam bata tahan api, mortar tahan api dan semen tahan api, beton dan komposit sejenisnya yang tahan api, seperti alumina, silica dan basic.',NULL,NULL,0),
	(524,'23919','INDUSTRI BARANG TAHAN API DARI TANAH LIAT/KERAMIK LAINNYA','Kelompok ini mencakup usaha pembuatan macam-macam barang tahan api, selain bata tahan api. Termasuk barang keramik penyekat panas dari tepung fossil siliceous; ubin dan balok refraktori; tabung kimia atau labu destilasi, wadah tempat melebur logam, penyaring, tabung, pipa dan sebagainya; dan barang refraktori yang mengandung magnet, dolomit atau kromit.',NULL,NULL,0),
	(525,'23921','INDUSTRI BATU BATA DARI TANAH LIAT/KERAMIK','Kelompok ini mencakup usaha pembuatan macam-macam batu bata seperti bata pres, bata berongga, bata hiasan, bata bukan pres dan bata lubang. Termasuk juga pembuatan semen merah dan kerikil tanah liat.',NULL,NULL,0),
	(526,'23922','INDUSTRI GENTENG DARI TANAH LIAT/KERAMIK','Kelompok ini mencakup usaha pembuatan macam-macam genteng tanah liat/keramik, seperti genteng pres, genteng biasa, genteng kodok dan genteng yang diglazur.',NULL,NULL,0),
	(527,'23923','INDUSTRI PERALATAN SANITER DARI PORSELEN','Kelompok ini mencakup usaha pembuatan macam-macam peralatan saniter dari porselen seperti kloset, bidet, wastafel, urinoir, bak cuci, bak mandi dan lain-lain.',NULL,NULL,0),
	(528,'23929','INDUSTRI BAHAN BANGUNAN DARI TANAH LIAT/KERAMIK BUKAN BATU BATA DAN GENTENG','Kelompok ini mencakup usaha pembuatan barang dari tanah liat/keramik untuk keperluan bahan bangunan bukan batu bata, genteng dan peralatan saniter dari porselen, seperti saluran air, ubin, lubang angin dan buis (cincin untuk sumur). Termasuk tungku keramik atau ubin dinding non refraktori, kubus mosaik dan sebagainya, paving atau ubin keramik non refraktori, ubin untuk atap, cerobong asap, pipa, saluran keramik dan sebagainya dan balok lantai dari tanah liat yang dibakar.',NULL,NULL,0),
	(529,'23931','INDUSTRI PERLENGKAPAN RUMAH TANGGA DARI PORSELEN','Kelompok ini mencakup usaha pembuatan macam-macam perlengkapan rumah tangga dari porselen, seperti piring, tatakan, cangkir, mangkok, teko, kendi, sendok , asbak, barang toilet dan toples dan barang-barang sejenis yang digunakan untuk pengangkutan atau pengepakan barang. Termasuk juga usaha pembuatan barang pajangan dari porselen seperti arca atau patung dan barang keramik ornamental lainnya, tempat bunga, kotak rokok dan guci.',NULL,NULL,0),
	(530,'23932','INDUSTRI PERLENGKAPAN RUMAH TANGGA DARI TANAH LIAT/KERAMIK','Kelompok ini mencakup usaha pembuatan macam-macam barang dari tanah liat untuk perlengkapan rumah tangga, pajangan/hiasan dan sejenisnya, seperti piring, cangkir, mangkok, kendi, teko, periuk, tempayan, patung, vas bunga, tempat sirih, kotak sigaret, celengan, toples, dan barang-barang sejenis yang digunakan untuk pengangkutan atau pengepakan barang dan lain-lain.',NULL,NULL,0),
	(531,'23933','INDUSTRI ALAT LABORATORIUM DAN ALAT LISTRIK/TEKNIK DARI PORSELEN','Kelompok ini mencakup usaha pembuatan macam-macam alat laboratorium, listrik dan teknik serta perlengkapan dari porselen seperti lumpang dan alu, piring penapis, tabung kimia, botol/guci, cawan, rumah sekering, insulator, isolator tegangan rendah dan isolator tegangan tinggi. Termasuk magnet ferit dan keramik dan barang-barang keramik laboratorium, kimia dan industrial.',NULL,NULL,0),
	(532,'23939','INDUSTRI BARANG TANAH LIAT/KERAMIK DAN PORSELEN LAINNYA BUKAN BAHAN BANGUNAN','Kelompok ini mencakup usaha pembuatan macam-macam barang dari tanah liat/keramik dan porselen lainnya bukan bahan bangunan yang belum tercakup dalam kelompok 23931 sampai dengan 23933. Termasuk furnitur keramik dan barang-barang keramik lainnya, ytdl.',NULL,NULL,0),
	(533,'23941','INDUSTRI SEMEN','Kelompok ini mencakup usaha pembuatan macam-macam semen (semen hidrolik dan arang atau kerak besi), seperti portland, natural, semen mengandung alumunium, semen terak dan semen superfosfat dan jenis semen lainnya.',NULL,NULL,0),
	(534,'23942','INDUSTRI KAPUR','Kelompok ini mencakup usaha pembuatan macam-macam kapur dari batu kapur, seperti kapur tohor, kapur tembok dan kapur lepaan. Termasuk kapur slaked lime dan kapur hidrolik.',NULL,NULL,0),
	(535,'23943','INDUSTRI GIPS','Kelompok ini mencakup usaha pembuatan gips, yang terbentuk dari calcined gipsum atau calsium sulphate. Termasuk calcined dolomite.',NULL,NULL,0),
	(536,'23951','INDUSTRI BARANG DARI SEMEN','Kelompok ini mencakup usaha pembuatan macam-macam barang dari semen, seperti patung, pot kembang dan lain-lain.',NULL,NULL,0),
	(537,'23952','INDUSTRI BARANG DARI KAPUR','Kelompok ini mencakup usaha pembuatan macam-macam barang dari kapur, seperti kapur tulis, kapur gambar, batako dan dempul.',NULL,NULL,0),
	(538,'23953','INDUSTRI BARANG DARI SEMEN DAN KAPUR UNTUK KONSTRUKSI','Kelompok ini mencakup usaha pembuatan macam-macam barang dari semen dan atau kapur atau batu buatan untuk keperluan konstruksi seperti ubin, bata/dinding, pipa beton dan beton praktekan, papan, lembaran, panel, tonggak dan sebagainya, komponen struktur prafabrik untuk gedung atau bangunan sipil dan bahan-bahan bangunan dari substansi tumbuh-tumbuhan (wol kayu, alang-alang, jerami dan lain- lain) yang disatukan dengan semen atau bahan pencampur mineral lainnya.',NULL,NULL,0),
	(539,'23954','INDUSTRI BARANG DARI GIPS UNTUK KONSTRUKSI','Kelompok ini mencakup pembuatan barang dari gips yang digunakan dalam konstruksi, seperti papan, lembaran, panel dan lain-lain. Termasuk Industri bahan bangunan dari substansi tumbuh-tumbuhan (wol kayu, alang-alang, jerami dan lain- lain) yang disatukan plester gips.',NULL,NULL,0),
	(540,'23955','INDUSTRI BARANG DARI ASBES UNTUK KEPERLUAN BAHAN BANGUNAN','Kelompok ini mencakup usaha pembuatan macam-macam barang dari asbes untuk keperluan bahan bangunan seperti asbes gelombang, asbes rata, pipa asbes bertekanan dan asbes berlapis.',NULL,NULL,0),
	(541,'23956','INDUSTRI BARANG DARI ASBES UNTUK KEPERLUAN INDUSTRI','Kelompok ini mencakup usaha pembuatan macam-macam barang dari asbes untuk keperluan industri.',NULL,NULL,0),
	(542,'23957','INDUSTRI MORTAR ATAU BETON SIAP PAKAI','Kelompok ini mencakup usaha pembuatan mortar atau beton siap pakai (ready mixed and dry mixed concrete and mortar).',NULL,NULL,0),
	(543,'23959','INDUSTRI BARANG DARI SEMEN, KAPUR, GIPS DAN ASBES LAINNYA','Kelompok ini mencakup usaha pembuatan macam-macam barang dari semen, kapur, gips dan asbes lainnya, yang belum tercakup dalam kelompok 23951 sampai dengan 23957, seperti industri barang dari semen serat selulosa atau sejenisnya, seperti reservoir, palung atau bak, kolam, bak cuci piring, guci, mebel, rangka jendela dan lain- lain, barang lainnya dari beton, plester gips, semen atau batu buatan, seperti patung, furnitur, relief gambar timbul dan sebagainya dan mortar bubuk.',NULL,NULL,0),
	(544,'23961','INDUSTRI BARANG DARI MARMER DAN GRANIT UNTUK KEPERLUAN RUMAH TANGGA DAN PAJANGAN','Kelompok ini mencakup usaha pembuatan macam-macam barang dari marmer/granit untuk keperluan rumah tangga dan pajangan, seperti daun meja, ornamen dan patung. Termasuk pembuatan furnitur dari marmer dan granit.',NULL,NULL,0),
	(545,'23962','INDUSTRI BARANG DARI MARMER DAN GRANIT UNTUK KEPERLUAN BAHAN BANGUNAN','Kelompok ini mencakup usaha pembuatan macam-macam barang dari marmer/granit untuk keperluan bahan bangunan, seperti ubin dan bak mandi.',NULL,NULL,0),
	(546,'23963','INDUSTRI BARANG DARI BATU UNTUK KEPERLUAN RUMAH TANGGA, PAJANGAN, DAN BAHAN BANGUNAN','Kelompok ini mencakup usaha pembuatan macam-macam barang dari batu untuk keperluan rumah tangga, pajangan, dan bahan bangunan, seperti lumpang, cobek, batu pipisan, batu asah, batu lempengan, batu pecah-pecahan, abu batu dan kubus mozaik.',NULL,NULL,0),
	(547,'23969','INDUSTRI BARANG DARI MARMER, GRANIT DAN BATU LAINNYA','Kelompok ini mencakup usaha pembuatan macam-macam barang dari batu marmer, granit atau batu lainnya untuk keperluan lainnya yang belum tercakup dalam kelompok 23961 hingga 23963, seperti industri batu monumen.',NULL,NULL,0),
	(548,'23990','INDUSTRI BARANG GALIAN BUKAN LOGAM LAINNYA YTDL','Kelompok ini mencakup usaha pembuatan macam-macam barang dari bahan galian lainnya yang belum tercakup di tempat lain, seperti tepung kaolin, tepung gips, dan tepung talk. Termasuk juga usaha pembuatan kertas penggosok (abrasive paper) dan gerinda, penajaman dan pengilapan batu dan batu abrasi atau penggosok baik alami atau buatan, batu korek api (lighter flint); bahan friksi dan barang tak berbingkai dengan bahan pokok substansi mineral atau selulosa; bahan penyekat dari mineral, seperti wol terak, wol batu dan jenis wol lainnya; exfoliated vermiculate, tanah liat yang dikembangkan dan sejenis penyekat dengan panas, bahan penyerap suara; barang dari berbagai substansi mineral, seperti mika dan barang dari mika, barang dari tanah gemuk (peat) sebagai bahan pembakar, barang dari grafit (barang elektris); barang dari aspal atau material sejenisnya, misalnya perekat berbahan dasar aspal, aspal karet alam, ter batu bara dan sebagainya; dan karbon dan serat grafit dan barang turunannya (kecuali elektroda dan peralatan elektris).',NULL,NULL,0),
	(549,'24101','INDUSTRI BESI DAN BAJA DASAR (IRON AND STEEL MAKING)','Kelompok ini mencakup usaha pembuatan besi dan baja dalam bentuk dasar, seperti pellet bijih besi, besi spons, besi kasar (pig iron) dan pembuatan besi dan baja dalam bentuk baja kasar seperti ingot baja, billet baja, baja bloom dan baja slab. Termasuk juga pembuatan besi dan baja paduan. Termasuk kegiatan tungku pembakar, steel converter, pabrik penggulungan dan finishing; produksi besi kasar dalam bentuk dasar seperti balok; produksi besi campuran; produksi produk besi yang direduksi langsung dari bijih besi dan produk besi berongga lainnya; produksi besi dari hasil pemurnian dengan proses elektrolisis dan proses kimia lainnya; produksi butir besi dan bubuk besi; produksi baja batangan (ingot) atau bentuk dasar lainnya; peleburan kembali ingot sisaan besi atau baja; dan produksi baja setengah jadi.',NULL,NULL,0),
	(550,'24102','INDUSTRI PENGGILINGAN BAJA (STEEL ROLLING)','Kelompok ini mencakup usaha penggilingan baja, baik penggilingan panas maupun dingin, yang membuat produk-produk gilingan batang kawat baja, baja tulangan, baja profil (H-beam, I-beam dan sejenisnya), baja strip, baja rel, pelat baja, baja lembaran hasil gilingan panas (hot rolled sheet) dan baja lembaran hasil gilingan dingin (cold rolled sheet) dilapisi atau tidak dilapisi dengan logam atau non logam lainnya termasuk penggilingan baja scrap. Termasuk industri baja balok atau potongan gulungan panas, industri baja open section gulungan panas, industri baja balok dan baja solid section hasil proses cold drawing, grinding dan turning, industri baja open section hasil pembentukan dingin progresif pada mesin penggulung atau pelipatan pada mesin pres atau pada penggulungan flat baja, industri kawat baja baik kawat satuan maupun pilinan (strand) hasil proses cold drawing, tempering, dan stressing, industri lembaran tiang pancang baja atau baja las open section, industri material rel kereta api baja (rel belum terpasang).',NULL,NULL,0),
	(551,'24103','INDUSTRI PIPA DAN SAMBUNGAN PIPA DARI BAJA DAN BESI','Kelompok ini mencakup usaha pembuatan tabung, pipa dan sambungan pipa dari besi dan baja. Termasuk Industri tabung, pipa dan profile berongga baja tanpa kelim hasil pembentukan gulungan panas, hot drawing atau hot extruding, gulungan dingin atau cold drawing; industri tabung dan pipa baja las hasil pengelasan dan pembentukan panas atau dingin, sebagai proses lanjutan dari gulungan dingin atau cold drawing; dan industri fittings pipa baja, seperti flat flanges dan flanges with forged collar, butt- welded fittings, threaded fittings dan socket-welded fiitings.',NULL,NULL,0),
	(552,'24201','INDUSTRI PEMBUATAN LOGAM DASAR MULIA','Kelompok ini mencakup usaha pemurnian, peleburan, pemaduan dan penuangan logam mulia dalam bentuk dasar (ingot, billet, slab, batang, pellet, block, sheet, pig, paduan dan bubuk) seperti ingot perak, ingot emas, pellet platina dan sebagainya.',NULL,NULL,0),
	(553,'24202','INDUSTRI PEMBUATAN LOGAM DASAR BUKAN BESI','Kelompok ini mencakup usaha pemurnian, peleburan, pemaduan dan penuangan logam-logam bukan besi dalam bentuk dasar (ingot, billet, slab, batang, pellet, block, sheet, pig, paduan dan bubuk) seperti ingot kuningan, ingot aluminium, ingot seng, ingot tembaga, ingot timah, billet kuningan, billet aluminium, slab kuningan, slab aluminium, batang (rod) kuningan, batang aluminium, pellet kuningan, pellet aluminium, paduan perunggu, paduan nikel dan logam anti gesekan (bearing metal) serta logam tanah jarang dan paduan logam tanah jarang (15 unsur lantanida ditambah unsur scandium dan yttrium).',NULL,NULL,0),
	(554,'24203','INDUSTRI PENGGILINGAN LOGAM BUKAN BESI','Kelompok ini mencakup usaha penggilingan logam bukan besi, baik penggilingan panas maupun penggilingan dingin, seperti pelat tembaga, pelat aluminium, sheet (lembaran) tembaga, sheet aluminium, strip (jalur) perak, strip seng, strip aluminium, sheet tembaga, sheet magnesium, tin foil dan strip platina. Termasuk pembuatan kawat logam.',NULL,NULL,0),
	(555,'24204','INDUSTRI EKSTRUSI LOGAM BUKAN BESI','Kelompok ini mencakup usaha ekstrusi logam bukan besi, seperti ekstrusi tembaga dan paduannya, ekstrusi aluminium dan ekstrusi tungsten.',NULL,NULL,0),
	(556,'24205','INDUSTRI PIPA DAN SAMBUNGAN PIPA DARI LOGAM BUKAN BESI DAN BAJA','Kelompok ini mencakup usaha pembuatan tabung, pipa dan sambungan pipa dari logam bukan besi dan baja.',NULL,NULL,0),
	(557,'24206','INDUSTRI PENGOLAHAN URANIUM DAN BIJIH URANIUM','Kelompok ini mencakup pemurnian logam uranium dari bijih uranium atau bijih lainnya yang mengandung uranium, pengolahan uranium alam dan persenyawaannya, pengayaan uranium dan persenyawaannya, plutonium dan persenyawaannya, atau pemisahan dan penggabungan persenyawaan tersebut.',NULL,NULL,0),
	(558,'24310','INDUSTRI PENGECORAN BESI DAN BAJA','Kelompok ini mencakup usaha peleburan, pencampuran dan pengecoran atau penuangan logam besi dan baja yang menghasilkan produk-produk tuangan dalam bentuk kasar, seperti besi tuang, baja tuang dan baja tuang paduan. Termasuk pengecoran produk besi setengah jadi, pengecoran besi tuang abu-abu, pengecoran besi tuang grafit spheroid, pengecoran besi tuang yang dapat ditempa, pengecoran produk baja setengah jadi, pengecoran baja tuang, industri tabung, pipa dan profile berongga serta fittings tabung dan pipa yang terbuat dari besi tuang, industri tabung dan pipa baja tanpa kelim dari proses pengecoran sentrifugal dan industri tabung dan pipa fittings yang terbuat dari baja tuang.',NULL,NULL,0),
	(559,'24320','INDUSTRI PENGECORAN LOGAM BUKAN BESI DAN BAJA','Kelompok ini mencakup usaha peleburan, pemaduan dan pengecoran atau penuangan logam-logam bukan besi dalam bentuk dasar, seperti tuangan tembaga dan paduannya, tuangan aluminium dan paduannya, tuangan nikel dan paduannya. Termasuk Pengecoran produk setengah jadi dari aluminium, magnesium, titanium, seng dan lain-lain, pengecoran logam ringan tuang, pengecoran logam berat tuang, pengecoran logam mulia tuang dan die-casting logam bukan besi.',NULL,NULL,0),
	(560,'25111','INDUSTRI BARANG DARI LOGAM BUKAN ALUMINIUM SIAP PASANG UNTUK BANGUNAN','Kelompok ini mencakup usaha pembuatan bahan bangunan siap pasang dari logam bukan aluminium, seperti pagar besi, teralis, pintu/jendela, lubang angin, tangga dan produk-produk konstruksi ringan lainnya. Industri pembuatan bahan konstruksi berat siap pasang dari baja, seperti untuk jembatan, menara listrik tegangan tinggi, pintu air dan sejenisnya dimasukkan dalam kelompok 25113, sedangkan industri pembuatan ketel uap, bejana tekan dan sejenisnya dimasukkan dalam kelompok 25120.',NULL,NULL,0),
	(561,'25112','INDUSTRI BARANG DARI LOGAM ALUMINIUM SIAP PASANG UNTUK BANGUNAN','Kelompok ini mencakup usaha pembuatan bahan bangunan siap pasang dari logam aluminium, seperti kusen jendela, kusen pintu, teralis aluminium, atap aluminium (awning), rolling door, krei aluminium dan produk-produk konstruksi ringan lainnya.',NULL,NULL,0),
	(562,'25113','INDUSTRI KONSTRUKSI BERAT SIAP PASANG DARI BAJA UNTUK BANGUNAN','Kelompok ini mencakup usaha pembuatan bahan bangunan konstruksi berat siap pasang dari baja untuk jembatan, bangunan hanggar, menara listrik tegangan tinggi, pintu air dan sejenisnya.',NULL,NULL,0),
	(563,'25119','INDUSTRI BARANG DARI LOGAM SIAP PASANG UNTUK KONSTRUKSI LAINNYA','Kelompok ini mencakup usaha pembuatan barang-barang dari logam siap pasang untuk konstruksi yang belum tercakup dalam kelompok 25111 s.d. 25113.',NULL,NULL,0),
	(564,'25120','INDUSTRI TANGKI, TANDON AIR DAN WADAH DARI LOGAM','Kelompok ini mencakup usaha pembuatan ketel uap untuk proses pengolahan (industri boiler), ketel untuk keperluan pembangkit tenaga (utility boiler), bejana tekan (presure vessel), scrubber dan sejenisnya. Termasuk pula usaha pembuatan tangki- tangki lainnya yang bertekanan seperti autoclave, tabung gas bertekanan (tabung gas LPG), tangki-tangki silo, alat penukar panas (heat exchanger) dan berbagai jenis alat penghasil uap gas lainnya. Termasuk tandon, tangki dan wadah dari logam yang secara umum dibuat untuk perlengkapan/tempat penyimpanan atau untuk keperluan industri dan ketel pemanas dan radiator.',NULL,NULL,0),
	(565,'25130','INDUSTRI GENERATOR UAP, BUKAN KETEL PEMANAS','Kelompok ini mencakup usaha pembuatan generator uap, termasuk komponen dan perlengkapannya, seperti steam accumulatator, economizer dan sejenisnya. Termasuk industri mesin uap lainnya, mesin tambahan yang digunakan dengan generator uap (kondenser, economizer, superheater, steam collectors dan accumulators), suku cadang ketel kapal laut atau ketel tenaga, reaktor nuklir beserta komponen dan perlengkapannya kecuali pemisah isotop.',NULL,NULL,0),
	(566,'25200','INDUSTRI SENJATA DAN AMUNISI','Kelompok ini mencakup pembuatan senjata berat (meriam, mobile guns, peluncur roket, tabung torpedo, senjata mesin berat), pembuatan senjata ringan/kecil (revolver, senapan, senapan mesin ringan) baik untuk militer atau polisi, pembuatan senjata gas dan amunisinya, senapan angin atau pistol dan amunisi perang. Termasuk pembuatan senjata api untuk berburu, olahraga atau perlindungan dan amunisinya, alat peledak seperti bom, granat, torpedo, ranjau, roket dan sebagainya.',NULL,NULL,0),
	(567,'25910','INDUSTRI PENEMPAAN, PENGEPRESAN, PENCETAKAN DAN PEMBENTUKAN LOGAM; METALURGI BUBUK','Kelompok ini mencakup pembuatan berbagai barang jadi dan setengah jadi dari logam baik baja, besi maupun logam bukan besi menjadi logam dalam bentuk logam tempaan, pres-an dan atau logam gulungan.',NULL,NULL,0),
	(568,'25920','JASA INDUSTRI UNTUK BERBAGAI PENGERJAAN KHUSUS LOGAM DAN BARANG DARI LOGAM','Kelompok ini mencakup kegiatan jasa industri untuk pelapisan, pemolesan, pewarnaan, pengukiran, pengerasan, pengkilapan, pengelasan, pemotongan dan berbagai pekerjaan khusus terhadap logam atau barang-barang dari logam. Kegiatannya termasuk industri penyepuhan logam, anodizing dan lain-lain; industri pengolahan panas logam; deburring, penyemprotan pasir (sandbalasting), perobohan (tumbling) dan pembersihan logam; industri pewarnaan dan pengukiran atau pemahatan logam; industri pelapisan bukan metalik logam, seperti pelapisan dengan plastik, email atau porselain, lak/pernis dan lain-lain; industri pengerasan dan pengkilapan logam; industri pengeboran, pengolahan, penggilingan, pengikisan, pembentukan, pemutaran, broaching, leveling, penggergajian, penghalusan, penajaman, penyemiran, pengelasan, penyambungan dan lain-lain bagian pekerjaan logam; dan industri pemotongan atau penulisan pada logam dengan sinar laser.',NULL,NULL,0),
	(569,'25931','INDUSTRI ALAT POTONG DAN PERKAKAS TANGAN UNTUK PERTANIAN','Kelompok ini mencakup usaha pembuatan alat-alat/perkakas tangan pertanian yang tidak digerakkan dengan tenaga dari logam, seperti cangkul, sekop, bajak, garu, sabit, ani-ani, alat perontok padi, alat pemipil jagung dan hand sprayer.',NULL,NULL,0),
	(570,'25932','INDUSTRI ALAT POTONG DAN PERKAKAS TANGAN PERTUKANGAN','Kelompok ini mencakup usaha pembuatan alat-alat pertukangan dari logam, seperti water pass, siku-siku, beliung, pahat, obeng, martil, serut/ketam, gergaji dan mata gergaji, mata gergaji bundar dan mata gergaji rantai, mata bor dan sejenisnya, kampak dan pisau pemotong kaca. Termasuk industri pisau dan mata pisau untuk mesin atau untuk peralatan mekanik, perkakas tangan (tang, obeng dan lain-lain), perkakas tangan pertanian yang tidak digerakkan dengan tenaga, alat yang dapat dipertukarkan untuk perkakas tangan, baik yang tidak digerakkan dengan tenaga atau mesin perkakas (seperti bor, pemukul, pisau penggiling dan lain-lain), perkakas pengepres, perkakas pandai besi (seperti alat tempa, landasan tempa dan lain-lain), kotak cetakan dan cetakan (kecuali cetakan ingot) dan perkakas kelim.',NULL,NULL,0),
	(571,'25933','INDUSTRI ALAT POTONG DAN PERKAKAS TANGAN YANG DIGUNAKAN DALAM RUMAH TANGGA','Kelompok ini mencakup usaha pembuatan bermacam-macam pisau, parang/golok, pisau bergerigi, pisau cukur, silet, gunting, hair clipper, gunting rambut, gunting kuku, sendok, garpu dan peralatan sejenisnya yang digunakan di dapur dan meja makan. Industri alat-alat dapur (misalnya periuk, panci, dandang dan kompor) dimasukkan dalam kelompok 25992.',NULL,NULL,0),
	(572,'25934','INDUSTRI PERALATAN UMUM','Kelompok ini mencakup usaha pembuatan peralatan lainnya dari logam yang belum termasuk dalam kelompok 25931 s.d. 25933, misalnya kunci, gembok, kunci pintu, engsel, gerendel dan peralatan sejenisnya untuk bangunan, furnitur dan lainnya. Termasuk industri pisau pendek atau belati, pedang, bayonet, dan lain-lain.',NULL,NULL,0),
	(573,'25940','INDUSTRI EMBER, KALENG, DRUM DAN WADAH SEJENIS DARI LOGAM','Kelompok ini mencakup usaha pembuatan wadah dari logam/kaleng, seperti kaleng makanan/minuman, kaleng cat/bahan kimia lainnya, tong, drum, ember, kotak, jerrycan dan sejenisnya. Termasuk industri metallic closure.',NULL,NULL,0),
	(574,'25951','INDUSTRI BARANG DARI KAWAT','Kelompok ini mencakup usaha pembuatan macam-macam barang dari kawat logam, termasuk tali kawat logam, seperti kawat berduri, pagar kawat, kasa kawat, jaring kawat dan alat pemanggang (grill). Industri kabel listrik dan komunikasi dimasukkan dalam kelompok 27310 dan 27320. Termasuk industri pegas (selain pegas jam), seperti leaf springs, helical springs, torsion bar springs dan lembaran untuk pegas dan industri rantai (kecuali power transmission chain).',NULL,NULL,0),
	(575,'25952','INDUSTRI PAKU, MUR DAN BAUT','Kelompok ini mencakup usaha pembuatan paku, mur, baut dan barang berulir sejenis yang terbuat dari besi, baja, tembaga, alumunium dan logam lainnya.',NULL,NULL,0),
	(576,'25991','INDUSTRI BRANKAS, FILLING KANTOR DAN SEJENISNYA','Kelompok ini mencakup pembuatan alat-alat kantor dari logam, seperti brankas, filling cabinet, tidak termasuk furnitur dari logam. Termasuk industri peti besi, lemari besi, pintu lapis baja dan lain-lain.',NULL,NULL,0),
	(577,'25992','INDUSTRI PERALATAN DAPUR DAN PERALATAN MEJA DARI LOGAM','Kelompok ini mencakup usaha pembuatan alat-alat dapur baik dari alumunium maupun dari logam bukan alumunium seperti peralatan makan, piring, piring ceper, mangkok, teko, panci, wajan ketel, periuk, dandang, ketel masak, rantang, baskom, baki, pot dan sejenisnya. Termasuk peralatan bukan listrik lainnya yang digunakan di meja atau di dapur, peralatan kecil dapur lainnya yang digerakkan dengan tangan dan aksesorinya dan alat penggosok dari logam.',NULL,NULL,0),
	(578,'25993','INDUSTRI KEPERLUAN RUMAH TANGGA DARI LOGAM BUKAN PERALATAN DAPUR DAN PERALATAN MEJA','Kelompok ini mencakup usaha pembuatan alat-alat untuk keperluan rumah tangga lainnya baik dari alumunium maupun dari logam bukan alumunium seperti jemuran, tangga, lemari dapur dan lain-lain. Termasuk industri bak mandi, bak cuci (piring), wastafel dan peralatan sejenis.',NULL,NULL,0),
	(579,'25994','INDUSTRI PEMBUATAN PROFIL','Kelompok ini mencakup usaha pembuatan baja profil dengan cara las, seperti profil H (H-Beam), profil I (I-Beam) dan sejenisnya.',NULL,NULL,0),
	(580,'25995','INDUSTRI LAMPU DARI LOGAM','Kelompok ini mencakup usaha pembuatan macam-macam lampu yang bahan utamanya dari logam, seperti lampu mercu suar, lampu tekan dan lampu gantung termasuk komponennya.',NULL,NULL,0),
	(581,'25999','INDUSTRI BARANG LOGAM LAINNYA YTDL','Kelompok ini mencakup usaha pembuatan macam-macam barang dari logam, yang belum tercakup di subgolongan manapun seperti jepitan rambut, peniti, stapless, paper clips, jarum, jarum jahit, jarum bordir dan jarum sejenisnya, kepala gesper, rantai logam, bel, bingkai (lis) gambar, papan nama logam dan berbagai barang logam yang kecil. Termasuk baling-baling, rantai kapal, jangkar kapal, lonceng, perlengkapan tetap (fixture) rel kereta api yang terpasang, kabel logam yang dijalin pembalut sejenisnya, kabel logam yang tidak terisolasi atau kabel logam terisolasi yang tidak dapat digunakan sebagai konduktor listrik, paku dan paku payung, paku sumbat/keling, cincing penutup dan barang-barang tidak berulir sejenis, screw machine product, kantong timah, magnet logam permanen, botol atau kendi logam hampa udara, tanda logam (bukan listrik), lencana logam dan lencana militer logam dan pengeriting rambut dan sisir logam, kerangka dan pegangan payung.',NULL,NULL,0),
	(582,'26110','INDUSTRI TABUNG ELEKTRON DAN KONEKTOR ELEKTRONIK','Kelompok ini mencakup pembuatan tabung gambar televisi, tabung kamera televisi, tabung dan katup amplifier dan receiver. Termasuk tabung elektron, konektor elektronik, kabel printer, kabel monitor, kabel USB, konektor dan lain-lain, katup elektronik dan tabung lampu.',NULL,NULL,0),
	(583,'26120','INDUSTRI SEMI KONDUKTOR DAN KOMPONEN ELEKTRONIK LAINNYA','Kelompok ini mencakup pembuatan semi konduktor dan komponen elektronik lainnya, seperti transistor dan peralatan semi konduktor yang sejenis, integrated circuits, printed circuits, induktor, resistor, kapasitor dan berbagai komponen elektronik lainnya. Termasuk industri mikroprosesor, induktor jenis komponen elektronik (misalnya cok, gulungan, trafo), kristal elektronik dan crystal assemblies, solenoida, switch dan transducer untuk aplikasi elektronik, interface cards (misalnya sound (kartu suara), video (kartu video), kontroler, kartu jaringan, modem), komponen layar (plasma, polimer, LCD), light emitting diodes (LED), IC atau integrated circuit (analog, digital, maupun hibrid) dan dioda. Termasuk juga pembuatan sel fotovoltaik dan chip smartcard.',NULL,NULL,0),
	(584,'26210','INDUSTRI KOMPUTER DAN/ATAU PERAKITAN KOMPUTER','Kelompok ini mencakup usaha pembuatan berbagai macam mesin komputasi, seperti komputer desktop, komputer laptop, komputer mainframe, komputer ukuran tangan (misal PDA), komputer tablet, dan server komputer. Termasuk kegiatan perakitan komputer.',NULL,NULL,0),
	(585,'26220','INDUSTRI PERLENGKAPAN KOMPUTER','Kelompok ini mencakup pembuatan perlengkapan komputer, seperti disk drive magnetik, flash drive dan alat penyimpanan lainnya, disk drive optik (misalnya CD-RW, CD-ROM, DVD-ROM, DVD-RW), printer, monitor, keyboard, mouse, joystick, dan aksesori trackball, terminal komputer, scanner, bar code scanner, smart card reader, proyektor komputer (video beamer), alat perlengkapan media imersif (virtual reality/augmented reality/mixed reality) seperti virtual reality helmets, augmented reality glasses, dan alat pendukung lainnya. Termasuk industri terminal komputer, seperti anjungan tunai mandiri (ATM), terminal point of sale (POS), yang tidak dioperasikan secara mekanis dan peralatan kantor multifungsi, seperti kombinasi faks- scanner-fotokopi.',NULL,NULL,0),
	(586,'26310','INDUSTRI PERALATAN TELEPON DAN FAKSIMILI','Kelompok ini mencakup pembuatan alat-alat transmisi komunikasi, seperti peralatan pesawat telepon dan faksimili, termasuk di dalamnya mesin penjawab dan lainnya.',NULL,NULL,0),
	(587,'26320','INDUSTRI PERALATAN KOMUNIKASI TANPA KABEL (WIRELESS)','Kelompok ini mencakup pembuatan alat-alat transmisi komunikasi, seperti peralatan pager, telepon selular, tablet seluler, dan peralatan komunikasi bergerak (mobile) dan lainnya.',NULL,NULL,0),
	(588,'26391','INDUSTRI KARTU CERDAS (SMART CARD)','Kelompok ini mencakup pembuatan smart card, seperti perencanaan design chip (design house), perencanaan tata letak sirkuit smart card, industri chip foundry, industri chip module packaging, pembuatan firmware dan software yang berkaitan langsung dengan smart card, chip packaging. Contoh smart card seperti simcard, Near Field Communications (NFC), dengan teknologi 2G, 3G, 4G, 5G dst, kartu perbankan, kartu akses, micro dan macro payment, kartu kredit dan semua kartu yang menggunakan pengaman data dan atau komunikasi.',NULL,NULL,0),
	(589,'26399','INDUSTRI PERALATAN KOMUNIKASI LAINNYA','Kelompok ini mencakup pembuatan alat-alat transmisi komunikasi lainnya, peralatan Private Branch Exchange (PBX), peralatan komunikasi data (bridge, router, gateway), pesawat telepon tanpa kabel, peralatan TV kabel, antena transmisi (pemancar) dan penerima, peralatan studio televisi dan radio dan peralatan siaran termasuk kamera televisi, modem peralatan carrier, sistem alarm kebakaran dan pencurian, transmitor radio dan televisi, peralatan infrared (misalnya remote kontrol), EDC (Electronic Data Capture) dan lainnya. Termasuk juga pembuatan set top box untuk terestrial dan satelit.',NULL,NULL,0),
	(590,'26410','INDUSTRI TELEVISI DAN/ATAU PERAKITAN TELEVISI','Kelompok ini mencakup pembuatan televisi, seperti pesawat penerima televisi dan kombinasi, monitor televisi dan pertunjukan. Termasuk perakitan televisi.',NULL,NULL,0),
	(591,'26420','INDUSTRI PERALATAN PEREKAM, PENERIMA DAN PENGGANDA AUDIO DAN VIDEO, BUKAN INDUSTRI TELEVISI','Kelompok ini mencakup pembuatan peralatan audio dan video elektronik untuk hiburan di rumah (home entertainment) untuk rumah tangga dan kendaraan bermotor, seperti pesawat penerima radio dan kombinasi, tape recorder dan video recorder. Termasuk industri peralatan stereo, pemutar CD dan VCD/DVD, kamera video jenis rumah tangga dan jukebox.',NULL,NULL,0),
	(592,'26490','INDUSTRI PERALATAN AUDIO DAN VIDEO ELEKTRONIK LAINNYA','Kelompok ini mencakup pembuatan peralatan elektronika untuk rumah tangga, seperti mikrofon, loudspeaker, headphone, amplifier dan sebagainya. Termasuk industri mesin karaoke, headphone (radio, stereo, komputer) dan konsol video game dan lainnya.',NULL,NULL,0),
	(593,'26511','INDUSTRI ALAT UKUR DAN ALAT UJI MANUAL','Kelompok ini mencakup usaha pembuatan alat-alat pengukur, pemeriksa dan pengujian manual, baik yang ada maupun yang tidak ada hubungannya dengan penyelidikan ilmu pengetahuan dan bersifat mekanis, seperti pesawat ukur, thermometer, barometer, kompas, timbangan presisi, pesawat terapi mekanis, meteran air ledeng dan gas, serta instrumen ukur tanah. Termasuk juga perlengkapan dari peralatan-peralatan tersebut. Kelompok ini mencakup juga usaha pembuatan alat-alat pengukur, pemeriksa dan pengujian manual yang berhubungan dengan kesehatan, seperti timbangan badan dan timbangan bayi.',NULL,NULL,0),
	(594,'26512','INDUSTRI ALAT UKUR DAN ALAT UJI ELEKTRIK','Kelompok ini mencakup usaha pembuatan alat-alat pengukur, pemeriksa dan pengujian elektrik/listrik, baik yang ada maupun yang tidak ada hubungannya dengan penyelidikan ilmu pengetahuan, seperti meteran arus listrik. Termasuk juga perlengkapan dari peralatan-peralatan tersebut.',NULL,NULL,0),
	(595,'26513','INDUSTRI ALAT UKUR DAN ALAT UJI ELEKTRONIK','Kelompok ini mencakup usaha pembuatan alat-alat instrumen analitis, skala, neraca dan inkubator laboratorium serta alat laboratorium lainnya untuk pengukuran dan pengujian, alat-alat pengukur dan pemeriksa elektronik, baik yang ada maupun yang tidak ada hubungannya dengan penyelidikan ilmu pengetahuan, seperti pesawat pengatur elektronik otomatis, speedometer, argometer, elektronik sinar katoda, radar, radio kontrol dan instrumen navigasi, meteorologi, geofisika, hidrologi dan spectofotometer serta alat ukur digital (termasuk thermometer dan barometer). Termasuk juga perlengkapan dari peralatan-peralatan tersebut. Kelompok ini mencakup juga usaha pembuatan mikroskop proton dan elektron (kecuali mikroskop optis) dan timbangan digital.',NULL,NULL,0),
	(596,'26514','INDUSTRI ALAT UJI DALAM PROSES INDUSTRI','Kelompok ini mencakup pembuatan berbagai peralatan pengukuran dan kontrol dari barang-barang yang sedang diproses, baik alat ukur panas, tekanan, kekentalan, maupun alat ukur sifat-sifat barang.',NULL,NULL,0),
	(597,'26520','INDUSTRI ALAT UKUR WAKTU','Kelompok ini mencakup usaha pembuatan macam-macam jam seperti arloji tangan, arloji saku, arloji kalung, jam dinding, jam beker dan lonceng. Termasuk juga usaha pembuatan bagian-bagian dari jam/arloji, seperti movement part, dial plate/hand, pegas, batu baterai, lempeng jam, jarum dan bagian lainnya, case (badan) jam dan arloji, termasuk case (badan) dari logam mulia, alarm for watch, instrumen panel clocks, crono meter, stop watch, pencatat waktu parking, pencatat waktu datang dan pulang pegawai (pencatat waktu absen), time/date stamps dan pencatat waktu proses, time locks (pengunci waktu) dan lain-lain.',NULL,NULL,0),
	(598,'26601','INDUSTRI PERALATAN IRADIASI/SINAR X, PERLENGKAPAN DAN SEJENISNYA','Kelompok ini mencakup usaha pembuatan peralatan dan tabung iradiasi (penyinaran) yang didasarkan pada penggunaan radiasi sinar X, Alpha, Beta, atau Gamma, baik yang digunakan pada bidang kesehatan dan industri, seperti peralatan industri, peralatan iradiasi susu dan makanan, diagnosa medis, terapi medis, penelitian dan ilmu pengetahuan, peralatan pengukuran (gauging), dan peralatan pengeboran (well logging). Misalnya peralatan radiasi sinar X, beta, gamma dan sinar lainnya. Termasuk pula pembuatan tabung sinar X, kontrol panel, screen dan yang terkait, serta peralatan sterilisasi dengan sinar ultra violet.',NULL,NULL,0),
	(599,'26602','INDUSTRI PERALATAN ELEKTROMEDIKAL DAN ELEKTROTERAPI','Kelompok ini mencakup pembuatan peralatan dan perlengkapan elektromedikal dan elektroterapi, seperti peralatan electrocardiograph, peralatan test mata (termasuk reflektor, endoscope dan lain-lain), ozone therapy, oxygen therapy, penangkap citra (scanner) untuk diagnosa medis, peralatan MRI (magnetic resonce imaging), peralatan ultrasound medis, peralatan endoskopi elektromedikal, peralatan laser medis, peralatan alat bantu dengar dan peralatan alat pacu jantung.',NULL,NULL,0),
	(600,'26710','INDUSTRI PERALATAN FOTOGRAFI','Kelompok ini mencakup usaha pembuatan macam-macam kamera fotografi, seperti kamera foto biasa, kamera langsung jadi, kamera untuk micro film, kamera digital, kamera untuk still picture dan kamera untuk penelitian udara.',NULL,NULL,0),
	(601,'26791','INDUSTRI KAMERA CINEMATOGRAFI PROYEKTOR DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha pembuatan macam-macam kamera cinematografi, proyektor, seperti kamera cinematografi, proyektor cinematografi, image proyektor, slide projector, overhead transparancy projector, aparat cahaya kilat fotografi, frame kamera, tempat film dan lensa kamera zoom. Termasuk alat pengukur cahaya untuk fotografi.',NULL,NULL,0),
	(602,'26792','INDUSTRI TEROPONG DAN INSTRUMEN OPTIK BUKAN KACA MATA','Kelompok ini mencakup usaha pembuatan teropong dan alat optik serta bagian- bagiannya untuk ilmu pengetahuan dan percetakan seperti teropong monoculer, teropong astronomi, elbow telescope, periscope, optik, spectroscope, spectograph, lensa berlapis diasah, lensa prisma. Termasuk mikroskop optik, binokular dan teleskop, cermin optik, peralatan kaca pembesar optik, peralatan presisi (ketepatan) masinis optik, komparator optik, peralatan pembidik senjata optik, peralatan positioning optik, peralatan dan instrumen pengukuran dan pemeriksaan optik (misalnya peralatan pengontrol api/fire control equipment, pengukur jarak) dan peralatan laser. Kelompok ini juga mencakup industri pelapisan, penggosokan lensa dan mounting lensa (bukan opthalmik) dan lainnya.',NULL,NULL,0),
	(603,'26800','INDUSTRI MEDIA MAGNETIK DAN MEDIA OPTIK','Kelompok ini mencakup usaha pembuatan media rekam magnetik dan optik untuk suara, gambar maupun data, yang bahan utamanya dari plastik, seperti pita audio dan video magnetik kosong, kaset audio dan video magnetik kosong, piringan hitam kosong, film yang belum peka terhadap cahaya, pita untuk merekam data dan disk/diskette kosong dan disk optik kosong dan media hard drive. Usaha pembuatan film yang peka terhadap cahaya dimasukkan dalam kelompok 20299. Usaha rekaman suara dengan media pita kaset, piringan hitam dimasukkan dalam kelompok 59201. Sedangkan rekaman gambar film dan pita video dimasukkan dalam subgolongan 5911 (Produksi gambar Bergerak, Video dan Program Televisi). Usaha rekaman data dengan pita, disk/diskette dan sejenisnya yang menggunakan jasa komputer dimasukkan dalam kelompok 62090.',NULL,NULL,0),
	(604,'27111','INDUSTRI MOTOR LISTRIK','Kelompok ini mencakup usaha pembuatan motor listrik dan komponen/bagiannya, seperti motor AC, motor DC, stator, rotor, brush dan commutator, kecuali mesin pembakaran dalam untuk menyalakan motor.',NULL,NULL,0),
	(605,'27112','INDUSTRI MESIN PEMBANGKIT LISTRIK','Kelompok ini mencakup usaha pembuatan generator dan komponen/bagiannya seperti generator arus bolak-balik, generator arus searah, generator set, stator, rotor, commutator dan rotary converter. Termasuk generator tenaga (kecuali alternator pengisi baterai untuk mesin pembakaran dalam), perangkat generator motor (kecuali perangkat generator turbin) dan perangkat generator penggerak utama.',NULL,NULL,0),
	(606,'27113','INDUSTRI PENGUBAH TEGANGAN (TRANSFORMATOR), PENGUBAH ARUS (RECTIFIER) DAN PENGONTROL TEGANGAN (VOLTAGE STABILIZER)','Kelompok ini mencakup usaha pembuatan transformator, pengubah arus, pengontrol tegangan dan komponen/bagiannya, seperti transformator distribusi, transformator tenaga, pengubah arus AC ke DC , pengontrol tegangan, radiator, ring bike lite dan commutator. Termasuk transformator distribusi listrik, transformator arc-welding, flourescent ballast atau lighting ballast, transformator sub stasiun untuk distribusi tenaga listrik dan pengatur transmisi dan distribusi voltase listrik.',NULL,NULL,0),
	(607,'27120','INDUSTRI PERALATAN PENGONTROL DAN PENDISTRIBUSIAN LISTRIK','Kelompok ini mencakup usaha pembuatan panel listrik dan switch gear serta komponen/bagiannya, seperti control panel otomatis, ligthing distribution board, pemutus aliran listrik, pemutus arus dan control desk, control panel dan pengaliran sakelar tertutup. Termasuk sakelar pemutus aliran listrik, angker dinamo untuk untuk pabrik, surge suppressor/penindas sentakan listrik (untuk distribusi tingkat voltase), panel kontrol untuk distribusi tenaga listrik, relay listrik, pipa/saluran peralatan papan penghubung/switchboard aliran listrik, sekering listrik, peralatan pemindah tenaga (power switching), saklar tenaga listrik (kecuali tombol tekan, snap, solenoida, tumbler) dan KWH meter.',NULL,NULL,0),
	(608,'27201','INDUSTRI BATU BATERAI','Kelompok ini mencakup usaha pembuatan segala macam batu baterai, seperti sel dan baterai listrik primer, baterai alkali, dan baterai mercury. Termasuk baterai dan sel-sel utama, baik yang mengandung mangan dioksida, merkuri dioksida, perak oksida atau lainnya, baterai asam timah, baterai Ni-Cad, baterai Ni-Mh, baterai Lithium, baterai cell kering dan baterai cell basah. Termasuk penggunaan untuk baterai HP dan baterai laptop.',NULL,NULL,0),
	(609,'27202','INDUSTRI AKUMULATOR LISTRIK','Kelompok ini mencakup usaha pembuatan macam-macam akumulator listrik, aki dan komponennya seperti aki dari 6V atau 12V dengan kekuatan 200 amper atau kurang, pelat aki, separator, wadah, penutup, pole dan jepitan aki (tipe gigi).',NULL,NULL,0),
	(610,'27203','INDUSTRI BATERAI UNTUK KENDARAAN BERMOTOR LISTRIK','Kelompok ini mencakup usaha pembuatan segala macam baterai untuk kendaraan bermotor listrik.',NULL,NULL,0),
	(611,'27310','INDUSTRI KABEL SERAT OPTIK','Kelompok ini mencakup usaha pembuatan kabel serat optik.',NULL,NULL,0),
	(612,'27320','INDUSTRI KABEL LISTRIK DAN ELEKTRONIK LAINNYA','Kelompok ini mencakup usaha pembuatan macam-macam kabel listrik dan kabel elektronik yang dibalut dengan isolator atau berpenyekat dari baja, tembaga atau aluminium, seperti kabel komunikasi atau telepon, kabel listrik jaringan tegangan rendah/menengah/ tinggi. Usaha pembuatan kawat/kabel logam tanpa dibalut dimasukkan dalam kelompok 24202.',NULL,NULL,0),
	(613,'27330','INDUSTRI PERLENGKAPAN KABEL','Kelompok ini mencakup usaha pembuatan fitting, sakelar, stop kontak dan sebagainya, seperti batang penghantar, konduktor listrik (kecuali jenis switchgear), GFCI (ground fault circuit interrupter), lamp holder, penangkal petir dan koil, steker untuk untuk perangkat kawat listrik (misalnya penekan, tombol tekan, snap, tumbler switcher), outlet dan socket listrik (stop kontak), kotak untuk peralatan kawat listrik (seperti junction, outlet, switch box), kabel dan peralatan listrik, kutub transmisi dan line hardware dan plastik untuk peralatan kawat bukan pembawa arus termasuk kotak plastik junction, face plates dan sejenisnya dan peralatan pole line plastik.',NULL,NULL,0),
	(614,'27401','INDUSTRI BOLA LAMPU PIJAR, LAMPU PENERANGAN TERPUSAT DAN LAMPU ULTRA VIOLET','Kelompok ini mencakup usaha pembuatan macam-macam lampu pijar untuk penerangan, seperti bohlam tidak termasuk fitting dan perlengkapannya, penerangan fotografi (flash bulbs) dan penerangan untuk panggung/lampu sorot (spot light). Termasuk lampu ultra violet dan infra red, lampu senter, penerangan pada alat-alat kedokteran. Usaha pembuatan peralatan penerangan pada sepeda dan kendaraan bermotor dimasukkan pada kelompok 27403.',NULL,NULL,0),
	(615,'27402','INDUSTRI LAMPU TABUNG GAS (LAMPU PEMBUANG LISTRIK)','Kelompok ini mencakup usaha pembuatan macam-macam lampu tabung gas dan discharge, seperti lampu neon, lampu helium, lampu argon, lampu natrium dan lampu mercury. Termasuk lampu listrik serangga.',NULL,NULL,0),
	(616,'27403','INDUSTRI PERALATAN PENERANGAN UNTUK ALAT TRANSPORTASI','Kelompok ini mencakup pembuatan peralatan penerangan untuk alat transportasi motor, mobil, pesawat, kapal dan alat transportasi lainnya (lampu rem, lampu tanda berbelok, lampu interior dan sebagainya). Termasuk usaha pembuatan komponen dan perlengkapannya.',NULL,NULL,0),
	(617,'27404','INDUSTRI LAMPU LED','Kelompok ini mencakup usaha pembuatan lampu LED, baik berupa lampu LED terpisah maupun dirakit menjadi lampu untuk kebutuhan tertentu. Misalnya lampu LED lampu senter, kendaraan mauapu pencahayaan umum.',NULL,NULL,0),
	(618,'27409','INDUSTRI PERALATAN PENERANGAN LAINNYA','Kelompok ini mencakup usaha pembuatan atau industri peralatan penerangan yang dipasang di langit-langit, tempat lilin (chandeliers), lampu meja, perangkat lampu hias pohon natal, batang perapian listrik, lentera (dengan bahan bakar karbit, listrik, gas, bensin, minyak tanah), peralatan lampu jalan (kecuali rambu-rambu lalu lintas) dan peralatan penerangan bukan listrik. Termasuk komponen lampu listrik seperti stater, filamen dan reflektor. Industri ballast tercakup di kelompok 27113.',NULL,NULL,0),
	(619,'27510','INDUSTRI PERALATAN LISTRIK RUMAH TANGGA','Kelompok ini mencakup pembuatan selimut listrik, penghisap debu (vacuum cleaners), pengkilat lantai (floor polishers), tempat sampah listrik, peralatan untuk mengolah dan mempersiapkan makanan (grinders, blenders, pembuka kaleng, juicers, dan sebagainya) dan peralatan listrik lainnya seperti sikat gigi listrik, alat-alat cukur listrik dan alat-alat perawatan tubuh listrik lainnya, pengasah pisau listrik dan sebagainya. Termasuk kulkas (refrigerator), mesin pencuci piring, mesin pencuci dan pengering pakaian, unit pembuangan/tempat sampah dan kap ventilasi. Pembuatan mesin cuci, mesin pengering dan sejenisnya dalam bentuk yang besar atau untuk kepentingan niaga dimasukkan dalam kelompok 28262. Pembuatan mesin jahit baik untuk keperluan rumah tangga maupun tidak dimasukkan dalam kelompok 28262.',NULL,NULL,0),
	(620,'27520','INDUSTRI PERALATAN ELEKTROTERMAL RUMAH TANGGA','Kelompok ini mencakup pembuatan kompor (misalnya oven, microwave oven, cookers, hot plates, toasters, pembuat kopi dan teh, frypans, roasters, penggorengan dan pemanggang listrik dan hoods dan sebagainya), alat pemanas dan alat masak dengan menggunakan arus listrik, kipas angin dan pemanas ruangan. Termasuk industri peralatan elektrotermal rumah tangga, seperti alat pemanas air listrik, selimut listrik, alat listrik untuk perawatan rambut (pengering, sisir, sikat, pengeriting), setrika listrik, alat resistor pemanas listrik dan lain-lain.',NULL,NULL,0),
	(621,'27530','INDUSTRI PERALATAN PEMANAS DAN MASAK BUKAN LISTRIK RUMAH TANGGA','Kelompok ini mencakup pembuatan atau industri peralatan masak dan pemanas bukan listrik rumah tangga, seperti kompor masak, panggangan, pemanas air, peralatan masak lain, penghangat makanan, penghangat piring dan lain-lain dan pemanas ruangan bukan listrik, seperti tungku atau perapian.',NULL,NULL,0),
	(622,'27900','INDUSTRI PERALATAN LISTRIK LAINNYA','Kelompok ini mencakup pembuatan dinamo lampu sepeda, dinamo magnetik, busi, alat-alat peringatan suara (sirine, klakson, alarm, bel, dan sebagainya), peralatan sinyal listrik seperti alat-alat pengatur lalu-lintas jalan raya, jalan kereta api, di pelabuhan laut dan udara dan sinyal untuk pejalan kaki, berbagai peralatan listrik dan elektronik yang tidak termasuk kelompok manapun, seperti charger (pengisi) baterai padat, alat pembuka dan penutup pintu listrik, mesin pembersih ultrasonik (kecuali untuk laboratorium, dokter gigi), tanning beds, peralatan solid state inverter, peralatan rektifikasi, fuel cells, penyuplai daya teregulasi dan tidak teregulasi, UPS (uninterruptible power supllies), supresor gelombang (kecuali untuk distribusi level voltase), kabel peralatan, kabel sambungan, perangkat kabel listrik lainnya yang berpenyekat dan berkonektor, karbon dan grafit elektroda, kontak dan produk karbon dan grafit listrik lainnya, akselerator partikel, kapasitor, resistor, kondenser listrik dan komponen sejenisnya, elektromagnet, papan skor listrik, reklame listrik, insulator (penyekat) listrik (kecuali penyekat kaca atau porselen), peralatan patri dan solder listrik, besi solder tangan dan pembuatan peralatan modul fotovoltaik (panel surya), rokok elektrik (vape). Termasuk usaha pembuatan komponen dan perlengkapannya.',NULL,NULL,0),
	(623,'28111','INDUSTRI MESIN UAP, TURBIN DAN KINCIR','Kelompok ini mencakup usaha pembuatan motor penggerak yang bukan berupa motor bakar dalam, seperti mesin uap, turbin dan bagian-bagiannya, turbin uap dan turbin sejenis lainnya, turbin hidrolik, kincir air dan regulatornya, turbin angin dan turbin gas/udara, kecuali turbojet atau turbo baling-baling untuk pesawat terbang; perangkat turbin-ketel (boiler-turbine), perangkat generator-turbin dan kincir angin.',NULL,NULL,0),
	(624,'28112','INDUSTRI MOTOR PEMBAKARAN DALAM','Kelompok ini mencakup usaha pembuatan motor penggerak mula dengan bahan pembakaran dalam, baik berupa motor bakar cetus api maupun motor bakar nyala kompresi, seperti motor diesel, motor bensin, motor bakar dalam dengan bahan bakar gas/alkohol, dan sejenisnya. Termasuk Industri mesin piston pembakaran dalam (kecuali mesin kendaraan bermotor, pesawat terbang dan mesin penggerak putaran), seperti mesin kapal laut dan mesin kereta api. Usaha pembuatan motor pembakaran dalam untuk kendaraan bermotor roda empat atau lebih dimasukkan dalam kelompok 29101 dan 29102. Usaha pembuatan motor pembakaran dalam untuk kendaraan bermotor roda dua dan tiga dimasukkan dalam kelompok 30912, dan motor pembakaran dalam untuk pesawat terbang dimasukan dalam kelompok 30300.',NULL,NULL,0),
	(625,'28113','INDUSTRI KOMPONEN DAN SUKU CADANG MESIN DAN TURBIN','Kelompok ini mencakup usaha pembuatan komponen/suku cadang, dari mesin-mesin penggerak mula (kelompok 28111 dan 28112), seperti engine block, piston, cincin piston, karburator cylinder head dan sejenisnya untuk semua jenis mesin pembakaran dalam, mesin diesel dan sebagainya dan inlet dan klep/katup pelepas gas dari mesin pembakaran dalam.',NULL,NULL,0),
	(626,'28120','INDUSTRI PERALATAN TENAGA ZAT CAIR DAN GAS','Kelompok ini mencakup usaha pembuatan komponen hidrolik dan pneumatik, termasuk didalamnya pompa hidrolik, motor hidrolik, silinder hidrolik dan pneumatik, klep/katup hidrolik dan pneumatik, perkakas dan pipa karet hidrolik dan pneumatik; peralatan pengolahan udara yang digunakan dalam sistem pneumatik; sistem tenaga zat cair dan gas; dan peralatan transmisi hidrolik.',NULL,NULL,0),
	(627,'28130','INDUSTRI POMPA LAINNYA, KOMPRESOR, KRAN DAN KLEP/KATUP','Kelompok ini mencakup usaha pembuatan kompresor udara dan gas, kompresor untuk refrigerator dan AC, kompresor untuk kendaraan bermotor, pompa laboratorium, pompa air, pompa udara, pompa vakum atau pompa udara, kompresor udara dan gas lainnya, pompa untuk zat cair baik terpasang alat pengukur ataupun tidak, pompa yang didesain untuk mesin pembakaran dalam, seperti pompa bahan bakar, oli, dan air untuk kendaraan bermotor dan sebagainya. Termasuk katup dan keran air dari logam, seperti klep/katup dan kran untuk keperluan industri, mencakup klep/katup regulasi dan kran pipa masuk; kran dan katup untuk kebersihan (sanitasi); kran dan katup untuk pemanasan; dan pompa tangan. Katup dari karet dimasukkan ke subgolongan 2219. Keran dari porselen dimasukkan ke subgolongan 23931.',NULL,NULL,0),
	(628,'28140','INDUSTRI BEARING, RODA GIGI DAN ELEMEN PENGGERAK MESIN','Kelompok ini mencakup usaha pembuatan bola dan bantalan poros (ball and roller bearings), termasuk bola, bantalan guling, ring dan bagian-bagian lain dari bearings. Termasuk pula pembuatan komponen dan suku cadang peralatan transmisi mekanik, antara lain cam shafts, poros engkol (crank shafts), engkol, kerangka bearing dan bearing poros sederhana, persneling, roda gigi, bantalan blok, kopling dan poros kopling, roda gendeng dan kerek/katrol, mata rantai bersambung, rantai transmisi tenaga (rantai keteng) dan sebagainya.',NULL,NULL,0),
	(629,'28151','INDUSTRI OVEN, PERAPIAN DAN TUNGKU PEMBAKAR SEJENIS YANG TIDAK MENGGUNAKAN ARUS LISTRIK','Kelompok ini mencakup usaha pembuatan tungku dan alat sejenis yang tidak menggunakan arus listrik, untuk memanaskan, memanggang dan melelehkan bijih besi, logam dan sejenisnya, tungku pembakar, peralatan pemanas rumah tangga bukan listrik permanen untuk daerah pegunungan, seperti peralatan pemanas solar, pemanas uap, pemanas minyak dan peralatan pemanas dan tungku sejenisnya. Termasuk pembuatan mechanical stokers, mechanical grates, mechanical ash discharges dan sejenisnya.',NULL,NULL,0),
	(630,'28152','INDUSTRI OVEN, PERAPIAN DAN TUNGKU PEMBAKAR SEJENIS YANG MENGGUNAKAN ARUS LISTRIK','Kelompok ini mencakup usaha pembuatan tungku, oven dan alat pemanas lainnya yang penggunaannya memerlukan arus listrik, misalnya peralatan induksi listrik untuk industri dan laboratorium termasuk incinerator, tungku pembakar, peralatan pemanas ruangan listrik permanen untuk daerah pegunungan, pemanas kolam renang listrik dan tungku listrik untuk rumah tangga. Alat pengatur panas untuk makanan, minuman dan tembakau termasuk pula non-electric oven untuk pembuat roti dimasukkan dalam kelompok 28250, sedangkan alat pengatur panas untuk pulp, kertas dan bahan industri lainnya dimasukkan dalam kelompok 28292 dan 28299.',NULL,NULL,0),
	(631,'28160','INDUSTRI ALAT PENGANGKAT DAN PEMINDAH','Kelompok ini mencakup pembuatan mesin pengangkat dan pemindah (pemuat dan pembongkar) barang dan orang yang digerakkan dengan tangan atau tenaga yang digunakan di pabrik, gudang, pelabuhan, terminal, stasiun kereta api, bandar udara dan sebagainya, seperti katrol kerek (alat kerek), winches, putaran/paksi jangkar dan dongkrak; derrick, crane, mobile lifting frame, staddle carriers dan lain-lain; truk kerja, baik yang memakai alat angkut dan alat angkat maupun tidak, baik yang tidak dilengkapi dengan pendorong maupun yang tidak, dan truk kerja yang digunakan dalam pabrik (termasuk alat angkut dengan tangan dan gerobak tangan); manipulator mekanik dan robot yang khusus dibuat untuk mengangkut, mengangkat, memuat dan membongkar. Termasuk alat pembawa barang, teleferics (kereta gantung) dan lain- lain, lift, eskalator dan pemindah pejalan kaki (lantai bergerak) dan bagian-bagian, conveyor, komponen dan peralatan khusus alat angkut dan alat angkat. Alat pengangkat dan pemindah seperti traktor yang digunakan di sektor pertanian dimasukkan dalam kelompok 28210. Alat pengangkut dan pemindah yang dibuat khusus untuk penggunaan di bawah tanah dimasukkan dalam kelompok 28240.',NULL,NULL,0),
	(632,'28171','INDUSTRI MESIN KANTOR DAN AKUNTANSI MANUAL','Kelompok ini mencakup usaha pembuatan macam-macam mesin kantor dan akuntansi secara manual, seperti mesin hitung manual, mesin tik manual, mesin stensil manual, mesin peruncing pensil, sempoa, alat timbang pos (postage meters), mesin pengelola surat (pengisi amplop, penyegel dan mesin pemberi alamat, membuka, mengurutkan, menscan), mesin pemeriksa, mesin stenografi, alat penjilid (penjilid plastik atau pita), mesin penghitung koin dan pembungkus koin, stapler dan pembersih stapler, mesin pemungutan suara, mesin isolasi (tape dispencer) dan mesin pembuat lubang kertas dan sejenisnya. Termasuk pembuatan komponen dan suku cadangnya. Jasa pemeliharaan dan perbaikannya tercakup dalam kelompok 33121.',NULL,NULL,0),
	(633,'28172','INDUSTRI MESIN KANTOR DAN AKUNTANSI ELEKTRIK','Kelompok ini mencakup usaha pembuatan macam-macam mesin kantor dan akuntansi elektrik, seperti mesin hitung elektrik, mesin tik elektrik, mesin stensil elektrik dan sejenisnya, kalkulator, alat timbang pos (postage meters), mesin pengelola surat (pengisi amplop, penyegel dan mesin pemberi alamat, membuka, mengurutkan, menscan), mesin pemeriksa, mesin stenografi, alat penjilid (contoh penjilid plastik atau pita), mesin pemeriksa tulisan, mesin penghitung koin dan pembungkus koin, peruncing pensil, stapler dan pembersih stapler, mesin pemungutan suara, mesin pembuat lubang kertas. Termasuk usaha pembuatan komponen dan suku cadangnya. Jasa pemeliharaan dan perbaikannya tercakup dalam kelompok 33121.',NULL,NULL,0),
	(634,'28173','INDUSTRI MESIN KANTOR DAN AKUNTANSI ELEKTRONIK','Kelompok ini mencakup usaha pembuatan macam-macam mesin kantor dan akuntansi elektronik, seperti mesin hitung elektronik, cash register dan sejenisnya. Usaha pembuatan sub assembly dan komponen elektronik mesin komputasi dimasukkan dalam kelompok 26120.',NULL,NULL,0),
	(635,'28174','INDUSTRI MESIN FOTOCOPI','Kelompok ini mencakup usaha pembuatan mesin fotocopi, mesin electronic sheet, mesin lightdruk dengan sistem optik atau contact type, termasuk perlengkapan dari mesin-mesin tersebut.',NULL,NULL,0),
	(636,'28179','INDUSTRI MESIN DAN PERALATAN KANTOR LAINNYA','Kelompok ini mencakup usaha pembuatan macam-macam mesin kantor lainnya, seperti toner cartridge, papan tulis, seperti white board dan marker board dan mesin pendikte.',NULL,NULL,0),
	(637,'28180','INDUSTRI PERKAKAS TANGAN YANG DIGERAKKAN TENAGA','Kelompok ini mencakup usaha pembuatan perkakas tangan (pertukangan) yang digerakkan tenaga, baik dengan motor listrik atau motor bukan listrik atau yang digerakkan dengan tekanan udara, seperti gergaji sirkular dan reciprocating, bor dan bor palu, penabur pasir yang digerakkan dengan tangan, alat pemaku (pneumatik), penyangga (buffers), router, penggerinda, stepler, alat paku tembak, alat ketam/serut, gunting dan catut, kunci inggris dan alat pemaku (powder actuated).',NULL,NULL,0),
	(638,'28191','INDUSTRI MESIN UNTUK PEMBUNGKUS, PEMBOTOLAN DAN PENGALENGAN','Kelompok ini mencakup pembuatan mesin pembungkus, pembotolan, dan pengalengan yang berfungsi sebagai pengisi, penutup, penyegel, pembungkus dan pemberian label di botol, kaleng dan kotak. Termasuk mesin untuk pengering dan pembersih botol minuman, mesin untuk mencampur udara ke dalam minuman dan sejenisnya.',NULL,NULL,0),
	(639,'28192','INDUSTRI MESIN TIMBANGAN','Kelompok ini mencakup pembuatan mesin-mesin timbangan (bukan untuk laboratorium), seperti timbangan untuk keperluan toko, kantor dan rumah tangga, alat penimbang yang menyatu dengan kalkulator, timbangan stasiun, scale for continuous weighing, jembatan timbang dan timbangan lainnya, baik bergerak atau tidak. Termasuk pembuatan komponen dan perlengkapannya.',NULL,NULL,0),
	(640,'28193','INDUSTRI MESIN PENDINGIN','Kelompok ini mencakup pembuatan mesin pendingin dan pembeku (cold storage) untuk tujuan komersial dan perakitan komponen utamanya, seperti lemari pamer (display cases), mesin-mesin penjual (dispense cases), mesin AC (air conditioning) termasuk untuk kendaraan bermotor, kipas angin dan exhaust hood untuk keperluan industri dan laboratorium termasuk pembuatan komponen dan perlengkapannya, dan mesin pendingin produk biologis (vaksin dan darah).',NULL,NULL,0),
	(641,'28199','INDUSTRI MESIN UNTUK KEPERLUAN UMUM LAINNYA YTDL','Kelompok ini mencakup pembuatan mesin umum lainnya, seperti fire sprinklers, mesin penyaring dan pembersih cairan dan gas, unit penyulingan cairan, peralatan untuk proyeksi, penyebaran atau penyemprotan cairan atau bubuk, seperti pistol semprot, pemadam api, mesin penyemprot pasir, mesin pembersih dengan uap air dan lain-lain, mesin penyulingan atau rektifikasi untuk kilang minyak, industry kimia, industry minuman dan lain-lain, mesin penukar panas (heat exchanger), mesin untuk mencairkan udara atau gas, generator gas, mesin penggulung lainnya dan silindernya (kecuali untuk logam dan kaca) termasuk calendering machine (mesin pres), mesin sentrifugal (kecuali mesin pemisah krim dan pengering pakaian), mesin paking dan tali untuk isolasi dan sejenisnya yang terbuat dari kombinasi bahan atau lapisan bahan yang sama, mesin penjual barang otomatis, kipas ventilasi loteng (kipas gable/dinding, ventilasi atap dan lain-lain), meteran pita dan perkakas tangan sejenis, alat presisi masinis (bukan optik) dan peralatan patri dan solder bukan listrik. Termasuk pembuatan komponen dan peralatannya.',NULL,NULL,0);
INSERT INTO `mst_kbli` (`id`, `kode`, `uraian`, `keterangan`, `created_at`, `updated_at`, `id_parent`)
VALUES
	(642,'28210','INDUSTRI MESIN PERTANIAN DAN KEHUTANAN','Kelompok ini mencakup usaha pembuatan mesin-mesin untuk penyiapan dan pengolahan lahan pertanian dan kehutanan misalnya traktor dan mesin bajak; mesin- mesin penanam, pemupuk, pemeliharaan tanaman dan pemanenan hasil-hasil (misalnya mesin penabur benih, mesin penugal, mesin penabur pupuk, mesin pemanen, mesin penyemprot, mesin pemotong rumput dan mesin penuai); serta mesin-mesin untuk pengolahan awal hasil pertanian (misalnya mesin perontok, mesin pengupas, mesin penyosoh dan mesin penggilingan gabah), trailer (kereta gandeng) atau semi trailer bongkar muat secara otomatis untuk pertanian, mesin pembersih dan pemilih atau penyortir telur, buah-buahan dan hasil perkebunan, mesin pemerah susu, mesin penghangat unggas, mesin beternak lebah, peralatan untuk penyiapan makanan ternak dan mesin lainnya untuk keperluan tanaman pangan, peternakan, perkebunan dan kehutanan. Termasuk mesin pembuatan komponen dan perlengkapan/implement mesin-mesin pertanian.',NULL,NULL,0),
	(643,'28221','INDUSTRI MESIN DAN PERKAKAS MESIN UNTUK PENGERJAAN LOGAM','Kelompok ini mencakup pembuatan mesin-mesin/peralatan untuk pengolahan dan pengerjaan logam, seperti mesin perkakas (misalnya mesin bubut, mesin freis, mesin gerinda, mesin gergaji, mesin press, mesin gunting), serta perlengkapan dan komponennya (seperti cutting tools, mould and dies, jig and fixture).',NULL,NULL,0),
	(644,'28222','INDUSTRI MESIN DAN PERKAKAS MESIN UNTUK PENGERJAAN KAYU','Kelompok ini mencakup pembuatan mesin-mesin/peralatan untuk pengolahan dan pengerjaan kayu, bambu, rotan, gabus dan sejenisnya, seperti berbagai mesin/peralatan, baik yang sederhana maupun modern, yang digunakan untuk pabrik sawmill, plywood, pabrik pengolahan rotan dan sejenisnya. Termasuk pula usaha pembuatan komponen dan perlengkapannya.',NULL,NULL,0),
	(645,'28223','INDUSTRI MESIN DAN PERKAKAS MESIN UNTUK PENGERJAAN BAHAN BUKAN LOGAM DAN KAYU','Kelompok ini mencakup pembuatan mesin-mesin/peralatan untuk pengolahan dan pengerjaan bahan selain logam dan kayu, seperti mesin/peralatan untuk pengolahan karet yang diperkeras (hardened rubber), plastik tebal (hard plastic), kaca, tulang dan lainnya.',NULL,NULL,0),
	(646,'28224','INDUSTRI MESIN DAN PERKAKAS MESIN UNTUK PENGELASAN YANG MENGGUNAKAN ARUS LISTRIK','Kelompok ini mencakup pembuatan mesin/peralatan untuk pengelasan dengan gas atau arus listrik, seperti mesin las listrik AC maupun DC. Termasuk pula pembuatan mesin sejenis yang menggunakan laser, photon beam, gelombang ultrasonic, electron beam dan magnetic pulse.',NULL,NULL,0),
	(647,'28230','INDUSTRI MESIN METALURGI','Kelompok ini mencakup pembuatan mesin dan perlengkapannya untuk pengerjaan logam panas, seperti mesin pengubah (converter), cetakan baja (ingot moulds), pencedok dan penuang dan mesin peleburan, mesin penggilingan penggulung logam dan penggulung untuk penggilingan sejenisnya. Termasuk pula pembuatan mesin canai logam baik panas maupun dingin.',NULL,NULL,0),
	(648,'28240','INDUSTRI MESIN PENAMBANGAN, PENGGALIAN DAN KONSTRUKSI','Kelompok ini mencakup pembuatan mesin-mesin peralatan untuk kegiatan pertambangan, penggalian, dan konstruksi, seperti alat pengangkat dan alat pengangkut (misalnya conveyor), mesin untuk menyaring, mensortir, memisahkan, mencuci, menghancurkan bahan-bahan mineral, mesin pengeboran, pemotongan dan mesin terowongan dan sinking (baik untuk penggunaan di bawah tanah atau tidak), traktor yang digunakan dalam kegiatan pertambangan dan konstruksi, mesin pemindah tanah, seperti bulldozer, angle dozer, graders, scrapers, leveler, sekop, sekop pemuatan dan perlengkapannya, dan berbagai mesin untuk kegiatan konstruksi, dan mesin pencampur beton dan mortar, mesin pile-driver dan pile ekstraktor, penyebar mortar dan aspal, mesin penghalus permukaan beton dan lain-lain, traktor tracklaying dan traktor yang digunakan dalam konstruksi atau pertambangan, pisau bulldozer dan angle dozer dan truk dumping off-road. Termasuk pembuatan bagian/komponen dan perlengkapannya.Pembuatan traktor untuk pertanian dimasukkan dalam kelompok 28210.',NULL,NULL,0),
	(649,'28250','INDUSTRI MESIN PENGOLAHAN MAKANAN, MINUMAN DAN TEMBAKAU','Kelompok ini mencakup pembuatan mesin-mesin untuk pengolahan berbagai makanan, minuman dan tembakau, seperti mesin pengolah makanan dan susu, mesin pengering pertanian, mesin pemisah krim, mesin pengolahan susu (misalnya homogenizers), mesin pengubah susu (misalnya pembuat keju, dan mesin pencetak keju) dan mesin pembuat keju (misalnya homogenizers, pencetakan, pengepresan), mesin untuk industri penggilingan padi atau biji-bjian, seperti mesin untuk membersihkan, memilih atau memilah benih padi atau biji-bijian dan sayuran kacang- kacangan yang dikeringkan (mesin penampi, lajur penyaring, pemisah, mesin penyikat biji-bijian dan lain-lain); dan mesin untuk memproduksi tepung dan bahan makanan dan lain-lain (mesin penggilingan biji-bijian, penyaring, pengayak tepung, pengisi, blender, pembersih kulit padi, penggilingan padi, pemecah kacang kapri dan lainnya), mesin pembuat minuman anggur dan juice buah, mesin pembuat roti, mie dan spaghetti dan sejenis seperti oven roti, mixer, pembuat adonan, cetakan, pemotong, mesin pembuat roti dan lain-lain, mesin pembuat rokok dan berbagai mesin pengolahan makanan yang lain. Termasuk mesin untuk industri roti atau pembuat macaroni, mesin dan peralatan untuk pengolahan berbagai makanan, seperti mesin untuk membuat gula-gula, kokoa atau coklat, mesin untuk industri gula, mesin untuk pembuatan bir, mesin untuk pengolahan daging dan unggas, mesin untuk pengolahan buah-buahan, kacang-kacangan dan sayuran, mesin untuk pengolahan ikan, kerang- kerangan dan hasil laut lainnya; mesin untuk penyulingan dan pemurnian; dan mesin lainnya untuk industri dan pengolahan makanan dan minuman; mesin pengambilan dan pengolahan minyak dan lemah hewan dan tumbuhan; mesin untuk pengolahan tembakau dan untuk pembuatan rokok dan cerutu atau untuk tembakau pipa atau tembakau kunyah atau snuff; mesin pengolahan makanan di hotel dan restoran.',NULL,NULL,0),
	(650,'28261','INDUSTRI KABINET MESIN JAHIT','Kelompok ini mencakup pembuatan kabinet mesin jahit, baik dari kayu, plywood, maupun dari logam.',NULL,NULL,0),
	(651,'28262','INDUSTRI MESIN JAHIT SERTA MESIN CUCI DAN MESIN PENGERING UNTUK KEPERLUAN NIAGA','Kelompok ini mencakup pembuatan mesin jahit dan kepala mesin jahit, baik untuk keperluan rumah tangga maupun untuk untuk keperluan niaga, termasuk pembuatan mesin obras, mesin bordir, mesin oversum dan mesin-mesin untuk penatu dan dry cleaning (mesin cuci, mesin pengering, mesin penyeterika dan lain-lain). Pembuatan mesin cuci, mesin pengering dan sejenisnya untuk keperluan rumah tangga dimasukkan dalam kelompok 27510.',NULL,NULL,0),
	(652,'28263','INDUSTRI MESIN TEKSTIL','Kelompok ini mencakup usaha pembuatan mesin-mesin tekstil, seperti mesin persiapan pengolahan serat, mesin pintal, mesin persiapan pembuatan kain, mesin tenun, mesin rajut, mesin pemeriksa kesalahan kain, mesin-mesin penyelesaian (finishing), mesin konveksi dan sejenisnya.',NULL,NULL,0),
	(653,'28264','INDUSTRI JARUM MESIN JAHIT, RAJUT, BORDIR DAN SEJENISNYA','Kelompok ini mencakup pembuatan jarum untuk mesin jahit, rajut, bordir dan sejenisnya.',NULL,NULL,0),
	(654,'28265','INDUSTRI MESIN PENYIAPAN DAN PEMBUATAN PRODUK KULIT','Kelompok ini mencakup pembuatan mesin produk kulit, seperti mesin untuk penyiapan, penyamakan, atau pengerjaan kulit atau kulit jangat dan mesin untuk membuat atau memperbaiki alas kaki atau produk lainnya dari kulit, kulit jangat dan kulit berbulu.',NULL,NULL,0),
	(655,'28291','INDUSTRI MESIN PERCETAKAN','Kelompok ini mencakup pembuatan mesin-mesin percetakan, seperti mesin press sederhana, mesin press silinder, mesin press putar dan mesin cetak lainnya. Termasuk mesin-mesin perlengkapan percetakan dan mesin penjilid, seperti mesin jahit buku, mesin penjilid dengan menggunakan spiral dan mesin penomor halaman.',NULL,NULL,0),
	(656,'28292','INDUSTRI MESIN PABRIK KERTAS','Kelompok ini mencakup pembuatan mesin pabrik kertas,seperti mesin untuk pengolahan pulp, kertas dan karton misalnya mesin pembuatan bubur kertas, mesin pembuatan kertas dan papan kertas, mesin pengeringan kayu, bubur kertas, kertas atau papan kertas, dan mesin untuk pembuatan barang-barang dari kertas atau papan kertas, seperti mesin pemotong kertas, pembuat amplop, kantong kertas dan sejenisnya dan mesin-mesin lainnya',NULL,NULL,0),
	(657,'28299','INDUSTRI MESIN KEPERLUAN KHUSUS LAINNYA','Kelompok ini mencakup industri berbagai mesin-mesin industri khusus lainnya yang belum termasuk kelompok sebelumnya, seperti mesin untuk pengerjaan karet atau plastik lunak atau untuk pembuatan produk dari bahan tersebut, seperti mesin extrude, pencetak, mesin pembuatan ban angin (pneumatik) atau ban vulkanisir, mesin lainnya untuk pembuatan produk dari plastik atau karet khusus, mesin cetak dan penjilidan buku dan mesin untuk pendukung pencetakan pada berbagai macam bahan, mesin cetak 3 dimensi (3d printing), mesin untuk memproduksi ubin, batu bata, perekat keramik potongan, pipa, grafit elektroda, kapur tulis, cetakan besi tuang dan lain-lain, mesin pabrik semi konduktor, robot industri yang menjalankan berbagai tugas untuk keperluan khusus, mesin untuk merakit lampu listrik dan lampu elektronik, tabung atau bola lampu, mesin untuk memproduksi atau pekerjaan panas dari kaca atau barang- barang dari kaca, serat kaca atau benang dan mesin atau peralatan untuk pemisahan isotopik, peralatan meluruskan dan menyeimbangkan ban (kecuali penyeimbang roda), mesin untuk memasang dan melepas ban (termasuk ban untuk alat berat dan alat pertahanan), sistem pelumasan pusat, persneling pesawat terbang (launching gear), pelontar pembawa pesawat terbang (carrier catapult) dan peralatan yang terkait, peralatan arena bowling otomatis (pin-setter), peralatan jalan berputar (roundabouts), ayunan, galeri menembak, gelanggang hiburan atau permainan lainnya, mesin pembuat briket dari produk pertanian dan mesin-mesin khusus lainnya.',NULL,NULL,0),
	(658,'29101','INDUSTRI KENDARAAN BERMOTOR RODA EMPAT ATAU LEBIH','Kelompok ini mencakup usaha pembuatan atau perakitan kendaraan bermotor untuk penumpang atau barang, seperti sedan, jeep, truck, pick up, bus dan stasion wagon dan sejenisnya dengan menggunakan mesin piston pembakaran dalam bolak-balik cetus api atau berputar, mesin piston bolak balik nyala kompresi (diesel atau semi diesel), atau motor listrik untuk penggerak. Termasuk pembuatan kendaraan untuk keperluan khusus, seperti mobil pemadam kebakaran, mobil toko, mobil penyapu jalan, ambulans, mobil salju, mobil golf, kendaraan amfibi, perpustakaan mobil (travelling libraries), mobil berlapis baja, lori pencampur beton dan ATV, go cart, mobil balap dan sejenisnya. Kelompok ini juga mencakup usaha pembuatan mesin kendaraan bermotor, chasis mesin dan industri pembangunan kembali mesin kendaraan bermotor.',NULL,NULL,0),
	(659,'29102','INDUSTRI KENDARAAN MULTIGUNA PEDESAAN','Kelompok ini mencakup usaha pembuatan atau perakitan kendaraan multiguna pedesaan atau dikenal sebagai AMMDES (Alat Mekanis Multiguna Pedesaan) yang dilengkapi dengan komponen seperti Power Take off (PTO), differential lock dan lain- lain yang menjadikannya multifungsi, antara lain sebagai alat transportasi, alat produksi maupun menggerakkan alat bantu lainnya sehingga mampu menjalankan berbagai fungsi sebagai mesin pegolahan seperti mesin-mesin untuk pengolahan hasil pertanian (mesin perontok, mesin pengupas, mesin penyosoh dan mesin penggilingan gabah), mesin perjernih dan pengolahan air minum, dan fungsi lainnya untuk keperluan tanaman pangan, peternakan, perikanan, perkebunan, kehutanan dan lain- lain. Termasuk untuk alat bantu penunjang kebutuhan medis seperti pengumpan ambulan (ambulance feeder).',NULL,NULL,0),
	(660,'29200','INDUSTRI KAROSERI KENDARAAN BERMOTOR RODA EMPAT ATAU LEBIH DAN INDUSTRI TRAILER DAN SEMI TRAILER','Kelompok ini mencakup usaha pembuatan bagian-bagian mobil atau karoseri kendaraan bermotor, seperti bak truk, bodi bus, bodi pick up, bodi untuk kendaraan penumpang, dan kendaraan bermotor untuk penggunaan khusus, seperti kontainer, caravan dan mobil tangki. Termasuk pembuatan trailer, semi trailer dan bagian- bagiannya.',NULL,NULL,0),
	(661,'29300','INDUSTRI SUKU CADANG DAN AKSESORI KENDARAAN BERMOTOR RODA EMPAT ATAU LEBIH','Kelompok ini mencakup usaha pembuatan komponen dan suku cadang kendaraan bermotor roda empat atau lebih, seperti leaf sporing, radiator, fuel tank, muffle, rem, gearboxes/persnelling, AS roda, road wheel, suspension shock absorber, silencer, pipa pembuangan, kataliser pengubah, kopling, roda kemudi, sistem kolom kemudi dan kotak kemudi; suku cadang dan aksesori untuk bodi karoseri kendaraan bermotor, seperti sabuk pengaman, pintu, bamper, airbag; tempat duduk mobil; peralatan listrik kendaraan bermotor, seperti generator, alternator, busi, ignition wiring harnesses/starter, sistem buka tutup pintu dan jendela otomatis, pemasangan argometer ke dalam panel instrumen, pengatur voltawse; inverter untuk kendaraan bermotor roda empat atau lebih; dan lain-lain.',NULL,NULL,0),
	(662,'30111','INDUSTRI KAPAL DAN PERAHU','Kelompok ini mencakup usaha pembuatan atau perakitan macam-macam kapal dan perahu komersil, yang terbuat dari baja, fibre glass, kayu atau ferro cement, baik yang bermotor maupun yang tidak bermotor, seperti kapal penumpang, kapal ferry, kapal kargo, kapal tanker, kapal penyeret, kapal layar untuk komersil, kapal perang, kapal untuk penelitian, kapal penangkap ikan dan kapal untuk pabrik pengolahan ikan.',NULL,NULL,0),
	(663,'30112','INDUSTRI BANGUNAN LEPAS PANTAI DAN BANGUNAN TERAPUNG','Kelompok ini mencakup usaha pembuatan konstruksi atau bangunan lepas pantai dan bangunan terapung, termasuk peralatan dan perlengkapannya, seperti konstruksi platform, bangunan terapung atau penyelaman untuk kegiatan pengeboran; konstruksi bangunan terapung, seperti dok terapung, sekoci dan kran apung, jembatan apung, ponton, coffer-dam, bangunan tempat pendaratan terapung, living quarter, jacket, platform dan morring buoy, pelampung/buoys, tangki terapung, kapal barkas, tongkang, kapal derek, rakit yang dapat diisi udara bukan untuk rekreasi dan lain-lain. Termasuk pembuatan hovercraft, kecuali hovercraft jenis rekreasi.',NULL,NULL,0),
	(664,'30113','INDUSTRI PERALATAN, PERLENGKAPAN DAN BAGIAN KAPAL','Kelompok ini mencakup usaha pembuatan perlengkapan, peralatan dan bagian kapal, seperti perlengkapan lambung, akomodasi kerja mesin geladak, alat kemudi dan alat bongkar muat.',NULL,NULL,0),
	(665,'30120','INDUSTRI PEMBUATAN KAPAL DAN PERAHU UNTUK TUJUAN WISATA ATAU REKREASI DAN OLAHRAGA','Kelompok ini mencakup usaha pembuatan kapal pesiar dan perahu untuk santai dan olahraga, seperti perahu dan rakit karet yang dapat diisi udara, kapal atau perahu layar (yatch) dengan atau tanpa motor penggerak, motor boats, hovercraft untuk rekreasi, kendaraan air pribadi, perahu untuk olahraga dan kapal pesiar yang lain, seperti kano, kayak, perahu dayung, sampan dan lain-lain.',NULL,NULL,0),
	(666,'30200','INDUSTRI LOKOMOTIF DAN GERBONG KERETA','Kelompok ini mencakup usaha pembuatan atau perakitan lokomotif kereta api listrik, diesel, uap dan lainnya; gerbong kereta api self propelled (pendorong sendiri) atau gerbong kereta api listrik atau trem, vans dan truk, termasuk perawatan atau perbaikannya; gerbong keretra api atau kereta api listrik, tidak self-propelled (pendorong sendiri), seperti gerbong penumpang, gerbong barang, gerbong tangki, gerbong bengkel, gerbong mobil derek, gerbong dan kereta pembongkar, gerobak dan lain-lain; suku cadang khusus kereta api atau kereta api listrik atau gerbong, seperti bogies, as dan roda, rem dan suku cadang rem, peralatan kopling dan hook, buffer dan suku cadang buffer, sok breker, kerangka lokomotif dan gerbong; bodi karoseri, penghubung antarkoridor dan lain-lain; peralatan signal mekanik dan elektromagnetik, peralatan pengaman dan pengontrol rambu-rambu kereta api, kereta api listrik, lalu lintas air, jalan raya, fasilitas parkir, lapangan udara dan lain-lain; lokomotif tambang dan kendaraan rel tambang; dan tempat duduk kereta api.',NULL,NULL,0),
	(667,'30300','INDUSTRI PESAWAT TERBANG DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha pembuatan atau perakitan dan modifikasi pesawat terbang untuk penumpang atau barang, seperti pesawat terbang bermesin jet, pesawat terbang propeller, helikopter, balon udara dan pesawat layang. Kelompok ini juga mencakup usaha pembuatan pesawat terbang untuk angkatan bersenjata, olahraga atau tujuan lain, pesawat peluncur dan pesawat peluncur gantung, wahana terbang tanpa awak (drone), kapal seplin/balon berkemudi dan balon udara panas, suku cadang dan aksesori pesawat terbang, seperti rakitan utama seperti badan pesawat terbang, sayap, pintu, pengontrol permukaan, roda gigi untuk mendarat, tanki bahan bakar, nacelles dan lain-lain; baling-baling, pisau rotor helikopter dan rotor pendorong; berbagai macam motor dan mesin yang terdapat di pesawat terbang; dan suku cadang jet turbo dan pendorong turbo untuk pesawat terbang, pesawat terbang latih darat, pesawat ruang angkasa dan pesawat peluncuran, satelit, satelit yang berhubungan dengan planet, stasiun orbit, shuttles dan intercontinental ballistic missiles (ICBM)/roket antarbenua. Termasuk pemeriksaan dan konversi pesawat atau mesin pesawat dan pembuatan tempat duduk pesawat terbang.',NULL,NULL,0),
	(668,'30400','INDUSTRI KENDARAAN PERANG','Kelompok ini mencakup pembuatan tank dan kendaraan lapis baja. Termasuk pembuatan kendaraan militer amfibi lapis baja dan kendaraan perang militer lainnya.',NULL,NULL,0),
	(669,'30911','INDUSTRI SEPEDA MOTOR RODA DUA DAN TIGA','Kelompok ini mencakup usaha pembuatan dan perakitan secara lengkap dari macam- macam kendaraan bermotor roda dua dan tiga, seperti sepeda motor, moped, skuter, bemo, a side-cars dan sejenisnya dengan menggunakan mesin piston pembakaran dalam bolak-balik cetus api atau berputar, atau motor listrik untuk penggerak. Termasuk sepeda yang dilengkapi motor.',NULL,NULL,0),
	(670,'30912','INDUSTRI KOMPONEN DAN PERLENGKAPAN SEPEDA MOTOR RODA DUA DAN TIGA','Kelompok ini mencakup usaha pembuatan komponen dan suku cadang kendaraan bermotor roda dua dan tiga, seperti motor pembakaran dalam, suspensi dan knalpot. Termasuk inverter untuk kendaraan bermotor roda dua dan tiga',NULL,NULL,0),
	(671,'30921','INDUSTRI SEPEDA DAN KURSI RODA TERMASUK BECAK','Kelompok ini mencakup usaha pembuatan dan perakitan macam-macam sepeda dan becak, seperti sepeda tanpa motor, sepeda roda tiga (pengantar), tandem (sepeda gandeng), dan sepeda anak-anak baik roda dua maupun roda tiga, termasuk pula pembuatan kereta bayi dan kendaraan difabel atau kursi roda baik bermotor maupun tidak.',NULL,NULL,0),
	(672,'30922','INDUSTRI PERLENGKAPAN SEPEDA DAN KURSI RODA TERMASUK BECAK','Kelompok ini mencakup usaha pembuatan suku cadang atau komponen dan aksesori sepeda, kereta bayi, kursi roda dan becak, seperti sadel, pedal, velg, rem, jari-jari, roda dan tire ventil. Usaha pembuatan ban sepeda (luar dan dalam) dimasukkan dalam kelompok 22111 dan 22112.',NULL,NULL,0),
	(673,'30990','INDUSTRI ALAT ANGKUTAN LAINNYA YTDL','Kelompok ini mencakup usaha pembuatan alat angkut yang belum termasuk kelompok lainnya, baik kendaran yang didorong oleh tangan maupun kendaraan yang ditarik binatang, seperti truk barang, handcart, sledge, troli, gerobak, delman, lori, kereta dorong, wheel barrows, kereta balap (sulkies), pedati yang ditarik keledai, kereta jenazah (keranda) dan alat pengangkutan lainnya.',NULL,NULL,0),
	(674,'31001','INDUSTRI FURNITUR DARI KAYU','Kelompok ini mencakup usaha pembuatan furnitur dari kayu untuk rumah tangga dan kantor, seperti meja, kursi, bangku, tempat tidur, lemari, rak, kabinet, penyekat ruangan dan sejenisnya.',NULL,NULL,0),
	(675,'31002','INDUSTRI FURNITUR DARI ROTAN DAN ATAU BAMBU','Kelompok ini mencakup pembuatan furnitur dengan bahan utamanya dari rotan dan atau bambu, seperti meja, kursi, bangku, tempat tidur, lemari, rak, penyekat ruangan dan sejenisnya.',NULL,NULL,0),
	(676,'31003','INDUSTRI FURNITUR DARI PLASTIK','Kelompok ini mencakup pembuatan furnitur yang bahan utamanya dari plastik, seperti meja, kursi, rak dan sejenisnya.',NULL,NULL,0),
	(677,'31004','INDUSTRI FURNITUR DARI LOGAM','Kelompok ini mencakup pembuatan furnitur untuk rumah tangga dan kantor yang bahan utamanya dari logam, seperti meja, kursi, rak, spring bed dan sejenisnya.',NULL,NULL,0),
	(678,'31009','INDUSTRI FURNITUR LAINNYA','Kelompok ini mencakup usaha pembuatan furnitur yang bahan utamanya bukan kayu, rotan, bambu, logam, plastik dan bukan barang imitasi, seperti bahan pelengkap matras atau kasur, matras atau kasur dengan per atau pegas atau yang yang diisi atau disumpal atau dilengkapi dengan bahan pelengkap lainnya (kapok, dakron) dan matras atau kasur plastik atau karet yang tidak dilapisi dan matras atau kasur sejenisnya. Termasuk kereta restoran dekorasi, seperti kereta desert, kereta makanan.',NULL,NULL,0),
	(679,'32111','INDUSTRI PERMATA','Kelompok ini mencakup usaha pemotongan, pengasahan dan penghalusan batu berharga atau permata dan sejenisnya, seperti berlian perhiasan, intan perhiasan, batu aji/ batu akik dan intan tiruan.',NULL,NULL,0),
	(680,'32112','INDUSTRI BARANG PERHIASAN DARI LOGAM MULIA UNTUK KEPERLUAN PRIBADI','Kelompok ini mencakup usaha pembuatan barang-barang perhiasan yang bahan utamanya dari logam mulia (emas, platina dan perak) untuk keperluan pribadi, seperti cincin, kalung, gelang, giwang, bross, ikat pinggang dan kancing, termasuk bagian dan perlengkapannya. Pembuatan perhiasan imitasi dimasukkan dalam kelompok 32120.',NULL,NULL,0),
	(681,'32113','INDUSTRI BARANG PERHIASAN DARI LOGAM MULIA BUKAN UNTUK KEPERLUAN PRIBADI','Kelompok ini mencakup usaha pembuatan perhiasan yang bahan utamanya dari logam mulia selain untuk keperluan pribadi, seperti peralatan makan dan minum, piring-piring ceper, wadah-wadah berongga, barang-barang toilet, barang hiasan untuk rumah tangga, barang-barang kantor atau meja, piala, medali dan noveltis atau barang-barang yang berhubungan dengan keagamaan, termasuk bagian dan perlengkapannya.',NULL,NULL,0),
	(682,'32114','INDUSTRI BARANG DARI LOGAM MULIA UNTUK KEPERLUAN TEKNIK DAN ATAU LABORATORIUM','Kelompok ini mencakup usaha pembuatan barang-barang untuk keperluan teknik dan atau laboratorium dari logam mulia (tidak termasuk instrument dan bagian- bagiannya), seperti spatula, crucibles, cuples, platinum grill yang digunakan sebagai katalisator dan electro-plating anodes.',NULL,NULL,0),
	(683,'32115','INDUSTRI PERHIASAN MUTIARA','Kelompok ini mencakup usaha pengerjaan mutiara dan pembuatan perhiasan dari mutiara atau perhiasan berbahan dasar utamanya adalah mutiara.',NULL,NULL,0),
	(684,'32119','INDUSTRI BARANG LAINNYA DARI LOGAM MULIA','Kelompok ini mencakup usaha pembuatan barang lainnya dari logam mulia, seperti tali jam tangan dari logam mulia, manset, ikat jam tangan dan kotak rokok. Termasuk pembuatan koin baik yang legal sebagai alat tukar maupun tidak dan jasa engraving baik pada perhiasan dari logam mulia atau bukan. Pembuatan case (badan) jam dan perhiasan jam dimasukkan dalam kelompok 26520.',NULL,NULL,0),
	(685,'32120','INDUSTRI PERHIASAN IMITASI DAN BARANG SEJENIS','Kelompok ini mencakup usaha pembuatan perhiasan imitasi dan sejenisnya, seperti cincin, gelang, kalung dan barang-barang sejenisnya yang dibuat dari logam dasar yang dilapisi logam mulia, perhiasan dengan batu imitasi seperti batu permata imitasi, berlian imitasi dan sejenisnya. Termasuk pembuatan tali jam tangan dari logam (kecuali logam mulia).',NULL,NULL,0),
	(686,'32201','INDUSTRI ALAT MUSIK TRADISIONAL','Kelompok ini mencakup usaha pembuatan alat-alat musik tradisional baik alat musik senar, tiup, pukul dan lainnya, seperti kecapi, seruling bambu, angklung, calung, kulintang, gong, gambang, gendang, terompet tradisional, rebab dan tifa. Termasuk pembuatan peluit, call horn (semacam terompet) dan alat sinyal suara yang ditiup lainnya.',NULL,NULL,0),
	(687,'32202','INDUSTRI ALAT MUSIK BUKAN TRADISIONAL','Kelompok ini mencakup usaha pembuatan alat-alat musik non tradisional, seperti alat musik petik (gitar, bass dan sejenisnya), alat musik tiup (terompet, saxophone, clarinet, harmonika dan sejenisnya), alat musik gesek (biola, cello dan sejenisnya), alat musik perkusi (drum set, selofon, metalofon dan sejenisnya). Termasuk usaha pembuatan piano/organ, pianika gamitan, akordeon dan garpu tala. Usaha pembuatan mikrofon, loudspeaker, headphone dan komponen yang sejenisnya dimasukkan dalam kelompok 26420. Sedangkan alat-alat musik untuk mainan dimasukkan dalam kelompok 32402.',NULL,NULL,0),
	(688,'32300','INDUSTRI ALAT OLAHRAGA','Kelompok ini mencakup usaha pembuatan alat-alat olahraga, seperti bola sepak, bola basket, bola volley, raket tenis, raket bulu tangkis, net volley, net pingpong, stik golf, stik hockey, meja pingpong, ski bindings dan poles (galah), sepatu ski, papan layar dan papan selancar, peralatan untuk olahraga memancing termasuk jaring penyerok, peralatan untuk berburu, panjat gunung, sarung tangan dan tutup kepala olahraga dari kulit, ice skate, roller skate, busur dan panah, peralatan untuk olahraga ketangkasan, peralatan gimnastik (senam), peralatan pusat kebugaran (fitness centre) atau peralatan atletik dan matras. Kelompok ini tidak termasuk usaha pembuatan layar perahu (13929), pakaian olahraga (14111), pakaian kuda (15123), sepatu olahraga (15202), senjata untuk olahraga (25200), sepeda olahraga (30921), kapal/sampan olahraga (30120), meja billiard/perlengkapan bowling (32401), cambuk dan pecut (15123).',NULL,NULL,0),
	(689,'32401','INDUSTRI ALAT PERMAINAN','Kelompok ini mencakup usaha pembuatan alat/perlengkapan seperti kartu domino, remi dan sejenisnya, kelereng, bekel, papan permainan dan permainan sejenisnya (halma, ular tangga), permainan elektronik, permainan catur, permainan yang dioperasikan dengan koin, bilyard, meja khusus untuk permainan judi dan sebagainya, fun fair, table and parlour games, meja billiard, meja casino, meja bowling dan perlengkapannya, puzzle dan mainan edukatif dan alat-alat permainan lainnya.',NULL,NULL,0),
	(690,'32402','INDUSTRI MAINAN ANAK-ANAK','Kelompok ini mencakup usaha pembuatan macam-macam mainan, seperti boneka dari kayu, kain, karet, dan sejenisnya termasuk pakaian boneka dan aksesorinya, mainan berupa senjata, toys set, tokoh super hero seperti superman, batman dan lain-lain, binatang mainan, alat musik mainan, kartu permainan, scale model dan model rekreasional sejenisnya, kereta api listrik, permainan konstruksi, mainan beroda yang dirancang untuk dikendarai (mainan jenis kendaraan) termasuk sepeda roda dua dan sepeda roda tiga yang terbuat dari plastik. Sepeda anak-anak dimasukkan dalam kelompok 30921.',NULL,NULL,0),
	(691,'32501','INDUSTRI FURNITUR UNTUK OPERASI, PERAWATAN KEDOKTERAN DAN KEDOKTERAN GIGI','Kelompok ini mencakup pembuatan perabot atau furnitur untuk kegiatan operasi, perawatan, kedokteran gigi dan kedokteran hewan, seperti meja operasi, tiang infus, tempat tidur rumah sakit dengan peralatan mekanik dan kursi untuk pemeriksaan dan perawatan gigi.',NULL,NULL,0),
	(692,'32502','INDUSTRI PERALATAN KEDOKTERAN DAN KEDOKTERAN GIGI, PERLENGKAPAN ORTHOPAEDIC DAN PROSTHETIC','Kelompok ini mencakup pembuatan peralatan dan perlengkapan untuk pemeriksaan kesehatan, operasi, kedokteran gigi dan kedokteran hewan, seperti electrocardiograph, alat-alat bor gigi, peralatan test mata (termasuk reflektor, endoscope, dan lain-lain), jarum suntik, peralatan sterilisasi, peralatan pijat, ozone therapy, oxygen therapy, peralatan pernapasan buatan, perlengkapan orthopaedic dan prosthetic (crutches, surgical belts and trussers, orthopaedic corsets and shoes dan lain-lain), thermometer kedokteran, tungku pembakar laboratorium kedokteran gigi, mesin pembersihan ultrasonik laboratorium, peralatan destilasi laboratorium, alat sentrifugal laboratorium, pelat dan baut tulang (bone plates and screws), alat suntik, jarum suntik, kateter, cannulae dan sebagaiya, peralatan kedokteran gigi (termasuk kursi periksa dokter gigi yang tergabung dengan perlengkapan dokter gigi lainnya), gigi buatan dan sebagainya yangdibuat di laboratorium kedokteran gigi, mata buatan dari gelas dan peralatan tubuh palsu lainnya, seperti mata palsu, tengkorak palsu dan bagian-bagian dalam tubuh palsu. Kelompok ini juga mencakup pembuatan berbagai peralatan dan perlengkapan dalam bentuk instrumen bedah, antara lain seperti gunting, pinset, tang.',NULL,NULL,0),
	(693,'32503','INDUSTRI KACA MATA','Kelompok ini mencakup usaha pembuatan macam-macam barang-barang opthalmik dan kaca mata berikut frame, seperti kaca mata pembantu penglihatan, kaca mata peredam sinar matahari/cahaya (sunglasses) dan safety googles (kaca mata untuk penahan debu, renang, selam, las). Termasuk juga pembuatan lensa kaca mata dan lensa kontak.',NULL,NULL,0),
	(694,'32509','INDUSTRI PERALATAN KEDOKTERAN DAN KEDOKTERAN GIGI SERTA PERLENGKAPAN LAINNYA','Kelompok ini mencakup usaha pembuatan peralatan kedokteran dan kedokteran gigi serta perlengkapan lainnya yang belum tercakup dalam kelompok 32501 sampai dengan 32503, seperti kain dan benang steril/benang bedah dan kertas tisue untuk operasi, semen dan penambal gigi (kecuali perekat gigi palsu 20234), lilin gigi dan preparat plester gigi lainnya, semen rekonstruksi tulang, masker medis seperti surgical mask.',NULL,NULL,0),
	(695,'32901','INDUSTRI ALAT TULIS DAN GAMBAR TERMASUK PERLENGKAPANNYA','Kelompok ini mencakup usaha pembuatan macam-macam alat tulis dan gambar termasuk perlengkapannya, seperti pensil hitam, pensil berwarna, pulpen, pena boll point, tangkai pena, pena sablon, jangka, kuas gambar, batu tulis, meja gambar, rapido, sablon, letraset dan crayon. Termasuk pembuatan cat air dan cat minyak.',NULL,NULL,0),
	(696,'32902','INDUSTRI PITA MESIN TULIS/GAMBAR','Kelompok ini mencakup usaha pembuatan macam-macam pita mesin tulis/gambar, seperti pita mesin tik, pita pencetak komputer dan pita mesin tulis lainnya.',NULL,NULL,0),
	(697,'32903','INDUSTRI KERAJINAN YTDL','Kelompok ini mencakup usaha pembuatan barang-barang kerajinan dari bahan tumbuh-tumbuhan dan hewan, seperti kerajinan pohon kelapa, tempurung, serabut, akar-akaran, kulit, gading, tanduk, tulang, bulu, rambut, binatang yang diawetkan, kegiatan taxidermy (mengisi kulit binatang dengan kapas dan lain-lain sehingga nampak seperti binatang hidup), karangan bunga, rangkaian bunga berbentuk lingkaran dan keranjang bunga; bunga, buah-buahan dan daun-daunan buatan dan barang-barang lukisan. Termasuk usaha pembuatan barang-barang kerajinan dari kulit ikan dan kekerangan, baik dari kulit kerang mutiara seperti kerang Pinctada maxima, kerang mabe (mutiara setengah bulat), maupun kerang lainnya.',NULL,NULL,0),
	(698,'32904','INDUSTRI PERALATAN UNTUK PELINDUNG KESELAMATAN','Kelompok ini mencakup usaha pembuatan peralatan untuk pelindung keselamatan, seperti pakaian pelindung dan pakaian anti api, sabuk pengaman tukang kawat dan sabuk lain untuk keperluan pekerjaan, pelampung, topi plastik yang keras (helm bangunan) dan perlengkapan keamanan lainnya yang terbuat dari plastik (helm olahraga dan segala macam helm sejenisnya), pakaian pelindung kebakaran, tutup kepala pengaman dari logam dan peralatan pengaman pribadi lain yang terbuat dari logam, penyumbat telinga dan hidung (misalnya untuk renang dan pengaman hidung) dan masker gas, masker non medis dan APD termasuk face shield.',NULL,NULL,0),
	(699,'32905','INDUSTRI SERAT SABUT KELAPA','Kelompok ini mencakup usaha pengolahan sabut kelapa menjadi bahan baku, seperti cocofiber (serat sabut kelapa), cocopeat (serbuk sabut kelapa), Rubberized Curl Coir (RCC)/ serat sabut kelapa berkaret (sebutret), dan lainnya. Contoh: cocofiber digunakan untuk pembuatan jok mobil, spring bed, dan lainnya serta cocopeat biasanya digunakan untuk media tanaman, dan lainnya.',NULL,NULL,0),
	(700,'32906','INDUSTRI PRODUKSI RADIOISOTOP','Kelompok ini mencakup usaha yang melakukan kegiatan pembuatan radioisotop hasil dari aktivasi akselerator (pemercepat partikel) atau iradiasi dari reaktor nuklir.',NULL,NULL,0),
	(701,'32907','INDUSTRI FABRIKASI ELEMEN BAKAR URANIUM','Kelompok ini mencakup usaha yang melakukan kegiatan fabrikasi elemen bakar uranium.',NULL,NULL,0),
	(702,'32909','INDUSTRI PENGOLAHAN LAINNYA YTDL','Kelompok ini mencakup usaha pembuatan barang-barang yang tidak diklasifikasikan di tempat lain, seperti papan nama, papan reklame (papan atau lampu display), segala macam payung, pipa rokok, lencana, piala, medali, stempel, tongkat, kap lampu, lilin, segala macam kancing, sapu, sikat ijuk, tempat cerutu dan sirih, pipa rokok, sisir, penyemprot wangi-wangian, botol vakum dan bejana vakum untuk keperluan pribadi atau rumah tangga, wig (rambut palsu), janggut palsu, bulu mata palsu dan lainnya yang belum tercakup dalam golongan lainnya, termasuk pembuatan korek api dari logam dan pembuatan perhiasan imitasi, boneka yang digunakan oleh penjahit untuk mengenakan baju, peti jenazah. Pembuatan sumbu lampu dimasukan dalam kelompok 13942.',NULL,NULL,0),
	(703,'33111','REPARASI PRODUK LOGAM SIAP PASANG UNTUK BANGUNAN, TANGKI, TANDON AIR DAN GENERATOR UAP','Kelompok ini mencakup reparasi dan perawatan produk logam pabrikasi di golongan 251, seperti reparasi tangki, reservoir dan kontainer atau wadah logam, drum pengapalan baja, generator uap atau uap air lainnya, mesin tambahan yang digunakan dalam generator uap (Kondensator, pemanas, pengumpul/kolektor dan akumulator uap), reactor nuklir kecuali separator isotop, suku cadang mesin kapal laut atau ketel uap tenaga dan peralatan kerja dari radiator dan pemanas pusat dan sejenisnya.',NULL,NULL,0),
	(704,'33112','REPARASI PRODUK SENJATA DAN AMUNISI','Kelompok ini mencakup reparasi dan perawatan produk logam di golongan 252, yaitu reparasi dan perawatan senjata api dan meriam/artileri (termasuk reparasi senjata untuk kegiatan olahraga atau rekreasional).',NULL,NULL,0),
	(705,'33119','REPARASI PRODUK LOGAM PABRIKASI LAINNYA','Kelompok ini mencakup reparasi dan perawatan produk logam pabrikasi di golongan 259, seperti reparasi dan perawatan alat potong, perkakas tangan dan peralatan umum (biasa digunakan umtuk pertanian, pertukangan dan rumah tangga), wadah dari logam, barang dari kawat, brankas, filling kabinet dan barang logam lainnya. Termasuk las (keliling) yang berpindah-pindah,',NULL,NULL,0),
	(706,'33121','REPARASI MESIN UNTUK KEPERLUAN UMUM','Kelompok ini mencakup reparasi mesin untuk keperluan umum yang tercakup dalam golongan 281, seperti reparasi dan perawatan mesin kapal laut atau kereta api, pompa dan peralatan yang terkait, peralatan tenaga uap atau zat cair, katup atau klep, roda gigi (persneling) dan peralatan kemudi, tungku pembakar pada proses industri, alat pengangkat dan pemindah, mesin dan peralatan kantor kecuali komputer dan perlengkapannya (cash register, mesin fotokopi, kalkulator, mesin ketik), perkakas tangan yang digerakkan tenaga, peralatan pendingin dan pembersih udara, timbangan, mesin penjual otomatis dan keperluan umum lainnya.',NULL,NULL,0),
	(707,'33122','REPARASI MESIN UNTUK KEPERLUAN KHUSUS','Kelompok ini mencakup reparasi dan perawatan mesin untuk keperluan khusus yang tercakup dalam golongan 282, seperti reparasi dan perawatan traktor pertanian, mesin pertanian dan mesin kehutanan dan penebangan, perkakas mesin pemotong logam dan pembentuk logam dan aksesorinya, perkakas mesin lainnya, mesin metalurgi, mesin pertambangan dan penggalian termasuk mesin pada ladang minyak dan gas, mesin konstruksi, mesin pengolahan makanan dan minuman, mesin pengolahan tembakau, mesin tekstil, mesin pembuatan pakaian dan pakaian dari kulit, mesin pembuatan kertas dan mesin keperluan khusus lainnya.',NULL,NULL,0),
	(708,'33131','REPARASI ALAT UKUR, ALAT UJI DAN PERALATAN NAVIGASI DAN PENGONTROL','Kelompok ini mencakup reparasi dan perawatan peralatan yang diproduksi dalam golongan 265, seperti reparasi dan perawatan peralatan mesin pesawat terbang, peralatan pengujian emisi mobil, peralatan meteorologi, peralatan pengujian dan pemeriksaan perlengkapan secara fisik, listrik dan kimia, peralatan penelitian atau survei, peralatan pendeteksi dan pemantauan radiasi dan sejenisnya.',NULL,NULL,0),
	(709,'33132','REPARASI PERALATAN IRADIASI, ELEKTROMEDIS DAN ELEKTROTERAPI','Kelompok ini mencakup reparasi dan perawatan peralatan iradiasi, elektromedis dan elektroterapi dalam golongan 266, seperti reparasi dan perawatan peralatan penggambaran resonansi magnetik (magnetic resonance imaging/MRI), peralatan kesehatan ultrasound, peralatan pembuka jalan (pacemaker), peralatan bantu pendengaran (hearing aids), peralatan elektrokardiografi, peralatan endoskopis elektromedis, peralatan iradiasi dan sejenisnya.',NULL,NULL,0),
	(710,'33133','REPARASI PERALATAN FOTOGRAFI DAN OPTIK','Kelompok ini mencakup reparasi dan perawatan peralatan fotografi dan optik dalam golongan 267, jika utamanya digunakan secara komersial, seperti reparasi dan perawatan teropong, mikroskop (kecuali mikroskop elektron, proton), teleskop, prisma dan lensa (kecuali ophtalmik), peralatan fotografi dan sejenisnya.',NULL,NULL,0),
	(711,'33141','REPARASI MOTOR LISTRIK, GENERATOR DAN TRANSFORMATOR','Kelompok ini mencakup reparasi dan perawatan mesin dan peralatan yang diproduksi dalam golongan 271, seperti reparasi dan perawatan mesin tenaga, distribusi dan khususnya transformator, motor listrik, generator dan perangkat motor generator, peralatan saklar dan papan hubung, peralatan relay dan pengontrol industri.',NULL,NULL,0),
	(712,'33142','REPARASI BATERAI DAN AKUMULATOR LISTRIK','Kelompok ini mencakup reparasi dan perawatan baterai dan akumulator motor listrik dan lainnya yang termasuk dalam golongan 272.',NULL,NULL,0),
	(713,'33149','REPARASI PERALATAN LISTRIK LAINNYA','Kelompok ini mencakup reparasi dan perawatan peralatan listrik lainnya dalam golongan 273, 274 dan 279, seperti reparasi dan perawatan peralatan penerangan listrik, peralatan kawat pembawa arus dan bukan pembawa arus untuk sirkuit kabel listrik dan peralatan listrik sejenis lainnya.',NULL,NULL,0),
	(714,'33151','REPARASI KAPAL, PERAHU DAN BANGUNAN TERAPUNG','Kelompok ini mencakup jasa reparasi dan perawatan alat angkutan dalam golongan 301, seperti jasa reparasi dan perawatan kapal, perahu, kapal pesiar, kapal atau perahu untuk kepeluan rekreasi dan olahraga dan sejenisnya. Termasuk usaha jasa reparasi dan perawatan dan modifikasi bangunan lepas pantai.',NULL,NULL,0),
	(715,'33152','REPARASI LOKOMOTIF DAN GERBONG KERETA','Kelompok ini mencakup jasa reparasi dan perawatan lokomotif dan gerbong kereta api dan kendaraan jalan rel lainnya (kecuali industri pembangunan kembali dan pengubahan) dalam golongan 302.',NULL,NULL,0),
	(716,'33153','REPARASI PESAWAT TERBANG','Kelompok ini mencakup reparasi dan perawatan pesawat terbang (kecuali industri pengubahan, pemeriksaan, dan pembangunan kembali), mesin pesawat terbang dan perlengkapannya dalam golongan 303.',NULL,NULL,0),
	(717,'33159','REPARASI ALAT ANGKUTAN LAINNYA, BUKAN KENDARAAN BERMOTOR','Kelompok ini mencakup reparasi dan perawatan alat angkut lainnya bukan sepeda motor dan sepeda, seperti reparasi dan perawatan kendaraan perang, andong dan kereta yang ditarik binatang dan alat angkut sejenis lainnya.',NULL,NULL,0),
	(718,'33190','REPARASI PERALATAN LAINNYA','Kelompok ini mencakup reparasi peralatan lainnya, seperti reparasi jaring untuk menangkap ikan, tali jerat, tali temali, canvas dan terpal (tarp), kantong penyimpan pupuk dan bahan kimia, pallet kayu, drum pengapalan dan tong sejenisnya, mesin pinball dan mesin permainan yang dioperasikan dengan koin, orgel dan peralatan musik bersejarah lainnya.',NULL,NULL,0),
	(719,'33200','INSTALASI/PEMASANGAN MESIN DAN PERALATAN INDUSTRI','Kelompok ini mencakup instalasi/pemasangan mesin dan peralatan industri, seperti instalsi/pemasangan mesin industri dalam pabrik, peralatan kendali/kontrol proses industri dan peralatan industri lainnya (peralatan komunikasi, mainframe dan komputer sejenis, peralatan iradiasi, peralatan gas medis dan elektromedis dan lain-lain), pembongkaran mesin dan peralatan berskala besar, kegiatan millwright, machine rigging dan integrasi/perakitan mesin seperti jasa perakitan peralatan arena bowling.',NULL,NULL,0),
	(720,'35111','PEMBANGKITAN TENAGA LISTRIK','Kelompok ini mencakup usaha memproduksi tenaga listrik melalui pembangkitan tenaga listrik yang menggunakan berbagai jenis sumber energi. Sumber energi fosil seperti batubara, gas, bahan bakar minyak, dan diesel. Sumber energi terbarukan seperti panas bumi, angin, bioenergi, sinar matahari, aliran dan terjunan air, gerakan dan perbedaan suhu lapisan laut. Sumber energi hybrid yang menggabungankan sumber energi fosil dengan energi terbarukan, dan energi yang berasal dari teknologi energy storage.',NULL,NULL,0),
	(721,'35112','TRANSMISI TENAGA LISTRIK','Kelompok ini mencakup usaha pengoperasian sistem transmisi atau usaha penyaluran tenaga listrik dari pembangkit ke jaringan distribusi melalui jaringan tenaga listrik yang bertegangan tinggi (antara 35 kilovolt s.d 150 kilovolt) dan/atau bertegangan ekstra tinggi (antara 150 kilovolt s.d 500 kilovolt) dan/atau bertegangan ultra tinggi (di atas 500 kilovolt) termasuk gardu-gardu induknya, baik berasal dari produksi sendiri maupun dari produksi pihak lain.',NULL,NULL,0),
	(722,'35113','DISTRIBUSI TENAGA LISTRIK','Kelompok ini mencakup usaha pengoperasian sistem distribusi atau usaha penyaluran tenaga listrik melalui jaringan tenaga listrik yang bertegangan menengah ke bawah (di bawah 35 kilovolt) sampai ke konsumen atau pelanggan termasuk dengan gardugardu distribusinya baik berasal dari produksi sendiri maupun dari produksi pihak lain.',NULL,NULL,0),
	(723,'35114','PENJUALAN TENAGA LISTRIK','Kelompok ini mencakup usaha penjualan tenaga listrik kepada konsumen akhir.',NULL,NULL,0),
	(724,'35115','PEMBANGKIT, TRANSMISI, DISTRIBUSI DAN PENJUALAN TENAGA LISTRIK DALAM SATU KESATUAN USAHA','Kelompok ini mencakup kegiatan memproduksi tenaga listrik, penyaluran tenaga listrik melalui jaringan transmisi dan distribusi tenaga listrik, serta penjualan tenaga listrik kepada konsumen akhir yang dilaksanakan dalam satu kesatuan usaha.',NULL,NULL,0),
	(725,'35116','PEMBANGKIT, TRANSMISI, DAN PENJUALAN TENAGA LISTRIK DALAM SATU KESATUAN USAHA','Kelompok ini mencakup kegiatan memproduksi tenaga listrik, penyaluran tenaga listrik melalui jaringan transmisi, dan penjualan tenaga listrik kepada konsumen akhir yang dilaksanakan dalam satu kesatuan usaha.',NULL,NULL,0),
	(726,'35117','PEMBANGKIT, DISTRIBUSI, DAN PENJUALAN TENAGA LISTRIK DALAM SATU KESATUAN USAHA','Kelompok ini mencakup kegiatan memproduksi tenaga listrik, penyaluran tenaga listrik melalui jaringan distribusi dan penjualan tenaga listrik kepada konsumen akhir yang dilaksanakan dalam satu kesatuan usaha.',NULL,NULL,0),
	(727,'35118','DISTRIBUSI, DAN PENJUALAN TENAGA LISTRIK DALAM SATU KESATUAN USAHA','Kelompok ini mencakup kegiatan penyaluran tenaga listrik melalui jaringan distribusi dan penjualan tenaga listrik kepada konsumen akhir yang dilaksanakan dalam satu kesatuan usaha.',NULL,NULL,0),
	(728,'35121','PENGOPERASIAN INSTALASI PENYEDIAAN TENAGA LISTRIK','Kelompok ini mencakup usaha pengoperasian yang dilakukan oleh pihak lain atas fasilitas pembangkit yang menghasilkan energi listrik, fasilitas sistem transmisi tenaga listrik dan sistem distribusi tenaga listrik.',NULL,NULL,0),
	(729,'35122','PENGOPERASIAN INSTALASI PEMANFAATAN TENAGA LISTRIK','Kelompok ini mencakup usaha pengoperasian yang dilakukan oleh pihak lain atas fasilitas instalasi pemanfaatan tenaga listrik mencakup instalasi pemanfaatan tenaga listrik tegangan tinggi, instalasi pemanfaatan tenaga listrik tegangan menengah, dan instalasi pemanfaatan tenaga listrik tegangan rendah.',NULL,NULL,0),
	(730,'35129','AKTIVITAS PENUNJANG TENAGA LISTRIK LAINNYA','Kelompok ini mencakup usaha jasa lain yang secara langsung berkaitan dengan penyediaan dan pemanfaatan tenaga listrik namun tidak tercakup dalam kelompok 35121 s.d. 35122, seperti jasa pencatatan meteran, pemberian tagihan dan kegiatan perdagangan pulsa/token listrik serta kegiatan penunjang kelistrikan lainnya.',NULL,NULL,0),
	(731,'35201','PENGADAAN GAS ALAM DAN BUATAN','Kelompok ini mencakup usaha pengolahan bahan bakar gas yang dapat dimanfaatkan secara langsung sebagai bahan bakar di mana pembuatannya disertai usaha peningkatan mutu gas, seperti pemurnian, pencampuran dan proses lainnya yang dihasilkan dari gas alam (termasuk LPG), karbonasi dan gasifikasi batu bara, atau bahan hidrokarbon lain.',NULL,NULL,0),
	(732,'35202','DISTRIBUSI GAS ALAM DAN BUATAN','Kelompok ini mencakup usaha penyaluran gas melalui jaringan yang bertekanan ekstra tinggi (lebih dari 10 bar); yang bertekanan tinggi (antara 4 bar s.d. 10 bar); dan yang bertekanan menengah ke bawah (di bawah 4 bar) baik berasal dari produksi sendiri maupun produksi pihak lain sampai ke konsumen atau pelanggan. Penyaluran gas melalui pipa atas dasar balas jasa atau fee, dimasukkan dalam kelompok 49300. Termasuk penyaluran, distribusi dan pengadaan semua jenis bahan bakar gas melalui sistem saluran, perdagangan gas kepada konsumen melalui saluran, kegiatan agen gas yang melakukan perdagangan gas melalui sistem distribusi gas yang dioperasikan oleh pihak lain dan pengoperasian pertukaran komoditas dan kapasitas pengangkutan bahan bakar gas.',NULL,NULL,0),
	(733,'35203','PENGADAAN GAS BIO','Kelompok ini mencakup usaha pengolahan bahan bakar gas yang dapat dimanfaatkan secara langsung sebagai bahan bakar yang dihasilkan dari produk sampingan pertanian, perkebunan, peternakan, atau sampah/limbah dimana pembuatannya disertai usaha peningkatan mutu gas, seperti pemurnian, pencampuran dan proses lainnya.',NULL,NULL,0),
	(734,'35301','PENGADAAN UAP/AIR PANAS DAN UDARA DINGIN','Kelompok ini mencakup kegiatan memproduksi dan mendistribusikan uap dan air panas untuk pemanasan, pembangkit tenaga dan penggunaan lainnya. Kegiatannya seperti produksi, pengumpulan dan distribusi uap dan air panas untuk pemanas, energi dan kegunaan lain dan kegiatan produksi dan distribusi udara dingin.',NULL,NULL,0),
	(735,'35302','PRODUKSI ES','Kelompok ini mencakup kegiatan produksi dan distribusi air dingin/air es untuk kebutuhan pendinginan, dan produksi es, termasuk es untuk kebutuhan makanan atau minuman dan kegunaan lain (misal pendinginan).',NULL,NULL,0),
	(736,'36001','PENAMPUNGAN, PENJERNIHAN DAN PENYALURAN AIR MINUM','Kelompok ini mencakup usaha pengambilan air secara langsung dari mata air dan air tanah serta penjernihan air permukaan dari sumber air (sungai, danau, sumur dan sebagainya) dan penyaluran air minum secara langsung dari terminal air melalui saluran pipa, mobil tangki (asal mobil tangki tersebut masih dalam satu pengelolaan administratif dari perusahaan air minum tersebut) untuk dijual kepada konsumen atau pelanggan, seperti rumah tangga, instansi/lembaga/badan pemerintah, badan-badan sosial, badan usaha milik negara, perusahaan/usaha swasta antara lain hotel, industri pengolahan dan pertokoan.',NULL,NULL,0),
	(737,'36002','PENAMPUNGAN DAN PENYALURAN AIR BAKU','Kelompok ini mencakup usaha pengadaan dan penyaluran air baku untuk keperluan industri, pembangkit listrik dan lain-lain. Kelompok ini juga mencakup kegiatan pengelolaan jaringan irigasi, namun tidak mencakup pengoperasian peralatan irigasi seperti alat penyemprot untuk keperluan pertanian.',NULL,NULL,0),
	(738,'36003','AKTIVITAS PENUNJANG TREATMENT AIR','Kelompok ini mencakup usaha atau kegiatan yang secara langsung berhubungan dengan usaha pengadaan dan penyaluran air bersih, seperti jasa pencatatan meteran, pemberian tagihan dan kegiatan penunjang lainnya. Kegiatan pada kelompok ini termasuk distribusi air yang dilakukan perorangan seperti pedagang air pikulan/dorongan/mobil tangki.',NULL,NULL,0),
	(739,'37011','PENGUMPULAN AIR LIMBAH TIDAK BERBAHAYA','Kelompok ini mencakup kegiatan pengumpulan dan pengangkutan air limbah industri atau air limbah rumah tangga yang tidak berbahaya melalui saluran dari jaringan pembuangan air limbah, pengumpul air limbah dan fasilitas pengangkutan lainnya (kendaraan pengangkutan limbah/kotoran). Kelompok ini juga mencakup kegiatan penyedotan dan pembersihan tangki septik (perigi jamban), bak dan lubang pembuangan limbah/kotoran; pengumpulan air limbah dari toilet kimia (toilet portable, toilet pesawat, toilet kereta).',NULL,NULL,0),
	(740,'37012','PENGUMPULAN AIR LIMBAH BERBAHAYA','Kelompok ini mencakup kegiatan pengumpulan dan pengangkutan air limbah industri atau air limbah rumah tangga yang berbahaya melalui saluran dari jaringan pembuangan air limbah, pengumpul air limbah dan fasilitas pengangkutan lainnya (kendaraan pengangkutan limbah/kotoran). Kelompok ini juga mencakup kegiatan penyedotan dan pembersihan tangki, bak dan lubang pembuangan air limbah berbahaya.',NULL,NULL,0),
	(741,'37021','TREATMENT DAN PEMBUANGAN AIR LIMBAH TIDAK BERBAHAYA','Kelompok ini mencakup kegiatan pengoperasian sistem pembuangan air limbah atau fasilitas pengolahan air limbah tidak berbahaya, pengolahan air limbah tidak berbahaya (mencakup air limbah industri dan rumah tangga, air dari kolam renang dan lain-lain) melalui saluran secara proses fisika, kimia dan biologi seperti pengenceran, penyaringan dan sedimentasi dan lain-lain. Kelompok ini juga mencakup kegiatan pengelolaan dan pembersihan saluran air limbah tidak berbahaya dan saluran pembuangannya.',NULL,NULL,0),
	(742,'37022','TREATMENT DAN PEMBUANGAN AIR LIMBAH BERBAHAYA','Kelompok ini mencakup kegiatan pengoperasian sistem pembuangan air limbah atau fasilitas pengolahan air limbah berbahaya, pengolahan air limbah berbahaya (mencakup air limbah industri dan rumah tangga dan lain-lain) melalui saluran secara proses fisika, kimia dan biologi seperti pengenceran, penyaringan dan sedimentasi dan lain-lain. Kelompok ini juga mencakup kegiatan treatment dan pembersihan saluran air limbah berbahaya dan saluran pembuangannya.',NULL,NULL,0),
	(743,'38110','PENGUMPULAN LIMBAH DAN SAMPAH TIDAK BERBAHAYA','Kelompok ini mencakup pengumpulan sampah padat yang tidak berbahaya dalam suatu daerah, misalnya pengumpulan sampah rumah tangga dan usaha dengan menggunakan tempat sampah, tempat sampah beroda, kontainer sampah dan lainlain yang meliputi campuran bahan-bahan yang dapat dipulihkan, pengumpulan bahan-bahan yang dapat didaur ulang, pengumpulan minyak dan lemak masak bekas pakai dan pengumpulan sampah dari tempat sampah di tempat umum. Termasuk juga usaha pengumpulan sampah konstruksi dan pembongkaran bangunan, pengumpulan dan pembersihan runtuhan atau puing, pengumpulan sampah dari pabrik tekstil dan pengoperasian pos pemindah sampah untuk sampah yang tidak berbahaya.',NULL,NULL,0),
	(744,'38120','PENGUMPULAN LIMBAH BERBAHAYA','Kelompok ini mencakup pengumpulan limbah padat maupun tidak padat yang berbahaya serta sampah spesifik, misalnya bahan yang mudah meledak, bahan yang mudah teroksidasi, bahan yang mudah terbakar, bahan beracun, iritan, karsinogenik, korosif, bahan yang dapat menyebabkan infeksi dan substansi dan preparat lainnya yang berbahaya untuk kesehatan manusia dan lingkungan. Kegiatan ini juga memerlukan identifikasi, penanganan, pengemasan dan pelabelan limbah berbahaya dan sampah spesifik. Kelompok ini mencakup usaha pengumpulan limbah berbahaya dan sampah spesifik, seperti minyak bekas pakai dari kapal atau bengkel, sampah biologis yang berbahaya (bio-hazardous), aki dan baterai bekas pakai.',NULL,NULL,0),
	(745,'38211','TREATMENT DAN PEMBUANGAN LIMBAH DAN SAMPAH TIDAK BERBAHAYA','Kelompok ini mencakup usaha pengoperasian lahan untuk pembuangan limbah dan sampah yang tidak berbahaya, pembuangan limbah dan sampah yang tidak berbahaya melalui pembakaran atau metode lain dengan atau tanpa menghasilkan produk berupa listrik atau uap, bahan bakar substitusi, biogas, abu atau produk ikutan lainnya untuk kegunaan lebih lanjut, dan sebagainya dan treatment limbah dan sampah organik untuk pembuangan.',NULL,NULL,0),
	(746,'38212','PRODUKSI KOMPOS SAMPAH ORGANIK','Kelompok ini mencakup usaha produksi kompos dari sampah organik dan abu tanaman (pupuk alam organik).',NULL,NULL,0),
	(747,'38220','TREATMENT DAN PEMBUANGAN LIMBAH BERBAHAYA','Kelompok ini mencakup usaha treatment dan pembuangan yang dikelola baik oleh pemerintah dan swasta, seperti pembuangan dan treatment limbah padat atau limbah tidak padat yang berbahaya serta limbah spesifik, mencakup bahan mudah meledak, bahan mudah teroksidasi, bahan yang mudah terbakar, bahan beracun, iritan, karsinogenik, korosif atau bahan yang dapat menyebabkan infeksi dan substansi dan preparat lainnya yang berbahaya untuk kesehatan manusia dan lingkungan. Kegiatannya adalah usaha pengoperasian fasilitas untuk pembuangan limbah berbahaya dan sampah spesifik, treatment dan pembuangan binatang hidup atau mati yang beracun dan limbah terkontaminasi lainnya, pembakaran limbah berbahaya, treatment, pembuangan dan penyimpanan limbah radioaktif, seperti treatment dan pembuangan limbah radioaktif transisi, mencakup peluruhan pada masa/periode pembuangan limbah dan pembungkusan, penyiapan dan treatment lainnya terhadap limbah radioaktif.',NULL,NULL,0),
	(748,'38301','PEMULIHAN MATERIAL BARANG LOGAM','Kelompok ini mencakup usaha pengolahan barang bekas dari logam dan sisa-sisa barang logam menjadi bahan baku sekunder. Hasil dari daur ulang/pemulihan material barang logam adalah bahan baku sekunder berbagai bentuk seperti potonganpotongan atau serpihan logam dan lainnya. Kegiatan pada kelompok ini mencakup pemisahan dan pemilihan sampah logam, penghancuran secara mekanik sampah logam, reduksi mekanik sampah logam, pembongkaran, pemotongan dan pengirisan sampah logam, pemotongan kapal dan alat apung lainnya (ship breaking) dan lainnya. Pembuatan barang logam baru yang menggunakan bahan baku sekunder, barang logam bekas dan sisa-sisa barang logam dimasukkan dalam kelompok industri yang sesuai.',NULL,NULL,0),
	(749,'38302','PEMULIHAN MATERIAL BARANG BUKAN LOGAM','Kelompok ini mencakup usaha pengolahan barang bekas dari bukan logam dan sisasisa barang bukan logam menjadi bahan baku sekunder. Hasil dari daur ulang/pemulihan material barang bukan logam adalah bahan baku sekunder berbagai bentuk seperti potongan-potongan atau serpihan bukan logam dan lainnya. Kegiatan pada kelompok ini mencakup pemisahan dan pemilihan sampah bukan logam, reklamasi karet dan ban bekas, pemilihan plastik, pengolahan sampah plastik atau karet menjadi butiran, penghancuran, pembersihan dan pemilihan kaca, pengolahan minyak dan lemak bekas pakai menjadi bahan sekunder, pengolahan sampah makanan, minuman dan tembakau dan sampah bukan logam lainnya. Pembuatan barang bukan logam yang baru dari bahan baku sekunder, barang bekas bukan logam dan sisa-sisa barang bukan logam dimasukkan dalam kelompok industri yang sesuai.',NULL,NULL,0),
	(750,'39000','AKTIVITAS REMEDIASI DAN PENGELOLAAN LIMBAH DAN SAMPAH LAINNYA','Kelompok ini mencakup usaha jasa pembersihan dan pengelolaan limbah dan sampah lainnya oleh pemerintah dan swasta, seperti dekontaminasi tanah dan air tanah di tempat yang tercemar polusi, baik in situ dan ex situ, menggunakan metode mekanik, kimia atau biologi; dekontaminasi tempat atau pabrik industri, termasuk tempat dan penanaman nuklir; dekontaminasi dan pembersihan air permukaan akibat polusi, contoh karena terkumpulnya polutan atau karena bahan kimia lainnya; pembersihan minyak yang tumpah (oil spill) dan polusi lain pada tanah, air permukaan, di samudera dan laut, termasuk pesisir pantai; pengurangan asbes, cat dan bahan-bahan beracun lainnya; kegiatan pengontrol polusi khusus lainnya; dan penyemprotan kuman,dan usaha jasa kebersihan lainnya yang sejenis',NULL,NULL,0),
	(751,'KODE','KONSTRUKSI GEDUNG HUNIAN','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan yang dipakai untuk hunian, seperti rumah tinggal, rumah tinggal sementara, rumah susun, apartemen dan kondominium. Termasuk pembangunan gedung untuk hunian yang dikerjakan oleh perusahaan real estat dengan tujuan untuk dijual dan kegiatan perubahan dan renovasi gedung hunian.',NULL,NULL,0),
	(752,'41012','KONSTRUKSI GEDUNG PERKANTORAN','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan yang dipakai untuk gedung perkantoran, seperti kantor dan rumah kantor (rukan). Termasuk pembangunan gedung untuk perkantoran yang dikerjakan oleh perusahaan real estat dengan tujuan untuk dijual dan kegiatan perubahan dan renovasi gedung perkantoran.',NULL,NULL,0),
	(753,'41013','KONSTRUKSI GEDUNG INDUSTRI','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan yang dipakai untuk industri, seperti gedung perindustrian/pabrik, gedung workshop/bengkel kerja, bangunan pabrik untuk pengelolaan dan pemrosesan bahan nuklir. Termasuk kegiatan perubahan dan renovasi gedung industri.',NULL,NULL,0),
	(754,'41014','KONSTRUKSI GEDUNG PERBELANJAAN','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan yang dipakai untuk perbelanjaan, seperti gedung perdagangan/pasar/mall, toserba, toko, rumah toko (ruko) dan warung. Termasuk pembangunan ruko yang dikerjakan oleh perusahaan real estat dengan tujuan untuk dijual dan kegiatan perubahan dan renovasi gedung perbelanjaan.',NULL,NULL,0),
	(755,'41015','KONSTRUKSI GEDUNG KESEHATAN','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan yang dipakai untuk sarana kesehatan, seperti rumah sakit, poliklinik, puskesmas, balai pengobatan, gedung pelayanan kesehatan dan gedung laboratorium. Termasuk kegiatan perubahan dan renovasi gedung kesehatan.',NULL,NULL,0),
	(756,'41016','KONSTRUKSI GEDUNG PENDIDIKAN','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan yang dipakai untuk sarana pendidikan, seperti gedung sekolah, tempat kursus, laboratorium dan bangunan penunjang pendidikan lainnya. Termasuk kegiatan perubahan dan renovasi gedung pendidikan.',NULL,NULL,0),
	(757,'41017','KONSTRUKSI GEDUNG PENGINAPAN','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan yang dipakai untuk penginapan, seperti gedung perhotelan, hostel dan losmen. Termasuk kegiatan perubahan dan renovasi gedung penginapan.',NULL,NULL,0),
	(758,'41018','KONSTRUKSI GEDUNG TEMPAT HIBURAN DAN OLAHRAGA','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan yang dipakai untuk tempat hiburan, seperti bioskop, gedung kebudayaan/kesenian, gedung wisata dan rekreasi serta gedung olahraga. Termasuk pembangunan gedung untuk tempat hiburan yang dikerjakan oleh perusahaan real estat dengan tujuan untuk dijual dan kegiatan perubahan dan renovasi gedung tempat hiburan dan olahraga.',NULL,NULL,0),
	(759,'41019','KONSTRUKSI GEDUNG LAINNYA','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan yang dipakai penggunaan selain dalam kelompok 41011 s.d. 41018, seperti tempat ibadah (masjid, gereja katolik, gereja kristen, pura, wihara, kelenteng), gedung terminal/stasiun, balai yasa (kereta api), bangunan monumental, gedung negara dan pemerintah pusat/daerah, bangunan bandara, gedung hangar pesawat, gedung PKPPK (Pemadam Kebakaran di Bandar Udara), gedung bersejarah, gedung penjara, gedung balai pertemuan, gudang, gedung genset, rumah pompa, depo, gedung power house, gedung gardu listrik, gedung gardu sinyal, gedung tower, gedung penyimpanan termasuk penyimpanan bahan peledak dan lainnya. Termasuk kegiatan perubahan dan renovasi gedung lainnya.',NULL,NULL,0),
	(760,'41020','JASA PEKERJAAN KONSTRUKSI PRAPABRIKASI BANGUNAN GEDUNG','Kelompok ini mencakup kegiatan pemasangan bahan hasil produksi pabrik seperti beton pracetak, baja, plastik, karet, dan hasil produksi pabrik lainnya dengan metode pabrikasi, erection, dan/ atau perakitan untuk bangunan gedung.',NULL,NULL,0),
	(761,'42101','KONSTRUKSI BANGUNAN SIPIL JALAN','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan jalan (raya, sedang, dan kecil), jalan bebas hambatan/jalan tol, dan jalan landasan terbang (pacu, taksi, dan parkir), dan lapangan penyimpanan peti kemas (containers yard). Termasuk kegiatan penunjang pembangunan, peningkatan, pemeliharaan konstruksi pagar/tembok penahan jalan. Tidak termasuk jalan layang.',NULL,NULL,0),
	(762,'42102','KONSTRUKSI BANGUNAN SIPIL JEMBATAN, JALAN LAYANG, FLY OVER, DAN UNDERPASS','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan jembatan (termasuk jembatan rel), jalan layang, underpass, dan fly over. Termasuk kegiatan pembangunan, peningkatan, pemeliharaan penunjang, pelengkap dan perlengkapan jembatan dan jalan layang, seperti pagar/tembok penahan, drainase jalan, marka jalan, dan rambu-rambu.',NULL,NULL,0),
	(763,'42103','KONSTRUKSI JALAN REL','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali jalan rel. Seperti jalan rel untuk kereta api. Termasuk pekerjaan pemasangan rel dan bantalan kereta api dan penimbunan kerikil (agregat kelas A) untuk badan jalan kereta api.',NULL,NULL,0),
	(764,'42104','KONSTRUKSI TEROWONGAN','Kelompok ini mencakup usaha pembangunan terowongan dengan menggunakan mesin bor dan/atau bahan peledak, bekisting, pembesian, dan pengecoran beton; pemeliharaan dan perbaikan bangunan terowongan di bawah permukaan air, di bukit atau pegunungan dan di bawah permukaan tanah.',NULL,NULL,0),
	(765,'42201','KONSTRUKSI JARINGAN IRIGASI DAN DRAINASE','Kelompok ini mencakup usaha pembangunan pemeliharaan, dan/atau pembangunan kembali bangunan jaringan saluran air irigasi dan jaringan drainase.',NULL,NULL,0),
	(766,'42202','KONSTRUKSI BANGUNAN SIPIL PENGOLAHAN AIR BERSIH','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan penyadap dan penyalur air baku, bangunan pengolahan air baku, bangunan pengolahan air minum, bangunan menara air minum, reservoir air minum, jaringan pipa/penyalur distribusi air bersih, tangki air minum dan bangunan pelengkap air minum lainnya.',NULL,NULL,0),
	(767,'42203','KONSTRUKSI BANGUNAN SIPIL PRASARANA DAN SARANA SISTEM PENGOLAHAN LIMBAH PADAT, CAIR, DAN GAS','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan pengolahan limbah padat, cair, dan gas, reservoir limbah, jaringan perpipaan limbah,bangunan jaringan air limbah dalam kota (jaringan pengumpul air limbah domestik/manusia dan air limbah industri), bangunan tempat pembuangan dan pembakaran (incenerator) limbah, dan bangunan pelengkap limbah padat, cair, dan gas, bangunan tempat pembuangan akhir sampah beserta bangunan pelengkapnya, dan jasa pemasangan konstruksi sistem septik, konstruksi unit pengolahan limbah yang dihasilkan dari pembangkit thermal, hydro, panas bumi, energi baru dan terbarukan (EBT) lainnya.',NULL,NULL,0),
	(768,'42204','KONSTRUKSI BANGUNAN SIPIL ELEKTRIKAL','Kelompok ini mencakup kegiatan pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan sipil elektrikal seperti bangunan sipil pembangkit, transmisi, distribusi dan instalasi pemanfaatan tenaga listrik, jaringan pipa listrik lokal dan jarak jauh termasuk pembangunan gardu induk dan pemasangan tiang listrik dan menara.',NULL,NULL,0),
	(769,'42205','KONSTRUKSI BANGUNAN SIPIL TELEKOMUNIKASI UNTUK PRASARANA TRANSPORTASI','Kelompok ini mencakup kegiatan pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan fasilitas telekomunikasi sarana bantu navigasi laut, bangunan telekomunikasi navigasi udara, bangunan sinyal dan telekomunikasi kereta api, termasuk bangunan menara/tiang/ pipa/antena dan bangunan sejenisnya.',NULL,NULL,0),
	(770,'42206','KONSTRUKSI SENTRAL TELEKOMUNIKASI','Kelompok ini mencakup kegiatan pembangunan, pemeliharaan dan perbaikan konstruksi bangunan sentral telekomunikasi beserta perlengkapannya, seperti bangunan sentral telepon, telegraf, bangunan menara pemancar, penerima radar gelombang mikro, bangunan stasiun bumi kecil dan stasiun satelit. Termasuk jaringan pipa komunikasi lokal dan jarak jauh, jaringan transmisi, dan jaringan distribusi kabel telekomunikasi/ telepon di atas permukaan tanah, di bawah tanah dan di dalam air.',NULL,NULL,0),
	(771,'42207','PEMBUATAN/PENGEBORAN SUMUR AIR TANAH','Kelompok ini mencakup kegiatan khusus pembuatan/pengeboran untuk mendapatkan air tanah, baik skala kecil, skala sedang, maupun skala besar dan tekanan tinggi sebagai bagian dari pekerjaan yang tercakup dalam konstruksi gedung. Termasuk pekerjaan pengeboran atau penggalian sumur air, pemasangan pompa dan pipanya.',NULL,NULL,0),
	(772,'42209','KONSTRUKSI JARINGAN IRIGASI, KOMUNIKASI, DAN LIMBAH LAINNYA','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan konstruksi lainnya yang belum tercakup dalam kelompok 42201 s.d. 42207. Termasuk penataan bangunan dan lingkungan, prasarana kawasan permukiman, industri, rumah sakit, dan lain-lain.',NULL,NULL,0),
	(773,'42911','KONSTRUKSI BANGUNAN PRASARANA SUMBER DAYA AIR','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan prasarana sumber daya air seperti bendungan (dam), bendung (weir), embung, pintu air, talang (viaduk), siphon, check dam, tanggul dan saluran pengendali banjir, tanggul laut, bangunan pengambilan (free intake), krib, waduk dan sejenisnya, stasiun pompa dan/atau prasarana sumber daya air lainnya.',NULL,NULL,0),
	(774,'42912','KONSTRUKSI BANGUNAN PELABUHAN BUKAN PERIKANAN','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan dermaga (jetty), trestle,sarana pelabuhan, dan sejenisnya pelabuhan bukan perikanan. Termasuk konstruksi jalan air atau terusan, pelabuhan dan sarana jalur sungai, dok (pangkalan), lock (panama canal lock, hoover dam) dan lain-lain.',NULL,NULL,0),
	(775,'42913','KONSTRUKSI BANGUNAN PELABUHAN PERIKANAN','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan dermaga (jetty), trestle,sarana pelabuhan, dan sejenisnya pelabuhan perikanan. Termasuk konstruksi jalan air atau terusan, pelabuhan dan sarana jalur sungai, dok (pangkalan), lock (panama canal lock, hoover dam) dan lain-lain.',NULL,NULL,0),
	(776,'42914','PENGERUKAN','Kelompok ini mencakup usaha pengerukan atau normalisasi dan pemeliharaan sungai, pelabuhan, rawa, danau, alur pelayaran, kolam dan kanal, baik dengan sifat pekerjaan ringan, sedang, maupun berat. Termasuk pengerukan untuk pembuatan jalur transportasi air.',NULL,NULL,0),
	(777,'42915','KONSTRUKSI BANGUNAN SIPIL MINYAK DAN GAS BUMI','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan sipil pada kegiatan usaha hulu dan hilir minyak dan gas.',NULL,NULL,0),
	(778,'42916','KONSTRUKSI BANGUNAN SIPIL PERTAMBANGAN','Kelompok ini mencakup usaha pembangunan, pemeliharaan, dan/atau pembangunan kembali fasilitas eksplorasi dan operasi produksi pertambangan, termasuk pengendalian dampak lingkungan.',NULL,NULL,0),
	(779,'42917','KONSTRUKSI BANGUNAN SIPIL PANAS BUMI','Kelompok ini mencakup jasa konstruksi untuk pembangunan, pemeliharaan, dan/atau pembangunan kembali, fasilitas hulu panas bumi, seperti sumur dan pipa penyalur.',NULL,NULL,0),
	(780,'42918','KONSTRUKSI BANGUNAN SIPIL FASILITAS OLAH RAGA','Kelompok ini mencakup kegiatan pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan fasilitas olah raga seperti bangunan stadion, olah raga lapangan (sepakbola, baseball, rugby, lintasan balap mobil dan motor), lapangan basket, hockey, lapangan tenis, lapangan golf, kolam renang termasuk kolam renang berdinding baja galvanized stainless steel standar olympic, lintasan atletik, lapangan panahan, gelanggang olahraga dan lain-lain.',NULL,NULL,0),
	(781,'42919','KONSTRUKSI BANGUNAN SIPIL LAINNYA YTDL','Kelompok ini mencakup usaha pembangunan, pemeliharaan dan perbaikan bangunan sipil lainnya yang belum tercakup dalam kelompok 42911 s.d. 42918, seperti lapangan parkir dan sarana lingkungan pemukiman (di luar gedung) lainnya. Kelompok ini mencakup pembagian lahan dengan pengembangannya (misalnya penambahan jalan, prasarana umum dan lain-lain). Termasuk pengadaan dan pelaksanaan konstruksi fasilitas mikroelektronika dan pabrik pengolahan, seperti yang memproduksi mikroprosesor, chip silikon dan wafer, mikrosirkuit, dan semikonduktor; pengadaan dan pelaksanaan konstruksi pabrik pengolahan tekstil dan pakaian; pengadaan dan pelaksanaan konstruksi pengolahan besi dan baja; dan/atau pengadaan dan pelaksanaan konstruksi pabrik pengolahan lainnya.',NULL,NULL,0),
	(782,'42921','KONSTRUKSI RESERVOIR PEMBANGKIT LISTRIK TENAGA AIR','Kelompok ini mencakup kegiatan pembangunan reservoir, intake, control gate, penstock, dan outflow pada pembangkit listrik tenaga air.',NULL,NULL,0),
	(783,'42922','JASA PEKERJAAN KONSTRUKSI PELINDUNG PANTAI','Kelompok ini mencakup kegiatan pembangunan, pemeliharaan, dan/atau pembangunan kembali bangunan pelindung pantai termasuk groin, breakwater, seawall, artificial headland, beach nourishment, terumbu buatan dan pekerjaan lainnya yang sejenis.',NULL,NULL,0),
	(784,'42923','KONSTRUKSI BANGUNAN SIPIL FASILITAS PENGOLAHAN PRODUK KIMIA, PETROKIMIA, FARMASI, DAN INDUSTRI LAINNYA','Kelompok ini mencakup kegiatan pembangunan, pemeliharaan, dan/atau pembangunan kembali pabrik pengolahan bahan kimia dasar; pengolahan pupuk; pabrik plastik dan pabrik pengolahan karet; pengolahan hasil agrokimia; pabrik pengolahan kimia lainnya termasuk pabrik pengolahan produk farmasi dan petrokimia.',NULL,NULL,0),
	(785,'42924','KONSTRUKSI BANGUNAN SIPIL FASILITAS MILITER DAN PELUNCURAN SATELIT','Kelompok ini mencakup kegiatan pembangunan, pemeliharaan, dan/atau pembangunan kembali konstruksi bangunan untuk fasilitas militer seperti benteng, lubang perlindungan, pusat pengujian militer. Termasuk tempat peluncuran satelit.',NULL,NULL,0),
	(786,'42929','KONSTRUKSI KHUSUS BANGUNAN SIPIL LAINNYA YTDL','Kelompok ini mencakup kegiatan pembangunan, pemeliharaan, dan/atau pembangunan kembali konstruksi khusus bangunan sipil lainnya yang belum tercakup dalam kelompok 42921 s.d. 42924.',NULL,NULL,0),
	(787,'42930','JASA PEKERJAAN KONSTRUKSI PRAPABRIKASI BANGUNAN SIPIL','Kelompok ini mencakup kegiatan pemasangan bahan hasil produksi pabrik seperti beton pracetak, baja, plastik, karet, dan hasil produksi pabrik lainnya dengan metode pabrikasi, erection, dan/ atau perakitan untuk bangunan sipil.',NULL,NULL,0),
	(788,'43110','PEMBONGKARAN','Kelompok ini mencakup usaha pembongkaran dan penghancuran atau perataan gedung atau bangunan lainnya serta pembersihannya. Tidak termasuk penyiapan lahan untuk pertambangan minyak dan gas.',NULL,NULL,0),
	(789,'43120','PENYIAPAN LAHAN','Kelompok ini mencakup usaha penyiapan lahan untuk kegiatan konstruksi yang berikutnya, seperti pelaksanaan pembersihan dan pematangan lahan konstruksi, pembersihan semak belukar; pembukaan lahan/stabilisasi tanah, (penggalian, membuat kemiringan, pengurukan, perataan lahan konstruksi, penggalian parit, pemindahan, penghancuran atau peledakan batu dan sebagainya); pelaksanaan pekerjaan tanah dan/atau tanah berbatu, penggalian, membuat kemiringan, perataan tanah dengan galian dan timbunan untuk konstruksi jalan (raya, sedang, dan kecil), jalan bebas hambatan, jalan rel kereta api, dan jalan landasan terbang (pacu, taksi, dan parkir), pabrik, pembangkit, transmisi, gardu induk, dan distribusi tenaga listrik, fasilitas produksi, serta bangunan gedung dan bangunan sipil lainnya; pemasangan, pemindahan, dan perlindungan utilitas, tes/uji dengan sondir dan bor, pemboran, ekstraksi material, dan penyelidikan lapangan/pengambilan contoh untuk keperluan konstruksi, geofisika, geologi atau keperluan sejenis; dan penyiapan lahan untuk fasilitas ketenaganukliran. Kegiatan penunjang penyiapan lahan seperti pemasangan fasilitas alat bantu konstruksi (pemasangan sheet pile, papan nama proyek, dan gorong-gorong untuk pemasangan kabel, pekerjaan pembuatan kantor, basecamp, direksi kit, gudang, bengkel proyek), pengukuran kembali, pembuatan/pengalihan jalan sementara, perbaikan dan pemeliharaan jalan umum, dewatering/pengeringan, mobilisasi dan demobilisasi, dan pekerjaan sejenis lainnya.',NULL,NULL,0),
	(790,'43211','INSTALASI LISTRIK','Kelompok ini mencakup kegiatan pembangunan, pemasangan, pemeliharaan, pembangunan kembali instalasi listrik pada pembangkit, transmisi, gardu induk, distribusi tenaga listrik, sistem catu daya, dan instalasi listrik pada bangunan gedung baik untuk hunian maupun non hunian, seperti pemasangan instalasi jaringan listrik tegangan rendah. Termasuk kegiatan pemasangan dan pemeliharaan instalasi listrik pada bangunan sipil, seperti jalan raya, jalan kereta api dan lapangan udara.',NULL,NULL,0),
	(791,'43212','INSTALASI TELEKOMUNIKASI','Kelompok ini mencakup kegiatan pemasangan instalasi telekomunikasi pada bangunan gedung baik untuk hunian maupun non hunian, seperti pemasangan antena. Kelompok ini juga mencakup kegiatan pemasangan, pemeliharaan dan perbaikan instalasi telekomunikasi pada sentral telepon/telegraf, stasiun pemancar radar gelombang mikro, stasiun bumi kecil/stasiun satelit dan sejenisnya. Termasuk kegiatan pemasangan transmisi dan jaringan telekomunikasi dan Instalasi telekomunikasi di bangunan gedung dan bangunan sipil.',NULL,NULL,0),
	(792,'43213','INSTALASI ELEKTRONIKA','Kelompok ini mencakup kegiatan pemasangan instalasi elektronika pada bangunan gedung baik untuk hunian maupun non hunian, dan elektronika bandara serta teknologi informasi (termasuk telekomunikasi dan sistem teknologi informasi), seperti pemasangan sistem alarm, close circuit TV dan sound system dan commercial management system (pre-paid electricity voucher). Termasuk juga instalasi access control, scoring board, timing system, perimeter pixel display, master clock dan fasilitas elektronik lainnya.',NULL,NULL,0),
	(793,'43214','JASA INSTALASI KONSTRUKSI NAVIGASI LAUT, SUNGAI, DAN UDARA','Kelompok ini mencakup kegiatan pemasangan dan perawatan konstruksi dan peralatan terkait dengan sarana bantu navigasi laut,sungai dan udara, telekomunikasipelayaran/penerbangan, hidrografi dan meteorologi, alur perlintasan, pemanduan, untuk kepentingan keselamatan pelayaran dan penerbangan.',NULL,NULL,0),
	(794,'43215','INSTALASI SINYAL DAN TELEKOMUNIKASI KERETA API','Kelompok ini mencakup pemasangan, pemeliharaan dan perbaikan instalasi sinyal dan telekomunikasi kereta api.',NULL,NULL,0),
	(795,'43216','INSTALASI SINYAL DAN RAMBU-RAMBU JALAN RAYA','Kelompok ini mencakup kegiatan pemasangan, pemeliharaan dan perbaikan instalasi sinyal dan rambu-rambu jalan raya. Termasuk pemasangan perlengkapan jalan dan/atau rambu jalan, marka jalan, marka jembatan, termasuk reflector, deliniator, papan penunjuk jalan, patok pengarah, patok kilometer, patok hektometer, kerb pracetak, median beton, guardrail, dan perlengkapan lainnya yang sejenis.',NULL,NULL,0),
	(796,'43221','INSTALASI SALURAN AIR (PLAMBING)','Kelompok ini mencakup kegiatan instalasi air bersih, air limbah dan saluran drainase, termasuk pekerjaan perpipaan pada bangunan gedung hunian maupun non hunian. Termasuk kegiatan pemeliharaan dan perbaikan instalasi saluran air, pipa distribusi air bersih dan instalasi Water Treatment Plant (WTP)/Reverse Osmosis (RO), pipa air kotor.',NULL,NULL,0),
	(797,'43222','INSTALASI PEMANAS DAN GEOTERMAL','Kelompok ini mencakup kegiatan pemasangan dan perawatan peralatan pemanas (heating) dan geotermal pada bangunan gedung untuk hunian maupun bukan hunian, elektrik maupun non elektrik, termasuk pekerjaan pipa, ducting dan lembaran logam; sistem pengendali pemanasan sentral, penghubung ke sistem pemanasan area, termasuk boiler domestik alat pembakar (burner). Termasuk pekerjaan isolasi panas pada pipa atau tangki, pemasangan insulasi termal kedap cuaca sebelah luar dinding, pemasangan insulasi thermal (untuk pipa air panas dan dingin, ketel uap dan saluran pembuang), insulasi kedap kebakaran, dan pemasangan sistem pelindung kebakaran.',NULL,NULL,0),
	(798,'43223','INSTALASI MINYAK DAN GAS','Kelompok ini mencakup kegiatan pemasangan dan pemeliharaan instalasi minyak dan gas pada bangunan gedung hunian dan non hunian serta bangunan sipil lainnya, pekerjaan inspeksi, dan perawatan fasilitas produksi minyak, gas, petrokimia dan panas bumi termasuk pekerjaan instalasi perpipaannya di darat maupun di bawah laut. Termasuk instalasi fasilitas produksi dan penyimpanan di darat dan di laut untuk minyak, gas, petrokimia dan panas bumi termasuk anjungan lepas pantai dan bawah laut.',NULL,NULL,0),
	(799,'43224','INSTALASI PENDINGIN DAN VENTILASI UDARA','Kelompok ini mencakup kegiatan pemasangan dan perawatan ventilasi (ventilation), lemari pendingin dan penyejuk udara (Air Conditioner/AC) untuk bangunan gedung baik untuk hunian maupun bukan hunian, termasuk pekerjaan pipa, ducting dan lembaran logam.',NULL,NULL,0),
	(800,'43291','INSTALASI MEKANIKAL','Kelompok ini mencakup kegiatan pemasangan dan pemeliharaan instalasi mekanikal alat angkut dan alat angkat pada bangunan gedung hunian dan non hunian serta bangunan sipil lainnya, seperti lift, tangga berjalan (eskalator), ban berjalan (conveyor), jalan-tapak bergerak (travelator), gondola, dan pintu otomatis termasuk pekerjaan perlengkapan tangga keselamatan dari kebakaran.',NULL,NULL,0),
	(801,'43292','INSTALASI METEOROLOGI, KLIMATOLOGI DAN GEOFISIKA','Kelompok ini mencakup kegiatan pemasangan instalasi meteorologi, klimatologi dan geofisika ukuran kecil, sedang atau besar.',NULL,NULL,0),
	(802,'43293','INSTALASI FASILITAS SUMBER RADIASI PENGION','Kelompok ini mencakup kegiatan instalasi terhadap fasilitas sumber radiasi pengion.',NULL,NULL,0),
	(803,'43294','INSTALASI NUKLIR','Kelompok ini mencakup kegiatan instalasi terhadap reaktor nuklir dan instalasi nuklir non reaktor.',NULL,NULL,0),
	(804,'43299','INSTALASI KONSTRUKSI LAINNYA YTDL','Kelompok ini mencakup kegiatan pemasangan instalasi gedung lainnya dan kegiatan pemasangan, pemeliharaan dan perbaikan instalasi bangunan sipil lainnya yang belum tercakup dalam kelompok 43291 s.d. 43294. Termasuk pemasangan dan pemeliharaan instalasi fasilitas pertambangan dan manufaktur seperti loading and discharging stations, winding shafts, chemical plants, iron foundaries, blast furnaces dan coke oven; pemasangan instalasi sistem pengolahan dan peralatan pemurnian air laut, air payau, air tawar menjadi air murni pada pembangkit listrik.',NULL,NULL,0),
	(805,'43301','PENGERJAAN PEMASANGAN KACA DAN ALUMUNIUM','Kelompok ini mencakup kegiatan pemasangan kaca, alumunium, dan bahan lainnya untuk dinding luar dan dalam dalam rangka penyelesaian bangunan gedung hunian dan non hunian serta bangunan sipil lainnya. Termasuk instalasi atau pemasangan pintu (kecuali pintu otomatis dan pintu putar), jendela, rangka pintu dan jendela dari kayu atau bahan lainnya.',NULL,NULL,0),
	(806,'43302','PENGERJAAN LANTAI, DINDING, PERALATAN SANITER DAN PLAFON','Kelompok ini mencakup kegiatan pengerjaan lantai, dinding, kolom, peralatan saniter dan plafon dalam rangka penyelesaian bangunan gedung hunian dan non hunian serta bangunan sipil lainnya. Termasuk aplikasi bangunan atau proyek konstruksi lainnya dari plester (pelapisan) interior dan eksterior, termasuk bahan-bahan lathing yang berkaitan, penyelesaian interior seperti langit-langit, pelapisan dinding dengan kayu, gypsum, panel penutup akustik, partisi/sekat yang dapat dibongkar pasang dan sebagainya, pengubinan, penggantungan atau pemasangan dalam bangunan atau proyek konstruksi lainnya dari keramik, dinding, beton atau ubin lantai, parket (lantai dari papan yang bergambar) dan pelapisan lantai dengan kayu, pelapisan lantai linoleum dan karpet, termasuk karet atau plastik, teraso, marmer, granit atau pelapisan lantai atau dinding dan wallpaper (kertas dinding) serta dinding bangunan kedap suara.',NULL,NULL,0),
	(807,'43303','PENGECATAN','Kelompok ini mencakup kegiatan pengecatan interior dan eksterior bangunan dalam rangka penyelesaian bangunan gedung hunian dan non hunian serta bangunan sipil lainnya. Tidak termasuk pengecatan atap bangunan.',NULL,NULL,0),
	(808,'43304','DEKORASI INTERIOR','Kelompok ini mencakup kegiatan pengerjaan dekorasi interior dalam rangka penyelesaian bangunan gedung hunian dan non hunian serta bangunan sipil lainnya. Kegiatan pengerjaan dekorasi interior mencakup aplikasi bangunan atau proyek konstruksi lainnya dari plester (pelapisan) interior, termasuk bahan-bahan lathing yang berkaitan, instalasi atau pemasangan pintu (kecuali pintu otomatis dan pintu putar), kusen, jendela, rangka pintu dan jendela dari kayu atau bahan lainnya, instalasi dapur (kitchen set), tangga dan sejenisnya, pagar, instalasi furnitur, penyelesaian interior seperti langit-langit, pelapisan dinding dengan kayu, partisi/sekat yang dapat dibongkar pasang dan sebagainya, pengubinan atau pemasangan dalam bangunan atau proyek konstruksi lainnya dari keramik, dinding beton atau ubin lantai, parket (lantai dari papan yang bergambar) dan pelapisan lantai dengan kayu, pelapisan lantai linoleum dan karpet, termasuk karet atau plastik, teraso, marmer, granit atau pelapisan lantai atau dinding dan wallpaper (kertas dinding). Termasuk pengecatan, pemasangan kaca, cermin dan pemasangan ornamen dan pekerjaan dekorasi interior seni lainnya pada permukaan dinding, kolom atau plafon dengan bahan logam, kayu dan bahan lainnya.',NULL,NULL,0),
	(809,'43305','DEKORASI EKSTERIOR','Kelompok ini mencakup kegiatan pengerjaan dekorasi eksterior pada bangunan gedung hunian dan non hunian serta bangunan sipil lainnya, seperti konstruksi taman. Kegiatan pengerjaan dekorasi eksterior mencakup pelapisan eksterior bangunan atau proyek konstruksi lainnya dari plester, termasuk bahan-bahan lathing yang berkaitan, pelapisan eksterior dinding dengan keramik, teraso, marmer dan granit, kaca, batu alam, dan bahan lainnya.',NULL,NULL,0),
	(810,'43309','PENYELESAIAN KONSTRUKSI BANGUNAN LAINNYA','Kelompok ini mencakup kegiatan pembersihan dan perapihan gedung hunian dan non hunian serta bangunan sipil lainnya yang baru selesai dibangun, termasuk instalasi interior untuk toko, rumah bergerak, perahu, dan lain-lain dan pengerjaan penyelesaian konstruksi bangunan lainnya ytdl.',NULL,NULL,0),
	(811,'43901','PEMASANGAN PONDASI DAN TIANG PANCANG','Kelompok ini mencakup kegiatan khusus pemasangan berbagai pondasi dan tiang pancang termasuk pengecoran beton dan pembesian pondasi untuk gedung, jalan/jembatan, bangunan pengairan, dermaga, bangunan lepas pantai dan sejenisnya sebagai bagian dari pekerjaan yang tercakup dalam konstruksi gedung hunian dan non hunian serta bangunan sipil lainnya.',NULL,NULL,0),
	(812,'43902','PEMASANGAN PERANCAH (STEIGER)','Kelompok ini mencakup kegiatan khusus pemasangan perancah/steiger pada bangunan gedung, jalan/jembatan, bangunan pengairan, dermaga dan sejenisnya.',NULL,NULL,0),
	(813,'43903','PEMASANGAN RANGKA DAN ATAP/ROOF COVERING','Kelompok ini mencakup kegiatan khusus pemasangan kerangka dan atap bangunan gedung hunian dan non hunian sebagai bagian dari pekerjaan yang tercakup dalam konstruksi gedung. Termasuk pekerjaan talang dan pengecatan atap.',NULL,NULL,0),
	(814,'43904','PEMASANGAN KERANGKA BAJA','Kelompok ini mencakup kegiatan khusus pemasangan kerangka baja sebagai bagian dari pekerjaan yang tercakup dalam konstruksi gedung.',NULL,NULL,0),
	(815,'43905','PENYEWAAN ALAT KONSTRUKSI DENGAN OPERATOR','Kelompok ini mencakup usaha penyewaan alat atau mesin konstruksi dan perlengkapannya dengan operator. Termasuk penyewaan alat produksi dan operasional minyak, gas, petrokimia, panas bumi, komunikasi seperti SCADA (Supervisory Control and Data Acquisition), dan penyewaan derek. Penyewaan mesin konstruksi dan perlengkapannya tanpa operator dicakup dalam kelompok 77393.',NULL,NULL,0),
	(816,'43909','KONSTRUKSI KHUSUS LAINNYA YTDL','Kelompok ini mencakup kegiatan konstruksi khusus lainnya yang belum diklasifikasikan dalam kelompok 43901 s.d. 43905 yang memerlukan keahlian atau perlengkapan khusus, seperti kegiatan pengerjaan penahan lembab dan air, dehumidifikasi (pelembaban) bangunan, shaft sinking, pemasangan cerobong asap dan oven untuk keperluan industri dan pekerjaan yang memerlukan keahlian memanjat dan penggunaan perlengkapan yang berkaitan, misalnya bekerja pada gedung-gedung yang tinggi. Termasuk pekerjaan di bawah permukaan tanah, pekerjaan lapis perkerasan beton; pekerjaan perkerasan aspal; pekerjaan perkerasan berbutir; pekerjaan konstruksi pengeboran dan injeksi semen bertekanan; pekerjaan beton struktur; pekerjaan konstruksi beton pascatarik (post tensioned); pekerjaan konstruksi kedap air pada tangki penyimpanan air, minyak, gas, dan lainnya yang sejenis; serta pemasangan konstruksi tahan api (tanur, anneling, flare, incenerator) untuk bangunan gedung hunian dan non hunian serta bangunan sipil lainnya.',NULL,NULL,0),
	(817,'45101','PERDAGANGAN BESAR MOBIL BARU','Kelompok ini mencakup usaha perdagangan besar mobil baru, termasuk mobil khusus (seperti ambulans, karavan, mikrobus, pemadam kebakaran, dan sebagainya), lori, trailer, semi-trailer dan berbagai kendaraan pengangkut bermotor lainnya.',NULL,NULL,0),
	(818,'45102','PERDAGANGAN BESAR MOBIL BEKAS','Kelompok ini mencakup usaha perdagangan besar mobil bekas, termasuk mobil khusus (seperti ambulans, karavan, mikrobus, pemadam kebakaran, dan sebagainya), lori, trailer, semi-trailer dan berbagai kendaraan pengangkut bermotor lainnya.',NULL,NULL,0),
	(819,'45103','PERDAGANGAN ECERAN MOBIL BARU','Kelompok ini mencakup usaha penjualan eceran mobil baru, termasuk mobil khusus (seperti ambulans, karavan, mikrobus, pemadam kebakaran, dan sebagainya), lori, trailer, semi-trailer dan berbagai kendaraan pengangkut bermotor lainnya.',NULL,NULL,0),
	(820,'45104','PERDAGANGAN ECERAN MOBIL BEKAS','Kelompok ini mencakup usaha penjualan eceran mobil bekas, termasuk mobil khusus (seperti ambulans, karavan, mikrobus, pemadam kebakaran, dan sebagainya), lori, trailer, semi-trailer dan berbagai kendaraan pengangkut bermotor lainnya.',NULL,NULL,0),
	(821,'45201','REPARASI MOBIL','Kelompok ini mencakup usaha reparasi dan perawatan mobil, seperti reparasi mekanik, reparasi elektrik, reparasi sistem injeksi elektronik, servis regular, reparasi badan mobil, reparasi bagian kendaraan bermotor, penyemprotan dan pengecatan, reparasi kaca dan jendela dan reparasi tempat duduk kendaraan bermotor. Termasuk reparasi, pemasangan atau penggantian ban dan pipa, perawatan anti karat, pemasangan bagian dan aksesori yang bukan bagian dari proses pembuatan dan usaha perawatan lainnya.',NULL,NULL,0),
	(822,'45202','PENCUCIAN DAN SALON MOBIL','Kelompok ini mencakup usaha pencucian mobil dan salon mobil, seperti pencucian dan pemolesan dan pemasangan bagian dan aksesori yang bukan bagian dari proses pembuatan di salon mobil.',NULL,NULL,0),
	(823,'45301','PERDAGANGAN BESAR SUKU CADANG DAN AKSESORI MOBIL','Kelompok ini mencakup usaha perdagangan besar berbagai suku cadang, komponen dan aksesori mobil yang terpisah dari perdagangannya, seperti karet ban dan ban dalam, busi mobil, baterai (aki), perlengkapan lampu dan bagian-bagian kelistrikan.',NULL,NULL,0),
	(824,'45302','PERDAGANGAN ECERAN SUKU CADANG DAN AKSESORI MOBIL','Kelompok ini mencakup usaha penjualan eceran berbagai suku cadang, komponen dan aksesori mobil yang terpisah dari perdagangannya, seperti karet ban dan ban dalam, busi mobil, baterai (aki), perlengkapan lampu dan bagian-bagian kelistrikan.',NULL,NULL,0),
	(825,'45401','PERDAGANGAN BESAR SEPEDA MOTOR BARU','Kelompok ini mencakup usaha perdagangan besar sepeda motor baru, termasuk motor sepeda atau moped.',NULL,NULL,0),
	(826,'45402','PERDAGANGAN BESAR SEPEDA MOTOR BEKAS','Kelompok ini mencakup usaha perdagangan besar sepeda motor bekas, termasuk motor sepeda atau moped.',NULL,NULL,0),
	(827,'45403','PERDAGANGAN ECERAN SEPEDA MOTOR BARU','Kelompok ini mencakup usaha penjualan eceran sepeda motor baru, termasuk motor sepeda atau moped.',NULL,NULL,0),
	(828,'45404','PERDAGANGAN ECERAN SEPEDA MOTOR BEKAS','Kelompok ini mencakup usaha penjualan eceran sepeda motor bekas, termasuk motor sepeda atau moped.',NULL,NULL,0),
	(829,'45405','PERDAGANGAN BESAR SUKU CADANG SEPEDA MOTOR DAN AKSESORINYA','Kelompok ini mencakup usaha perdagangan besar suku cadang sepeda motor dan aksesorinya.',NULL,NULL,0),
	(830,'45406','PERDAGANGAN ECERAN SUKU CADANG SEPEDA MOTOR DAN AKSESORINYA','Kelompok ini mencakup usaha penjualan eceran suku cadang sepeda motor dan aksesorinya.',NULL,NULL,0),
	(831,'45407','REPARASI DAN PERAWATAN SEPEDA MOTOR','Kelompok ini mencakup usaha pemeliharaan dan reparasi sepeda motor, termasuk pencucian sepeda motor dan usaha perawatan lainnya.',NULL,NULL,0),
	(832,'46100','PERDAGANGAN BESAR ATAS DASAR BALAS JASA (FEE) ATAU KONTRAK','Kelompok ini mencakup usaha agen yang menerima komisi, perantara (makelar), pelelangan, dan pedagang besar lainnya yang memperdagangkan barang-barang di dalam negeri, luar negeri atas nama pihak lain. Kegiatannya antara lain agen komisi, broker barang dan seluruh perdagangan besar lainnya yang menjual atas nama dan tanggungan pihak lain; kegiatan yang terlibat dalam penjualan dan pembelian bersama atau melakukan transaksi atas nama perusahaan, termasuk melalui internet; dan agen yang terlibat dalam perdagangan seperti bahan baku pertanian, binatang hidup; bahan baku tekstil dan barang setengah jadi; bahan bakar, bijih-bijihan, logam dan industri kimia, termasuk pupuk; makanan, minuman dan tembakau; tekstil, pakaian, bulu, alas kaki dan barang dari kulit; kayu-kayuan dan bahan bangunan; mesin, termasuk mesin kantor dan komputer, perlengkapan industri, kapal, pesawat; furnitur, barang keperluan rumah tangga dan perangkat keras; kegiatan perdagangan besar rumah pelelangan; agen komisi zat radioaktif dan pembangkit radiasi pengion. Termasuk penyelenggara pasar lelang komoditas. Tidak termasuk kegiatan perdagangan besar mobil dan sepeda motor, dimasukkan dalam golongan 451 s.d. 454.',NULL,NULL,0),
	(833,'46201','PERDAGANGAN BESAR PADI DAN PALAWIJA','Kelompok ini mencakup usaha perdagangan besar hasil pertanian tanaman padi dan palawija sebagai bahan baku atau bahan dasar dari suatu kegiatan berikutnya, seperti padi, jagung, gabah, gandum dan seralia lainnya. Termasuk perdagangan besar benih dan bibit padi, palawija, dan serealia lainnya.',NULL,NULL,0),
	(834,'46202','PERDAGANGAN BESAR BUAH YANG MENGANDUNG MINYAK','Kelompok ini mencakup usaha perdagangan besar hasil pertanian tanaman buah yang mengandung minyak, seperti kelapa dan kelapa sawit. Termasuk perdagangan besar bibit buah yang mengandung minyak.',NULL,NULL,0),
	(835,'46203','PERDAGANGAN BESAR BUNGA DAN TANAMAN HIAS','Kelompok ini mencakup usaha perdagangan besar hasil pertanian tanaman bunga dan tanaman hias lainnya, seperti tanaman bunga mawar, melati, tanaman hias dan tumbuhan lainnya. Termasuk bibit tanaman hias, bunga dan sebagainya.',NULL,NULL,0),
	(836,'46204','PERDAGANGAN BESAR TEMBAKAU RAJANGAN','Kelompok ini mencakup usaha perdagangan besar hasil pertanian tanaman tembakau, seperti daun tembakau yang belum diolah dan tembakau rajangan dan sebagainya.',NULL,NULL,0),
	(837,'46205','PERDAGANGAN BESAR BINATANG HIDUP','Kelompok ini mencakup usaha perdagangan besar yang berhubungan dengan binatang hidup, seperti unggas, ternak potong dan ternak atau binatang hidup lainnya. Termasuk perdagangan besar bibit binatang.',NULL,NULL,0),
	(838,'46206','PERDAGANGAN BESAR HASIL PERIKANAN','Kelompok ini mencakup usaha perdagangan besar hasil perikanan sebagai bahan baku atau bahan dasar dari kegiatan berikutnya, seperti ikan, udang, kepiting, tiram, mutiara, kerang, rumput laut, bunga karang dan kodok, termasuk ikan hidup, ikan hias, serta bibit hasil perikanan.',NULL,NULL,0),
	(839,'46207','PERDAGANGAN BESAR HASIL KEHUTANAN DAN PERBURUAN','Kelompok ini mencakup usaha perdagangan besar hasil pengusahaan kehutanan, pengambilan hasil hutan dan perburuan, seperti bambu, kayu cendana, getah damar dan sejenisnya. Termasuk perdagangan besar bibit tanaman kehutanan.',NULL,NULL,0),
	(840,'46208','PERDAGANGAN BESAR KULIT DAN KULIT JANGAT','Kelompok ini mencakup usaha perdagangan besar kulit dan kulit jangat, termasuk kulit imitasi.',NULL,NULL,0),
	(841,'46209','PERDAGANGAN BESAR HASIL PERTANIAN DAN HEWAN HIDUP LAINNYA','Kelompok ini mencakup usaha perdagangan besar hasil pertanian dan hewan hidup lainnya yang belum diklasifikasikan di tempat lain. Termasuk dalam kelompok ini perdagangan besar bahan baku pertanian, sisaan dan sampah pertanian, dan hasil ikutan pertanian yang digunakan untuk makanan hewan, serta tanaman dan bibit tanaman lainnya yang belum disebutkan di atas.',NULL,NULL,0),
	(842,'46311','PERDAGANGAN BESAR BERAS','Kelompok ini mencakup usaha perdagangan besar beras untuk digunakan sebagai konsumsi akhir.',NULL,NULL,0),
	(843,'46312','PERDAGANGAN BESAR BUAH-BUAHAN','Kelompok ini mencakup usaha perdagangan besar buah-buahan untuk digunakan sebagai konsumsi akhir, seperti jeruk, apel, pear, mangga dan buah lainnya.',NULL,NULL,0),
	(844,'46313','PERDAGANGAN BESAR SAYURAN','Kelompok ini mencakup usaha perdagangan besar sayur-sayuran untuk digunakan sebagai konsumsi akhir, seperti bayam, kangkung, kol dan sayuran lainnya.',NULL,NULL,0),
	(845,'46314','PERDAGANGAN BESAR KOPI, TEH DAN KAKAO','Kelompok ini mencakup usaha perdagangan besar kopi, teh dan kakao.',NULL,NULL,0),
	(846,'46315','PERDAGANGAN BESAR MINYAK DAN LEMAK NABATI','Kelompok ini mencakup usaha perdagangan besar minyak dan lemak nabati, termasuk margarin serta produk berbahan dasar lemak nabati seperti non-dairy cream, dan produk sejenis lainnya.',NULL,NULL,0),
	(847,'46319','PERDAGANGAN BESAR BAHAN MAKANAN DAN MINUMAN HASIL PERTANIAN LAINNYA','Kelompok ini mencakup usaha perdagangan besar bahan makanan dan minuman hasil pertanian lainnya, seperti tanaman bumbu-bumbuan dan rempah-rempah.',NULL,NULL,0),
	(848,'46321','PERDAGANGAN BESAR DAGING SAPI DAN DAGING SAPI OLAHAN','Kelompok ini mencakup usaha perdagangan besar daging sapi dan daging sapi olahan, termasuk daging sapi yang diawetkan.',NULL,NULL,0),
	(849,'46322','PERDAGANGAN BESAR DAGING AYAM DAN DAGING AYAM OLAHAN','Kelompok ini mencakup usaha perdagangan besar daging ayam dan daging ayam olahan, termasuk daging ayam yang diawetkan.',NULL,NULL,0),
	(850,'46323','PERDAGANGAN BESAR DAGING DAN DAGING OLAHAN LAINNYA','Kelompok ini mencakup usaha perdagangan besar daging dan daging olahan lainnya, termasuk daging lainnya yang diawetkan.',NULL,NULL,0),
	(851,'46324','PERDAGANGAN BESAR HASIL OLAHAN PERIKANAN','Kelompok ini mencakup usaha perdagangan besar pengolahan hasil perikanan.',NULL,NULL,0),
	(852,'46325','PERDAGANGAN BESAR TELUR DAN HASIL OLAHAN TELUR','Kelompok ini mencakup usaha perdagangan besar telur dan hasil olahan telur.',NULL,NULL,0),
	(853,'46326','PERDAGANGAN BESAR SUSU DAN PRODUK SUSU','Kelompok ini mencakup usaha perdagangan besar susu dan produk susu.',NULL,NULL,0),
	(854,'46327','PERDAGANGAN BESAR MINYAK DAN LEMAK HEWANI','Kelompok ini mencakup usaha perdagangan besar minyak dan lemak hewani.',NULL,NULL,0),
	(855,'46329','PERDAGANGAN BESAR BAHAN MAKANAN DAN MINUMAN HASIL PETERNAKAN DAN PERIKANAN LAINNYA','Subgolongan ini mencakup perdagangan besar bahan makanan dan minuman hasil peternakan dan perikanan yang belum tercakup dalam kelompok 46321 s.d 46327, seperti perdagangan besar madu hasil peternakan lebah, dan pemungutan madu hasil hutan.',NULL,NULL,0),
	(856,'46331','PERDAGANGAN BESAR GULA, COKLAT DAN KEMBANG GULA','Kelompok ini mencakup usaha perdagangan besar gula, coklat, kembang gula dan sediaan pemanis.',NULL,NULL,0),
	(857,'46332','PERDAGANGAN BESAR PRODUK ROTI','Kelompok ini mencakup usaha perdagangan besar produk roti, kue dan bakeri lainnya.',NULL,NULL,0),
	(858,'46333','PERDAGANGAN BESAR MINUMAN BERALKOHOL','Kelompok ini mencakup usaha perdagangan besar minuman beralkohol, seperti minuman keras, anggur, malt, bir dan lain-lain.',NULL,NULL,0),
	(859,'46334','PERDAGANGAN BESAR MINUMAN NON ALKOHOL BUKAN SUSU','Kelompok ini mencakup usaha perdagangan besar minuman non alkohol, seperti sari buah, jus, minuman ringan, air mineral, air kemasan, dan produk sejenis lainnya.',NULL,NULL,0),
	(860,'46335','PERDAGANGAN BESAR ROKOK DAN TEMBAKAU','Kelompok ini mencakup usaha perdagangan besar hasil pengolahan tembakau dan bumbu rokok, seperti rokok kretek dan rokok putih.',NULL,NULL,0),
	(861,'46339','PERDAGANGAN BESAR MAKANAN DAN MINUMAN LAINNYA','Kelompok ini mencakup usaha perdagangan besar makanan dan minuman lainnya, seperti tepung beras, tepung tapioka, premiks bakeri, karamel, madu olahan, kerupuk udang dan lain-lain. Termasuk pangan untuk keperluan gizi khusus (untuk bayi, anak, dan dewasa), bahan tambahan pangan (food additive), bahan penolong (processing aid), makanan ringan lainnya, serealia dan produk berbasis serealia yang belum diolah maupun telah diolah, minuman produk kedelai, makanan siap saji, serta perdagangan besar makanan untuk hewan piaraan dan makanan ternak.',NULL,NULL,0),
	(862,'46411','PERDAGANGAN BESAR TEKSTIL','Kelompok ini mencakup usaha perdagangan besar hasil industri tekstil, seperti bermacam-macam tekstil/kain, kain batik dan lain-lain. Termasuk barang linen rumah tangga (bahan kain untuk keperluan rumah tangga) dan lain-lain.',NULL,NULL,0),
	(863,'46412','PERDAGANGAN BESAR PAKAIAN','Kelompok ini mencakup usaha perdagangan besar pakaian, termasuk pakaian olahraga dan perdagangan besar aksesoris pakaian seperti sarung tangan, dasi dan penjepit. Termasuk perdagangan besar kaos kaki.',NULL,NULL,0),
	(864,'46413','PERDAGANGAN BESAR ALAS KAKI','Kelompok ini mencakup usaha perdagangan besar alas kaki, seperti sepatu, sandal, selop dan sejenisnya.',NULL,NULL,0),
	(865,'46414','PERDAGANGAN BESAR BARANG LAINNYA DARI TEKSTIL','Kelompok ini mencakup usaha perdagangan besar hasil industri tekstil, seperti talitemali, karpet/permadani dari bahan tekstil, karung, macam-macam hasil rajutan dan barang jadi lainnya dari tekstil selain pakaian jadi.',NULL,NULL,0),
	(866,'46419','PERDAGANGAN BESAR TEKSTIL, PAKAIAN DAN ALAS KAKI LAINNYA','Kelompok ini mencakup usaha perdagangan besar haberdashery, seperti jarum, benang jahit dan lain-lain, perdagangan besar barang dari kulit berbulu dan perdagangan besar payung.',NULL,NULL,0),
	(867,'46421','PERDAGANGAN BESAR ALAT TULIS DAN GAMBAR','Kelompok ini mencakup usaha perdagangan besar peralatan tulis dan gambar, seperti buku tulis, buku gambar, alat tulis dan alat gambar.',NULL,NULL,0),
	(868,'46422','PERDAGANGAN BESAR BARANG PERCETAKAN DAN PENERBITAN DALAM BERBAGAI BENTUK','Kelompok ini mencakup usaha perdagangan besar barang percetakan dan penerbitan dalam berbagai bentuk, seperti buku-buku, majalah, surat kabar dan lain-lain.',NULL,NULL,0),
	(869,'46430','PERDAGANGAN BESAR ALAT FOTOGRAFI DAN BARANG OPTIK','Kelompok ini mencakup usaha perdagangan besar alat fotografi dan barang optik (seperti kaca mata, teropong dan kaca pembesar).',NULL,NULL,0),
	(870,'46441','PERDAGANGAN BESAR OBAT FARMASI UNTUK MANUSIA','Kelompok ini mencakup usaha perdagangan besar obat farmasi untuk keperluan rumah tangga, seperti obat-obatan dan suplemen kesehatan untuk manusia.',NULL,NULL,0),
	(871,'46442','PERDAGANGAN BESAR OBAT TRADISIONAL UNTUK MANUSIA','Kelompok ini mencakup usaha perdagangan besar obat tradisional atau jamu dan suplemen kesehatan untuk manusia.',NULL,NULL,0),
	(872,'46443','PERDAGANGAN BESAR KOSMETIK UNTUK MANUSIA','Kelompok ini mencakup usaha perdagangan besar kosmetik untuk manusia seperti parfum, sabun, bedak dan lainnya.',NULL,NULL,0),
	(873,'46444','PERDAGANGAN BESAR OBAT FARMASI UNTUK HEWAN','Kelompok ini mencakup usaha perdagangan besar obat farmasi untuk hewan yang meliputi kegiatan pemasukan, pengeluaran dan distribusi.',NULL,NULL,0),
	(874,'46445','PERDAGANGAN BESAR OBAT TRADISIONAL UNTUK HEWAN','Kelompok ini mencakup usaha perdagangan besar obat tradisional atau obat alami untuk hewan yang meliputi kegiatan pemasukan, pengeluaran dan distribusi.',NULL,NULL,0),
	(875,'46446','PERDAGANGAN BESAR KOSMETIK UNTUK HEWAN','Kelompok ini mencakup usaha perdagangan besar kosmetik untuk hewan, termasuk parfum, shampo, sabun, bedak, krim atau lotion, dan lainnya, yang meliputi kegiatan pemasukan, pengeluaran dan distribusi.',NULL,NULL,0),
	(876,'46447','PERDAGANGAN BESAR BAHAN FARMASI UNTUK MANUSIA DAN HEWAN','Kelompok ini mencakup usaha perdagangan besar bahan baku farmasi baik untuk manusia maupun hewan.',NULL,NULL,0),
	(877,'46448','PERDAGANGAN BESAR BAHAN BAKU OBAT TRADISIONAL UNTUK MANUSIA DAN HEWAN','Kelompok ini mencakup usaha perdagangan besar bahan baku obat tradisional baik untuk manusia maupun hewan.',NULL,NULL,0),
	(878,'46491','PERDAGANGAN BESAR PERALATAN DAN PERLENGKAPAN RUMAH TANGGA','Kelompok ini mencakup usaha perdagangan besar peralatan dan perlengkapan rumah tangga, seperti perabot rumah tangga (furniture), peralatan dapur dan memasak, lampu dan perlengkapannya, elektronik konsumen seperti radio, televisi, perekam dan pemutar CD dan DVD, perlengkapan stereo, konsol video game; alat penerangan, bermacam peralatan makan minum porselen dan gelas, peralatan sendok, pisau, garpu, peralatan dari kayu, barang dari anyaman dan barang dari gabus, karpet dan sebagainnya.',NULL,NULL,0),
	(879,'46492','PERDAGANGAN BESAR ALAT OLAHRAGA','Kelompok ini mencakup usaha perdagangan besar berbagai alat olahraga (termasuk sepeda dan bagian-bagiannya serta aksesorinya).',NULL,NULL,0),
	(880,'46493','PERDAGANGAN BESAR ALAT MUSIK','Kelompok ini mencakup usaha perdagangan besar berbagai alat musik, baik alat musik tradisional maupun alat musik modern, seperti kecapi, seruling bambu, calung, angklung, kulintang, gamelan, set, rebab, rebana, tifa, sasando, seruling (flute), saxophone, harmonika, trombone, gitar, mandolin, ukulele, harpa, bass, gambus, biola, cello, piano/organ, drum set dan garpu tala.',NULL,NULL,0),
	(881,'46494','PERDAGANGAN BESAR PERHIASAN DAN JAM','Kelompok ini mencakup usaha perdagangan besar berbagai barang perhiasan dan jam.',NULL,NULL,0),
	(882,'46495','PERDAGANGAN BESAR ALAT PERMAINAN DAN MAINAN ANAK-ANAK','Kelompok ini mencakup usaha perdagangan besar berbagai alat permainan dan mainan anak-anak baik permainan tradisional maupun modern seperti boardgame.',NULL,NULL,0),
	(883,'46499','PERDAGANGAN BESAR BERBAGAI BARANG DAN PERLENGKAPAN RUMAH TANGGA LAINNYA YTDL','Kelompok ini mencakup usaha perdagangan besar berbagai barang dan perlengkapan rumah tangga lainnya, seperti barang-barang dari kulit, koper, alat-alat pembersih dan sebagainya. Termasuk rekaman suara dan video dalam kaset, CD dan DVD, barang kimia untuk rumah tangga (deterjen, pembersih lantai dan lain-lain), serta alat peraga pendidikan.',NULL,NULL,0),
	(884,'46511','PERDAGANGAN BESAR KOMPUTER DAN PERLENGKAPAN KOMPUTER','Kelompok ini mencakup usaha perdagangan besar komputer dan pelengkapan komputer.',NULL,NULL,0),
	(885,'46512','PERDAGANGAN BESAR PIRANTI LUNAK','Kelompok ini mencakup usaha perdagangan besar piranti lunak.',NULL,NULL,0),
	(886,'46521','PERDAGANGAN BESAR SUKU CADANG ELEKTRONIK','Kelompok ini mencakup usaha perdagangan besar katup dan tabung elektronik, peralatan semi konduktor, mikrochip dan IC dan PCB.',NULL,NULL,0),
	(887,'46522','PERDAGANGAN BESAR DISKET, FLASH DRIVE, PITA AUDIO DAN VIDEO, CD DAN DVD KOSONG','Kelompok ini mencakup usaha perdagangan besar disket, flash drive, pita audio dan pita video kosong, CD dan DVD kosong.',NULL,NULL,0),
	(888,'46523','PERDAGANGAN BESAR PERALATAN TELEKOMUNIKASI','Kelompok ini mencakup usaha perdagangan besar peralatan telekomunikasi, seperti perlengkapan telepon dan komunikasi. Termasuk peralatan penyiaran radio dan televisi.',NULL,NULL,0),
	(889,'46530','PERDAGANGAN BESAR MESIN, PERALATAN DAN PERLENGKAPAN PERTANIAN','Kelompok ini mencakup usaha perdagangan besar mesin, peralatan dan perlengkapan pertanian, seperti : bajak, penyebar pupuk, penanam biji, alat panen, alat penebah, mesin pemerah susu, mesin beternak unggas dan mesin beternak lebah dan traktor yang digunakan dalam pertanian dan kehutanan. Termasuk mesin pemotong rumput.',NULL,NULL,0),
	(890,'46591','PERDAGANGAN BESAR MESIN KANTOR DAN INDUSTRI PENGOLAHAN, SUKU CADANG DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan besar mesin industri dan mesin kantor kecuali komputer, serta perlengkapannya, seperti mesin pengolahan kayu dan logam, macam-macam mesin untuk industri dan untuk keperluan kantor. Termasuk perdagangan besar robot-robot produksi pengolahan, mesin-mesin lain ytdl untuk keperluan industri, dan mesin yang dikendalikan komputer untuk industri tekstil serta mesin jahit dan rajut yang dikendalikan komputer.',NULL,NULL,0),
	(891,'46592','PERDAGANGAN BESAR ALAT TRANSPORTASI LAUT, SUKU CADANG DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan besar macam-macam alat transportasi laut bermotor ataupun tidak bermotor, termasuk usaha perdagangan besar macammacam suku cadang dan perlengkapannya.',NULL,NULL,0),
	(892,'46593','PERDAGANGAN BESAR ALAT TRANSPORTASI DARAT (BUKAN MOBIL, SEPEDA MOTOR, DAN SEJENISNYA), SUKU CADANG DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan besar macam-macam alat transportasi darat, bermotor ataupun tidak bermotor (bukan mobil, sepeda motor dan sejenisnya), termasuk usaha perdagangan besar macam-macam suku cadang dan perlengkapannya.',NULL,NULL,0),
	(893,'46594','PERDAGANGAN BESAR ALAT TRANSPORTASI UDARA, SUKU CADANG DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan besar macam-macam alat transportasi udara, termasuk usaha perdagangan besar macam-macam suku cadang dan perlengkapannya.',NULL,NULL,0),
	(894,'46599','PERDAGANGAN BESAR MESIN, PERALATAN DAN PERLENGKAPAN LAINNYA','Kelompok ini mencakup usaha perdagangan besar mesin dan peralatan serta perlengkapan yang belum diklasifikasikan dalam kelompok 46591 s.d. 46594, seperti mesin penggerak mula, turbin, mesin pembangkit listrik dan mesin untuk keperluan rumah tangga. Termasuk perdagangan besar robot-robot produksi selain untuk pengolahan, mesin-mesin lain ytdl untuk perdagangan dan navigasi serta jasa lainnya, perdagangan besar kabel dan sakelar serta instalasi peralatan lain, perkakas mesin berbagai jenis dan untuk berbagai bahan, perkakas mesin yang dikendalikan komputer dan peralatan dan perlengkapan pengukuran.',NULL,NULL,0),
	(895,'46610','PERDAGANGAN BESAR BAHAN BAKAR PADAT, CAIR DAN GAS DAN PRODUK YBDI','Kelompok ini mencakup usaha perdagangan besar bahan bakar gas, cair, dan padat serta produk sejenisnya, seperti minyak bumi mentah, minyak mentah, bahan bakar diesel, gasoline, bahan bakar oli, kerosin, premium, solar, minyak tanah, batu bara, arang, ampas arang batu, bahan bakar kayu, nafta, bahan bakar nabati (biofuels) dan bahan bakar lainnya termasuk pula bahan bakar gas (LPG, gas butana dan propana, dan lain-lain) dan minyak semir, minyak pelumas dan produk minyak bumi yang telah dimurnikan, serta bahan bakar nuklir.',NULL,NULL,0),
	(896,'46620','PERDAGANGAN BESAR LOGAM DAN BIJIH LOGAM','Kelompok ini mencakup usaha perdagangan besar bijih logam dan logam dasar, seperti bijih besi dan bijih bukan besi dalam bentuk dasar, seperti bijih nikel, bijih tembaga, alumunium, besi, baja dan perdagangan besar produk logam besi dan bukan besi setengah jadi ytdl dan lain-lainnya. Termasuk perdagangan besar emas dan logam mulia lain (perak, platina).',NULL,NULL,0),
	(897,'46631','PERDAGANGAN BESAR BARANG LOGAM UNTUK BAHAN KONSTRUKSI','Kelompok ini mencakup usaha perdagangan besar berbagai macam baja/besi untuk bahan konstruksi seperti baja tulangan, baja profil, pelat baja, dan baja lembaran, pipa besi/baja, kawat tali, kawat nyamuk, paku, mur/baut, engsel, gerendel, kunci, anak kunci, tangki air, menara air, rolling door, awning dan seng lembaran.',NULL,NULL,0),
	(898,'46632','PERDAGANGAN BESAR KACA','Kelompok ini mencakup usaha perdagangan besar kaca lembaran untuk bahan konstruksi, seperti kaca lembaran bening, kaca lembaran buram, kaca lembaran bening berwarna dan kaca lembaran berukir.',NULL,NULL,0),
	(899,'46633','PERDAGANGAN BESAR GENTENG, BATU BATA, UBIN DAN SEJENISNYA DARI TANAH LIAT, KAPUR, SEMEN ATAU KACA','Kelompok ini mencakup usaha perdagangan besar genteng, batu bata dan ubin yang terbuat dari tanah liat, kapur, semen atau kaca untuk bahan konstruksi, seperti genteng pres, genteng kodok, batu bata pres, batu bata berongga, bata tahan api, ubin lantai, ubin dinding, ubin batako, termasuk juga lubang angin, bak mandi, kloset, eternit, pipa irigasi dan buis.',NULL,NULL,0),
	(900,'46634','PERDAGANGAN BESAR SEMEN, KAPUR, PASIR DAN BATU','Kelompok ini mencakup usaha perdagangan besar semen, kapur, pasir, dan batu untuk bahan konstruksi, seperti semen portland putih, semen portland abu-abu, semen posolan kapur, semen portland posolan, kapur tohor, kapur tembok, pasir, kerikil, koral, batu, batu pecahan, batu lempengan, batu pualam dan kubus mosaik.',NULL,NULL,0),
	(901,'46635','PERDAGANGAN BESAR BAHAN KONSTRUKSI DARI PORSELEN','Kelompok ini mencakup usaha perdagangan besar bahan konstruksi dari porselen, seperti kloset, bidet, wastafel, winoir, bak cuci, bak mandi dan ubin dinding.',NULL,NULL,0),
	(902,'46636','PERDAGANGAN BESAR BAHAN KONSTRUKSI DARI KAYU','Kelompok ini mencakup usaha perdagangan besar bahan konstruksi dari kayu, seperti papan, galar, papan reng, papan lis, tiang telepon, tiang listrik, balok bantalan, kusen pintu/jendela, daun pintu/jendela, ubin kayu, atap kayu (sirap), kayu lapis tripleks, kayu lapis interior, teak wood, particle board, chip board, kayu pelapis dan kayu lapis untuk cetak beton.',NULL,NULL,0),
	(903,'46637','PERDAGANGAN BESAR CAT','Kelompok ini mencakup usaha perdagangan besar berbagai macam cat untuk bahan konstruksi, seperti cat dasar, cat logam, cat kayu dan cat tembok. Termasuk juga perdagangan eceran email, dempul dan plamir.',NULL,NULL,0),
	(904,'46638','PERDAGANGAN BESAR BERBAGAI MACAM MATERIAL BANGUNAN','Kelompok ini mencakup usaha perdagangan besar macam-macam material bangunan, seperti semen, pasir, paku, cat dan lain-lain.',NULL,NULL,0),
	(905,'46639','PERDAGANGAN BESAR BAHAN KONSTRUKSI LAINNYA','Kelompok ini mencakup usaha perdagangan besar bahan konstruksi lainnya yang belum tercakup dalam kelompok 46631 s.d. 46638, seperti wallpaper, pipa dan selang dari plastik, formika, plastik lembaran bergelombang, asbes semen rata, asbes semen berlapis dan pipa saluran asbes semen. Termasuk perdagangan besar pemanas air (water heater).',NULL,NULL,0),
	(906,'46641','PERDAGANGAN BESAR MINERAL BUKAN LOGAM','Kelompok ini mencakup usaha perdagangan besar mineral bukan logam seperti intan, korundum, grafit, arsen, pasir kuarsa, fluorspar, kriolit, yodium, brom, klor, belerang, fosfat, halit, asbes, talk, mika, magnesit, yarosit, oker, fluorit, ball clay, zeolit, kaolin, feldspar, bentonit, gipsum, dolomit, kalsit, rijang, pirofilit, kuarsit, zirkon, wolastonit, tawas, batu kuarsa, perlit, garam batu, clay, dan batu gamping untuk semen.',NULL,NULL,0),
	(907,'46642','PERDAGANGAN BESAR MINERAL RADIOAKTIF','Kelompok ini mencakup usaha perdagangan besar mineral radio aktif seperti radium, torium, uranium, monasit, dan bahan galian radioaktif lainnya.',NULL,NULL,0),
	(908,'46643','PERDAGANGAN BESAR ZAT RADIOAKTIF DAN PEMBANGKIT RADIASI PENGION','Kelompok ini mencakup usaha perdagangan besar zat radioaktif dan pembangkit radiasi pengion.',NULL,NULL,0),
	(909,'46651','PERDAGANGAN BESAR BAHAN DAN BARANG KIMIA','Kelompok ini mencakup usaha perdagangan besar bahan dan barang kimia dasar atau kimia industri, seperti tinta printer, minyak esensial, gas industri, perekat kimia, pewarna, resin buatan, metanol, parafin, perasa dan pewangi, soda, garam industri, asam dan sulfur dan lain-lain.',NULL,NULL,0),
	(910,'46652','PERDAGANGAN BESAR PUPUK DAN PRODUK AGROKIMIA','Kelompok ini mencakup usaha perdagangan besar pupuk dan produk agrokimia atau kimia pertanian.',NULL,NULL,0),
	(911,'46653','PERDAGANGAN BESAR BAHAN BERBAHAYA (B2)','Kelompok ini mencakup usaha perdagangan besar bahan berbahaya (B2).',NULL,NULL,0),
	(912,'46654','PERDAGANGAN BESAR BAHAN BERBAHAYA DAN BERACUN (B3)','Kelompok ini mencakup usaha perdagangan besar bahan berbahaya dan beracun (B3).',NULL,NULL,0),
	(913,'46691','PERDAGANGAN BESAR ALAT LABORATORIUM, ALAT FARMASI DAN ALAT KEDOKTERAN UNTUK MANUSIA','Kelompok ini mencakup usaha perdagangan besar alat laboratorium, alat farmasi dan alat kedokteran untuk manusia.',NULL,NULL,0),
	(914,'46692','PERDAGANGAN BESAR ALAT LABORATORIUM, ALAT FARMASI DAN ALAT KEDOKTERAN UNTUK HEWAN','Kelompok ini mencakup usaha perdagangan besar alat laboratorium, alat farmasi dan alat kedokteran untuk hewan yang meliputi kegiatan pemasukan, pengeluaran dan distribusi.',NULL,NULL,0),
	(915,'46693','PERDAGANGAN BESAR KARET DAN PLASTIK DALAM BENTUK DASAR','Kelompok ini mencakup usaha perdagangan besar karet dan bahan plastik dalam bentuk dasar.',NULL,NULL,0),
	(916,'46694','PERDAGANGAN BESAR KERTAS DAN KARTON','Kelompok ini mencakup usaha perdagangan besar kertas dan karton.',NULL,NULL,0),
	(917,'46695','PERDAGANGAN BESAR BARANG DARI KERTAS DAN KARTON','Kelompok ini mencakup usaha perdagangan besar barang dari kertas dan karton.',NULL,NULL,0),
	(918,'46696','PERDAGANGAN BESAR BARANG BEKAS DAN SISA-SISA TAK TERPAKAI (SCRAP)','Kelompok ini mencakup usaha perdagangan besar barang bekas dan sisa-sisa tak terpakai dan potongan logam dan non-logam bahan untuk daur ulang, termasuk pengumpulan, pengurutan, pemisahan, pelepasan barang yang masih berguna misalnya mobil agar mendapatkan bagian yang masih bisa digunakan, pengepakan dan pengepakan kembali, penyimpanan dan pengiriman, tapi tanpa proses perubahan yang nyata. Dimana pembelian dan penjualan barang sisaan masih mempunyai nilai.',NULL,NULL,0),
	(919,'46699','PERDAGANGAN BESAR PRODUK LAINNYA YTDL','Kelompok ini mencakup usaha perdagangan besar produk lainnya yang belum tercakup dalam salah satu kelompok perdagangan besar diatas. Termasuk perdagangan besar serat atau fiber tekstil dan lain-lain, perdagangan besar batu mulia (berlian, intan, safir dan lain-lain).',NULL,NULL,0),
	(920,'46900','PERDAGANGAN BESAR BERBAGAI MACAM BARANG','Kelompok ini mencakup usaha perdagangan besar berbagai macam barang yang tanpa mengkhususkan barang tertentu (tanpa ada kekhususan tertentu) termasuk perkulakan.',NULL,NULL,0),
	(921,'47111','PERDAGANGAN ECERAN BERBAGAI MACAM BARANG YANG UTAMANYA MAKANAN, MINUMAN ATAU TEMBAKAU DI MINIMARKET/SUPERMARKET/HYPERMARKET','Kelompok ini mencakup usaha perdagangan eceran berbagai jenis barang kebutuhan yang utamanya bahan makanan/makanan, minuman atau tembakau dengan harga yang sudah ditentukan serta pembeli mengambil dan membayar sendiri kepada kasir (self service/swalayan). Disamping itu juga dapat menjual beberapa barang bukan makanan seperti perabot rumah tangga, mainan anak-anak, dan pakaian. Misalnya minimarket atau supermarket atau hypermarket.',NULL,NULL,0),
	(922,'47112','PERDAGANGAN ECERAN BERBAGAI MACAM BARANG YANG UTAMANYA MAKANAN, MINUMAN ATAU TEMBAKAU BUKAN DI MINIMARKET/SUPERMARKET/HYPERMARKET (TRADISIONAL)','Kelompok ini mencakup usaha perdagangan eceran berbagai jenis barang kebutuhan yang utamanya bahan makanan/makanan, minuman atau tembakau di dalam bangunan bukan swalayan/minimarket/supermarket/hypermarket. Disamping itu juga dapat menjual beberapa barang bukan makanan seperti pakaian, perabot rumah tangga, dan mainan anak. Misalnya warung atau toko bahan kebutuhan pokok.',NULL,NULL,0),
	(923,'47191','PERDAGANGAN ECERAN BERBAGAI MACAM BARANG YANG UTAMANYA BUKAN MAKANAN, MINUMAN ATAU TEMBAKAU DI TOSERBA (DEPARTMENT STORE)','Kelompok ini mencakup usaha perdagangan eceran berbagai jenis barang yang utamanya bukan makanan, minuman atau tembakau dalam toserba (department store), yang terintegrasi di bawah satu pengelolaan. Pada umumnya barang-barang yang diperdagangkan antara lain pakaian, mebel, perhiasan, mainan anak-anak, alatalat olahraga dan kosmetik.',NULL,NULL,0),
	(924,'47192','PERDAGANGAN ECERAN BERBAGAI MACAM BARANG YANG UTAMANYA BUKAN MAKANAN, MINUMAN ATAU TEMBAKAU (BARANG-BARANG KELONTONG) BUKAN DI TOSERBA (DEPARTMENT STORE)','Kelompok ini mencakup usaha perdagangan eceran berbagai jenis barang yang utamanya bukan makanan, minuman atau tembakau bukan toserba/department store. Pada umumnya barang-barang yang diperdagangkan antara lain pakaian, perabot rumah tangga, perhiasan, mainan anak-anak dan kosmetik, yang terintegrasi di bawah satu pengelolaan. Misalnya toko barang kelontong.',NULL,NULL,0),
	(925,'47211','PERDAGANGAN ECERAN PADI DAN PALAWIJA','Kelompok ini mencakup usaha perdagangan eceran khusus padi dan palawija, di dalam bangunan seperti gabah, jagung, ubi jalar, ubi kayu, talas, kacang kedelai, kacang tanah, kacang hitam dan kacang polong.',NULL,NULL,0),
	(926,'47212','PERDAGANGAN ECERAN BUAH-BUAHAN','Kelompok ini mencakup usaha perdagangan eceran khusus buah-buahan di dalam bangunan, seperti apel, anggur, alpokat, belimbing, duku, durian, jambu, jeruk, mangga, manggis, nanas, pisang, pepaya, rambutan, sawo, salak dan semangka.',NULL,NULL,0),
	(927,'47213','PERDAGANGAN ECERAN SAYURAN','Kelompok ini mencakup usaha perdagangan eceran khusus sayuran di dalam bangunan, seperti bawang merah, bawang putih, kentang, wortel, terong, buncis, mentimun, labu siam, kacang panjang dan kacang merah.',NULL,NULL,0),
	(928,'47214','PERDAGANGAN ECERAN HASIL PETERNAKAN','Kelompok ini mencakup usaha perdagangan eceran khusus hasil peternakan di dalam bangunan, seperti susu dan telur, termasuk pula daging ternak dan unggas.',NULL,NULL,0),
	(929,'47215','PERDAGANGAN ECERAN HASIL PERIKANAN','Kelompok ini mencakup usaha perdagangan eceran khusus hasil perikanan di dalam bangunan, seperti udang segar, ikan segar, cumi-cumi segar, nener (benih bandeng), benur (benih udang), benih ikan, dan rumput laut.',NULL,NULL,0),
	(930,'47216','PERDAGANGAN ECERAN HASIL KEHUTANAN DAN PERBURUAN','Kelompok ini mencakup usaha perdagangan eceran khusus komoditi hasil hutan dan perburuan, seperti kijang, buah kenari, dan bambu muda (rebung).',NULL,NULL,0),
	(931,'47219','PERDAGANGAN ECERAN HASIL PERTANIAN LAINNYA','Kelompok ini mencakup usaha perdagangan eceran khusus komoditi hasil pertanian yang belum tercakup dalam kelompok 47211 s.d. 47216 di dalam bangunan seperti lada, pala, kunyit, kencur, temulawak, lengkuas dan madu.',NULL,NULL,0),
	(932,'47221','PERDAGANGAN ECERAN MINUMAN BERALKOHOL','Kelompok ini mencakup usaha perdagangan eceran khusus minuman beralkohol didalam bangunan yang tidak langsung diminum di tempat, seperti minuman keras (whisky, genever, brandy, gin, arak, rum, sake, tuak), minuman anggur dan minuman yang mengandung malt (bir, ale, stout, temulawak).',NULL,NULL,0),
	(933,'47222','PERDAGANGAN ECERAN MINUMAN TIDAK BERALKOHOL','Kelompok ini mencakup usaha perdagangan eceran khusus minuman tidak beralkohol di dalam bangunan yang tidak langsung diminum di tempat, seperti minuman ringan (limun, air soda, markisa, teh botol, air mineral dan beras kencur). Termasuk perdagangan eceran minuman kopi.',NULL,NULL,0),
	(934,'47230','PERDAGANGAN ECERAN KHUSUS ROKOK DAN TEMBAKAU DI TOKO','Kelompok ini mencakup usaha perdagangan eceran khusus rokok dan atau tembakau di dalam bangunan seperti rokok kretek, rokok putih, rokok cerutu, rokok kelembak, tembakau krosok, tembakau susur dan tembakau pipa/papier.',NULL,NULL,0),
	(935,'47241','PERDAGANGAN ECERAN BERAS','Kelompok ini mencakup usaha perdagangan eceran khusus berbagai jenis beras di dalam bangunan, seperti beras cianjur, beras cisadane, beras saigon dan beras ketan.',NULL,NULL,0),
	(936,'47242','PERDAGANGAN ECERAN ROTI, KUE KERING, SERTA KUE BASAH DAN SEJENISNYA','Kelompok ini mencakup usaha perdagangan eceran khusus berbagai jenis roti, kue kering dan kue basah di dalam bangunan, seperti roti manis, roti tawar, bolu, cake/tart, biskuit, wafer, kue semprong dan cookies.',NULL,NULL,0),
	(937,'47243','PERDAGANGAN ECERAN KOPI, GULA PASIR DAN GULA MERAH','Kelompok ini mencakup usaha perdagangan eceran khusus kopi,gula pasir atau gula merah di dalam bangunan.',NULL,NULL,0),
	(938,'47244','PERDAGANGAN ECERAN TAHU, TEMPE, TAUCO DAN ONCOM','Kelompok ini mencakup usaha perdagangan eceran khusus tahu, tempe, tauco dan oncom di dalam bangunan.',NULL,NULL,0),
	(939,'47245','PERDAGANGAN ECERAN DAGING DAN IKAN OLAHAN','Kelompok ini mencakup usaha perdagangan eceran khusus berbagai jenis produk daging olahan dan ikan, udang, kerang yang diasinkan atau dikeringkan di dalam bangunan, seperti sosis, bakso, abon, ikan teri, cucut, selar, kerapu, udang, rebon, petek, gabus, sepat, cumi-cumi, kepah, remis, dan kerang.',NULL,NULL,0),
	(940,'47249','PERDAGANGAN ECERAN MAKANAN LAINNYA','Kelompok ini mencakup usaha perdagangan eceran khusus komoditi makanan hasil industri yang belum tercakup dalam kelompok 47241 s.d 47245 di dalam bangunan seperti asinan buah-buahan dan sayuran, buah-buahan dan sayuran yang diawetkan, kerupuk dan emping/ceriping.',NULL,NULL,0),
	(941,'47301','PERDAGANGAN ECERAN BAHAN BAKAR MINYAK, BAHAN BAKAR GAS (BBG), DAN LIQUEFIED PETROLEUM GAS (LPG) DI SARANA PENGISIAN BAHAN BAKAR TRANSPORTASI DARAT, LAUT, DAN UDARA','Kelompok ini mencakup usaha perdagangan eceran bahan bakar minyak, bahan bakar gas, LPG, atau jenis bahan bakar lain di sarana pengisian bahan bakar untuk transportasi darat, laut, dan udara (seperti SPBU, SPBG dsb) untuk kendaraan bermotor seperti mobil dan sepeda motor (misalnya bensin, solar, BBG, dan LPG), termasuk pula bahan bakar untuk speed boat dan genset. Biasanya kegiatan ini dikombinasikan dengan penjualan bahan-bahan pelumas, cooling products, bahan-bahan pembersih dan barang-barang lain untuk keperluan mobil dan sepeda motor. Perdagangan besar bahan bakar dimasukkan dalam kelompok 46610. Perdagangan eceran LPG dan bahan bakar untuk keperluan memasak atau pemanas dimasukkan dalam kelompok 47772.',NULL,NULL,0),
	(942,'47302','PERDAGANGAN ECERAN BAHAN BAKAR MINYAK, BAHAN BAKAR GAS (BBG), DAN LIQUEFIED PETROLEUM GAS (LPG) SELAIN DI SARANA PENGISIAN BAHAN BAKAR TRANSPORTASI DARAT, LAUT, DAN UDARA','Kelompok ini mencakup perdagangan eceran bahan bakar minyak, bahan bakar gas, LPG, atau jenis bahan bakar lain selain di sarana pengisian bahan bakar untuk transportasi darat, laut, dan udara (seperti agen BBM, agen LPG dsb). Perdagangan eceran bahan bakar untuk mobil dan sepeda motor di SPBU dimasukkan dalam kelompok 47301.',NULL,NULL,0),
	(943,'47303','PERDAGANGAN ECERAN MINYAK PELUMAS DI TOKO','Kelompok ini mencakup usaha perdagangan eceran minyak pelumas di toko. Termasuk perdagangan eceran produk pendingin untuk mobil.',NULL,NULL,0),
	(944,'47411','PERDAGANGAN ECERAN KOMPUTER DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan eceran khusus macam-macam komputer, peralatan dan perlengkapannya.',NULL,NULL,0),
	(945,'47412','PERDAGANGAN ECERAN PERALATAN VIDEO GAME DAN SEJENISNYA','Kelompok ini mencakup perdagangan eceran peralatan video game.',NULL,NULL,0),
	(946,'47413','PERDAGANGAN ECERAN PIRANTI LUNAK (SOFTWARE)','Kelompok ini mencakup usaha perdagangan eceran khusus piranti lunak (software), seperti bermacam piranti lunak, termasuk piranti lunak untuk video game.',NULL,NULL,0),
	(947,'47414','PERDAGANGAN ECERAN ALAT TELEKOMUNIKASI','Kelompok ini mencakup usaha perdagangan eceran alat telekomunikasi, seperti handphone, pesawat telepon dan perlengkapannya lainnya.',NULL,NULL,0),
	(948,'47415','PERDAGANGAN ECERAN MESIN KANTOR','Kelompok ini mencakup usaha perdagangan eceran khusus mesin kantor selain komputer, seperti bermacam mesin tik, mesin hitung, cash register dan sejenisnya.',NULL,NULL,0),
	(949,'47420','PERDAGANGAN ECERAN KHUSUS PERALATAN AUDIO DAN VIDEO DI TOKO','Kelompok ini mencakup usaha perdagangan eceran khusus peralatan audio dan video, seperti radio, televisi, video, tape recorder, audio amplifier dan cassete recorder. Termasuk peralatan stereo dan peralatan perekam dan pemutar CD dan DVD.',NULL,NULL,0),
	(950,'47511','PERDAGANGAN ECERAN TEKSTIL','Kelompok ini mencakup usaha perdagangan eceran khusus tekstil, seperti macammacam kain terbuat dari serat alam, sintetis, maupun campuran, kain tenun (kain sarung katun, kain sarung polister, kain suiting sutera, kain suiting serat campuran), kain cetak (kain cetak kapas, kain cetak polyamida, kain kedap air), kain batik (kain batik tulis, kain batik cap, kain batik kombinasi tulis dan cap) dan kain rajut (kain rajut wol, kain rajut rayon, kain rajut wol/kapas). Termasuk perdagangan eceran bahan dasar untuk pembuatan permadani, permadani hiasan dinding dan bordiran atau sulaman.',NULL,NULL,0),
	(951,'47512','PERDAGANGAN ECERAN PERLENGKAPAN RUMAH TANGGA DARI TEKSTIL','Kelompok ini mencakup usaha perdagangan eceran khusus perlengkapan rumah tangga dari tekstil, seperti taplak meja, seprei, sarung bantal, kelambu, kain kasur, kain bantal, kain pel, linen rumah tangga dan lain-lain.',NULL,NULL,0),
	(952,'47513','PERDAGANGAN ECERAN PERLENGKAPAN JAHIT MENJAHIT','Kelompok ini mencakup usaha perdagangan eceran khusus perlengkapan jahit menjahit, seperti benang dan jarum jahit.',NULL,NULL,0),
	(953,'47521','PERDAGANGAN ECERAN BARANG LOGAM UNTUK BAHAN KONSTRUKSI','Kelompok ini mencakup usaha perdagangan eceran khusus barang logam untuk bahan konstruksi seperti baja tulangan, baja profil, pelat baja, dan baja lembaran, pipa besi/baja, kawat tali, kawat nyamuk, paku, mur/baut, engsel, gerendel, kunci, anak kunci, tangki air, menara air, rolling door, awning dan seng lembaran.',NULL,NULL,0),
	(954,'47522','PERDAGANGAN ECERAN KACA','Kelompok ini mencakup usaha perdagangan eceran khusus kaca lembaran untuk bahan konstruksi, seperti kaca lembaran bening, kaca lembaran buram, kaca lembaran bening berwarna dan kaca lembaran berukir.',NULL,NULL,0),
	(955,'47523','PERDAGANGAN ECERAN GENTENG, BATU BATA, UBIN DAN SEJENISNYA DARI TANAH LIAT, KAPUR, SEMEN ATAU KACA','Kelompok ini mencakup usaha perdagangan eceran khusus genteng, batu bata dan ubin yang terbuat dari tanah liat, kapur, semen, atau gelas untuk bahan konstruksi, seperti genteng pres, genteng kodok, batu bata pres, batu bata berongga, bata tahan api, ubin lantai, ubin dinding, ubin batako, termasuk juga lubang angin, bak mandi, kloset, eternit, pipa irigasi dan buis.',NULL,NULL,0),
	(956,'47524','PERDAGANGAN ECERAN SEMEN, KAPUR, PASIR DAN BATU','Kelompok ini mencakup usaha perdagangan eceran khusus semen, kapur, pasir dan batu untuk bahan konstruksi, seperti semen portland putih, semen portland abu-abu, semen posolan kapur, semen portland posolan, kapur tohor, kapur tembok, pasir, kerikil, koral, batu, batu pecahan, batu lempengan, batu pualam dan kubus mosaik.',NULL,NULL,0),
	(957,'47525','PERDAGANGAN ECERAN BAHAN KONSTRUKSI DARI PORSELEN','Kelompok ini mencakup usaha perdagangan eceran khusus bahan konstruksi dari porselen, seperti kloset, bidet, wastafel, winoir, bak cuci, bak mandi dan ubin dinding.',NULL,NULL,0),
	(958,'47526','PERDAGANGAN ECERAN BAHAN KONSTRUKSI DARI KAYU','Kelompok ini mencakup usaha perdagangan eceran khusus bahan konstruksi dari kayu, seperti papan, galar, papan reng, papan lis, tiang telepon, tiang listrik, balok bantalan, kusen pintu/jendela, daun pintu/jendela, ubin kayu, atap kayu (sirap), kayu lapis tripleks, kayu lapis interior, teak wood, particle board, chip board, kayu pelapis dan kayu lapis untuk cetak beton.',NULL,NULL,0),
	(959,'47527','PERDAGANGAN ECERAN CAT, PERNIS DAN LAK','Kelompok ini mencakup usaha perdagangan eceran khusus berbagai macam cat untuk bahan konstruksi, seperti cat dasar, cat logam, cat kayu dan cat tembok. Termasuk juga perdagangan eceran email, dempul, plamir dan pernis dan lak.',NULL,NULL,0),
	(960,'47528','PERDAGANGAN ECERAN BERBAGAI MACAM MATERIAL BANGUNAN','Kelompok ini mencakup usaha perdagangan eceran khusus berbagai macam material bangunan, seperti semen, pasir , paku, cat dan lain-lain.',NULL,NULL,0),
	(961,'47529','PERDAGANGAN ECERAN BAHAN DAN BARANG KONSTRUKSI LAINNYA','Kelompok ini mencakup usaha perdagangan eceran khusus bahan dan barang konstruksi lainnya yang belum tercakup dalam kelompok 47521 s.d. 47528, seperti pipa dan selang dari plastik, formika, plastik lembaran bergelombang, asbes semen rata, asbes semen berlapis dan pipa saluran asbes semen. Termasuk perdagangan eceran pemotong rumput dan alat mandi uap.',NULL,NULL,0),
	(962,'47530','PERDAGANGAN ECERAN KHUSUS KARPET, PERMADANI DAN PENUTUP DINDING DAN LANTAI DI TOKO','Kelompok ini mencakup usaha perdagangan eceran khusus karpet, permadani dan penutup dinding dan lantai, termasuk keset kamar mandi, sajadah, karpet, tirai, gorden dan lain-lain.',NULL,NULL,0),
	(963,'47591','PERDAGANGAN ECERAN FURNITUR','Kelompok ini mencakup usaha perdagangan eceran khusus furniture, seperti meja, kursi, lemari, tempat tidur, rak buku, rak sepatu dan bufet. Termasuk juga usaha perdagangan eceran khusus kasur dan bantal/guling.',NULL,NULL,0),
	(964,'47592','PERDAGANGAN ECERAN PERALATAN LISTRIK RUMAH TANGGA DAN PERALATAN PENERANGAN DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan eceran khusus peralatan listrik rumah tangga dan perlengkapan penerangan, seperti mesin cuci, lemari es, kipas angin, alat pengisap debu, alat penggosok lantai, mixer, seterika listrik, blender, lampu pijar, lampu neon, starter, ballast, reflektor, kabel, sakelar, stop kontak, fiting dan sekering.',NULL,NULL,0),
	(965,'47593','PERDAGANGAN ECERAN BARANG PECAH BELAH DAN PERLENGKAPAN DAPUR DARI PLASTIK','Kelompok ini mencakup usaha perdagangan eceran khusus barang pecah belah dan perlengkapan dapur yang terbuat dari plastik, seperti piring, pisin, mangkok, cangkir, teko, sendok, garpu, rantang, stoples, botol susu bayi, panci, baki, ember, termos dan jerigen.',NULL,NULL,0),
	(966,'47594','PERDAGANGAN ECERAN BARANG PECAH BELAH DAN PERLENGKAPAN DAPUR DARI BATU ATAU TANAH LIAT','Kelompok ini mencakup usaha perdagangan eceran khusus barang pecah belah dan perlengkapan dapur yang terbuat dari batu atau tanah liat, seperti piring, mangkok, cangkir, teko, kendi, periuk, cobek, tempayan, lumpang, asbak dan uleg-uleg.',NULL,NULL,0),
	(967,'47595','PERDAGANGAN ECERAN BARANG PECAH BELAH DAN PERLENGKAPAN DAPUR DARI KAYU, BAMBU ATAU ROTAN','Kelompok ini mencakup usaha perdagangan eceran khusus barang pecah belah dan perlengkapan dapur yang terbuat dari kayu, bambu atau rotan, seperti rak bambu, alu, lesung, parutan kelapa, talenan, papan gilesan, centong, bakul, tampah, kukusan, kipas, tudung saji, tusukan sate dan gilingan daging.',NULL,NULL,0),
	(968,'47596','PERDAGANGAN ECERAN BARANG PECAH BELAH DAN PERLENGKAPAN DAPUR BUKAN DARI PLASTIK, BATU, TANAH LIAT, KAYU, BAMBU ATAU ROTAN','Kelompok ini mencakup usaha perdagangan eceran khusus barang pecah belah dan perlengkapan dapur yang terbuat bukan dari plastik, batu, tanah liat, kayu, bambu atau rotan, seperti piring, pisau, mangkok, cangkir, teko, sendok, garpu, rantang, stoples, botol susu bayi, panci, baki, termos, kompor gas dan kompor minyak tanah. Baik yang terbuat dari kaca atau dari logam atau bahan lainnya.',NULL,NULL,0),
	(969,'47597','PERDAGANGAN ECERAN ALAT MUSIK','Kelompok ini mencakup usaha perdagangan eceran khusus alat musik, baik alat musik tradisional maupun alat musik modern, seperti kecapi, seruling bambu, calung, angklung, kulintang, gamelan, set, rebab, rebana, tifa, sasando, seruling (flute), saksophone, harmonika, trombone, gitar, mandolin, ukulele, harpa, bass, gambus, biola, cello, piano/organ, drum set dan garpu tala.',NULL,NULL,0),
	(970,'47599','PERDAGANGAN ECERAN PERALATAN DAN PERLENGKAPAN RUMAH TANGGA LAINNYA YTDL','Kelompok ini mencakup usaha perdagangan eceran khusus peralatan dan perlengkapan rumah tangga lainnya dalam subgolongan 4759 yang tidak diklasifikasikan di tempat lain.',NULL,NULL,0),
	(971,'47611','PERDAGANGAN ECERAN ALAT TULIS MENULIS DAN GAMBAR','Kelompok ini mencakup usaha perdagangan eceran khusus alat tulis-menulis dan gambar, seperti pensil, pulpen, spidol, balpoin, sign pen, pensil mekanik, jangka, kuas gambar, rapido, crayon dan pastel, papan tulis, meja gambar, white board, alat-alat sablon, pita mesin tulis, cat air, cat minyak, karet penghapus, kayu penghapus, tip-ex, tinta, pengasah pensil, penggaris dan kapur tulis.',NULL,NULL,0),
	(972,'47612','PERDAGANGAN ECERAN HASIL PENCETAKAN DAN PENERBITAN','Kelompok ini mencakup usaha perdagangan eceran khusus hasil pencetakan dan penerbitan, seperti faktur, nota, kuitansi, kartu nama, etiket, amplop, agenda, buku alamat, kartu ucapan, kartu pos, perangko, materai, album, buku tulis, buku gambar, kertas bergaris, kertas grafik, atlas, huruf braile, surat kabar, majalah, buletin, kamus, buku ilmu pengetahuan dan buku bergambar.',NULL,NULL,0),
	(973,'47620','PERDAGANGAN ECERAN KHUSUS REKAMAN MUSIK DAN VIDEO DI TOKO','Kelompok ini mencakup usaha perdagangan eceran khusus rekaman musik dan video, seperti audio tape, CD dan kaset dan video tape dan DVD. Termasuk perdagangan eceran kaset dan CD/DVD kosong.',NULL,NULL,0),
	(974,'47630','PERDAGANGAN ECERAN KHUSUS PERALATAN OLAHRAGA DI TOKO','Kelompok ini mencakup usaha perdagangan eceran khusus peralatan olahraga, seperti berbagai macam bola, raket, jaring/net, stik, bat, peralatan panahan, peralatan pancing, peralatan anggar, peralatan terjun payung, sepatu roda/skate board, sarung tinju, halter, sepeda olahraga, perlengkapan catur, meja biliar, meja pingpong, perlengkapan golf, alat pengaman olahraga, matras, spring board, scoring board, dan ring tinju. Termasuk perdagangan eceran peralatan untuk kemah, perahu dan sepeda standard, sepeda balap dan sepeda mini.',NULL,NULL,0),
	(975,'47640','PERDAGANGAN ECERAN KHUSUS ALAT PERMAINAN DAN MAINAN ANAK-ANAK DI TOKO','Kelompok ini mencakup usaha perdagangan eceran khusus alat permainan dan mainan anak-anak, seperti boneka, kelereng, bekel, congklak, scrable, karambol, mainan yang berupa alat musik, mobil-mobilan, mainan berupa senjata, mainan berupa alat memasak dan mainan berupa perabotan rumah tangga yang terbuat dari berbagai bahan.',NULL,NULL,0),
	(976,'47650','PERDAGANGAN ECERAN KERTAS, KERTAS KARTON DAN BARANG DARI KERTAS/KARTON','Kelompok ini mencakup usaha perdagangan eceran khusus kertas, karton dan barang dari kertas/karton, seperti kertas HVS, kertas doorslag, kertas kraft, kertas tipis, kertas kalkir, kertas berwarna, karton manila, karton buffalo skin, karton serat (fiber board), kertas pembungkus (wrapping), karton kemasan untuk makanan/minuman, kantong kertas, kertas/karton berlapis, kertas surat (stationary), stensil sheet, kertas karbon dan kertas duplikator.',NULL,NULL,0),
	(977,'47711','PERDAGANGAN ECERAN PAKAIAN','Kelompok ini mencakup usaha perdagangan eceran khusus pakaian, baik terbuat dari tekstil, kulit, maupun kulit buatan, seperti kemeja, celana, jas, mantel, jaket, piyama, kebaya, blus, rok, daster, singlet, kutang/BH, gaun, rok dalam, baju bayi, pakaian tari, pakaian adat, mukena dan jubah.',NULL,NULL,0),
	(978,'47712','PERDAGANGAN ECERAN SEPATU, SANDAL DAN ALAS KAKI LAINNYA','Kelompok ini mencakup usaha perdagangan eceran khusus sepatu, sandal dan alas kaki lainnya baik terbuat dari kulit, kulit buatan, plastik, karet, kain maupun kayu, seperti sepatu laki-laki dewasa, sepatu perempuan dewasa, sepatu anak, sepatu olahraga, sepatu sandal, sandal, selop dan sepatu kesehatan.',NULL,NULL,0),
	(979,'47713','PERDAGANGAN ECERAN PELENGKAP PAKAIAN','Kelompok ini mencakup usaha perdagangan eceran khusus pelengkap pakaian, seperti selendang, kerudung, sapu tangan, ikat kepala, blangkon, peci, topi, dasi, ikat pinggang, cadar, sarung tangan, kaos kaki, handuk dan selimut. Termasuk juga perdagangan eceran kancing baju, ritsleting dan lainnya.',NULL,NULL,0),
	(980,'47714','PERDAGANGAN ECERAN TAS, DOMPET, KOPER, RANSEL DAN SEJENISNYA','Kelompok ini mencakup usaha perdagangan eceran khusus tas, dompet, koper, ransel dan sejenisnya baik terbuat dari kulit, kulit buatan, tekstil, plastik ataupun karet, seperti tas tangan, tas belanja, tas sekolah, tas surat, tas olahraga, dompet, kotak rias, sarung pedang/pisau, tempat kamera, tempat kaca mata dan kotak pensil. Termasuk perdagangan eceran payung.',NULL,NULL,0),
	(981,'47721','PERDAGANGAN ECERAN BARANG DAN OBAT FARMASI UNTUK MANUSIA DI APOTIK','Kelompok ini mencakup usaha perdagangan eceran khusus barang farmasi dan obatobatan untuk manusia yang berbentuk jadi (sediaan) di apotik, misalnya dalam bentuk tablet, kapsul, salep, bubuk, larutan, larutan parenteral dan suspensi, seperti obat-obat untuk penyakit kulit, mata, gigi, telinga, saluran pernapasan, saluran pencernaan, darah tinggi, kelainan hormon dan vitamin-vitamin serta suplemen kesehatan, termasuk juga barang keperluan kesehatan dari karet, antara lain kondom, alat sedot susu ibu, dot susu, kantong darah, sarung tangan untuk pembedahan, pipet karet, alat keluarga berencana dan sumbat karet untuk botol kecil (vial) farmasi.',NULL,NULL,0),
	(982,'47722','PERDAGANGAN ECERAN BARANG DAN OBAT FARMASI UNTUK MANUSIA BUKAN DI APOTIK','Kelompok ini mencakup usaha perdagangan eceran khusus barang farmasi dan obatobatan untuk manusia yang berbentuk jadi (sediaan) bukan apotik, misalnya dalam bentuk tablet, kapsul, salep, larutan, larutan parenteral dan suspensi, seperti obatobatan untuk penyakit kulit, mata, gigi, telinga, saluran pernapasan, saluran pencernaan, darah tinggi, kelainan hormon dan vitamin-vitamin serta suplemen kesehatan. Contohnya adalah toko obat.',NULL,NULL,0),
	(983,'47723','PERDAGANGAN ECERAN OBAT TRADISIONAL UNTUK MANUSIA','Kelompok ini mencakup usaha perdagangan eceran khusus berbagai macam jamu (obat tradisional) untuk manusia yang bahannya berasal dari tumbuh-tumbuhan, hewan atau mineral misalnya yang berbentuk pil, kapsul, bubuk dan bentuk cair di dalam bangunan.',NULL,NULL,0),
	(984,'47724','PERDAGANGAN ECERAN KOSMETIK UNTUK MANUSIA','Kelompok ini mencakup usaha perdagangan eceran khusus barang-barang kosmetik untuk manusia, seperti kosmetik untuk tata rias muka (eye shadow, maskara, krim wajah, lipstik, lipliner); preparat wangi-wangian (cologne, toilet water, parfum), preparat rambut (sampo, tonik rambut, minyak rambut); preparat kuku (base coat, nail polish, nail cream, cuticle remover); preparat perawat kulit (baby oil, cleansing lotion, masker, krim kaki); preparat untuk kebersihan badan (deodoran semprot, deodoran krim, douches); preparat cukur (sabun cukur, shaving cream); kosmetik tradisional (bedak, mangir, lulur); kosmetik lainnya antara lain bedak badan, kapas kecantikan dan baby powder. Contohnya toko kosmetik.',NULL,NULL,0),
	(985,'47725','PERDAGANGAN ECERAN ALAT LABORATORIUM, ALAT FARMASI DAN ALAT KESEHATAN UNTUK MANUSIA','Kelompok ini mencakup usaha perdagangan eceran khusus alat laboratorium, alat farmasi dan alat kesehatan untuk manusia, antara lain berbagai macam alat laboratorium dari gelas (tabung uji, tabung ukur, kaca sorong mikroskop, cuvet, botol serum/infus); alat laboratorium dari porselen (tabung kimia, piring penapis, lumpang dan alu, cawan); alat dan perlengkapan profesi kedokteran (instrumen dan pesawat bedah, instrumen dan pesawat perawatan gigi, aparat elektro medis, termometer, pengukuran tekanan darah).',NULL,NULL,0),
	(986,'47726','PERDAGANGAN ECERAN BARANG DAN OBAT FARMASI UNTUK HEWAN DI APOTIK DAN BUKAN DI APOTIK','Kelompok ini mencakup usaha perdagangan eceran khusus barang dan obat farmasi untuk hewan seperti obat-obatan yang berbentuk jadi (sediaan), misalnya dalam serbuk, tablet, kapsul, salep, bubuk, larutan, suspensi, aerosol, dan lainnya.',NULL,NULL,0),
	(987,'47727','PERDAGANGAN ECERAN OBAT TRADISIONAL UNTUK HEWAN','Kelompok ini mencakup usaha perdagangan eceran khusus berbagai macam obat tradisional atau obat alami untuk hewan.',NULL,NULL,0),
	(988,'47728','PERDAGANGAN ECERAN KOSMETIK UNTUK HEWAN','Kelompok ini mencakup usaha perdagangan eceran kosmetik untuk hewan, seperti parfum, shampo, sabun, bedak, krim atau lotion, dan lainnya.',NULL,NULL,0),
	(989,'47729','PERDAGANGAN ECERAN KHUSUS BARANG DAN OBAT FARMASI, ALAT KEDOKTERAN, PARFUM DAN KOSMETIK LAINNYA','Kelompok ini mencakup usaha perdagangan eceran khusus lainnya yang belum tercakup dalam kelompok 47721 s.d. 47728, seperti bahan obat farmasi dan bahan baku obat tradisional (simplisia) untuk manusia dan hewan; serta alat laboratorium, alat farmasi, dan alat kesehatan untuk hewan antara lain berbagai macam alat laboratorium dari gelas (tabung uji, tabung ukur, kaca sorong mikroskop, cuvet, botol serum/infus); alat laboratorium dari porselen (tabung kimia, piring penapis, lumpang dan alu, cawan); alat dan perlengkapan profesi kedokteran hewan seperti (instrumen dan pesawat bedah, instrumen dan pesawat perawatan gigi, aparat elektro medis, termometer, pengukuran tekanan darah, dan lainnya), alat kesehatan hewan, dan alatalat diagnosa medis, dan lainnya.',NULL,NULL,0),
	(990,'47731','PERDAGANGAN ECERAN ALAT FOTOGRAFI DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan eceran khusus alat fotografi dan perlengkapannya, seperti kamera foto, kamera sinematografi, proyektor sinematografi, pesawat rekam suara, pesawat reproduksi suara proyektor gambar, over head projector, aparat cahaya kilat fotografi, frame kamera, camera bodies, perlengkapan proyektor gambar dan cassete film transfer.',NULL,NULL,0),
	(991,'47732','PERDAGANGAN ECERAN ALAT OPTIK DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan eceran khusus alat optik dan perlengkapannya, seperti kaca mata pengelas, teropong monokuler, teropong binokuler, kaca pembesar, kaca pengintip, strereoskop dan mikroskop.',NULL,NULL,0),
	(992,'47733','PERDAGANGAN ECERAN KACA MATA','Kelompok ini mencakup usaha perdagangan eceran khusus berbagai macam kaca mata, seperti kaca mata pembantu penglihatan, kaca mata peredam sinar matahari/cahaya, lensa kontak (contact lens, soft lens) dan frame kaca mata.',NULL,NULL,0),
	(993,'47734','PERDAGANGAN ECERAN JAM','Kelompok ini mencakup usaha perdagangan eceran khusus berbagai jam, seperti arloji tangan, arloji saku, jam dinding, jam beker, lonceng dan alat ukur waktu lainnya, termasuk perdagangan eceran bagian dari arloji dan jam.',NULL,NULL,0),
	(994,'47735','PERDAGANGAN ECERAN BARANG PERHIASAN','Kelompok ini mencakup usaha perdagangan eceran khusus barang perhiasan baik terbuat dari batu mulia, berlian, intan, batu aji, serbuk dan bubuk intan, batu permata, batu permata tiruan, logam mulia ataupun bukan logam mulia, seperti cincin, kalung, gelang, giwang (anting-anting), tusuk konde peniti, bross, ikat pinggang dan kancing dari logam mulia (platina, emas dan perak).',NULL,NULL,0),
	(995,'47736','PERDAGANGAN ECERAN PERLENGKAPAN PENGENDARA KENDARAAN BERMOTOR','Kelompok ini mencakup usaha perdagangan eceran perlengkapan pengendara kendaraan bermotor, seperti helm, jaket, jas hujan, sarung tangan, masker dan lainlainnya.',NULL,NULL,0),
	(996,'47737','PERDAGANGAN ECERAN PEMBUNGKUS DARI PLASTIK','Golongan ini mencakup perdagangan eceran barang pembungkus dari plastik, seperti plastik kiloan, plastik sampah, kantong plastik dan barang pembungkus dari plastik lainnya.',NULL,NULL,0),
	(997,'47739','PERDAGANGAN ECERAN KHUSUS BARANG BARU LAINNYA YTDL','Kelompok ini mencakup usaha perdagangan eceran khusus barang baru lainnya yang tidak diklasifikasikan di tempat lain, seperti kegiatan perdagangan eceran bahan pembersih, senjata dan amunisi, perangko dan uang logam dan produk bukan makanan ytdl.',NULL,NULL,0),
	(998,'47741','PERDAGANGAN ECERAN BARANG BEKAS PERLENGKAPAN RUMAH TANGGA','Kelompok ini mencakup usaha perdagangan eceran barang bekas perlengkapan rumah tangga, seperti meja bekas, kursi bekas, lemari bekas, tempat tidur bekas, bufet bekas dan perangkat untuk makan dan minum bekas. Perdagangan eceran mobil dan sepeda motor bekas dimasukkan dalam kelompok 45104 dan 45404.',NULL,NULL,0),
	(999,'47742','PERDAGANGAN ECERAN PAKAIAN, ALAS KAKI DAN PELENGKAP PAKAIAN BEKAS','Kelompok ini mencakup usaha perdagangan eceran pakaian, alas kaki dan pelengkap pakaian bekas, seperti baju bekas, celana bekas, mantel bekas, sepatu bekas, selendang dan topi bekas.',NULL,NULL,0),
	(1000,'47743','PERDAGANGAN ECERAN BARANG PERLENGKAPAN PRIBADI BEKAS','Kelompok ini mencakup usaha perdagangan eceran barang perlengkapan pribadi bekas, seperti jam tangan bekas, jam dinding bekas dan barang perhiasan bekas.',NULL,NULL,0),
	(1001,'47744','PERDAGANGAN ECERAN BARANG LISTRIK DAN ELEKTRONIK BEKAS','Kelompok ini mencakup usaha perdagangan eceran barang listrik dan elektronik bekas, seperti radio bekas, tape recorder bekas, televisi bekas, mesin cuci bekas, seterika listrik bekas dan pengering/pengeriting rambut bekas.',NULL,NULL,0),
	(1002,'47745','PERDAGANGAN ECERAN BAHAN KONSTRUKSI DAN SANITASI BEKAS','Kelompok ini mencakup usaha perdagangan eceran bahan konstruksi dan sanitasi bekas, seperti wastafel bekas, kloset bekas dan bak air bekas.',NULL,NULL,0),
	(1003,'47746','PERDAGANGAN ECERAN BARANG ANTIK','Kelompok ini mencakup usaha perdagangan eceran barang-barang antik, seperti guci bekas, bokor bekas, lampu gantung bekas dan meja/kursi marmer bekas.',NULL,NULL,0),
	(1004,'47749','PERDAGANGAN ECERAN BARANG BEKAS LAINNYA','Kelompok ini mencakup usaha perdagangan eceran barang bekas lainnya yang belum tercakup dalam kelompok 47741 s.d. 47746.',NULL,NULL,0),
	(1005,'47751','PERDAGANGAN ECERAN HEWAN PIARAAN (PET ANIMALS)','Kelompok ini mencakup usaha perdagangan eceran hewan piaraan, seperti kucing, anjing, ular, kelinci, biawak, dan lain-lain, misalnya pet shop.',NULL,NULL,0),
	(1006,'47752','PERDAGANGAN ECERAN HEWAN TERNAK','Kelompok ini mencakup usaha perdagangan eceran hewan ternak, seperti sapi, kambing, dan unggas.',NULL,NULL,0),
	(1007,'47753','PERDAGANGAN ECERAN IKAN HIAS','Kelompok ini mencakup usaha perdagangan eceran benih ikan hias dan ikan hias. Perdagangan ikan olahan dari perikanan masuk di kelompok 47245.',NULL,NULL,0),
	(1008,'47754','PERDAGANGAN ECERAN PAKAN TERNAK/UNGGAS/IKAN DAN HEWAN PIARAAN','Kelompok ini mencakup usaha perdagangan eceran khusus pakan ternak/unggas/ikan dan makanan hewan piaraan di dalam bangunan, seperti ransum pakan ternak/unggas/ikan, konsentrat pakan ternak/unggas/ikan, tepung tulang, tepung darah dan tepung kerang.',NULL,NULL,0),
	(1009,'47761','PERDAGANGAN ECERAN BUNGA POTONG/FLORIST','Kelompok ini mencakup usaha perdagangan eceran bunga potong/florist.',NULL,NULL,0),
	(1010,'47762','PERDAGANGAN ECERAN TANAMAN DAN BIBIT TANAMAN','Kelompok ini mencakup usaha perdagangan eceran khusus tanaman dan biji benih/bibit tanaman. Termasuk perdagangan eceran tanaman obat dan tanaman hias, seperti anggrek, mawar, melati, sedap malam dan bibit tanaman hias/obat.',NULL,NULL,0),
	(1011,'47763','PERDAGANGAN ECERAN PUPUK DAN PEMBERANTAS HAMA','Kelompok ini mencakup usaha perdagangan eceran khusus berbagai macam pupuk dan pemberantas hama, seperti pupuk buatan tunggal (urea, ZA, TSP, DSP), pupuk buatan majemuk dan campuran (mono amonium fosfat, diamonium fosfat, nitrogen fosfat kalium), pupuk alam (pupuk kompos, pupuk dolomit, pupuk kapur), insektisida, fungisida, rodentisida, herbisida, nematisida dan akarisida.',NULL,NULL,0),
	(1012,'47764','PERDAGANGAN ECERAN PERLENGKAPAN DAN MEDIA TANAMAN HIAS','Kelompok ini mencakup usaha perdagangan eceran perlengkapan tanaman hias, seperti pot, media tanam, dan lainnya.',NULL,NULL,0),
	(1013,'47771','PERDAGANGAN ECERAN MINYAK TANAH','Kelompok ini mencakup usaha perdagangan eceran khusus minyak tanah.',NULL,NULL,0),
	(1014,'47772','PERDAGANGAN ECERAN GAS ELPIJI','Kelompok ini mencakup usaha perdagangan eceran khusus gas elpiji.',NULL,NULL,0),
	(1015,'47773','PERDAGANGAN ECERAN BAHAN KIMIA','Kelompok ini mencakup usaha perdagangan eceran khusus bahan kimia di dalam bangunan, seperti soda kostik, soda abu, kalium hidroksida, amoniak, argon, bahan pewarna, bahan pengawet, bahan untuk pestisida, pelarut dan eter.',NULL,NULL,0),
	(1016,'47774','PERDAGANGAN ECERAN AROMATIK/PENYEGAR (MINYAK ATSIRI)','Kelompok ini mencakup usaha perdagangan eceran khusus aromatik/penyegar minyak atsiri, seperti minyak kenanga, minyak sereh, minyak kayu putih, minyak cendana, minyak lawang, minyak tengkawang, minyak gandapura, minyak jarak, minyak kapulaga, minyak pala, minyak delas dan minyak akar wangi.',NULL,NULL,0),
	(1017,'47779','PERDAGANGAN ECERAN BAHAN KIMIA, DAN AROMATIK/PENYEGAR (MINYAK ATSIRI), DAN BAHAN BAKAR BUKAN BAHAN BAKAR UNTUK KENDARAAN BERMOTOR LAINNNYA','Kelompok ini mencakup usaha perdagangan eceran lainnya yang tidak tercakup dalam kelompok 47771 s.d. 47774, seperti gelatin, bahan isolasi panas selain plastik dan karet, bahan semir, kapur barus.',NULL,NULL,0),
	(1018,'47781','PERDAGANGAN ECERAN BARANG KERAJINAN DARI KAYU, BAMBU, ROTAN, PANDAN, RUMPUT DAN SEJENISNYA','Kelompok ini mencakup usaha perdagangan eceran khusus barang kerajinan dari kayu, bambu, rotan, pandan, rumput dan sejenisnya, seperti patung, topeng, relief, ukiran nama, wayang, pigura, kap lampu, bingkai, talam/baki, tas, keranjang, tikar, topi/tudung, kerai, hiasan dinding dan keset. Termasuk kegiatan galeri kesenian yang menjual barang kerajinan tersebut.',NULL,NULL,0),
	(1019,'47782','PERDAGANGAN ECERAN BARANG KERAJINAN DARI KULIT, TULANG, TANDUK, GADING, BULU DAN BINATANG/HEWAN YANG DIAWETKAN','Kelompok ini mencakup usaha perdagangan eceran khusus barang kerajinan dari kulit, tulang, tanduk, bulu dan binatang/hewan yang diawetkan, seperti kipas dari kulit penyu, karangan bunga dari kulit kerang, pipa rokok dari tulang, pajangan dari tanduk, pajangan dari gading, pajangan dari bulu burung merak dan binatang/hewan yang diawetkan. Termasuk kegiatan galeri kesenian yang menjual barang kerajinan tersebut.',NULL,NULL,0),
	(1020,'47783','PERDAGANGAN ECERAN BARANG KERAJINAN DARI LOGAM','Kelompok ini mencakup usaha perdagangan eceran khusus barang kerajinan dari logam, seperti vas bunga, patung, tempat lilin, piala, medali dan gantungan kunci. Termasuk kegiatan galeri kesenian yang menjual barang kerajinan tersebut.',NULL,NULL,0),
	(1021,'47784','PERDAGANGAN ECERAN BARANG KERAJINAN DARI KERAMIK','Kelompok ini mencakup usaha perdagangan eceran khusus barang kerajinan dari keramik, seperti patung, vas bunga, asbak, tempat sirih, celengan dan pot bunga. Termasuk kegiatan galeri kesenian yang menjual barang kerajinan tersebut.',NULL,NULL,0),
	(1022,'47785','PERDAGANGAN ECERAN LUKISAN','Kelompok ini mencakup usaha perdagangan eceran khusus lukisan, seperti lukisan orang, lukisan binatang dan lukisan pemandangan. Termasuk kegiatan galeri kesenian yang menjual lukisan.',NULL,NULL,0),
	(1023,'47789','PERDAGANGAN ECERAN BARANG KERAJINAN DAN LUKISAN LAINNYA','Kelompok ini mencakup usaha perdagangan eceran khusus barang-barang kerajinan dan lukisan lainnya yang belum tercakup dalam kelompok 47781 s.d. 47785. Termasuk kegiatan galeri kesenian yang menjual barang kerajinan tersebut.',NULL,NULL,0),
	(1024,'47791','PERDAGANGAN ECERAN MESIN PERTANIAN DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan eceran khusus mesin pertanian dan perlengkapannya, seperti traktor, mesin bajak, mesin pemupuk, mesin semai, mesin penanam, mesin penugal, mesin potong rumput, mesin penyemprot, mesin pengupas, mesin perontok, rice milling unit, mesin perah susu, serta komponen dan suku cadang mesin pertanian.',NULL,NULL,0),
	(1025,'47792','PERDAGANGAN ECERAN MESIN JAHIT DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan eceran khusus mesin jahit dan perlengkapannya, seperti mesin jahit tangan/kaki, mesin jahit listrik, mesin obras, mesin bordir, mesin oversum, serta komponen dan suku cadang mesin jahit.',NULL,NULL,0),
	(1026,'47793','PERDAGANGAN ECERAN MESIN LAINNYA DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan eceran khusus mesin lainnya yang belum terliput dalam kelompok 47791 dan 47792, seperti mesin pembangkit tenaga listrik/generator, mesin las, mesin giling kopi, mesin giling tepung, mesin gergaji, mesin bubut, turbin, kincir, mesin tenun, mesin rajut, dan mesin cetak.',NULL,NULL,0),
	(1027,'47794','PERDAGANGAN ECERAN ALAT TRANSPORTASI DARAT TIDAK BERMOTOR DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan eceran khusus alat transportasi darat tidak bermotor, seperti sepeda khusus untuk orang cacat, becak, pedati, gerobak, sado, kereta dorong, serta komponen dan perlengkapannya.',NULL,NULL,0),
	(1028,'47795','PERDAGANGAN ECERAN ALAT TRANSPORTASI AIR DAN PERLENGKAPANNYA','Kelompok ini mencakup usaha perdagangan eceran alat transportasi air (bermotor atau tidak), seperti perahu dan sampan, beserta komponen dan perlengkapannya.',NULL,NULL,0),
	(1029,'47796','PERDAGANGAN ECERAN ALAT-ALAT PERTANIAN','Kelompok ini mencakup usaha perdagangan eceran khusus alat-alat pertanian, seperti cangkul, bajak, sabit, linggis, alat perontok padi bukan mesin.',NULL,NULL,0),
	(1030,'47797','PERDAGANGAN ECERAN ALAT-ALAT PERTUKANGAN','Kelompok ini mencakup usaha perdagangan eceran alat-alat pertukangan, seperti pahat, gergaji, obeng, tang, palu, ketam, kampak.',NULL,NULL,0),
	(1031,'47811','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR KOMODITI PADI DAN PALAWIJA','Kelompok ini mencakup usaha perdagangan eceran padi dan palawija, yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti gabah, jagung, ubi jalar, ubi kayu, talas, kacang kedelai, kacang tanah, kacang hitam dan kacang polong.',NULL,NULL,0),
	(1032,'47812','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR KOMODITI BUAH-BUAHAN','Kelompok ini mencakup usaha perdagangan eceran buah-buahan yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti apel, anggur, alpokat, belimbing, duku, durian, mangga dan lain-lain.',NULL,NULL,0),
	(1033,'47813','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR KOMODITI SAYUR-SAYURAN','Kelompok ini mencakup usaha perdagangan eceran sayur-sayuran yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti bawang merah, bawang putih, kentang, wortel, terong, buncis, mentimun, labu siam, kacang panjang dan kacang merah.',NULL,NULL,0),
	(1034,'47814','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR KOMODITI HASIL PETERNAKAN','Kelompok ini mencakup usaha perdagangan eceran hasil peternakan yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti susu dan telur, daging ternak dan unggas.',NULL,NULL,0),
	(1035,'47815','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR KOMODITI HASIL PERIKANAN','Kelompok ini mencakup usaha perdagangan eceran hasil perikanan yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti udang segar, ikan segar, cumi-cumi segar, ikan hias, nener, benur, benih ikan dan rumput laut.',NULL,NULL,0),
	(1036,'47816','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR KOMODITI HASIL KEHUTANAN DAN PERBURUAN','Kelompok ini mencakup usaha perdagangan eceran komoditi hasil kehutanan dan perburuan yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti kayu bakar, bambu, kayu cendana, getah damar dan sejenisnya.',NULL,NULL,0),
	(1037,'47819','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR KOMODITI TANAMAN HIAS DAN HASIL PERTANIAN LAINNYA','Kelompok ini mencakup usaha perdagangan eceran tanaman hias dan hasil pertanian lainnya yang belum tercakup dalam kelompok 47811 s.d. 47816 yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti anggrek, mawar, melati sedap malam, tanaman hias lainnya dan bibit tanaman hias, bibit buah-buahan dan obat-obatan.',NULL,NULL,0),
	(1038,'47821','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR BERAS','Kelompok ini mencakup usaha perdagangan eceran berbagai jenis beras yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti beras cianjur, beras cisadane, beras saigon, beras ketan dan lain-lain.',NULL,NULL,0),
	(1039,'47822','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR ROTI, KUE KERING, KUE BASAH DAN SEJENISNYA','Kelompok ini mencakup usaha perdagangan eceran berbagai jenis roti, kue kering dan kue basah yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti roti manis, roti tawar, bolu, cake/tart, biskuit, wafer, kue semprong dan cookies.',NULL,NULL,0),
	(1040,'47823','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR KOPI, GULA PASIR, GULA MERAH DAN SEJENISNYA','Kelompok ini mencakup usaha perdagangan eceran kopi, gula pasir, gula merah dan teh yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar).',NULL,NULL,0),
	(1041,'47824','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR TAHU, TEMPE, TAUCO DAN ONCOM','Kelompok ini mencakup usaha perdagangan eceran tahu, tempe, tauco dan oncom yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar).',NULL,NULL,0),
	(1042,'47825','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR DAGING OLAHAN DAN IKAN OLAHAN','Kelompok ini mencakup usaha perdagangan eceran berbagai jenis daging olahan dan ikan olahan yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti abon, sosis, bakso, ikan teri, cucut, selar, kerapu dan ikan, udang, kerang yang diasinkan/dikeringkan.',NULL,NULL,0),
	(1043,'47826','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR MINUMAN','Kelompok ini mencakup usaha perdagangan eceran berbagai minuman yang tidak langsung diminum di tempat, yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti minuman keras (whisky, genever, brandy, gin, arak, rum, sake, tuak), minuman anggur; minuman yang mengandung malt (bir, ale, stout, temulawak) dan minuman ringan (limun, air soda, markisa, teh botol, air mineral dan beras kencur).',NULL,NULL,0),
	(1044,'47827','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR ROKOK DAN TEMBAKAU','Kelompok ini mencakup usaha perdagangan eceran berbagai jenis rokok dan tembakau yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti tembakau krosok, tembakau susur dan tembakau pipa (papier), rokok (putih atau kretek).',NULL,NULL,0),
	(1045,'47828','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR PAKAN TERNAK, PAKAN UNGGAS DAN PAKAN IKAN','Kelompok ini mencakup usaha perdagangan eceran berbagai jenis pakan ternak/unggas/ikan yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti ransum pakan ternak/unggas/ikan, konsentrat pakan ternak/unggas/ikan, tepung tulang, tepung darah dan tepung kerang.',NULL,NULL,0),
	(1046,'47829','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR KOMODITI MAKANAN DAN MINUMAN YTDL','Kelompok ini mencakup usaha perdagangan eceran berbagai jenis makanan dan minuman lainnya yang belum tercakup pada kelompok 47821 s.d. 47828 yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti asinan buah-buahan dan sayuran, kerupuk dan emping/ceriping.',NULL,NULL,0),
	(1047,'47831','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR TEKSTIL','Kelompok ini mencakup usaha perdagangan eceran macam-macam tekstil atau kain baik terbuat dari serat alam, sintetis, maupun campuran yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti kain tenun (kain sarung katun, kain sarung polister, kain suiting sutera, kain suiting serat campuran), kain cetak (kain cetak kapas, kain cetak polyamida, kain kedap air), kain batik (kain batik tulis, kain batik cap, kain batik kombinasi tulis dan cap) dan kain rajut (kain rajut wol, kain rajut rayon, kain rajut wol/kapas).',NULL,NULL,0),
	(1048,'47832','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR PAKAIAN','Kelompok ini mencakup usaha perdagangan eceran macam-macam pakaian baik terbuat dari tekstil, kulit, maupun kulit buatan yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti kemeja, celana, jas, mantel, jaket, piyama, kebaya, blus, rok, daster, singlet, kutang/BH, gaun, rok dalam, baju bayi, pakaian tari, pakaian adat, mukena dan jubah.',NULL,NULL,0),
	(1049,'47833','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR SEPATU, SANDAL DAN ALAS KAKI LAINNYA','Kelompok ini mencakup usaha perdagangan eceran berbagai macam sepatu, sandal, selop dan alas kaki lainnya baik terbuat dari kulit, kulit buatan, plastik, karet, kain ataupun kayu yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti sepatu laki-laki dewasa, sepatu perempuan dewasa, sepatu anak, sepatu olahraga, sepatu sandal, sandal, selop dan sepatu kesehatan.',NULL,NULL,0),
	(1050,'47834','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR PELENGKAP PAKAIAN DAN BENANG','Kelompok ini mencakup usaha perdagangan eceran pelengkap pakaian dan benang yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti selendang, kerudung, sapu tangan, ikat kepala, blangkon, peci, topi, dasi, ikat pinggang, cadar, sarung tangan, handuk, dan selimut. Termasuk juga perdagangan eceran kancing baju, risleting dan benang jahit.',NULL,NULL,0),
	(1051,'47841','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR BAHAN KIMIA','Kelompok ini mencakup usaha perdagangan eceran bahan kimia yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti soda kostik, soda abu, kalium hidroksida, amoniak, argon, bahan pewarna, bahan pengawet, bahan untuk pestisida, pelarut dan eter.',NULL,NULL,0),
	(1052,'47842','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR FARMASI','Kelompok ini mencakup usaha perdagangan eceran farmasi atau obat-obatan yang berbentuk jadi (sediaan), misalnya dalam bentuk tablet, kapsul, salep, bubuk, larutan, larutan parenteral dan suspensi yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti obat-obat untuk penyakit kulit, mata, gigi, telinga, saluran pernapasan, saluran pencernaan, darah tinggi, kelainan hormon dan vitaminvitamin, termasuk juga barang keperluan kesehatan dari karet, antara lain kondom, alat sedot susu ibu, dot susu, kantong darah, sarung tangan untuk pembedahan, pipet karet, alat keluarga berencana dan sumbat karet untuk botol kecil (vial) farmasi.',NULL,NULL,0),
	(1053,'47843','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR OBAT TRADISIONAL','Kelompok ini mencakup usaha perdagangan eceran berbagai macam jamu (obat tradisional) yang bahannya berasal dari tumbuh-tumbuhan, hewan atau mineral misalnya yang berbentuk pil, kapsul, bubuk, dan bentuk cair yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar),',NULL,NULL,0),
	(1054,'47844','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR KOSMETIK','Kelompok ini mencakup usaha perdagangan eceran barang kosmetik yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti kosmetik untuk tata rias muka (eye shadow, maskara, krim wajah, lipstik, lipliner), preparat wangiwangian (cologne, toilet water, parfum), preparat rambut (sampo, tonik rambut, minyak rambut), preparat kuku (base coat, nail polish, nail cream, cuticle remover), preparat perawat kulit (baby oil, cleansing lotion, masker, krim kaki), preparat untuk kebersihan badan (deodoran semprot, deodoran krim, douches), preparat cukur (sabun cukur, shaving cream), kosmetik tradisional (bedak, mangir, lulur) dan kosmetik lainnya antara lain bedak badan, kapas kecantikan dan baby powder.',NULL,NULL,0),
	(1055,'47845','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR PUPUK DAN PEMBERANTAS HAMA','Kelompok ini mencakup usaha perdagangan eceran berbagai macam pupuk dan pemberantas hama yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti pupuk buatan tunggal (urea, ZA, TSP, DSP), pupuk buatan majemuk dan campuran (mono amonium fosfat, diamonium fosfat, nitrogen fosfat kalium), pupuk alam (pupuk kompos, pupuk dolomit, pupuk kapur), insektisida, fungisida, rodentisida, herbisida, nematisida dan akarisida.',NULL,NULL,0),
	(1056,'47846','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR AROMATIK/PENYEGAR (MINYAK ATSIRI)','Kelompok ini mencakup usaha perdagangan eceran aromatik/penyegar (minyak atsiri) yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti minyak kenanga, minyak sereh, minyak kayu putih, minyak cendana, minyak lawang, minyak tengkawang, minyak gandapura, minyak jarak, minyak kapulaga, minyak pala, minyak delas dan minyak akar wangi.',NULL,NULL,0),
	(1057,'47849','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR BAHAN KIMIA, FARMASI, KOSMETIK DAN ALAT LABORATORIUM DAN YBDI YTDL','Kelompok ini mencakup usaha perdagangan eceran kaki lima dan los pasar lainnya yang belum tercakup dalam kelompok 47841 s.d. 47846, seperti gelatin, bahan isolasi panas selain plastik dan karet, bahan semir, kapur barus dan bahan jamu (simplisia).',NULL,NULL,0),
	(1058,'47851','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR KACA MATA','Kelompok ini mencakup usaha perdagangan eceran berbagai macam kaca mata yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti kaca mata pembantu penglihatan, kaca mata peredam sinar matahari/cahaya, lensa kontak (contact lens, soft lens) dan frame kaca mata.',NULL,NULL,0),
	(1059,'47852','PERDAGANGAN ECERAN KAKI LIMA DAN LOS PASAR BARANG PERHIASAN','Kelompok ini mencakup usaha perdagangan eceran barang perhiasan baik terbuat dari batu mulia, batu permata, batu permata tiruan, berlian, intan, batu aji, serbuk dan bubuk intan, logam mulia ataupun bukan logam mulia yang dilakukan di pinggir jalan umum (kaki lima), serambi muka (emper) toko atau tempat tetap di pasar yang dapat dipindah-pindah atau didorong (los pasar), seperti cincin, kalung, gelang, giwang (anting-anting), tusuk konde peniti, bross, ikat pinggang dan kancing dari logam mulia (platina, emas dan perak).',NULL,NULL,0),
